static int64_t framework_framework_uptime_millis(void) {
    struct timespec ts = {0};
    (void)clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

static bool framework_framework_network_trace_slot(void) {
    return atomic_fetch_add_explicit(&framework_g_fw.network_trace_count, 1u, memory_order_relaxed) < 96u;
}

static void framework_copy_text(char *dst, size_t cap, const char *src, const char *fallback) {
    const char *value = src && src[0] ? src : fallback;
    if (!value) value = "";
    if (!cap) return;
    snprintf(dst, cap, "%s", value);
}

static bool framework_join_path(char *out, size_t cap, const char *a, const char *b) {
    if (!out || cap == 0 || !a || !b) {
        return false;
    }

    const size_t a_len = strlen(a);
    const size_t b_len = strlen(b);
    const bool needs_separator = a_len != 0 && a[a_len - 1] != '/';
    const size_t separator_len = needs_separator ? 1u : 0u;

    if (a_len >= cap || b_len > cap - a_len - 1u) {
        out[0] = '\0';
        return false;
    }
    if (separator_len != 0 && b_len > cap - a_len - separator_len - 1u) {
        out[0] = '\0';
        return false;
    }

    memcpy(out, a, a_len);
    size_t pos = a_len;
    if (needs_separator) {
        out[pos++] = '/';
    }
    memcpy(out + pos, b, b_len);
    out[pos + b_len] = '\0';
    return true;
}

static bool framework_init_framework_paths(void) {
    struct framework_PathSpec {
        char *out;
        size_t cap;
        const char *leaf;
    };
    const struct framework_PathSpec paths[] = {
        {framework_g_fw.data_dir, sizeof(framework_g_fw.data_dir), "data"},
        {framework_g_fw.files_dir, sizeof(framework_g_fw.files_dir), "files"},
        {framework_g_fw.cache_dir, sizeof(framework_g_fw.cache_dir), "cache"},
        {framework_g_fw.code_cache_dir, sizeof(framework_g_fw.code_cache_dir), "code_cache"},
        {framework_g_fw.no_backup_dir, sizeof(framework_g_fw.no_backup_dir), "no_backup"},
        {framework_g_fw.external_files_dir, sizeof(framework_g_fw.external_files_dir), "external/files"},
        {framework_g_fw.external_cache_dir, sizeof(framework_g_fw.external_cache_dir), "external/cache"},
        {framework_g_fw.obb_dir, sizeof(framework_g_fw.obb_dir), "obb"},
        {framework_g_fw.prefs_dir, sizeof(framework_g_fw.prefs_dir), "shared_prefs"},
    };

    for (size_t i = 0; i < framework_ARRAY_COUNT(paths); ++i) {
        if (!framework_join_path(paths[i].out, paths[i].cap, framework_g_fw.root, paths[i].leaf)) {
            ETD2X_LOGCE("ANDROID", "path too long root=%s leaf=%s", framework_g_fw.root, paths[i].leaf);
            return false;
        }
    }
    return true;
}

/* Android-facing java.io.File paths must remain Android/Unix paths.  Host
 * paths such as "sdmc:/..." are an implementation detail and must not leak to
 * Cocos or application code: Cocos2d-x classifies absolute filesystem paths by
 * their leading '/', and a device-prefixed host path can therefore be treated
 * as a resource/search-path name instead of a file.  Keep the Java-visible
 * path guest-native and translate only when the framework touches the host FS. */
static bool framework_framework_private_guest_path(char *out, size_t cap, const char *suffix) {
    if (!out || cap == 0 || !framework_g_fw.package_name[0]) return false;
    if (!suffix) suffix = "";
    while (*suffix == '/') ++suffix;
    const int n = suffix[0]
        ? snprintf(out, cap, "/data/data/%s/%s", framework_g_fw.package_name, suffix)
        : snprintf(out, cap, "/data/data/%s", framework_g_fw.package_name);
    return n > 0 && (size_t)n < cap;
}

static bool framework_framework_normalize_absolute_guest_path(const char *path, char *out, size_t cap) {
    if (!path || !out || cap < 2u || path[0] != '/') return false;
    size_t out_len = 1u;
    out[0] = '/';
    out[1] = '\0';
    const char *p = path + 1;
    while (*p) {
        while (*p == '/') ++p;
        if (!*p) break;
        const char *start = p;
        while (*p && *p != '/') ++p;
        const size_t len = (size_t)(p - start);
        if (len == 1u && start[0] == '.') continue;
        if (len == 2u && start[0] == '.' && start[1] == '.') {
            while (out_len > 1u && out[out_len - 1u] != '/') --out_len;
            if (out_len > 1u) --out_len;
            out[out_len] = '\0';
            continue;
        }
        const size_t needed = out_len + (out_len > 1u ? 1u : 0u) + len + 1u;
        if (needed > cap) return false;
        if (out_len > 1u) out[out_len++] = '/';
        memcpy(out + out_len, start, len);
        out_len += len;
        out[out_len] = '\0';
    }
    return true;
}

typedef enum framework_FrameworkStorageDomain {
    FRAMEWORK_STORAGE_OTHER = 0,
    FRAMEWORK_STORAGE_PRIVATE,
    FRAMEWORK_STORAGE_EXTERNAL,
} framework_FrameworkStorageDomain;

static framework_FrameworkStorageDomain framework_framework_storage_domain(const char *path) {
    if (!path) return FRAMEWORK_STORAGE_OTHER;
    char normalized[PATH_CAP];
    const char *guest = path;
    if (path[0] == '/' && framework_framework_normalize_absolute_guest_path(path, normalized, sizeof(normalized)))
        guest = normalized;
    static const char *private_roots[] = {"/data/data", "/data/user/0", "/data/user_de/0"};
    static const char *external_roots[] = {"/sdcard", "/mnt/sdcard", "/storage/emulated/0", "/storage/self/primary"};
    for (size_t i = 0; i < framework_ARRAY_COUNT(private_roots); ++i) {
        const size_t n = strlen(private_roots[i]);
        if (strncmp(guest, private_roots[i], n) == 0 && (guest[n] == '\0' || guest[n] == '/'))
            return FRAMEWORK_STORAGE_PRIVATE;
    }
    for (size_t i = 0; i < framework_ARRAY_COUNT(external_roots); ++i) {
        const size_t n = strlen(external_roots[i]);
        if (strncmp(guest, external_roots[i], n) == 0 && (guest[n] == '\0' || guest[n] == '/'))
            return FRAMEWORK_STORAGE_EXTERNAL;
    }
    return FRAMEWORK_STORAGE_OTHER;
}

static bool framework_framework_external_app_namespace_foreign(const char *path, const char *root,
                                                      const char *kind) {
    if (!path || !root || !kind || !framework_g_fw.package_name[0]) return false;
    char prefix[TEXT_CAP];
    const int n = snprintf(prefix, sizeof(prefix), "%s/Android/%s/", root, kind);
    if (n <= 0 || (size_t)n >= sizeof(prefix) || strncmp(path, prefix, (size_t)n) != 0)
        return false;
    const char *pkg = path + (size_t)n;
    const size_t active_len = strlen(framework_g_fw.package_name);
    return strncmp(pkg, framework_g_fw.package_name, active_len) != 0 ||
           (pkg[active_len] != '\0' && pkg[active_len] != '/');
}

/* Join a host root and a guest relative path, encoding FAT-reserved name
 * characters exactly as Bionic's path mapping does (etd2x/host_name.h). */
static bool framework_join_guest_path(char *out, size_t cap, const char *root, const char *guest_suffix) {
    char encoded[PATH_CAP];
    return etd2x_host_name_encode(guest_suffix, encoded, sizeof(encoded)) &&
           framework_join_path(out, cap, root, encoded);
}

static const char *framework_framework_file_host_path(const char *path, char *out, size_t cap) {
    if (!path || !out || cap == 0) return path;
    if (strncmp(path, "sdmc:", 5) == 0) return path;

    char normalized[PATH_CAP];
    const char *guest = path;
    if (path[0] == '/' && framework_framework_normalize_absolute_guest_path(path, normalized, sizeof(normalized)))
        guest = normalized;

    const char *suffix = NULL;
    char prefix[TEXT_CAP];
    /* Android's system trust store: the firmware roots ETD2X exports (the
     * same directory Bionic file calls see at this path). */
    static const char k_system_ca[] = "/system/etc/security/cacerts";
    if (strncmp(guest, k_system_ca, sizeof(k_system_ca) - 1u) == 0 &&
        (guest[sizeof(k_system_ca) - 1u] == '\0' || guest[sizeof(k_system_ca) - 1u] == '/')) {
        const char *ca_dir = etd2x_compat_network_ca_dir ? etd2x_compat_network_ca_dir() : NULL;
        if (!ca_dir || !ca_dir[0]) return path;
        suffix = guest + sizeof(k_system_ca) - 1u;
        while (*suffix == '/') ++suffix;
        if (!framework_join_guest_path(out, cap, ca_dir, suffix)) return path;
        return out;
    }
    static const char *roots[] = {"/data/data/", "/data/user/0/", "/data/user_de/0/"};
    for (size_t i = 0; i < framework_ARRAY_COUNT(roots); ++i) {
        const int n = snprintf(prefix, sizeof(prefix), "%s%s", roots[i], framework_g_fw.package_name);
        if (n <= 0 || (size_t)n >= sizeof(prefix)) continue;
        const size_t pn = (size_t)n;
        if (strncmp(guest, prefix, pn) != 0 || (guest[pn] != '\0' && guest[pn] != '/')) continue;
        suffix = guest + pn;
        while (*suffix == '/') ++suffix;
        if (!framework_join_guest_path(out, cap, framework_g_fw.root, suffix)) return path;
        return out;
    }

    /* Mirror Android's equivalent external-storage aliases while retaining one
     * package backing tree. Java File and Bionic must resolve these aliases in
     * the same way. */
    static const char *external_roots[] = {
        "/sdcard", "/mnt/sdcard", "/storage/emulated/0", "/storage/self/primary"
    };
    for (size_t i = 0; i < framework_ARRAY_COUNT(external_roots); ++i) {
        const int en = snprintf(prefix, sizeof(prefix), "%s/Android/data/%s",
                                external_roots[i], framework_g_fw.package_name);
        if (en > 0 && (size_t)en < sizeof(prefix)) {
            const size_t pn = (size_t)en;
            if (strncmp(guest, prefix, pn) == 0 && (guest[pn] == '\0' || guest[pn] == '/')) {
                suffix = guest + pn;
                while (*suffix == '/') ++suffix;
                char external_root[PATH_CAP];
                if (!framework_join_path(external_root, sizeof(external_root), framework_g_fw.root, "external") ||
                    !framework_join_guest_path(out, cap, external_root, suffix)) return path;
                return out;
            }
        }
        const int on = snprintf(prefix, sizeof(prefix), "%s/Android/obb/%s",
                                external_roots[i], framework_g_fw.package_name);
        if (on > 0 && (size_t)on < sizeof(prefix)) {
            const size_t pn = (size_t)on;
            if (strncmp(guest, prefix, pn) == 0 && (guest[pn] == '\0' || guest[pn] == '/')) {
                suffix = guest + pn;
                while (*suffix == '/') ++suffix;
                if (!framework_join_guest_path(out, cap, framework_g_fw.obb_dir, suffix)) return path;
                return out;
            }
        }
    }
    for (size_t i = 0; i < framework_ARRAY_COUNT(external_roots); ++i) {
        if (framework_framework_external_app_namespace_foreign(guest, external_roots[i], "data") ||
            framework_framework_external_app_namespace_foreign(guest, external_roots[i], "obb"))
            return path;
    }
    for (size_t i = 0; i < framework_ARRAY_COUNT(external_roots); ++i) {
        const size_t ext_n = strlen(external_roots[i]);
        if (strncmp(guest, external_roots[i], ext_n) != 0 ||
            (guest[ext_n] != '\0' && guest[ext_n] != '/')) continue;
        suffix = guest + ext_n;
        while (*suffix == '/') ++suffix;
        char external_root[PATH_CAP];
        if (!framework_join_path(external_root, sizeof(external_root), framework_g_fw.root, "external") ||
            !framework_join_guest_path(out, cap, external_root, suffix)) return path;
        return out;
    }
    return path;
}

static bool framework_framework_external_guest_path(char *out, size_t cap, const char *suffix) {
    if (!out || cap == 0 || !framework_g_fw.package_name[0]) return false;
    if (!suffix) suffix = "";
    while (*suffix == '/') ++suffix;
    const int n = suffix[0]
        ? snprintf(out, cap, "/storage/emulated/0/Android/data/%s/%s", framework_g_fw.package_name, suffix)
        : snprintf(out, cap, "/storage/emulated/0/Android/data/%s", framework_g_fw.package_name);
    return n > 0 && (size_t)n < cap;
}

static bool framework_framework_obb_guest_path(char *out, size_t cap) {
    if (!out || cap == 0 || !framework_g_fw.package_name[0]) return false;
    const int n = snprintf(out, cap, "/storage/emulated/0/Android/obb/%s", framework_g_fw.package_name);
    return n > 0 && (size_t)n < cap;
}

static bool framework_mkdir_one(const char *path) {
    if (!path || !path[0]) return false;
    if (mkdir(path, 0777) == 0) {
        if (etd2x_path_lookup_changed) etd2x_path_lookup_changed(path);
        return true;
    }
    if (errno != EEXIST) return false;
    /* EEXIST is success only when the existing node is actually a directory.
     * Treating a regular file as a created directory corrupts Java File.mkdirs()
     * semantics and can make later File.exists()/FileInputStream behavior diverge. */
    struct stat st;
    return stat(path, &st) == 0 && (st.st_mode & S_IFDIR) != 0;
}

static bool framework_mkdirs(const char *path) {
    if (!path || !path[0]) return false;
    /* Common case: the directory already exists (Context.getFilesDir() and
     * friends ensure it on every call). One stat instead of a mkdir+stat per
     * path component, each a file-system service round trip on Horizon. */
    struct stat existing;
    if (stat(path, &existing) == 0 && S_ISDIR(existing.st_mode)) return true;
    char tmp[PATH_CAP];
    if (snprintf(tmp, sizeof(tmp), "%s", path) >= (int)sizeof(tmp)) return false;
    const size_t n = strlen(tmp);
    for (size_t i = 1; i < n; ++i) {
        if (tmp[i] != '/') continue;
        const char saved = tmp[i];
        tmp[i] = '\0';
        const size_t len = strlen(tmp);
        if (len && tmp[len - 1] != ':' && !framework_mkdir_one(tmp)) return false;
        tmp[i] = saved;
    }
    return framework_mkdir_one(tmp);
}

static bool framework_path_stat(const char *path, struct stat *st) {
    if (!path || !st) return false;
    char mapped[PATH_CAP];
    const char *host = framework_framework_file_host_path(path, mapped, sizeof(mapped));
    return host && stat(host, st) == 0;
}

