/* Java-level blocking waits (Looper, CountDownLatch, Semaphore) are signal
 * safe points when the compat runtime is linked, so a guest thread parked in
 * one still takes thread-directed signals. Same weak-reference pattern as
 * above for the framework host tests. */
#if defined(__GNUC__)
extern int etd2x_signal_safe_cond_timedwait(pthread_cond_t *cond, pthread_mutex_t *mutex,
                                            const struct timespec *deadline) __attribute__((weak));
#endif
static int framework_framework_cond_timedwait(pthread_cond_t *cond, pthread_mutex_t *mutex,
                                    const struct timespec *deadline) {
#if defined(__GNUC__)
    if (!etd2x_signal_safe_cond_timedwait) return pthread_cond_timedwait(cond, mutex, deadline);
#endif
    return etd2x_signal_safe_cond_timedwait(cond, mutex, deadline);
}

static uint64_t framework_stable_mix64(uint64_t x) {
    x ^= x >> 30; x *= UINT64_C(0xbf58476d1ce4e5b9);
    x ^= x >> 27; x *= UINT64_C(0x94d049bb133111eb);
    return x ^ (x >> 31);
}

static bool framework_load_or_create_android_id(void) {
    if (framework_g_fw.android_id[0]) return true;
    char path[PATH_CAP];
    if (!framework_join_path(path, sizeof(path), framework_g_fw.prefs_dir, "__etd2x_android_id")) return false;
    FILE *f = fopen(path, "rb");
    if (f) {
        char buf[32] = {0};
        const size_t n = fread(buf, 1, 16, f);
        fclose(f);
        bool ok = n == 16;
        for (size_t i = 0; ok && i < 16; ++i)
            ok = (buf[i] >= '0' && buf[i] <= '9') || (buf[i] >= 'a' && buf[i] <= 'f');
        if (ok) { memcpy(framework_g_fw.android_id, buf, 16); framework_g_fw.android_id[16] = '\0'; return true; }
    }
    uint64_t seed = UINT64_C(1469598103934665603);
    for (const unsigned char *p = (const unsigned char *)framework_g_fw.package_name; *p; ++p) {
        seed ^= *p; seed *= UINT64_C(1099511628211);
    }
    struct timespec ts = {0};
    (void)clock_gettime(CLOCK_REALTIME, &ts);
    seed ^= (uint64_t)ts.tv_sec ^ ((uint64_t)ts.tv_nsec << 21) ^ (uintptr_t)&framework_g_fw;
    const uint64_t value = framework_stable_mix64(seed);
    static const char hex[] = "0123456789abcdef";
    for (unsigned i = 0; i < 8; ++i) {
        const unsigned char b = (unsigned char)(value >> (i * 8));
        framework_g_fw.android_id[i * 2] = hex[b >> 4];
        framework_g_fw.android_id[i * 2 + 1] = hex[b & 15];
    }
    framework_g_fw.android_id[16] = '\0';
    f = fopen(path, "wb");
    if (f) { (void)fwrite(framework_g_fw.android_id, 1, 16, f); (void)fclose(f); }
    ETD2X_LOGCI("ANDROID", "Settings.Secure Android ID initialized persistent=1");
    return true;
}

