static framework_FilePayload *framework_file_payload_new(const char *path) {
    framework_FilePayload *payload = calloc(1, sizeof(*payload));
    if (!payload) return NULL;
    payload->path = path ? strdup(path) : strdup("");
    if (!payload->path) { free(payload); return NULL; }
    payload->next = framework_g_fw.files;
    framework_g_fw.files = payload;
    return payload;
}

static void *framework_new_file(void *env, const char *path) {
    void *ref = etd2x_jni_new_local_object(env, "java/io/File");
    framework_FilePayload *payload = ref ? framework_file_payload_new(path) : NULL;
    if (!ref || !payload) return NULL;
    (void)etd2x_jni_set_object_host_data(ref, payload);
    return ref;
}

