static bool framework_nio_copy_option_named(void *env, void *array, const char *wanted) {
    const int32_t count = etd2x_jni_array_length_host(array);
    for (int32_t i = 0; i < count; ++i) {
        void *option = NULL;
        if (etd2x_jni_get_object_array_element_host(env, array, i, &option) != ETD2X_OK || !option) continue;
        char cls[128] = {0};
        (void)etd2x_jni_object_class_name_host(option, cls, sizeof(cls));
        framework_EnumPayload *ep = (framework_EnumPayload *)etd2x_jni_get_object_host_data(option);
        const bool match = strcmp(cls, "java/nio/file/StandardCopyOption") == 0 && ep &&
                           ep->magic == ENUM_PAYLOAD_MAGIC && ep->name && strcmp(ep->name, wanted) == 0;
        etd2x_jni_delete_local_ref_host(env, option);
        if (match) return true;
    }
    return false;
}

