static Etd2xJniValue framework_nio_files_move(void *env, void *token, const Etd2xJniValue *a, size_t n, void *ud) {
    (void)token; (void)ud;
    if (n != 3 || !a[0].l || !a[1].l) return framework_v_object(NULL);
    const char *src_guest = framework_nio_path_text_from_ref(a[0].l);
    const char *dst_guest = framework_nio_path_text_from_ref(a[1].l);
    if (!src_guest || !dst_guest) return framework_v_object(NULL);
    char src_mapped[PATH_CAP], dst_mapped[PATH_CAP];
    const char *src = framework_framework_file_host_path(src_guest, src_mapped, sizeof(src_mapped));
    const char *dst = framework_framework_file_host_path(dst_guest, dst_mapped, sizeof(dst_mapped));
    if (!src || !dst) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", "Files.move path mapping");
        return framework_v_object(NULL);
    }
    struct stat src_st;
    if (stat(src, &src_st) != 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/nio/file/NoSuchFileException", src_guest);
        return framework_v_object(NULL);
    }
    if (strcmp(src, dst) == 0)
        return framework_v_object(etd2x_jni_new_local_ref_host(env, a[1].l));
    struct stat dst_st;
    const bool dst_exists = stat(dst, &dst_st) == 0;
    const bool replace = a[2].l && framework_nio_copy_option_named(env, a[2].l, "REPLACE_EXISTING");
    const bool atomic = a[2].l && framework_nio_copy_option_named(env, a[2].l, "ATOMIC_MOVE");
    if (dst_exists && !replace && !atomic) {
        (void)etd2x_jni_throw_new_by_name(env, "java/nio/file/FileAlreadyExistsException", dst_guest);
        return framework_v_object(NULL);
    }
    /* fsdev rename cannot overwrite a destination. Reuse the rollback-capable
     * replacement path for ordinary moves; its backup dance is not atomic. */
    const bool replaced = replace && !atomic;
    const bool moved = replaced ? framework_framework_replace_file(src, dst) : rename(src, dst) == 0;
    if (!moved) {
        const int saved = errno;
        ETD2X_LOGCW("FILE", "Files.move source=%s target=%s replace=%d atomic=%d errno=%d",
                    src_guest, dst_guest, replace, atomic, saved);
        const char *exception = atomic && (saved == EXDEV || saved == EEXIST || saved == ENOTEMPTY)
            ? "java/nio/file/AtomicMoveNotSupportedException" : "java/io/IOException";
        char detail[128];
        snprintf(detail, sizeof(detail), "Files.move: %s (errno=%d)", strerror(saved), saved);
        (void)etd2x_jni_throw_new_by_name(env, exception, detail);
        return framework_v_object(NULL);
    }
    if (!replaced) etd2x_android_file_observer_notify_move(src, dst);
    return framework_v_object(etd2x_jni_new_local_ref_host(env, a[1].l));
}

