static bool framework_file_absolute_text(const char *path, char *out, size_t cap) {
    if (!path || !out || cap < 2) return false;
    if (path[0] == '/') return snprintf(out, cap, "%s", path) < (int)cap;
    return snprintf(out, cap, "/%s", path) < (int)cap;
}

