/* File.toURI(): new URI("file", null, slashify(getAbsolutePath(), isDirectory()), null).
 * java.net.URI is the AOSP class from the libcore overlay, so quoting and
 * parsing follow libcore exactly. */
static Etd2xJniValue framework_file_to_uri(void *env, void *token, const Etd2xJniValue *a, size_t n, void *ud) {
    (void)a; (void)ud;
    framework_FilePayload *p = framework_receiver_file(token);
    char absolute[PATH_CAP], sp[PATH_CAP + 4];
    if (n != 0 || !p || !framework_file_absolute_text(p->path, absolute, sizeof(absolute))) return framework_v_object(NULL);
    const size_t len = strlen(absolute);
    const bool dir = framework_file_is_dir(env, token, NULL, 0, NULL).z != 0;
    snprintf(sp, sizeof(sp), "%s%s%s", strncmp(absolute, "//", 2) == 0 ? "//" : "", absolute,
             dir && len && absolute[len - 1] != '/' ? "/" : "");
    void *uri = etd2x_jni_new_local_object(env, "java/net/URI");
    if (!uri) {
        if (!etd2x_jni_exception_pending_host(env))
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/NoClassDefFoundError", "java/net/URI");
        return framework_v_object(NULL);
    }
    Etd2xJniValue args[4] = {{.l = framework_new_string(env, "file")}, {.l = NULL}, {.l = framework_new_string(env, sp)}, {.l = NULL}};
    Etd2xJniValue out = {0};
    bool found = false;
    const Etd2xResult rc = etd2x_jni_invoke_method_host(
        env, uri, "java/net/URI", "<init>",
        "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;)V",
        false, args, &out, &found);
    if (args[0].l) etd2x_jni_delete_local_ref_host(env, args[0].l);
    if (args[2].l) etd2x_jni_delete_local_ref_host(env, args[2].l);
    if (rc != ETD2X_OK || !found || etd2x_jni_exception_pending_host(env)) {
        etd2x_jni_delete_local_ref_host(env, uri);
        if (!etd2x_jni_exception_pending_host(env))
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/NoSuchMethodError", "java/net/URI.<init>");
        return framework_v_object(NULL);
    }
    return framework_v_object(uri);
}

