static Etd2xJniValue framework_file_create_new_file(void *env, void *token, const Etd2xJniValue *a, size_t n, void *ud) {
    (void)a; (void)ud;
    framework_FilePayload *p = framework_receiver_file(token);
    if (n != 0 || !p || !p->path || !p->path[0]) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", "File.createNewFile");
        return framework_v_bool(false);
    }
    char mapped[PATH_CAP];
    const char *host = framework_framework_file_host_path(p->path, mapped, sizeof(mapped));
    if (!host) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", "File.createNewFile path mapping");
        return framework_v_bool(false);
    }
    /* java.io.File.createNewFile() is an atomic create-if-absent operation.
     * Keep that contract at the Android filesystem boundary: never implement
     * it as stat()+fopen(), which has a race between the existence check and
     * creation. */
    const int fd = open(host, O_WRONLY | O_CREAT | O_EXCL, 0666);
    if (fd >= 0) {
        (void)close(fd);
        etd2x_android_file_observer_notify_event(host, ETD2X_FO_CREATE);
        return framework_v_bool(true);
    }
    if (errno == EEXIST) return framework_v_bool(false);
    (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", "File.createNewFile");
    return framework_v_bool(false);
}

