static Etd2xJniValue framework_file_list_files(void *env, void *token, const Etd2xJniValue *a, size_t n, void *ud) {
    (void)a; (void)n; (void)ud;
    framework_FilePayload *p = framework_receiver_file(token);
    if (!p || !p->path) return framework_v_object(NULL);

    char mapped[PATH_CAP];
    const char *host = framework_framework_file_host_path(p->path, mapped, sizeof(mapped));
    if (!host) return framework_v_object(NULL);
    DIR *dir = opendir(host);
    if (!dir) return framework_v_object(NULL);

    char **names = NULL;
    size_t count = 0, cap = 0;
    struct dirent *entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        if (count == cap) {
            const size_t next_cap = cap ? cap * 2u : 16u;
            char **grown = realloc(names, next_cap * sizeof(*grown));
            if (!grown) {
                for (size_t i = 0; i < count; ++i) free(names[i]);
                free(names);
                closedir(dir);
                (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError",
                                                   "File.listFiles");
                return framework_v_object(NULL);
            }
            names = grown;
            cap = next_cap;
        }
        char guest_name[sizeof(entry->d_name) + 1];
        etd2x_host_name_decode(entry->d_name, guest_name, sizeof(guest_name));
        names[count] = strdup(guest_name);
        if (!names[count]) {
            for (size_t i = 0; i < count; ++i) free(names[i]);
            free(names);
            closedir(dir);
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError",
                                               "File.listFiles");
            return framework_v_object(NULL);
        }
        ++count;
    }
    closedir(dir);

    if (count > INT32_MAX) {
        for (size_t i = 0; i < count; ++i) free(names[i]);
        free(names);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError",
                                           "File.listFiles too large");
        return framework_v_object(NULL);
    }

    void *array = etd2x_jni_new_local_reference_array(env, "[Ljava/io/File;", (int32_t)count);
    if (!array) {
        for (size_t i = 0; i < count; ++i) free(names[i]);
        free(names);
        return framework_v_object(NULL);
    }
    for (size_t i = 0; i < count; ++i) {
        char child[PATH_CAP];
        if (!framework_join_path(child, sizeof(child), p->path, names[i])) {
            free(names[i]);
            continue;
        }
        void *file = framework_new_file(env, child);
        if (file) {
            (void)etd2x_jni_set_object_array_element_host(env, array, (int32_t)i, file);
            etd2x_jni_delete_local_ref_host(env, file);
        }
        free(names[i]);
    }
    free(names);
    return framework_v_object(array);
}


/* ---------- java.io.FileDescriptor / android.os.ParcelFileDescriptor ---------- */
#define ETD2X_PFD_MODE_READ_ONLY  0x10000000
#define ETD2X_PFD_MODE_WRITE_ONLY 0x20000000
#define ETD2X_PFD_MODE_READ_WRITE 0x30000000
#define ETD2X_PFD_MODE_CREATE     0x08000000
#define ETD2X_PFD_MODE_TRUNCATE   0x04000000
#define ETD2X_PFD_MODE_APPEND     0x02000000
#define ETD2X_PFD_MODE_ACCESS     0x30000000

static framework_ParcelFdPayload *framework_parcel_fd_payload_from_token(void *token) {
    framework_ParcelFdPayload *p = (framework_ParcelFdPayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == PARCEL_FD_PAYLOAD_MAGIC ? p : NULL;
}

static framework_JavaFileDescriptorPayload *framework_file_descriptor_payload_from_token(void *token) {
    framework_JavaFileDescriptorPayload *p = (framework_JavaFileDescriptorPayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == FILE_DESCRIPTOR_PAYLOAD_MAGIC ? p : NULL;
}

static int framework_file_descriptor_current_fd(framework_JavaFileDescriptorPayload *p) {
    if (!p || p->magic != FILE_DESCRIPTOR_PAYLOAD_MAGIC) return -1;
    if (p->pfd_owner) {
        framework_ParcelFdPayload *owner = p->pfd_owner;
        return owner->magic == PARCEL_FD_PAYLOAD_MAGIC && !owner->closed && !owner->detached
            ? owner->fd : -1;
    }
    if (p->stream_owner) {
        framework_StreamPayload *owner = p->stream_owner;
        return owner->magic == STREAM_PAYLOAD_MAGIC && !owner->closed && owner->fp
            ? fileno(owner->fp) : -1;
    }
    return p->fd;
}

static void *framework_new_file_descriptor(void *env, int fd, framework_StreamPayload *stream_owner, framework_ParcelFdPayload *pfd_owner) {
    void *ref = etd2x_jni_new_local_object(env, "java/io/FileDescriptor");
    if (!ref) return NULL;
    framework_JavaFileDescriptorPayload *p = calloc(1, sizeof(*p));
    if (!p) { etd2x_jni_delete_local_ref_host(env, ref); return NULL; }
    p->magic = FILE_DESCRIPTOR_PAYLOAD_MAGIC;
    p->fd = fd;
    p->stream_owner = stream_owner;
    p->pfd_owner = pfd_owner;
    p->next = framework_g_fw.file_descriptors;
    framework_g_fw.file_descriptors = p;
    if (etd2x_jni_set_object_host_data(ref, p) != ETD2X_OK) {
        p->magic = 0;
        etd2x_jni_delete_local_ref_host(env, ref);
        return NULL;
    }
    return ref;
}

static int framework_pfd_host_open_flags(int32_t mode, bool *ok) {
    const int32_t access = mode & ETD2X_PFD_MODE_ACCESS;
    int flags = 0;
    *ok = true;
    if (access == ETD2X_PFD_MODE_READ_ONLY) flags = O_RDONLY;
    else if (access == ETD2X_PFD_MODE_WRITE_ONLY) flags = O_WRONLY;
    else if (access == ETD2X_PFD_MODE_READ_WRITE) flags = O_RDWR;
    else { *ok = false; return 0; }
    if (mode & ETD2X_PFD_MODE_CREATE) flags |= O_CREAT;
    if (mode & ETD2X_PFD_MODE_TRUNCATE) flags |= O_TRUNC;
    if (mode & ETD2X_PFD_MODE_APPEND) flags |= O_APPEND;
#ifdef O_CLOEXEC
    flags |= O_CLOEXEC;
#endif
    return flags;
}

static framework_ParcelFdPayload *framework_parcel_fd_payload_new(int fd, const char *guest_path, const char *host_path) {
    framework_ParcelFdPayload *p = calloc(1, sizeof(*p));
    if (!p) return NULL;
    p->magic = PARCEL_FD_PAYLOAD_MAGIC;
    p->fd = fd;
    p->host_flags = O_RDONLY;
    p->guest_path = strdup(guest_path ? guest_path : "");
    p->host_path = strdup(host_path ? host_path : "");
    if (!p->guest_path || !p->host_path) {
        free(p->guest_path); free(p->host_path); free(p); return NULL;
    }
    p->next = framework_g_fw.parcel_fds;
    framework_g_fw.parcel_fds = p;
    return p;
}

static void framework_stream_close_payload(framework_StreamPayload *p);

static void framework_parcel_fd_close_owned(framework_ParcelFdPayload *p) {
    if (!p || p->magic != PARCEL_FD_PAYLOAD_MAGIC || p->closed || p->detached) return;
    if (p->stream) { framework_stream_close_payload(p->stream); return; }
    if (p->fd >= 0) {
        if (etd2x_file_contract_close) etd2x_file_contract_close(p->fd);
        (void)close(p->fd);
    }
    p->fd = -1;
    p->closed = true;
}

static int framework_framework_duplicate_fd(int source) {
    int fd;
    if (etd2x_file_contract_duplicate) return etd2x_file_contract_duplicate(source, 0, true);
#ifdef F_DUPFD_CLOEXEC
    fd = fcntl(source, F_DUPFD_CLOEXEC, 0);
#else
    fd = fcntl(source, F_DUPFD, 0);
    if (fd >= 0 && fcntl(fd, F_SETFD, FD_CLOEXEC) != 0) { close(fd); fd = -1; }
#endif
    if (fd >= 0 && etd2x_file_contract_dup) etd2x_file_contract_dup(source, fd);
    return fd;
}

static Etd2xJniValue framework_parcel_fd_duplicate(void *env, void *token, const Etd2xJniValue *a, size_t n, void *u) {
    framework_JavaFileDescriptorPayload *descriptor = NULL;
    framework_ParcelFdPayload *owner = NULL;
    int source = -1;
    if ((intptr_t)u == 1) { /* ParcelFileDescriptor.dup() */
        owner = framework_parcel_fd_payload_from_token(token);
        if (n == 0 && owner && !owner->closed && !owner->detached) source = owner->fd;
    } else if ((intptr_t)u == 2) { /* fromFd(int) */
        if (n == 1) source = a[0].i;
        for (framework_ParcelFdPayload *p = framework_g_fw.parcel_fds; source >= 0 && p; p = p->next)
            if (!p->closed && !p->detached && p->fd == source) { owner = p; break; }
    } else if (n == 1 && a[0].l) {
        descriptor = framework_file_descriptor_payload_from_token(etd2x_jni_object_token_host(a[0].l));
        source = framework_file_descriptor_current_fd(descriptor);
        owner = descriptor ? descriptor->pfd_owner : NULL;
    } else {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "orig");
        return framework_v_object(NULL);
    }
    /* Reconcile stdio's buffered position with Android's fd-based streams. */
    framework_StreamPayload *stream = descriptor ? descriptor->stream_owner : NULL;
    if (stream && source >= 0 && fflush(stream->fp) != 0) source = -1;
    int fd = -1;
    char host[PATH_CAP] = "";
    if (etd2x_file_contract_host_path && source >= 0)
        (void)etd2x_file_contract_host_path(source, host, sizeof(host));
    if (!host[0] && stream && stream->host_path) framework_copy_text(host, sizeof(host), stream->host_path, "");
    if (!host[0] && owner && owner->host_path) framework_copy_text(host, sizeof(host), owner->host_path, "");
    if (source >= 0) fd = framework_framework_duplicate_fd(source);
    if (fd < 0) {
        const int error = source < 0 ? EBADF : errno;
        ETD2X_LOGCW("FILE", "ParcelFileDescriptor.dup source=%d host=%s failed errno=%d", source, host, error);
        (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", strerror(error));
        return framework_v_object(NULL);
    }
    void *ref = etd2x_jni_new_local_object(env, "android/os/ParcelFileDescriptor");
    framework_ParcelFdPayload *p = ref ? framework_parcel_fd_payload_new(fd, owner ? owner->guest_path : host, host) : NULL;
    if (!p || etd2x_jni_set_object_host_data(ref, p) != ETD2X_OK) {
        if (p) framework_parcel_fd_close_owned(p);
        else { if (etd2x_file_contract_close) etd2x_file_contract_close(fd); close(fd); }
        if (ref) etd2x_jni_delete_local_ref_host(env, ref);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ParcelFileDescriptor");
        return framework_v_object(NULL);
    }
    if (owner) p->host_flags = owner->host_flags;
    else if (stream) p->host_flags = stream->readable ? (stream->writable ? O_RDWR : O_RDONLY) : O_WRONLY;
    else {
#ifndef __SWITCH__
        const int flags = fcntl(source, F_GETFL);
        if (flags >= 0) p->host_flags = flags;
#endif
    }
    ETD2X_LOGCI("FILE", "ParcelFileDescriptor.dup source=%d fd=%d host=%s", source, fd, host);
    return framework_v_object(ref);
}

static Etd2xJniValue framework_parcel_fd_open(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)ud;
    framework_FilePayload *file = n == 2 && args && args[0].l
        ? (framework_FilePayload *)etd2x_jni_get_object_host_data(args[0].l) : NULL;
    if (!file || !file->path) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/FileNotFoundException", "null file");
        return framework_v_object(NULL);
    }
    bool valid_mode = false;
    const int host_flags = framework_pfd_host_open_flags(args[1].i, &valid_mode);
    if (!valid_mode) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "Bad mode");
        return framework_v_object(NULL);
    }
    char mapped[PATH_CAP];
    const char *host = framework_framework_file_host_path(file->path, mapped, sizeof(mapped));
    if (!host) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/FileNotFoundException", file->path);
        return framework_v_object(NULL);
    }
    int fd = (host_flags & O_CREAT) ? open(host, host_flags, 0666) : open(host, host_flags);
    if (fd < 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/FileNotFoundException", file->path);
        return framework_v_object(NULL);
    }
    if (etd2x_file_contract_open)
        etd2x_file_contract_open(fd, file->path, host, 0, host_flags, false);
    void *ref = etd2x_jni_new_local_object(env, "android/os/ParcelFileDescriptor");
    framework_ParcelFdPayload *p = ref ? framework_parcel_fd_payload_new(fd, file->path, host) : NULL;
    if (!ref || !p) {
        if (etd2x_file_contract_close) etd2x_file_contract_close(fd);
        close(fd);
        if (ref) etd2x_jni_delete_local_ref_host(env, ref);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ParcelFileDescriptor");
        return framework_v_object(NULL);
    }
    (void)etd2x_jni_set_object_host_data(ref, p);
    p->host_flags = host_flags;
    ETD2X_LOGCI("ANDROID", "ParcelFileDescriptor.open guest=%s mode=0x%x fd=%d", file->path, args[1].i, fd);
    return framework_v_object(ref);
}

static Etd2xJniValue framework_parcel_fd_parse_mode(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)ud;
    char mode[16];
    if (n != 1 || !args || !framework_read_jstring(args[0].l, mode, sizeof(mode))) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "Bad mode");
        return framework_v_int(0);
    }
    if (strcmp(mode, "r") == 0) return framework_v_int(ETD2X_PFD_MODE_READ_ONLY);
    if (strcmp(mode, "w") == 0 || strcmp(mode, "wt") == 0)
        return framework_v_int(ETD2X_PFD_MODE_WRITE_ONLY | ETD2X_PFD_MODE_CREATE | ETD2X_PFD_MODE_TRUNCATE);
    if (strcmp(mode, "wa") == 0)
        return framework_v_int(ETD2X_PFD_MODE_WRITE_ONLY | ETD2X_PFD_MODE_CREATE | ETD2X_PFD_MODE_APPEND);
    if (strcmp(mode, "rw") == 0)
        return framework_v_int(ETD2X_PFD_MODE_READ_WRITE | ETD2X_PFD_MODE_CREATE);
    if (strcmp(mode, "rwt") == 0)
        return framework_v_int(ETD2X_PFD_MODE_READ_WRITE | ETD2X_PFD_MODE_CREATE | ETD2X_PFD_MODE_TRUNCATE);
    (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "Bad mode");
    return framework_v_int(0);
}

