static Etd2xJniValue framework_input_stream_read_range(void *env, void *token,
                                             const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    framework_StreamPayload *p = framework_stream_payload_from_token(token);
    if (n != 3 || !args || !args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "InputStream.read");
        return framework_v_int(-1);
    }
    const int32_t total = etd2x_jni_byte_array_length(args[0].l);
    const int32_t off = args[1].i, len = args[2].i;
    if (total < 0 || off < 0 || len < 0 || off > total || len > total - off) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IndexOutOfBoundsException", "InputStream.read");
        return framework_v_int(-1);
    }
    if (len == 0) return framework_v_int(0);
    if (!p) {
        /* InputStream's default range read uses the subclass's read(). Only
         * an IOException after the first byte is treated as a short read. */
        void *self = etd2x_jni_new_local_from_token(env, token);
        int32_t got = 0;
        while (self && got < len) {
            Etd2xJniValue byte = {0};
            bool read_ok = framework_java_call_virtual(env, self, "read", "()I", NULL, 0, &byte);
            if (!read_ok || etd2x_jni_exception_pending_host(env)) {
                void *error = etd2x_jni_exception_occurred_host(env);
                if (got && error && etd2x_jni_is_instance_of_class_host(error, "java/io/IOException"))
                    etd2x_jni_exception_clear_host(env);
                if (error) etd2x_jni_delete_local_ref_host(env, error);
                break;
            }
            if (byte.i < 0) break;
            if (etd2x_jni_primitive_array_set_host(args[0].l, 'B', off + got, (uint8_t)byte.i) != ETD2X_OK) break;
            ++got;
        }
        if (self) etd2x_jni_delete_local_ref_host(env, self);
        return framework_v_int(got ? got : -1);
    }
    if (p->closed || !p->readable || !p->fp) {
        (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", "Stream closed or not readable");
        return framework_v_int(-1);
    }
    int8_t *buf = malloc((size_t)len);
    if (!buf) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "InputStream.read"); return framework_v_int(-1); }
    const size_t got = fread(buf, 1, (size_t)len, p->fp);
    if (got && etd2x_jni_byte_array_write(args[0].l, off, (int32_t)got, buf) != ETD2X_OK) {
        free(buf); return framework_v_int(-1);
    }
    free(buf);
    if (got == 0) {
        if (ferror(p->fp)) {
            clearerr(p->fp);
            (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", "InputStream.read failed");
        }
        return framework_v_int(-1);
    }
    return framework_v_int((int32_t)got);
}

