static Etd2xJniValue framework_bundle_put_all(void *env,void*token,const Etd2xJniValue*args,size_t n,void*ud){
    (void)env;(void)ud;
    framework_BundlePayload *dst=framework_bundle_payload_ensure(token);
    if(!dst||n!=1||!args||!args[0].l)return framework_v_void();
    void *src_token=etd2x_jni_object_token_host(args[0].l);
    framework_BundlePayload *src=src_token?framework_bundle_payload(src_token):NULL;
    if(!src)return framework_v_void();
    for(const framework_AndroidMapValue*v=src->map.values;v;v=v->next){
        switch(v->type){
            case ANDROID_MAP_STRING:(void)framework_android_map_set_string(&dst->map,v->key,v->v.s);break;
            case ANDROID_MAP_INT:(void)framework_android_map_set_int(&dst->map,v->key,v->v.i);break;
            case ANDROID_MAP_LONG:(void)framework_android_map_set_long(&dst->map,v->key,v->v.j);break;
            case ANDROID_MAP_FLOAT:(void)framework_android_map_set_float(&dst->map,v->key,v->v.f);break;
            case ANDROID_MAP_BOOL:(void)framework_android_map_set_bool(&dst->map,v->key,v->v.z);break;
            case ANDROID_MAP_OBJECT:(void)framework_android_map_set_object(&dst->map,v->key,v->v.o);break;
            default:break;
        }
    }
    return framework_v_void();
}
