static framework_IntentPayload *framework_intent_payload(void *token) {
    return (framework_IntentPayload *)etd2x_jni_get_token_host_data(token);
}

static framework_IntentPayload *framework_intent_payload_new(void *token, const char *action) {
    if (!token) return NULL;
    framework_IntentPayload *p = calloc(1, sizeof(*p));
    if (!p) return NULL;
    if (action && action[0]) {
        p->action = strdup(action);
        if (!p->action) { free(p); return NULL; }
    }
    p->next = framework_g_fw.intents;
    framework_g_fw.intents = p;
    (void)etd2x_jni_set_token_host_data(token, p);
    return p;
}

static framework_BundlePayload *framework_intent_ensure_extras(framework_IntentPayload *intent) {
    if (!intent) return NULL;
    if (intent->extras) return intent->extras;
    void *global = framework_make_global_object("android/os/Bundle");
    if (!global) return NULL;
    void *token = etd2x_jni_object_token_host(global);
    framework_BundlePayload *bundle = framework_bundle_payload_new(token);
    if (!bundle) {
        etd2x_jni_delete_global_ref_host(etd2x_jni_current_env(), global);
        return NULL;
    }
    intent->extras = bundle;
    intent->extras_global = global;
    return bundle;
}

static Etd2xJniValue framework_intent_ctor_empty(void *env, void *token, const Etd2xJniValue *args,
                                       size_t n, void *ud) {
    (void)env; (void)args; (void)ud;
    if (n == 0 && !framework_intent_payload(token)) (void)framework_intent_payload_new(token, NULL);
    return framework_v_void();
}

static Etd2xJniValue framework_intent_ctor_action(void *env, void *token, const Etd2xJniValue *args,
                                        size_t n, void *ud) {
    (void)env; (void)ud;
    char action[TEXT_CAP]; action[0] = '\0';
    if (n == 1 && framework_read_jstring(args[0].l, action, sizeof(action))) {
        framework_IntentPayload *p = framework_intent_payload(token);
        if (!p) p = framework_intent_payload_new(token, action);
        else { free(p->action); p->action = strdup(action); }
    }
    return framework_v_void();
}

static Etd2xJniValue framework_intent_ctor_context_class(void *env, void *token, const Etd2xJniValue *args,
                                               size_t n, void *ud) {
    (void)env; (void)ud;
    if (n != 2 || !args || !args[1].l) return framework_v_void();
    char class_name[512];
    if (!etd2x_jni_class_ref_name_host(args[1].l, class_name, sizeof(class_name))) return framework_v_void();
    framework_IntentPayload *p = framework_intent_payload(token);
    if (!p) p = framework_intent_payload_new(token, NULL);
    if (!p) return framework_v_void();
    char *copy = strdup(class_name);
    if (copy) { free(p->target_class); p->target_class = copy; }
    return framework_v_void();
}

