static Etd2xJniValue framework_intent_set_action(void *env, void *token, const Etd2xJniValue *args,
                                       size_t n, void *ud) {
    (void)ud;
    char action[TEXT_CAP];
    framework_IntentPayload *p = framework_intent_payload(token);
    if (!p) p = framework_intent_payload_new(token, NULL);
    if (p && n == 1) {
        if (!args[0].l) { free(p->action); p->action = NULL; }
        else if (framework_read_jstring(args[0].l, action, sizeof(action))) {
            char *copy = strdup(action);
            if (copy) { free(p->action); p->action = copy; }
        }
    }
    return framework_v_object(etd2x_jni_new_local_from_token(env, token));
}

static Etd2xJniValue framework_intent_set_package(void *env, void *token, const Etd2xJniValue *args,
                                        size_t n, void *ud) {
    (void)ud;
    framework_IntentPayload *p = framework_intent_payload(token);
    if (!p) p = framework_intent_payload_new(token, NULL);
    if (!p || n != 1) return framework_v_object(etd2x_jni_new_local_from_token(env, token));
    if (!args[0].l) {
        free(p->package_name);
        p->package_name = NULL;
        return framework_v_object(etd2x_jni_new_local_from_token(env, token));
    }
    char package_name[TEXT_CAP];
    if (framework_read_jstring(args[0].l, package_name, sizeof(package_name))) {
        char *copy = strdup(package_name);
        if (copy) { free(p->package_name); p->package_name = copy; }
    }
    return framework_v_object(etd2x_jni_new_local_from_token(env, token));
}

