static framework_BroadcastRegistration *framework_broadcast_registration_find(void *receiver_ref,
                                                           framework_BroadcastRegistration ***out_link) {
    framework_BroadcastRegistration **link = &framework_g_fw.broadcast_registrations;
    while (*link) {
        if (etd2x_jni_same_object_host((*link)->receiver_global, receiver_ref)) {
            if (out_link) *out_link = link;
            return *link;
        }
        link = &(*link)->next;
    }
    if (out_link) *out_link = link;
    return NULL;
}

static Etd2xJniValue framework_context_register_receiver(void *env, void *token, const Etd2xJniValue *args,
                                                size_t n, void *ud) {
    (void)token; (void)ud;
    if ((n != 2 && n != 3) || !args[0].l || !args[1].l) return framework_v_object(NULL);
    if (n == 3 && (args[2].i & 2) != 0 && (args[2].i & 4) != 0) {
        etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException",
                                    "RECEIVER_EXPORTED and RECEIVER_NOT_EXPORTED are mutually exclusive");
        return framework_v_object(NULL);
    }
    framework_IntentFilterPayload *filter = (framework_IntentFilterPayload *)etd2x_jni_get_object_host_data(args[1].l);
    if (!filter) return framework_v_object(NULL);
    framework_BroadcastRegistration *registration = framework_broadcast_registration_find(args[0].l, NULL);
    if (!registration) {
        registration = calloc(1, sizeof(*registration));
        if (!registration) return framework_v_object(NULL);
        registration->receiver_global = etd2x_jni_new_global_ref_host(env, args[0].l);
        registration->filter_global = etd2x_jni_new_global_ref_host(env, args[1].l);
        if (!registration->receiver_global || !registration->filter_global) {
            if (registration->receiver_global) etd2x_jni_delete_global_ref_host(env, registration->receiver_global);
            if (registration->filter_global) etd2x_jni_delete_global_ref_host(env, registration->filter_global);
            free(registration);
            return framework_v_object(NULL);
        }
        registration->next = framework_g_fw.broadcast_registrations;
        framework_g_fw.broadcast_registrations = registration;
    } else {
        if (registration->filter_global) etd2x_jni_delete_global_ref_host(env, registration->filter_global);
        registration->filter_global = etd2x_jni_new_global_ref_host(env, args[1].l);
        if (!registration->filter_global) return framework_v_object(NULL);
    }
    registration->flags = n == 3 ? args[2].i : 0;
    ETD2X_LOGCI("ANDROID", "registerReceiver receiver=present actions=%zu categories=%zu flags=%d sticky=none",
                filter->action_count, filter->category_count, registration->flags);
    /* ETD2X has no Android system broadcast service. The registration itself
       is retained accurately so lifecycle/unregister semantics are observable;
       there is no sticky broadcast to return. */
    return framework_v_object(NULL);
}

static Etd2xJniValue framework_context_unregister_receiver(void *env, void *token, const Etd2xJniValue *args,
                                                  size_t n, void *ud) {
    (void)token; (void)ud;
    if (n != 1 || !args[0].l) {
        etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException",
                                    "Receiver not registered");
        return framework_v_void();
    }
    framework_BroadcastRegistration **link = NULL;
    framework_BroadcastRegistration *registration = framework_broadcast_registration_find(args[0].l, &link);
    if (!registration || !link) {
        etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException",
                                    "Receiver not registered");
        return framework_v_void();
    }
    *link = registration->next;
    etd2x_jni_delete_global_ref_host(env, registration->receiver_global);
    etd2x_jni_delete_global_ref_host(env, registration->filter_global);
    free(registration);
    ETD2X_LOGCI("ANDROID", "unregisterReceiver receiver=present result=removed");
    return framework_v_void();
}

