/* ---------- Preferences ---------- */
static void framework_free_pref_value(framework_PrefValue *v) {
    if (!v) return;
    free(v->key);
    if (v->type == PREF_STRING) free(v->v.s);
    if (v->type == PREF_STRING_SET) {
        for (size_t i = 0; i < v->v.set.count; ++i) free(v->v.set.items[i]);
        free(v->v.set.items);
    }
    free(v);
}
static framework_PrefValue *framework_pref_find(framework_PrefValue *head, const char *key) { for (framework_PrefValue *v=head;v;v=v->next) if(strcmp(v->key,key)==0) return v; return NULL; }
static void framework_pref_remove(framework_PrefValue **head, const char *key) {
    for (framework_PrefValue **p=head; *p; p=&(*p)->next) if(strcmp((*p)->key,key)==0){ framework_PrefValue *d=*p; *p=d->next; framework_free_pref_value(d); return; }
}
static framework_PrefValue *framework_pref_make(const char *key, framework_PrefType type) {
    framework_PrefValue *v=calloc(1,sizeof(*v)); if(!v) return NULL; v->key=strdup(key?key:""); if(!v->key){free(v);return NULL;} v->type=type; return v;
}
static void framework_pref_set(framework_PrefValue **head, framework_PrefValue *value) {
    if (!head || !value) {
        return;
    }
    framework_pref_remove(head, value->key);
    value->next = *head;
    *head = value;
}
static void framework_pref_free_list(framework_PrefValue *v){ while(v){framework_PrefValue*n=v->next;framework_free_pref_value(v);v=n;} }

static void framework_pref_escape(FILE *f, const char *s) {
    for (const unsigned char *p=(const unsigned char *)(s?s:""); *p; ++p) {
        if (*p=='\\') fputs("\\\\",f); else if(*p=='\t') fputs("\\t",f); else if(*p=='\n') fputs("\\n",f); else if(*p=='\r') fputs("\\r",f); else fputc(*p,f);
    }
}
static char *framework_pref_unescape(const char *s) {
    size_t n=strlen(s); char*out=malloc(n+1); if(!out)return NULL; size_t w=0;
    for(size_t i=0;i<n;i++){ if(s[i]=='\\'&&i+1<n){ char c=s[++i]; out[w++]=c=='t'?'\t':c=='n'?'\n':c=='r'?'\r':c; } else out[w++]=s[i]; } out[w]='\0'; return out;
}
static int framework_pref_set_item_compare(const void *a, const void *b) {
    const char *x = *(char *const *)a, *y = *(char *const *)b;
    return x && y ? strcmp(x, y) : x ? 1 : y ? -1 : 0;
}
static bool framework_pref_copy_set(framework_PrefValue *dst, const framework_PrefValue *src) {
    dst->v.set.items = calloc(src->v.set.count ? src->v.set.count : 1u, sizeof(char *));
    if (!dst->v.set.items) return false;
    dst->v.set.count = src->v.set.count;
    for (size_t i = 0; i < src->v.set.count; ++i) {
        if (!src->v.set.items[i]) continue;
        dst->v.set.items[i] = strdup(src->v.set.items[i]);
        if (!dst->v.set.items[i]) return false;
    }
    return true;
}
/* T records extend the existing escaped text format with a count and tab-
 * separated s<string>/n(null) entries; empty sets and empty strings differ. */
static bool framework_pref_parse_set(framework_PrefValue *v, char *text) {
    char *end = NULL;
    const unsigned long long count = strtoull(text, &end, 10);
    if (end == text || count > strlen(text) || (*end && *end != '\t')) return false;
    v->v.set.items = calloc(count ? (size_t)count : 1u, sizeof(char *));
    if (!v->v.set.items) return false;
    v->v.set.count = (size_t)count;
    for (size_t i = 0; i < v->v.set.count; ++i) {
        if (*end != '\t') return false;
        char *item = end + 1;
        char *separator = strchr(item, '\t');
        end = separator ? separator : item + strlen(item);
        if (separator) *separator = '\0';
        if (*item == 's') {
            v->v.set.items[i] = framework_pref_unescape(item + 1);
            if (!v->v.set.items[i]) return false;
        } else if (*item != 'n' || item[1]) return false;
        if (separator) *separator = '\t';
    }
    if (*end) return false;
    qsort(v->v.set.items, v->v.set.count, sizeof(char *), framework_pref_set_item_compare);
    return true;
}
static bool framework_pref_read_line(FILE *f, char **line, size_t *capacity) {
    size_t used = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (used + 1 >= *capacity) {
            if (*capacity > SIZE_MAX / 2u) return false;
            const size_t next = *capacity ? *capacity * 2u : 1024u;
            char *grown = realloc(*line, next);
            if (!grown) return false;
            *line = grown; *capacity = next;
        }
        if (c == '\n') break;
        (*line)[used++] = (char)c;
    }
    if (c == EOF && !used) return false;
    if (!*line) { *line = calloc(1, 1); if (!*line) return false; *capacity = 1; }
    (*line)[used] = '\0';
    return true;
}
static void *framework_pref_set_to_java(void *env, const framework_PrefValue *v) {
    void *set = etd2x_jni_new_local_object(env, "java/util/HashSet");
    for (size_t i = 0; set && i < v->v.set.count; ++i) {
        Etd2xJniValue item = {.l = v->v.set.items[i] ? framework_new_string(env, v->v.set.items[i]) : NULL}, out = {0};
        const bool ok = (!v->v.set.items[i] || item.l) &&
            etd2x_android_call_virtual(env, set, "add", "(Ljava/lang/Object;)Z", &item, 1, &out);
        if (item.l) etd2x_jni_delete_local_ref_host(env, item.l);
        if (!ok) { etd2x_jni_delete_local_ref_host(env, set); return NULL; }
    }
    return set;
}
static bool framework_framework_replace_file(const char *tmp_path, const char *final_path) {
    if (!tmp_path || !final_path) return false;
    if (rename(tmp_path, final_path) == 0) {
        etd2x_android_file_observer_notify_move(tmp_path, final_path);
        return true;
    }
    if (errno != EEXIST && errno != ENOTEMPTY) return false;

    struct stat dst;
    if (lstat(final_path, &dst) == 0) {
        if (S_ISDIR(dst.st_mode)) return false;
    } else if (errno != ENOENT) {
        return false;
    }

    char backup[PATH_CAP];
    if (snprintf(backup, sizeof(backup), "%s.bak", final_path) >= (int)sizeof(backup))
        return false;
    (void)remove(backup);
    const bool had_old = rename(final_path, backup) == 0;
    if (!had_old && errno != ENOENT) return false;
    if (rename(tmp_path, final_path) == 0) {
        if (had_old) (void)remove(backup);
        etd2x_android_file_observer_notify_move(tmp_path, final_path);
        return true;
    }
    const int saved = errno;
    if (had_old) (void)rename(backup, final_path);
    if (etd2x_path_lookup_changed) etd2x_path_lookup_changed(final_path);
    errno = saved;
    return false;
}

/* Store contents in the on-disk format; the caller holds g_prefs_lock. */
static char *framework_pref_serialize_locked(const framework_PrefStore *store, size_t *out_len) {
    char *buffer = NULL;
    size_t length = 0;
    FILE *f = store ? open_memstream(&buffer, &length) : NULL;
    if (!f) return NULL;
    for(framework_PrefValue*v=store->values;v;v=v->next){ fputc((char)v->type,f); fputc('\t',f); framework_pref_escape(f,v->key); fputc('\t',f);
        switch(v->type){case PREF_STRING:framework_pref_escape(f,v->v.s);break;case PREF_INT:fprintf(f,"%d",v->v.i);break;case PREF_LONG:fprintf(f,"%lld",(long long)v->v.j);break;case PREF_FLOAT:fprintf(f,"%.9g",(double)v->v.f);break;case PREF_BOOL:fputc(v->v.z?'1':'0',f);break;
            case PREF_STRING_SET:
                fprintf(f,"%zu",v->v.set.count);
                for(size_t i=0;i<v->v.set.count;++i){fputc('\t',f);fputc(v->v.set.items[i]?'s':'n',f);if(v->v.set.items[i])framework_pref_escape(f,v->v.set.items[i]);}
                break;
            default:break;} fputc('\n',f); }
    const bool ok = !ferror(f);
    if (fclose(f) != 0 || !ok) { free(buffer); return NULL; }
    *out_len = length;
    return buffer;
}

/* Durable replace: temp file, fsync, rename (no preference lock held). */
static bool framework_pref_write_file(const char *path, const char *data, size_t length) {
    char tmp_path[PATH_CAP];
    if (snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", path) >= (int)sizeof(tmp_path))
        return false;
    (void)remove(tmp_path);
    FILE *f = fopen(tmp_path, "wb");
    if (!f) return false;
    bool ok = (length == 0 || fwrite(data, 1, length, f) == length) && fflush(f) == 0;
    if (ok) {
        const int fd = fileno(f);
        ok = fd >= 0 && fsync(fd) == 0;
    }
    if (fclose(f) != 0) ok = false;
    if (!ok) { (void)remove(tmp_path); return false; }
    if (!framework_framework_replace_file(tmp_path, path)) {
        (void)remove(tmp_path);
        return false;
    }
    return true;
}

/* pref write queue */
/* SharedPreferences.Editor.apply: publish memory immediately, write immutable
 * snapshots on one worker. commit waits for its own write and all preceding
 * applies. Queue insertion occurs under g_prefs_lock, preserving memory order;
 * filesystem I/O never runs under either the memory or queue lock. */
typedef struct framework_PrefWrite {
    char path[PATH_CAP];
    char *data;
    size_t length;
    bool wait, done, ok;
    struct framework_PrefWrite *next;
} framework_PrefWrite;

static pthread_mutex_t framework_g_pref_queue_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t framework_g_pref_queue_cond = PTHREAD_COND_INITIALIZER;
static framework_PrefWrite *framework_g_pref_queue_head, *framework_g_pref_queue_tail;
static pthread_t framework_g_pref_worker;
static bool framework_g_pref_worker_started, framework_g_pref_worker_stopping;

static void *framework_pref_write_worker(void *unused) {
    (void)unused;
    pthread_mutex_lock(&framework_g_pref_queue_lock);
    for (;;) {
        while (!framework_g_pref_queue_head && !framework_g_pref_worker_stopping)
            pthread_cond_wait(&framework_g_pref_queue_cond, &framework_g_pref_queue_lock);
        if (!framework_g_pref_queue_head) break;
        framework_PrefWrite *job = framework_g_pref_queue_head;
        framework_g_pref_queue_head = job->next;
        if (!framework_g_pref_queue_head) framework_g_pref_queue_tail = NULL;
        pthread_mutex_unlock(&framework_g_pref_queue_lock);
        const bool ok = framework_pref_write_file(job->path, job->data, job->length);
        if (!ok) ETD2X_LOGCW("ANDROID", "SharedPreferences disk write failed errno=%d", errno);
        free(job->data);
        pthread_mutex_lock(&framework_g_pref_queue_lock);
        if (job->wait) {
            job->data = NULL;
            job->ok = ok;
            job->done = true;
            pthread_cond_broadcast(&framework_g_pref_queue_cond);
        } else free(job);
    }
    pthread_mutex_unlock(&framework_g_pref_queue_lock);
    return NULL;
}

/* Takes ownership of data on success. Async callers receive a boolean via
 * out_queued, because their job can be completed/freed before this returns. */
static framework_PrefWrite *framework_pref_enqueue_write(const char *path, char *data, size_t length,
                                    bool wait, bool *out_queued) {
    *out_queued = false;
    framework_PrefWrite *job = calloc(1, sizeof(*job));
    if (!job) return NULL;
    snprintf(job->path, sizeof(job->path), "%s", path);
    job->data = data; job->length = length; job->wait = wait;
    pthread_mutex_lock(&framework_g_pref_queue_lock);
    if (framework_g_pref_worker_stopping) goto failed;
    if (!framework_g_pref_worker_started) {
        pthread_attr_t attr;
        int rc = pthread_attr_init(&attr);
        if (rc != 0) goto failed;
        rc = pthread_attr_setstacksize(&attr, 128u * 1024u);
        if (rc == 0) rc = pthread_create(&framework_g_pref_worker, &attr, framework_pref_write_worker, NULL);
        pthread_attr_destroy(&attr);
        if (rc != 0) goto failed;
        framework_g_pref_worker_started = true;
    }
    /* Only the adjacent pending async snapshot can be replaced: never move a
     * newer value ahead of an intervening synchronous commit. */
    if (!wait && framework_g_pref_queue_tail && !framework_g_pref_queue_tail->wait &&
        strcmp(framework_g_pref_queue_tail->path, path) == 0) {
        free(framework_g_pref_queue_tail->data);
        framework_g_pref_queue_tail->data = data;
        framework_g_pref_queue_tail->length = length;
        free(job);
        job = NULL;
    } else {
        if (framework_g_pref_queue_tail) framework_g_pref_queue_tail->next = job;
        else framework_g_pref_queue_head = job;
        framework_g_pref_queue_tail = job;
    }
    *out_queued = true;
    pthread_cond_broadcast(&framework_g_pref_queue_cond);
    pthread_mutex_unlock(&framework_g_pref_queue_lock);
    return wait ? job : NULL;
failed:
    pthread_mutex_unlock(&framework_g_pref_queue_lock);
    free(job); /* caller still owns data */
    return NULL;
}

static bool framework_pref_wait_write(framework_PrefWrite *job) {
    if (!job) return false;
    pthread_mutex_lock(&framework_g_pref_queue_lock);
    while (!job->done) pthread_cond_wait(&framework_g_pref_queue_cond, &framework_g_pref_queue_lock);
    const bool ok = job->ok;
    pthread_mutex_unlock(&framework_g_pref_queue_lock);
    free(job);
    return ok;
}

/* Finish pending applies before application storage/observers are torn down. */
static void framework_pref_write_queue_reset(void) {
    pthread_mutex_lock(&framework_g_pref_queue_lock);
    const bool started = framework_g_pref_worker_started;
    framework_g_pref_worker_stopping = true;
    pthread_cond_broadcast(&framework_g_pref_queue_cond);
    pthread_mutex_unlock(&framework_g_pref_queue_lock);
    if (started) pthread_join(framework_g_pref_worker, NULL);
    pthread_mutex_lock(&framework_g_pref_queue_lock);
    framework_g_pref_worker_started = framework_g_pref_worker_stopping = false;
    pthread_mutex_unlock(&framework_g_pref_queue_lock);
}


static void framework_pref_load(framework_PrefStore *store) {
    FILE*f=fopen(store->path,"rb"); if(!f)return; char *line=NULL;size_t capacity=0;
    while(framework_pref_read_line(f,&line,&capacity)){ size_t n=strlen(line); while(n&&(line[n-1]=='\n'||line[n-1]=='\r'))line[--n]='\0';
        if (n < 3 || line[1] != '\t') {
            continue;
        }
        char *second = strchr(line + 2, '\t');
        if (!second) {
            continue;
        }
        *second = '\0';
        char*key=framework_pref_unescape(line+2);
        if(line[0]==PREF_STRING_SET){
            framework_PrefValue *v=key?framework_pref_make(key,PREF_STRING_SET):NULL;
            if(v&&framework_pref_parse_set(v,second+1))framework_pref_set(&store->values,v);else framework_free_pref_value(v);
            free(key);continue;
        }
        char*value=framework_pref_unescape(second+1); if(!key||!value){free(key);free(value);continue;}
        framework_PrefValue*v=framework_pref_make(key,(framework_PrefType)line[0]); if(v){ switch(v->type){case PREF_STRING:v->v.s=strdup(value);break;case PREF_INT:v->v.i=(int32_t)strtol(value,NULL,10);break;case PREF_LONG:v->v.j=(int64_t)strtoll(value,NULL,10);break;case PREF_FLOAT:v->v.f=strtof(value,NULL);break;case PREF_BOOL:v->v.z=value[0]=='1';break;default:framework_free_pref_value(v);v=NULL;break;} if(v)framework_pref_set(&store->values,v); }
        free(key);free(value);
    } free(line);fclose(f);
}
static framework_PrefStore *framework_pref_store_from_token(void *token){ return (framework_PrefStore*)etd2x_jni_get_token_host_data(token); }
static framework_PrefEditor *framework_pref_editor_from_token(void *token){ return (framework_PrefEditor*)etd2x_jni_get_token_host_data(token); }
/* Creating a store reads its file from storage. Creators serialize on
 * g_prefs_create_lock and load before publishing, so g_prefs_lock (taken by
 * every preference read/write) is never held across that I/O. */
static pthread_mutex_t framework_g_prefs_create_lock = PTHREAD_MUTEX_INITIALIZER;
static framework_PrefStore *framework_pref_store_find(const char *name){
    ETD2X_PERF_LOCK(&framework_g_prefs_lock);
    framework_PrefStore*found=NULL;
    for(framework_PrefStore*s=framework_g_fw.prefs;s&&!found;s=s->next)if(strcmp(s->name,name)==0)found=s;
    pthread_mutex_unlock(&framework_g_prefs_lock);
    return found;
}
static framework_PrefStore *framework_pref_store_get(const char *name){
    framework_PrefStore*existing=framework_pref_store_find(name);
    if(existing)return existing;
    pthread_mutex_lock(&framework_g_prefs_create_lock);
    existing=framework_pref_store_find(name);
    if(existing){pthread_mutex_unlock(&framework_g_prefs_create_lock);return existing;}
    framework_PrefStore*s=calloc(1,sizeof(*s));
    if(!s){pthread_mutex_unlock(&framework_g_prefs_create_lock);return NULL;}
    s->name=strdup(name);
    if(!s->name){free(s);pthread_mutex_unlock(&framework_g_prefs_create_lock);return NULL;}
    char leaf[256]; snprintf(leaf,sizeof(leaf),"%s.prefs",name);
    if(!framework_join_path(s->path,sizeof(s->path),framework_g_fw.prefs_dir,leaf)){free(s->name);free(s);pthread_mutex_unlock(&framework_g_prefs_create_lock);return NULL;}
    s->global_ref=framework_make_global_object("android/content/SharedPreferences");
    if(!s->global_ref){free(s->name);free(s);pthread_mutex_unlock(&framework_g_prefs_create_lock);return NULL;}
    framework_set_host_data_global(s->global_ref,s); framework_pref_load(s);
    ETD2X_PERF_LOCK(&framework_g_prefs_lock);
    s->next=framework_g_fw.prefs;framework_g_fw.prefs=s;
    pthread_mutex_unlock(&framework_g_prefs_lock);
    pthread_mutex_unlock(&framework_g_prefs_create_lock);
    return s;
}
static framework_PrefValue *framework_editor_value(framework_PrefEditor *e,const char*key,framework_PrefType type){ framework_PrefValue*v=framework_pref_make(key,type); if(v)framework_pref_set(&e->pending,v); return v; }
/* Delivers OnSharedPreferenceChangeListener callbacks; takes ownership of
 * keys and listener global refs (framework/io_net_extras.inc). */
static void framework_prefs_notify_changes(void *env, framework_PrefStore *s, char **keys, size_t key_count, bool cleared,
                                 void **listeners, size_t listener_count);
static bool framework_pref_value_equal(const framework_PrefValue *a, const framework_PrefValue *b) {
    if (!a || !b || a->type != b->type) return false;
    switch (a->type) {
        case PREF_STRING: return strcmp(a->v.s ? a->v.s : "", b->v.s ? b->v.s : "") == 0;
        case PREF_STRING_SET:
            if(a->v.set.count!=b->v.set.count)return false;
            for(size_t i=0;i<a->v.set.count;++i)if(framework_pref_set_item_compare(&a->v.set.items[i],&b->v.set.items[i]))return false;
            return true;
        case PREF_INT: return a->v.i == b->v.i;
        case PREF_LONG: return a->v.j == b->v.j;
        case PREF_FLOAT: return memcmp(&a->v.f, &b->v.f, sizeof(float)) == 0; /* Float.equals */
        case PREF_BOOL: return a->v.z == b->v.z;
        default: return false;
    }
}
/* SharedPreferencesImpl.EditorImpl.commitToMemory: clear() first, then each
 * pending change; only keys whose value actually changed are reported. */
static bool framework_editor_apply(void *env, framework_PrefEditor *e, bool wait_for_disk){
    if(!e||!e->store)return false;
    char **keys=NULL; size_t key_count=0, key_cap=0;
    void **listeners=NULL; size_t listener_count=0;
    bool cleared=false;
    bool memory_ok=true;
    ETD2X_PERF_LOCK(&framework_g_prefs_lock);
    framework_PrefStore *s=e->store;
    const bool track=s->listener_count>0;
    if(e->clear_all){framework_pref_free_list(s->values);s->values=NULL;cleared=true;}
    for(framework_PrefValue*v=e->pending;v;v=v->next){
        framework_PrefValue *old=framework_pref_find(s->values,v->key);
        if(v->type==PREF_REMOVE){
            if(!old)continue;
            framework_pref_remove(&s->values,v->key);
        } else {
            if(old&&framework_pref_value_equal(old,v))continue;
            framework_PrefValue*c=framework_pref_make(v->key,v->type);if(!c){memory_ok=false;continue;}
            if(v->type==PREF_STRING_SET){if(!framework_pref_copy_set(c,v)){framework_free_pref_value(c);memory_ok=false;continue;}}
            else {c->v=v->v;if(v->type==PREF_STRING){c->v.s=strdup(v->v.s?v->v.s:"");if(!c->v.s){framework_free_pref_value(c);memory_ok=false;continue;}}}
            framework_pref_set(&s->values,c);
        }
        if(track){
            if(key_count==key_cap){
                const size_t cap=key_cap?key_cap*2:8;
                char **grown=realloc(keys,cap*sizeof(*keys));
                if(!grown)continue;
                keys=grown;key_cap=cap;
            }
            keys[key_count]=strdup(v->key);
            if(keys[key_count])key_count++;
        }
    }
    if(track&&(key_count||cleared)){
        listeners=calloc(s->listener_count,sizeof(*listeners));
        for(size_t i=0;listeners&&i<s->listener_count;++i)
            if(s->listeners[i])listeners[listener_count++]=etd2x_jni_new_global_ref_host(env,s->listeners[i]);
    }
    /* Serialize under the lock; the slow durable write (fsync on the SD card)
     * runs without it so other preference reads and writes are not blocked. */
    size_t data_length=0;
    char *data=framework_pref_serialize_locked(s,&data_length);
    char path[PATH_CAP];
    snprintf(path,sizeof(path),"%s",s->path);
    if(memory_ok){framework_pref_free_list(e->pending);e->pending=NULL;e->clear_all=false;}
    bool queued=false;
    framework_PrefWrite *job=data?framework_pref_enqueue_write(path,data,data_length,wait_for_disk,&queued):NULL;
    pthread_mutex_unlock(&framework_g_prefs_lock);
    if(!queued){free(data);ETD2X_LOGCW("ANDROID","SharedPreferences could not enqueue disk write");}
    /* Wait even if memory allocation failed: this job still owns a snapshot. */
    const bool disk_ok=wait_for_disk?framework_pref_wait_write(job):queued;
    bool ok=disk_ok&&memory_ok;
    if(track)framework_prefs_notify_changes(env,s,keys,key_count,cleared,listeners,listener_count);
    return ok;
}

