static Etd2xJniValue framework_cb_private_path_file(void *env, const char *suffix){char path[PATH_CAP],mapped[PATH_CAP];if(!framework_framework_private_guest_path(path,sizeof(path),suffix))return framework_v_object(NULL);const char*host=framework_framework_file_host_path(path,mapped,sizeof(mapped));if(!host||!framework_mkdirs(host))return framework_v_object(NULL);return framework_v_object(framework_new_file(env,path));}
