static bool framework_external_type_leaf(void *string_ref, char *out, size_t cap) {
    if (!out || cap == 0) return false;
    out[0] = '\0';
    if (!string_ref) return true;
    if (!framework_read_jstring(string_ref, out, cap)) return false;
    if (!out[0]) return true;
    if (strcmp(out, ".") == 0 || strcmp(out, "..") == 0 || strchr(out, '/') || strchr(out, '\\'))
        return false;
    return true;
}
static void *framework_single_file_array(void *env, void *file) {
    void *array = etd2x_jni_new_local_object_array(env, 1);
    if (!array) return NULL;
    if (file && etd2x_jni_set_object_array_element_host(env, array, 0, file) != ETD2X_OK) {
        etd2x_jni_delete_local_ref_host(env, array);
        return NULL;
    }
    return array;
}
static bool framework_context_file_stream_guest_path(void *env, void *name_ref, char *out, size_t cap) {
    char name[TEXT_CAP];
    if (!name_ref || !framework_read_jstring(name_ref, name, sizeof(name))) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "name");
        return false;
    }
    char base[PATH_CAP];
    if (!framework_framework_private_guest_path(base, sizeof(base), "files")) return false;
    if (!etd2x_context_stream_path(base, name, out, cap)) {
        char message[TEXT_CAP + 48];
        snprintf(message, sizeof(message), "File %s contains a path separator", name);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", message);
        return false;
    }
    return true;
}

