static Etd2xJniValue framework_network_capabilities_has_capability(void *env, void *token,
                                                          const Etd2xJniValue *args,
                                                          size_t n, void *ud) {
    (void)env; (void)token; (void)ud;
    if (n != 1 || !framework_framework_network_is_available()) return framework_v_bool(false);
    /* Android constants used to describe an ordinary validated Internet
     * network. NIFM Connected is the host's authoritative Internet state. */
    switch (args[0].i) {
        case 12: /* NET_CAPABILITY_INTERNET */
        case 13: /* NET_CAPABILITY_NOT_RESTRICTED */
        case 14: /* NET_CAPABILITY_TRUSTED */
        case 15: /* NET_CAPABILITY_NOT_VPN */
        case 16: /* NET_CAPABILITY_VALIDATED */
        case 21: /* NET_CAPABILITY_NOT_SUSPENDED */
            return framework_v_bool(true);
        default:
            return framework_v_bool(false);
    }
}

/* Android platform trust-store bridge. Native BSD/TLS already exports the
 * Switch firmware roots; Android Java clients discover
 * the same roots through TrustManagerFactory/X509TrustManager. Verification
 * remains in the guest TLS stack: ETD2X supplies trust anchors only. */
static Etd2xJniValue framework_trust_manager_factory_default_algorithm(void *env, void *token,
                                                              const Etd2xJniValue *args,
                                                              size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    return framework_v_object(n == 0 ? framework_new_string(env, "PKIX") : NULL);
}

static Etd2xJniValue framework_trust_manager_factory_get_instance(void *env, void *token,
                                                         const Etd2xJniValue *args,
                                                         size_t n, void *ud) {
    (void)token; (void)ud;
    char algorithm[64];
    if (n != 1 || !args[0].l || !framework_read_jstring(args[0].l, algorithm, sizeof(algorithm))) {
        (void)etd2x_jni_throw_new_by_name(env, "java/security/NoSuchAlgorithmException",
                                           "TrustManagerFactory algorithm");
        return framework_v_object(NULL);
    }
    if (strcmp(algorithm, "PKIX") != 0 && strcmp(algorithm, "X509") != 0 &&
        strcmp(algorithm, "SunX509") != 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/security/NoSuchAlgorithmException", algorithm);
        return framework_v_object(NULL);
    }
    return framework_v_object(etd2x_jni_new_local_object(env, "javax/net/ssl/TrustManagerFactory"));
}

/* Factory and trust-manager host data: TMF_PLATFORM for the platform roots,
 * otherwise a global reference to the app KeyStore the factory was
 * initialized with (kept for the process; factories are few). */
#define TMF_PLATFORM ((void *)(uintptr_t)1u)
