static Etd2xJniValue framework_trust_manager_factory_init(void *env, void *token,
                                                 const Etd2xJniValue *args,
                                                 size_t n, void *ud) {
    (void)ud;
    if (n != 1 || !token) return framework_v_void();
    /* Per javax.net.ssl.TrustManagerFactory, null selects the platform default
     * trust store; a supplied KeyStore's certificate entries become exactly
     * the trust anchors (PKIX), never mixed with platform roots. */
    if (args[0].l) {
        void *store = etd2x_jni_new_global_ref_host(env, args[0].l);
        if (!store) {
            (void)etd2x_jni_throw_new_by_name(env, "java/security/KeyStoreException", "KeyStore reference");
            return framework_v_void();
        }
        (void)etd2x_jni_set_token_host_data(token, store);
        ETD2X_LOGCI("NET", "TrustManagerFactory.init appKeyStore=1");
        return framework_v_void();
    }
    (void)etd2x_jni_set_token_host_data(token, TMF_PLATFORM);
    ETD2X_LOGCI("NET", "TrustManagerFactory.init platformRoots=%zu",
                framework_platform_ca_count());
    return framework_v_void();
}

static Etd2xJniValue framework_trust_manager_factory_get_managers(void *env, void *token,
                                                         const Etd2xJniValue *args,
                                                         size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0 || !token || etd2x_jni_get_token_host_data(token) == NULL) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalStateException",
                                           "TrustManagerFactory not initialized");
        return framework_v_object(NULL);
    }
    void *array = etd2x_jni_new_local_reference_array(env, "[Ljavax/net/ssl/TrustManager;", 1);
    void *manager = array ? etd2x_jni_new_local_object(env, "javax/net/ssl/X509TrustManager") : NULL;
    if (manager) (void)etd2x_jni_set_object_host_data(manager, etd2x_jni_get_token_host_data(token));
    if (!array || !manager ||
        etd2x_jni_set_object_array_element_host(env, array, 0, manager) != ETD2X_OK) {
        if (manager) etd2x_jni_delete_local_ref_host(env, manager);
        if (array) etd2x_jni_delete_local_ref_host(env, array);
        return framework_v_object(NULL);
    }
    etd2x_jni_delete_local_ref_host(env, manager);
    return framework_v_object(array);
}

/* Certificate entries of an app KeyStore, as an X509Certificate array. */
static void *framework_trust_store_certificates(void *env, void *store) {
    Etd2xJniValue out = {0};
    void *certs[256];
    size_t count = 0;
    if (framework_java_call_virtual(env, store, "aliases", "()Ljava/util/Enumeration;", NULL, 0, &out) && out.l) {
        void *aliases = out.l;
        for (;;) {
            if (!framework_java_call_virtual(env, aliases, "hasMoreElements", "()Z", NULL, 0, &out) || !out.z) break;
            if (!framework_java_call_virtual(env, aliases, "nextElement", "()Ljava/lang/Object;", NULL, 0, &out) || !out.l) break;
            Etd2xJniValue alias = {.l = out.l};
            if (framework_java_call_virtual(env, store, "isCertificateEntry", "(Ljava/lang/String;)Z", &alias, 1, &out) &&
                out.z && framework_java_call_virtual(env, store, "getCertificate",
                                           "(Ljava/lang/String;)Ljava/security/cert/Certificate;", &alias, 1, &out) &&
                out.l) {
                if (count < sizeof(certs) / sizeof(certs[0])) certs[count++] = out.l;
                else etd2x_jni_delete_local_ref_host(env, out.l);
            }
            etd2x_jni_delete_local_ref_host(env, alias.l);
        }
        etd2x_jni_delete_local_ref_host(env, aliases);
    }
    if (etd2x_jni_exception_pending_host(env)) etd2x_jni_exception_clear_host(env);
    void *array = etd2x_jni_new_local_reference_array(env, "[Ljava/security/cert/X509Certificate;", (int32_t)count);
    for (size_t i = 0; i < count; ++i) {
        if (array) (void)etd2x_jni_set_object_array_element_host(env, array, (int32_t)i, certs[i]);
        etd2x_jni_delete_local_ref_host(env, certs[i]);
    }
    return array;
}

static Etd2xJniValue framework_x509_trust_manager_get_accepted_issuers(void *env, void *token,
                                                              const Etd2xJniValue *args,
                                                              size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    void *store = token ? etd2x_jni_get_token_host_data(token) : NULL;
    if (store && store != TMF_PLATFORM) {
        void *array = framework_trust_store_certificates(env, store);
        ETD2X_LOGCI("NET", "X509TrustManager.getAcceptedIssuers appKeyStore roots=%d",
                    array ? (int)etd2x_jni_array_length_host(array) : -1);
        return framework_v_object(array);
    }
    const size_t count = framework_platform_ca_count();
    if (count > INT32_MAX) return framework_v_object(NULL);
    void *array = etd2x_jni_new_local_reference_array(env, "[Ljava/security/cert/X509Certificate;", (int32_t)count);
    if (!array) return framework_v_object(NULL);
    for (size_t i = 0; i < count; ++i) {
        void *cert = etd2x_jni_new_local_object(env, "java/security/cert/X509Certificate");
        if (!cert || etd2x_jni_set_object_host_data(cert, (void *)(uintptr_t)(i + 1u)) != ETD2X_OK ||
            etd2x_jni_set_object_array_element_host(env, array, (int32_t)i, cert) != ETD2X_OK) {
            if (cert) etd2x_jni_delete_local_ref_host(env, cert);
            etd2x_jni_delete_local_ref_host(env, array);
            return framework_v_object(NULL);
        }
        etd2x_jni_delete_local_ref_host(env, cert);
    }
    ETD2X_LOGCI("NET", "X509TrustManager.getAcceptedIssuers roots=%zu", count);
    return framework_v_object(array);
}


/* ---------- java.math.BigInteger / java.security.PublicKey value models ----
 * These are deliberately data-backed value objects used by X.509 metadata.
 * They do not implement arbitrary-precision arithmetic or cryptographic key
 * operations; exposed methods are exact for the immutable values they carry. */

static void *framework_clone_byte_array_local(void *env, void *array_ref) {
    if (!array_ref) return NULL;
    const int32_t n = etd2x_jni_byte_array_length(array_ref);
    if (n < 0) return NULL;
    void *copy = etd2x_jni_new_local_byte_array(env, n);
    if (!copy) return NULL;
    if (n > 0) {
        int8_t *bytes = malloc((size_t)n);
        if (!bytes) {
            etd2x_jni_delete_local_ref_host(env, copy);
            return NULL;
        }
        const Etd2xResult rr = etd2x_jni_byte_array_read(array_ref, 0, n, bytes);
        const Etd2xResult wr = rr == ETD2X_OK
            ? etd2x_jni_byte_array_write(copy, 0, n, bytes) : rr;
        free(bytes);
        if (rr != ETD2X_OK || wr != ETD2X_OK) {
            etd2x_jni_delete_local_ref_host(env, copy);
            return NULL;
        }
    }
    return copy;
}

static bool framework_object_field_local(void *env, void *token, const char *class_name,
                               const char *field_name, const char *sig,
                               void **out_ref) {
    if (!env || !token || !class_name || !field_name || !sig || !out_ref) return false;
    *out_ref = NULL;
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (!self) return false;
    Etd2xJniValue value = {0}; bool found = false;
    const Etd2xResult rc = etd2x_jni_get_instance_field_value(
        env, self, class_name, field_name, sig, &value, &found);
    etd2x_jni_delete_local_ref_host(env, self);
    if (rc != ETD2X_OK || !found) {
        if (value.l) etd2x_jni_delete_local_ref_host(env, value.l);
        return false;
    }
    *out_ref = value.l;
    return true;
}

static bool framework_int_field_value(void *env, void *token, const char *class_name,
                            const char *field_name, int32_t *out_value) {
    if (!env || !token || !class_name || !field_name || !out_value) return false;
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (!self) return false;
    Etd2xJniValue value = {0}; bool found = false;
    const Etd2xResult rc = etd2x_jni_get_instance_field_value(
        env, self, class_name, field_name, "I", &value, &found);
    etd2x_jni_delete_local_ref_host(env, self);
    if (rc != ETD2X_OK || !found) return false;
    *out_value = value.i;
    return true;
}

static void *framework_big_integer_positive(void *env, const uint8_t *bytes, size_t size) {
    if (!env || (!bytes && size)) return NULL;
    while (size && bytes[0] == 0) { ++bytes; --size; }
    if (size > INT32_MAX) return NULL;
    void *obj = etd2x_jni_new_local_object(env, "java/math/BigInteger");
    void *mag = etd2x_jni_new_local_byte_array(env, (int32_t)size);
    if (!obj || !mag ||
        (size && etd2x_jni_byte_array_write(
            mag, 0, (int32_t)size, (const int8_t *)bytes) != ETD2X_OK)) {
        if (obj) etd2x_jni_delete_local_ref_host(env, obj);
        if (mag) etd2x_jni_delete_local_ref_host(env, mag);
        return NULL;
    }
    framework_set_instance_object_field(obj, "etd2xMagnitude", "[B", mag);
    framework_set_instance_int_field(obj, "etd2xSignum", size ? 1 : 0);
    etd2x_jni_delete_local_ref_host(env, mag);
    return obj;
}

static bool framework_big_integer_magnitude(void *env, void *token,
                                  uint8_t **out_bytes, size_t *out_size,
                                  int32_t *out_signum) {
    if (!out_bytes || !out_size || !out_signum) return false;
    *out_bytes = NULL; *out_size = 0; *out_signum = 0;
    void *array = NULL;
    if (!framework_object_field_local(env, token, "java/math/BigInteger",
                            "etd2xMagnitude", "[B", &array) || !array)
        return false;
    int32_t signum = 0;
    if (!framework_int_field_value(env, token, "java/math/BigInteger",
                         "etd2xSignum", &signum)) {
        etd2x_jni_delete_local_ref_host(env, array);
        return false;
    }
    const int32_t n = etd2x_jni_byte_array_length(array);
    if (n < 0) {
        etd2x_jni_delete_local_ref_host(env, array);
        return false;
    }
    uint8_t *bytes = n ? malloc((size_t)n) : NULL;
    if (n && (!bytes || etd2x_jni_byte_array_read(
            array, 0, n, (int8_t *)bytes) != ETD2X_OK)) {
        free(bytes);
        etd2x_jni_delete_local_ref_host(env, array);
        return false;
    }
    etd2x_jni_delete_local_ref_host(env, array);
    *out_bytes = bytes; *out_size = (size_t)n; *out_signum = signum;
    return true;
}

static Etd2xJniValue framework_big_integer_signum(void *env, void *token,
                                        const Etd2xJniValue *args,
                                        size_t n, void *ud) {
    (void)args; (void)ud;
    int32_t signum = 0;
    return framework_v_int(n == 0 && framework_int_field_value(
        env, token, "java/math/BigInteger", "etd2xSignum", &signum) ? signum : 0);
}

static Etd2xJniValue framework_big_integer_to_byte_array(void *env, void *token,
                                               const Etd2xJniValue *args,
                                               size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    uint8_t *mag = NULL; size_t size = 0; int32_t signum = 0;
    if (!framework_big_integer_magnitude(env, token, &mag, &size, &signum))
        return framework_v_object(NULL);
    while (size && mag[0] == 0) { memmove(mag, mag + 1, --size); }
    if (signum == 0 || !size) {
        free(mag);
        void *zero = etd2x_jni_new_local_byte_array(env, 1);
        const int8_t z = 0;
        if (zero) (void)etd2x_jni_byte_array_write(zero, 0, 1, &z);
        return framework_v_object(zero);
    }
    if (signum < 0) {
        /* Minimal two's-complement encoding of -magnitude. */
        unsigned carry = 1;
        for (size_t i = size; i-- > 0;) {
            const unsigned v = (uint8_t)~mag[i] + carry;
            mag[i] = (uint8_t)v;
            carry = v >> 8;
        }
        const bool pad = !(mag[0] & 0x80u);
        if (size > (size_t)INT32_MAX - (pad ? 1u : 0u)) { free(mag); return framework_v_object(NULL); }
        void *neg = etd2x_jni_new_local_byte_array(env, (int32_t)(size + (pad ? 1u : 0u)));
        if (neg && pad) { const int8_t ff = -1; (void)etd2x_jni_byte_array_write(neg, 0, 1, &ff); }
        if (neg) (void)etd2x_jni_byte_array_write(neg, pad ? 1 : 0, (int32_t)size, (const int8_t *)mag);
        free(mag);
        return framework_v_object(neg);
    }
    const bool prefix = size && (mag[0] & 0x80u);
    if (size > (size_t)INT32_MAX - (prefix ? 1u : 0u)) {
        free(mag); return framework_v_object(NULL);
    }
    void *array = etd2x_jni_new_local_byte_array(env, (int32_t)(size + (prefix ? 1u : 0u)));
    if (!array) { free(mag); return framework_v_object(NULL); }
    if (prefix) {
        const int8_t z = 0;
        (void)etd2x_jni_byte_array_write(array, 0, 1, &z);
    }
    if (size) (void)etd2x_jni_byte_array_write(
        array, prefix ? 1 : 0, (int32_t)size, (const int8_t *)mag);
    free(mag);
    return framework_v_object(array);
}

static uint64_t framework_big_integer_low_bits(const uint8_t *mag, size_t size, unsigned bytes) {
    uint64_t value = 0;
    const size_t start = size > bytes ? size - bytes : 0;
    for (size_t i = start; i < size; ++i) value = (value << 8) | mag[i];
    return value;
}

static Etd2xJniValue framework_big_integer_int_value(void *env, void *token,
                                           const Etd2xJniValue *args,
                                           size_t n, void *ud) {
    (void)args; (void)ud;
    uint8_t *mag = NULL; size_t size = 0; int32_t signum = 0;
    if (n != 0 || !framework_big_integer_magnitude(env, token, &mag, &size, &signum))
        return framework_v_int(0);
    uint32_t low = (uint32_t)framework_big_integer_low_bits(mag, size, 4);
    free(mag);
    return framework_v_int((int32_t)(signum < 0 ? 0u - low : low)); /* two's-complement low bits */
}

static Etd2xJniValue framework_big_integer_long_value(void *env, void *token,
                                            const Etd2xJniValue *args,
                                            size_t n, void *ud) {
    (void)args; (void)ud;
    uint8_t *mag = NULL; size_t size = 0; int32_t signum = 0;
    if (n != 0 || !framework_big_integer_magnitude(env, token, &mag, &size, &signum))
        return framework_v_long(0);
    uint64_t low = framework_big_integer_low_bits(mag, size, 8);
    free(mag);
    const int64_t value = (int64_t)low;
    return framework_v_long((int64_t)(signum < 0 ? UINT64_C(0) - (uint64_t)value : (uint64_t)value));
}

static void *framework_big_integer_string(void *env, const uint8_t *mag, size_t size, unsigned radix, bool negative) {
    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    while (size && *mag == 0) { ++mag; --size; }
    if (!size) return framework_new_string(env, "0");
    uint8_t *work = malloc(size);
    char *out = malloc(size * 8u + 3u);
    if (!work || !out) { free(work); free(out); return NULL; }
    memcpy(work, mag, size);
    size_t first = 0, count = 0;
    while (first < size) {
        unsigned rem = 0;
        for (size_t i = first; i < size; ++i) {
            const unsigned value = (rem << 8) | work[i];
            work[i] = (uint8_t)(value / radix);
            rem = value % radix;
        }
        out[count++] = digits[rem];
        while (first < size && work[first] == 0) ++first;
    }
    if (negative) out[count++] = '-'; /* reversed below */
    for (size_t i = 0; i < count / 2u; ++i) {
        const char tmp = out[i];
        out[i] = out[count - 1u - i];
        out[count - 1u - i] = tmp;
    }
    out[count] = '\0';
    void *result = framework_new_string(env, out);
    free(work); free(out);
    return result;
}

static Etd2xJniValue framework_big_integer_to_string(void *env, void *token,
                                           const Etd2xJniValue *args,
                                           size_t n, void *ud) {
    (void)ud;
    unsigned radix = 10;
    if (n == 1 && args) {
        radix = (args[0].i >= 2 && args[0].i <= 36) ? (unsigned)args[0].i : 10u;
    } else if (n != 0) {
        return framework_v_object(NULL);
    }
    uint8_t *mag = NULL; size_t size = 0; int32_t signum = 0;
    if (!framework_big_integer_magnitude(env, token, &mag, &size, &signum))
        return framework_v_object(NULL);
    void *result = framework_big_integer_string(env, mag, size, radix, signum < 0);
    free(mag);
    return framework_v_object(result);
}

static Etd2xJniValue framework_big_integer_equals(void *env, void *token,
                                        const Etd2xJniValue *args,
                                        size_t n, void *ud) {
    (void)ud;
    if (n != 1 || !args || !args[0].l ||
        !etd2x_jni_is_instance_of_class_host(args[0].l, "java/math/BigInteger"))
        return framework_v_bool(false);
    uint8_t *a = NULL, *b = NULL; size_t an = 0, bn = 0; int32_t as = 0, bs = 0;
    const bool ok_a = framework_big_integer_magnitude(env, token, &a, &an, &as);
    const bool ok_b = framework_big_integer_magnitude(
        env, etd2x_jni_object_token_host(args[0].l), &b, &bn, &bs);
    const bool equal = ok_a && ok_b && as == bs && an == bn &&
                       (!an || memcmp(a, b, an) == 0);
    free(a); free(b);
    return framework_v_bool(equal);
}

static Etd2xJniValue framework_big_integer_hash_code(void *env, void *token,
                                           const Etd2xJniValue *args,
                                           size_t n, void *ud) {
    (void)args; (void)ud;
    uint8_t *mag = NULL; size_t size = 0; int32_t signum = 0;
    if (n != 0 || !framework_big_integer_magnitude(env, token, &mag, &size, &signum))
        return framework_v_int(0);
    uint32_t hash = 0;
    size_t i = 0;
    const size_t first = size % 4u;
    if (first) {
        uint32_t word = 0;
        for (; i < first; ++i) word = (word << 8) | mag[i];
        hash = word;
    }
    while (i < size) {
        uint32_t word = 0;
        for (unsigned j = 0; j < 4; ++j) word = (word << 8) | mag[i++];
        hash = 31u * hash + word;
    }
    free(mag);
    return framework_v_int((int32_t)(signum < 0 ? 0u - hash : hash)); /* hashCode * signum */
}

/* Stores a sign-magnitude value (leading zero bytes stripped) into a
 * BigInteger being constructed. */
static bool framework_big_integer_store(void *env, void *token, int32_t signum,
                              const uint8_t *mag, size_t size) {
    while (size && mag[0] == 0) { ++mag; --size; }
    if (!size) signum = 0;
    if (size > INT32_MAX) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/ArithmeticException", "BigInteger would overflow supported range");
        return false;
    }
    void *self = etd2x_jni_new_local_from_token(env, token);
    void *array = etd2x_jni_new_local_byte_array(env, (int32_t)size);
    const bool ok = self && array &&
        (!size || etd2x_jni_byte_array_write(array, 0, (int32_t)size, (const int8_t *)mag) == ETD2X_OK);
    if (ok) {
        framework_set_instance_object_field(self, "etd2xMagnitude", "[B", array);
        framework_set_instance_int_field(self, "etd2xSignum", signum);
    }
    if (array) etd2x_jni_delete_local_ref_host(env, array);
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    return ok;
}

/* ----- BigInteger arithmetic on big-endian magnitudes ----- */
typedef struct framework_BigVal { int32_t signum; uint8_t *mag; size_t len; } framework_BigVal;

static void framework_big_trim(framework_BigVal *v) {
    size_t lead = 0;
    while (lead < v->len && v->mag[lead] == 0) ++lead;
    if (lead) { memmove(v->mag, v->mag + lead, v->len - lead); v->len -= lead; }
    if (!v->len) v->signum = 0;
}
static int framework_big_mag_cmp(const uint8_t *a, size_t an, const uint8_t *b, size_t bn) {
    while (an && !*a) { ++a; --an; }
    while (bn && !*b) { ++b; --bn; }
    if (an != bn) return an < bn ? -1 : 1;
    const int c = an ? memcmp(a, b, an) : 0;
    return c < 0 ? -1 : c > 0 ? 1 : 0;
}
static bool framework_big_mag_add(const uint8_t *a, size_t an, const uint8_t *b, size_t bn, framework_BigVal *out) {
    const size_t n = (an > bn ? an : bn) + 1u;
    out->mag = calloc(n, 1); out->len = n;
    if (!out->mag) return false;
    unsigned carry = 0;
    for (size_t i = 0; i < n; ++i) {
        const unsigned x = (i < an ? a[an - 1 - i] : 0u) + (i < bn ? b[bn - 1 - i] : 0u) + carry;
        out->mag[n - 1 - i] = (uint8_t)x;
        carry = x >> 8;
    }
    return true;
}
/* |a| >= |b| */
static bool framework_big_mag_sub(const uint8_t *a, size_t an, const uint8_t *b, size_t bn, framework_BigVal *out) {
    out->mag = calloc(an ? an : 1u, 1); out->len = an;
    if (!out->mag) return false;
    int borrow = 0;
    for (size_t i = 0; i < an; ++i) {
        int x = (int)a[an - 1 - i] - (i < bn ? (int)b[bn - 1 - i] : 0) - borrow;
        borrow = x < 0;
        out->mag[an - 1 - i] = (uint8_t)(x + (borrow ? 256 : 0));
    }
    return true;
}
static bool framework_big_mag_mul(const uint8_t *a, size_t an, const uint8_t *b, size_t bn, framework_BigVal *out) {
    const size_t n = an + bn;
    uint32_t *acc = calloc(n ? n : 1u, sizeof(*acc));
    out->mag = calloc(n ? n : 1u, 1); out->len = n;
    if (!acc || !out->mag) { free(acc); return false; }
    /* Big-endian schoolbook: a[i]*b[j] lands at i+j+1; carries move toward index 0. */
    for (size_t i = 0; i < an; ++i) {
        uint32_t carry = 0;
        for (size_t j = bn; j-- > 0;) {
            const size_t k = i + j + 1u;
            const uint32_t x = acc[k] + (uint32_t)a[i] * b[j] + carry;
            acc[k] = x & 0xffu;
            carry = x >> 8;
        }
        for (size_t k = i + 1u; carry && k-- > 0;) {
            const uint32_t x = acc[k] + carry;
            acc[k] = x & 0xffu;
            carry = x >> 8;
        }
    }
    for (size_t k = 0; k < n; ++k) out->mag[k] = (uint8_t)acc[k];
    free(acc);
    return true;
}
/* Long division by bits: q = a / b, r = a % b (magnitudes, b != 0). */
static bool framework_big_mag_divmod(const uint8_t *a, size_t an, const uint8_t *b, size_t bn, framework_BigVal *q, framework_BigVal *r) {
    q->mag = calloc(an ? an : 1u, 1); q->len = an;
    r->mag = calloc(bn + 1u, 1); r->len = bn + 1u;
    if (!q->mag || !r->mag) return false;
    for (size_t i = 0; i < an * 8u; ++i) {
        /* r = (r << 1) | next bit of a */
        unsigned carry = (a[i / 8u] >> (7u - i % 8u)) & 1u;
        for (size_t k = r->len; k-- > 0;) {
            const unsigned x = ((unsigned)r->mag[k] << 1) | carry;
            r->mag[k] = (uint8_t)x;
            carry = x >> 8;
        }
        if (framework_big_mag_cmp(r->mag, r->len, b, bn) >= 0) {
            int borrow = 0;
            for (size_t k = 0; k < r->len; ++k) {
                const size_t ri = r->len - 1 - k;
                int x = (int)r->mag[ri] - (k < bn ? (int)b[bn - 1 - k] : 0) - borrow;
                borrow = x < 0;
                r->mag[ri] = (uint8_t)(x + (borrow ? 256 : 0));
            }
            q->mag[i / 8u] |= (uint8_t)(1u << (7u - i % 8u));
        }
    }
    return true;
}

static bool framework_big_read(void *env, void *ref, framework_BigVal *out) {
    memset(out, 0, sizeof(*out));
    if (!ref) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "BigInteger");
        return false;
    }
    size_t size = 0;
    if (!framework_big_integer_magnitude(env, etd2x_jni_object_token_host(ref), &out->mag, &size, &out->signum)) return false;
    out->len = size;
    framework_big_trim(out);
    return true;
}
static void *framework_big_make(void *env, framework_BigVal *v) {
    framework_big_trim(v);
    void *obj = etd2x_jni_new_local_object(env, "java/math/BigInteger");
    void *arr = obj ? etd2x_jni_new_local_byte_array(env, (int32_t)v->len) : NULL;
    if (!obj || !arr || (v->len && etd2x_jni_byte_array_write(arr, 0, (int32_t)v->len, (const int8_t *)v->mag) != ETD2X_OK)) {
        if (obj) etd2x_jni_delete_local_ref_host(env, obj);
        if (arr) etd2x_jni_delete_local_ref_host(env, arr);
        return NULL;
    }
    framework_set_instance_object_field(obj, "etd2xMagnitude", "[B", arr);
    framework_set_instance_int_field(obj, "etd2xSignum", v->len ? v->signum : 0);
    etd2x_jni_delete_local_ref_host(env, arr);
    return obj;
}

/* Signed a + (negate_b ? -b : b) */
static bool framework_big_add_signed(const framework_BigVal *a, const framework_BigVal *b, bool negate_b, framework_BigVal *out) {
    const int32_t bs = negate_b ? -b->signum : b->signum;
    memset(out, 0, sizeof(*out));
    if (!b->signum) { out->mag = malloc(a->len ? a->len : 1u); if (!out->mag) return false; if (a->len) memcpy(out->mag, a->mag, a->len); out->len = a->len; out->signum = a->signum; return true; }
    if (!a->signum) { out->mag = malloc(b->len); if (!out->mag) return false; memcpy(out->mag, b->mag, b->len); out->len = b->len; out->signum = bs; return true; }
    if (a->signum == bs) { if (!framework_big_mag_add(a->mag, a->len, b->mag, b->len, out)) return false; out->signum = bs; return true; }
    const int c = framework_big_mag_cmp(a->mag, a->len, b->mag, b->len);
    if (c == 0) { out->mag = calloc(1, 1); out->len = 0; out->signum = 0; return out->mag != NULL; }
    if (c > 0) { if (!framework_big_mag_sub(a->mag, a->len, b->mag, b->len, out)) return false; out->signum = a->signum; }
    else { if (!framework_big_mag_sub(b->mag, b->len, a->mag, a->len, out)) return false; out->signum = bs; }
    return true;
}

enum { BIG_ADD, BIG_SUB, BIG_MUL, BIG_DIV, BIG_REM, BIG_MOD, BIG_MIN, BIG_MAX };

static Etd2xJniValue framework_big_integer_binary(void *env, void *t, const Etd2xJniValue *args, size_t n, void *u) {
    const int op = (int)(intptr_t)u;
    if (n != 1) return framework_v_object(NULL);
    void *self = etd2x_jni_new_local_from_token(env, t);
    framework_BigVal a = {0}, b = {0}, r = {0}, q = {0};
    void *result = NULL;
    if (!framework_big_read(env, self, &a) || !framework_big_read(env, args[0].l, &b)) goto done;
    switch (op) {
    case BIG_ADD: if (framework_big_add_signed(&a, &b, false, &r)) result = framework_big_make(env, &r); break;
    case BIG_SUB: if (framework_big_add_signed(&a, &b, true, &r)) result = framework_big_make(env, &r); break;
    case BIG_MUL:
        if (framework_big_mag_mul(a.mag, a.len, b.mag, b.len, &r)) { r.signum = a.signum * b.signum; result = framework_big_make(env, &r); }
        break;
    case BIG_MIN: case BIG_MAX: {
        const int c = a.signum != b.signum ? (a.signum < b.signum ? -1 : 1)
                    : a.signum * framework_big_mag_cmp(a.mag, a.len, b.mag, b.len);
        result = etd2x_jni_new_local_ref_host(env, (op == BIG_MIN) == (c <= 0) ? self : args[0].l);
        break;
    }
    default: /* DIV, REM, MOD */
        if (op == BIG_MOD && b.signum <= 0) {
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/ArithmeticException", "BigInteger: modulus not positive");
            break;
        }
        if (!b.signum) {
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/ArithmeticException", "BigInteger divide by zero");
            break;
        }
        if (!framework_big_mag_divmod(a.mag, a.len, b.mag, b.len, &q, &r)) break;
        if (op == BIG_DIV) { q.signum = a.signum * b.signum; result = framework_big_make(env, &q); break; }
        r.signum = a.signum; /* remainder takes the dividend's sign */
        framework_big_trim(&r);
        if (op == BIG_MOD && r.signum < 0) {
            framework_BigVal m = {0};
            if (framework_big_add_signed(&r, &b, false, &m)) { result = framework_big_make(env, &m); free(m.mag); }
            break;
        }
        result = framework_big_make(env, &r);
        break;
    }
done:
    free(a.mag); free(b.mag); free(r.mag); free(q.mag);
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    if (!result && !etd2x_jni_exception_pending_host(env))
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "BigInteger");
    return framework_v_object(result);
}

/* negate(), abs() */
static Etd2xJniValue framework_big_integer_unary(void *env, void *t, const Etd2xJniValue *args, size_t n, void *u) {
    (void)args;
    if (n != 0) return framework_v_object(NULL);
    void *self = etd2x_jni_new_local_from_token(env, t);
    framework_BigVal a = {0};
    void *result = NULL;
    if (framework_big_read(env, self, &a)) {
        if (u) a.signum = a.signum < 0 ? 1 : a.signum; else a.signum = -a.signum;
        result = framework_big_make(env, &a);
    }
    free(a.mag);
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    return framework_v_object(result);
}

static Etd2xJniValue framework_big_integer_compare_to(void *env, void *t, const Etd2xJniValue *args, size_t n, void *u) {
    (void)u;
    if (n != 1) return framework_v_int(0);
    void *self = etd2x_jni_new_local_from_token(env, t);
    framework_BigVal a = {0}, b = {0};
    int c = 0;
    if (framework_big_read(env, self, &a) && framework_big_read(env, args[0].l, &b))
        c = a.signum != b.signum ? (a.signum < b.signum ? -1 : 1) : a.signum * framework_big_mag_cmp(a.mag, a.len, b.mag, b.len);
    free(a.mag); free(b.mag);
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    return framework_v_int(c);
}

static Etd2xJniValue framework_big_integer_value_of(void *env, void *t, const Etd2xJniValue *args, size_t n, void *u) {
    (void)t; (void)u;
    if (n != 1) return framework_v_object(NULL);
    const int64_t x = args[0].j;
    uint64_t m = x < 0 ? UINT64_C(0) - (uint64_t)x : (uint64_t)x;
    uint8_t bytes[8];
    for (int i = 7; i >= 0; --i) { bytes[i] = (uint8_t)m; m >>= 8; }
    framework_BigVal v = {.signum = x < 0 ? -1 : x > 0 ? 1 : 0, .mag = malloc(8), .len = 8};
    if (!v.mag) return framework_v_object(NULL);
    memcpy(v.mag, bytes, 8);
    void *r = framework_big_make(env, &v);
    free(v.mag);
    return framework_v_object(r);
}

/* pow(int exponent) */
static Etd2xJniValue framework_big_integer_pow(void *env, void *t, const Etd2xJniValue *args, size_t n, void *u) {
    (void)u;
    if (n != 1) return framework_v_object(NULL);
    if (args[0].i < 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/ArithmeticException", "Negative exponent");
        return framework_v_object(NULL);
    }
    void *self = etd2x_jni_new_local_from_token(env, t);
    framework_BigVal base = {0}, acc = {.signum = 1, .mag = malloc(1), .len = 1};
    void *result = NULL;
    if (acc.mag && framework_big_read(env, self, &base)) {
        acc.mag[0] = 1;
        bool ok = true;
        for (int32_t e = args[0].i; ok && e > 0; --e) {
            framework_BigVal next = {0};
            ok = framework_big_mag_mul(acc.mag, acc.len, base.mag, base.len, &next);
            next.signum = acc.signum * base.signum;
            free(acc.mag);
            acc = next;
            framework_big_trim(&acc);
            if (!acc.len) break;
        }
        if (ok) result = framework_big_make(env, &acc);
    }
    free(base.mag); free(acc.mag);
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    return framework_v_object(result);
}

static uint8_t *framework_big_integer_byte_args(void *env, void *array, size_t *out_size) {
    *out_size = 0;
    if (!array) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "val");
        return NULL;
    }
    const int32_t n = etd2x_jni_byte_array_length(array);
    uint8_t *bytes = malloc(n > 0 ? (size_t)n : 1u);
    if (!bytes || n < 0 || (n && etd2x_jni_byte_array_read(array, 0, n, (int8_t *)bytes) != ETD2X_OK)) {
        free(bytes);
        return NULL;
    }
    *out_size = (size_t)n;
    return bytes;
}

/* BigInteger(int signum, byte[] magnitude) */
static Etd2xJniValue framework_big_integer_ctor_sign_magnitude(void *env, void *token,
                                                     const Etd2xJniValue *args,
                                                     size_t n, void *ud) {
    (void)ud;
    if (n != 2) return framework_v_void();
    size_t size = 0;
    uint8_t *mag = framework_big_integer_byte_args(env, args[1].l, &size);
    if (!mag) return framework_v_void();
    const int32_t signum = args[0].i;
    bool zero = true;
    for (size_t i = 0; i < size && zero; ++i) zero = mag[i] == 0;
    if (signum < -1 || signum > 1)
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NumberFormatException", "Invalid signum value");
    else if (signum == 0 && !zero)
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NumberFormatException", "signum-magnitude mismatch");
    else
        (void)framework_big_integer_store(env, token, signum, mag, size);
    free(mag);
    return framework_v_void();
}

/* BigInteger(byte[] val): big-endian two's-complement. */
static Etd2xJniValue framework_big_integer_ctor_twos_complement(void *env, void *token,
                                                      const Etd2xJniValue *args,
                                                      size_t n, void *ud) {
    (void)ud;
    if (n != 1) return framework_v_void();
    size_t size = 0;
    uint8_t *bytes = framework_big_integer_byte_args(env, args[0].l, &size);
    if (!bytes) return framework_v_void();
    if (!size) {
        free(bytes);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NumberFormatException", "Zero length BigInteger");
        return framework_v_void();
    }
    int32_t signum = 1;
    if (bytes[0] & 0x80u) {
        signum = -1;
        unsigned carry = 1;
        for (size_t i = size; i-- > 0;) {
            const unsigned v = (uint8_t)~bytes[i] + carry;
            bytes[i] = (uint8_t)v;
            carry = v >> 8;
        }
        /* -2^(8n-1) negates to itself; its magnitude needs the top bit. */
    }
    (void)framework_big_integer_store(env, token, signum, bytes, size);
    free(bytes);
    return framework_v_void();
}

static int framework_big_integer_digit(uint32_t c, unsigned radix) {
    unsigned d;
    if (c >= '0' && c <= '9') d = c - '0';
    else if (c >= 'a' && c <= 'z') d = c - 'a' + 10u;
    else if (c >= 'A' && c <= 'Z') d = c - 'A' + 10u;
    else if (c >= 0xff10u && c <= 0xff19u) d = c - 0xff10u;            /* fullwidth digits */
    else if (c >= 0xff41u && c <= 0xff5au) d = c - 0xff41u + 10u;      /* fullwidth a-z */
    else if (c >= 0xff21u && c <= 0xff3au) d = c - 0xff21u + 10u;      /* fullwidth A-Z */
    else return -1;
    return d < radix ? (int)d : -1;
}

/* BigInteger(String val[, int radix]) */
static Etd2xJniValue framework_big_integer_ctor_string(void *env, void *token,
                                             const Etd2xJniValue *args,
                                             size_t n, void *ud) {
    (void)ud;
    if (n != 1 && n != 2) return framework_v_void();
    const int32_t radix = n == 2 ? args[1].i : 10;
    if (!args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "val");
        return framework_v_void();
    }
    if (radix < 2 || radix > 36) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NumberFormatException", "Radix out of range");
        return framework_v_void();
    }
    int32_t len = 0;
    uint16_t *chars = etd2x_jni_string_utf16_dup_host(args[0].l, &len);
    if (len <= 0 || !chars) {
        free(chars);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NumberFormatException", "Zero length BigInteger");
        return framework_v_void();
    }
    int32_t pos = 0, signum = 1;
    if (chars[0] == '-' || chars[0] == '+') { signum = chars[0] == '-' ? -1 : 1; pos = 1; }
    /* Little-endian base-256 accumulator: mag = mag * radix + digit. */
    uint8_t *acc = calloc((size_t)len + 1u, 1u);
    size_t used = 0;
    bool ok = acc && pos < len;
    for (int32_t i = pos; ok && i < len; ++i) {
        const int d = framework_big_integer_digit(chars[i], (unsigned)radix);
        if (d < 0) { ok = false; break; }
        unsigned carry = (unsigned)d;
        for (size_t k = 0; k < used; ++k) {
            const unsigned v = acc[k] * (unsigned)radix + carry;
            acc[k] = (uint8_t)v;
            carry = v >> 8;
        }
        while (carry) { acc[used++] = (uint8_t)carry; carry >>= 8; }
    }
    free(chars);
    if (!ok) {
        free(acc);
        char text[160] = {0};
        (void)etd2x_jni_string_utf_copy(args[0].l, text, sizeof(text));
        char msg[200];
        snprintf(msg, sizeof(msg), "For input string: \"%s\"", text);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NumberFormatException", msg);
        return framework_v_void();
    }
    for (size_t i = 0; i < used / 2u; ++i) {
        const uint8_t t = acc[i]; acc[i] = acc[used - 1u - i]; acc[used - 1u - i] = t;
    }
    (void)framework_big_integer_store(env, token, signum, acc, used);
    free(acc);
    return framework_v_void();
}

static const char *framework_public_key_algorithm_name(const char *oid) {
    if (!oid) return "";
    if (!strcmp(oid, "1.2.840.113549.1.1.1")) return "RSA";
    if (!strcmp(oid, "1.2.840.10040.4.1")) return "DSA";
    if (!strcmp(oid, "1.2.840.10045.2.1")) return "EC";
    if (!strcmp(oid, "1.3.101.112")) return "Ed25519";
    if (!strcmp(oid, "1.3.101.113")) return "Ed448";
    if (!strcmp(oid, "1.3.101.110")) return "X25519";
    if (!strcmp(oid, "1.3.101.111")) return "X448";
    return oid;
}

static void *framework_encoded_public_key(void *env, const uint8_t *spki, size_t spki_size,
                                const char *algorithm) {
    if (!env || (!spki && spki_size) || spki_size > INT32_MAX) return NULL;
    void *key = etd2x_jni_new_local_object(env, "com/etd2x/security/EncodedPublicKey");
    void *encoded = etd2x_jni_new_local_byte_array(env, (int32_t)spki_size);
    void *name = framework_new_string(env, algorithm ? algorithm : "");
    if (!key || !encoded || !name ||
        (spki_size && etd2x_jni_byte_array_write(
            encoded, 0, (int32_t)spki_size, (const int8_t *)spki) != ETD2X_OK)) {
        if (key) etd2x_jni_delete_local_ref_host(env, key);
        if (encoded) etd2x_jni_delete_local_ref_host(env, encoded);
        if (name) etd2x_jni_delete_local_ref_host(env, name);
        return NULL;
    }
    framework_set_instance_object_field(key, "etd2xEncoded", "[B", encoded);
    framework_set_instance_object_field(key, "etd2xAlgorithm", "Ljava/lang/String;", name);
    etd2x_jni_delete_local_ref_host(env, encoded);
    etd2x_jni_delete_local_ref_host(env, name);
    return key;
}

static Etd2xJniValue framework_encoded_key_get_encoded(void *env, void *token,
                                             const Etd2xJniValue *args,
                                             size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    void *array = NULL;
    if (!framework_object_field_local(env, token, "com/etd2x/security/EncodedPublicKey",
                            "etd2xEncoded", "[B", &array) || !array)
        return framework_v_object(NULL);
    void *copy = framework_clone_byte_array_local(env, array);
    etd2x_jni_delete_local_ref_host(env, array);
    return framework_v_object(copy);
}

