static Etd2xJniValue framework_encoded_key_equals(void *env, void *token,
                                        const Etd2xJniValue *args,
                                        size_t n, void *ud) {
    (void)ud;
    if (n != 1 || !args || !args[0].l ||
        !etd2x_jni_is_instance_of_class_host(
            args[0].l, "com/etd2x/security/EncodedPublicKey"))
        return framework_v_bool(false);
    void *left = NULL, *right = NULL;
    const bool l_ok = framework_object_field_local(
        env, token, "com/etd2x/security/EncodedPublicKey", "etd2xEncoded", "[B", &left);
    const bool r_ok = framework_object_field_local(
        env, etd2x_jni_object_token_host(args[0].l),
        "com/etd2x/security/EncodedPublicKey", "etd2xEncoded", "[B", &right);
    bool equal = false;
    if (l_ok && r_ok && left && right) {
        const int32_t ln = etd2x_jni_byte_array_length(left);
        const int32_t rn = etd2x_jni_byte_array_length(right);
        if (ln >= 0 && ln == rn) {
            int8_t *lb = ln ? malloc((size_t)ln) : NULL;
            int8_t *rb = rn ? malloc((size_t)rn) : NULL;
            if ((!ln || (lb && rb)) &&
                (!ln || (etd2x_jni_byte_array_read(left,0,ln,lb)==ETD2X_OK &&
                         etd2x_jni_byte_array_read(right,0,rn,rb)==ETD2X_OK)))
                equal = !ln || memcmp(lb, rb, (size_t)ln) == 0;
            free(lb); free(rb);
        }
    }
    if (left) etd2x_jni_delete_local_ref_host(env, left);
    if (right) etd2x_jni_delete_local_ref_host(env, right);
    return framework_v_bool(equal);
}

static Etd2xJniValue framework_encoded_key_hash_code(void *env, void *token,
                                           const Etd2xJniValue *args,
                                           size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_int(0);
    void *array = NULL;
    if (!framework_object_field_local(env, token, "com/etd2x/security/EncodedPublicKey",
                            "etd2xEncoded", "[B", &array) || !array)
        return framework_v_int(0);
    const int32_t len = etd2x_jni_byte_array_length(array);
    uint32_t hash = 1u;
    if (len > 0) {
        int8_t *raw = malloc((size_t)len);
        if (raw && etd2x_jni_byte_array_read(array,0,len,raw)==ETD2X_OK)
            for (int32_t i=0;i<len;++i)
                hash = 31u * hash + (uint32_t)(int32_t)raw[i];
        free(raw);
    }
    etd2x_jni_delete_local_ref_host(env, array);
    return framework_v_int((int32_t)hash);
}

static bool framework_certificate_der_dup(void *env, void *token,
                                uint8_t **out_der, size_t *out_size) {
    if (!env || !token || !out_der || !out_size) return false;
    *out_der = NULL;
    *out_size = 0;

    /* Certificates produced by the ETD2X X.509 provider carry their exact
     * encoded DER in an instance field. */
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (self) {
        Etd2xJniValue value = {0};
        bool found = false;
        Etd2xResult rc = etd2x_jni_get_instance_field_value(
            env, self, "java/security/cert/X509Certificate",
            "etd2xEncoded", "[B", &value, &found);
        etd2x_jni_delete_local_ref_host(env, self);
        if (rc == ETD2X_OK && found && value.l) {
            const int32_t length = etd2x_jni_byte_array_length(value.l);
            if (length >= 0) {
                uint8_t *copy = length ? malloc((size_t)length) : NULL;
                if (!length || copy) {
                    if (!length || etd2x_jni_byte_array_read(
                            value.l, 0, length, (int8_t *)copy) == ETD2X_OK) {
                        *out_der = copy;
                        *out_size = (size_t)length;
                        etd2x_jni_delete_local_ref_host(env, value.l);
                        return true;
                    }
                }
                free(copy);
            }
            etd2x_jni_delete_local_ref_host(env, value.l);
        } else if (value.l) {
            etd2x_jni_delete_local_ref_host(env, value.l);
        }
    }

    /* Trust-manager certificates use a stable platform-CA index as host data. */
    const uintptr_t encoded_index = (uintptr_t)etd2x_jni_get_token_host_data(token);
    if (encoded_index == 0) return false;
    const size_t index = (size_t)(encoded_index - 1u);
    size_t size = 0;
    if (!framework_platform_ca_copy(index, NULL, 0, &size)) return false;
    uint8_t *der = size ? malloc(size) : NULL;
    if (size && !der) return false;
    if (!framework_platform_ca_copy(index, der, size, &size)) {
        free(der);
        return false;
    }
    *out_der = der;
    *out_size = size;
    return true;
}

static Etd2xJniValue framework_certificate_get_encoded(void *env, void *token,
                                              const Etd2xJniValue *args,
                                              size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    uint8_t *der = NULL;
    size_t size = 0;
    if (!framework_certificate_der_dup(env, token, &der, &size) || size > INT32_MAX) {
        free(der);
        return framework_v_object(NULL);
    }
    void *array = etd2x_jni_new_local_byte_array(env, (int32_t)size);
    if (!array || (size && etd2x_jni_byte_array_write(
            array, 0, (int32_t)size, (const int8_t *)der) != ETD2X_OK)) {
        if (array) etd2x_jni_delete_local_ref_host(env, array);
        free(der);
        return framework_v_object(NULL);
    }
    free(der);
    return framework_v_object(array);
}

static void *framework_certificate_bytes_local(void *env, const uint8_t *data, size_t size) {
    if (!env || size > INT32_MAX || (size && !data)) return NULL;
    void *array = etd2x_jni_new_local_byte_array(env, (int32_t)size);
    if (!array) return NULL;
    if (size && etd2x_jni_byte_array_write(
            array, 0, (int32_t)size, (const int8_t *)data) != ETD2X_OK) {
        etd2x_jni_delete_local_ref_host(env, array);
        return NULL;
    }
    return array;
}

