static bool framework_certificate_metadata_dup(void *env, void *token,
                                     uint8_t **out_der, size_t *out_size,
                                     Etd2xJavaX509Metadata *out_metadata) {
    if (!out_der || !out_size || !out_metadata) return false;
    *out_der = NULL;
    *out_size = 0;
    if (!framework_certificate_der_dup(env, token, out_der, out_size)) return false;
    if (!etd2x_java_security_x509_metadata ||
        etd2x_java_security_x509_metadata(*out_der, *out_size, out_metadata) != ETD2X_OK) {
        free(*out_der);
        *out_der = NULL;
        *out_size = 0;
        return false;
    }
    return true;
}

static Etd2xJniValue framework_certificate_get_version(void *env, void *token,
                                             const Etd2xJniValue *args,
                                             size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_int(0);
    uint8_t *der = NULL; size_t der_size = 0; Etd2xJavaX509Metadata meta = {0};
    if (!framework_certificate_metadata_dup(env, token, &der, &der_size, &meta)) return framework_v_int(0);
    const int32_t version = meta.version;
    free(der);
    return framework_v_int(version);
}

static void *framework_certificate_date_object(void *env, int64_t millis) {
    void *date = etd2x_jni_new_local_object(env, "java/util/Date");
    if (!date) return NULL;
    Etd2xJniValue arg = {.j = millis}, ignored = {0};
    bool found = false;
    const Etd2xResult rc = etd2x_jni_invoke_method_host(
        env, date, "java/util/Date", "<init>", "(J)V", false,
        &arg, &ignored, &found);
    if (rc != ETD2X_OK || !found || etd2x_jni_exception_pending_host(env)) {
        etd2x_jni_delete_local_ref_host(env, date);
        return NULL;
    }
    return date;
}

static Etd2xJniValue framework_certificate_get_validity_date_common(void *env, void *token,
                                                          const Etd2xJniValue *args,
                                                          size_t n, bool after) {
    (void)args;
    if (n != 0) return framework_v_object(NULL);
    uint8_t *der = NULL; size_t der_size = 0; Etd2xJavaX509Metadata meta = {0};
    if (!framework_certificate_metadata_dup(env, token, &der, &der_size, &meta))
        return framework_v_object(NULL);
    const int64_t millis = after ? meta.not_after_ms : meta.not_before_ms;
    free(der);
    return framework_v_object(framework_certificate_date_object(env, millis));
}
