static const char *framework_certificate_signature_name(const char *oid) {
    if (!oid) return "";
    if (!strcmp(oid, "1.2.840.113549.1.1.5")) return "SHA1withRSA";
    if (!strcmp(oid, "1.2.840.113549.1.1.11")) return "SHA256withRSA";
    if (!strcmp(oid, "1.2.840.113549.1.1.12")) return "SHA384withRSA";
    if (!strcmp(oid, "1.2.840.113549.1.1.13")) return "SHA512withRSA";
    if (!strcmp(oid, "1.2.840.10040.4.3")) return "SHA1withDSA";
    if (!strcmp(oid, "2.16.840.1.101.3.4.3.2")) return "SHA256withDSA";
    if (!strcmp(oid, "1.2.840.10045.4.1")) return "SHA1withECDSA";
    if (!strcmp(oid, "1.2.840.10045.4.3.2")) return "SHA256withECDSA";
    if (!strcmp(oid, "1.2.840.10045.4.3.3")) return "SHA384withECDSA";
    if (!strcmp(oid, "1.2.840.10045.4.3.4")) return "SHA512withECDSA";
    if (!strcmp(oid, "1.3.101.112")) return "Ed25519";
    if (!strcmp(oid, "1.3.101.113")) return "Ed448";
    return oid;
}

