static Etd2xJniValue framework_certificate_get_key_usage(void *env, void *token,
                                               const Etd2xJniValue *args,
                                               size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    uint8_t *der = NULL; size_t der_size = 0;
    if (!framework_certificate_der_dup(env, token, &der, &der_size)) return framework_v_object(NULL);
    bool *usage = NULL; size_t count = 0; bool present = false;
    const Etd2xResult rc = etd2x_java_security_x509_key_usage
        ? etd2x_java_security_x509_key_usage(
              der, der_size, &usage, &count, &present)
        : ETD2X_ERR_APK_UNSUPPORTED;
    free(der);
    if (rc != ETD2X_OK || !present || count > INT32_MAX) {
        free(usage);
        return framework_v_object(NULL);
    }
    void *array = etd2x_jni_new_local_boolean_array(env, (int32_t)count);
    if (!array) {
        free(usage);
        return framework_v_object(NULL);
    }
    uint8_t *bytes = count ? malloc(count) : NULL;
    if (count && !bytes) {
        free(usage);
        etd2x_jni_delete_local_ref_host(env, array);
        return framework_v_object(NULL);
    }
    for (size_t i = 0; i < count; ++i) bytes[i] = usage[i] ? 1u : 0u;
    free(usage);
    if (count && etd2x_jni_boolean_array_write(
            array, 0, (int32_t)count, bytes) != ETD2X_OK) {
        free(bytes);
        etd2x_jni_delete_local_ref_host(env, array);
        return framework_v_object(NULL);
    }
    free(bytes);
    return framework_v_object(array);
}

