static Etd2xJniValue framework_certificate_get_serial_number(void *env, void *token,
                                                   const Etd2xJniValue *args,
                                                   size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    uint8_t *der = NULL; size_t der_size = 0; Etd2xJavaX509Metadata meta = {0};
    if (!framework_certificate_metadata_dup(env, token, &der, &der_size, &meta))
        return framework_v_object(NULL);
    const uint8_t *serial = meta.serial_value;
    size_t serial_size = meta.serial_value_size;
    /* RFC 5280 serial numbers are non-negative. DER may include a leading
     * 00 octet solely to keep the INTEGER positive. */
    if (serial_size && serial[0] == 0) { ++serial; --serial_size; }
    void *result = framework_big_integer_positive(env, serial, serial_size);
    free(der);
    return framework_v_object(result);
}

