static void *framework_user_manager_local(void *env);

/* ---------- android.app.ActivityManager ----------
 * ETD2X currently hosts one Android application process.  Model that process
 * truthfully at the Android framework boundary instead of exposing Horizon
 * process/task details directly.  Broader task/service management remains a
 * Phase-10 service concern. */
static bool framework_activity_manager_fill_process(void *env, void *info) {
    if (!env || !info) return false;
    const int pid = getpid() > 0 ? getpid() : 1;
    void *process_name = framework_new_string(env, framework_g_fw.package_name);
    if (process_name) {
        framework_set_instance_object_field(info, "processName", "Ljava/lang/String;", process_name);
        etd2x_jni_delete_local_ref_host(env, process_name);
    }
    framework_set_instance_int_field(info, "pid", pid);
    framework_set_instance_int_field(info, "uid", 10000);
    framework_set_instance_int_field(info, "importance", 100); /* IMPORTANCE_FOREGROUND */
    framework_set_instance_int_field(info, "importanceReasonCode", 0);
    framework_set_instance_int_field(info, "lru", 0);
    framework_set_instance_int_field(info, "lastTrimLevel", 0);
    void *pkgs = etd2x_jni_new_local_reference_array(env, "[Ljava/lang/String;", 1);
    void *pkg = framework_new_string(env, framework_g_fw.package_name);
    if (pkgs && pkg) (void)etd2x_jni_set_object_array_element_host(env, pkgs, 0, pkg);
    if (pkg) etd2x_jni_delete_local_ref_host(env, pkg);
    if (pkgs) {
        framework_set_instance_object_field(info, "pkgList", "[Ljava/lang/String;", pkgs);
        etd2x_jni_delete_local_ref_host(env, pkgs);
    }
    return true;
}

static Etd2xJniValue framework_activity_manager_get_running_processes(void *env, void *token,
                                                             const Etd2xJniValue *args,
                                                             size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    void *list = etd2x_jni_new_local_object(env, "java/util/ArrayList");
    void *info = etd2x_jni_new_local_object(env, "android/app/ActivityManager$RunningAppProcessInfo");
    if (!list || !info || !framework_activity_manager_fill_process(env, info)) {
        if (info) etd2x_jni_delete_local_ref_host(env, info);
        if (list) etd2x_jni_delete_local_ref_host(env, list);
        return framework_v_object(NULL);
    }
    Etd2xJniValue arg = {.l = info}, out = {0};
    bool found = false;
    (void)etd2x_jni_invoke_method_host(env, list, "java/util/ArrayList", "add", "(Ljava/lang/Object;)Z",
                                        false, &arg, &out, &found);
    etd2x_jni_delete_local_ref_host(env, info);
    if (!found) { etd2x_jni_delete_local_ref_host(env, list); return framework_v_object(NULL); }
    return framework_v_object(list);
}

