/* SystemClock.elapsedRealtime: Horizon exposes no separate deep-sleep clock;
 * CLOCK_MONOTONIC is the monotonic time since boot ETD2X can observe. */
static Etd2xJniValue framework_system_clock_elapsed_realtime(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)env; (void)t; (void)a; (void)n; (void)u;
    struct timespec ts = {0};
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return framework_v_long((int64_t)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}
