#define FILE_OBSERVER_PAYLOAD_MAGIC UINT64_C(0x41504b36464f4231) /* APK6FOB1 */
#define FILE_OBSERVER_QUEUE_LIMIT 256u

typedef struct framework_FileObserverQueuedEvent {
    int event;
    bool has_path;
    char path[ETD2X_FO_NAME_CAP];
    struct framework_FileObserverQueuedEvent *next;
} framework_FileObserverQueuedEvent;

typedef struct framework_FileObserverPayload {
    uint64_t magic;
    char *guest_path;
    char *host_path;
    int mask;
    pthread_t thread;
    bool thread_valid;
    bool started;
    bool is_directory;
    bool refresh_requested;
    bool terminal_pending;
    size_t queued_count;
    pthread_mutex_t lock;
    atomic_bool stop;
    atomic_bool finished;
    void *observer_global;
    framework_FileObserverQueuedEvent *queue_head;
    framework_FileObserverQueuedEvent *queue_tail;
    struct framework_FileObserverPayload *next;
} framework_FileObserverPayload;

static pthread_mutex_t framework_g_file_observer_lock = PTHREAD_MUTEX_INITIALIZER;
static framework_FileObserverPayload *framework_g_file_observers;

static framework_FileObserverPayload *framework_file_observer_payload(void *token) {
    framework_FileObserverPayload *p = (framework_FileObserverPayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == FILE_OBSERVER_PAYLOAD_MAGIC ? p : NULL;
}

static Etd2xFileObserverSnapshot framework_file_observer_snapshot(bool exists, const struct stat *st) {
    Etd2xFileObserverSnapshot out = {0};
    out.exists = exists;
    if (exists && st) {
        out.inode = (uint64_t)st->st_ino;
        out.size = (int64_t)st->st_size;
        out.mtime = (int64_t)st->st_mtime;
        out.mode = (uint32_t)st->st_mode;
    }
    return out;
}

static int framework_file_observer_pick_event(int mask, bool old_exists, const struct stat *old_st,
                                    bool new_exists, const struct stat *new_st) {
    const Etd2xFileObserverSnapshot before = framework_file_observer_snapshot(old_exists, old_st);
    const Etd2xFileObserverSnapshot after = framework_file_observer_snapshot(new_exists, new_st);
    return etd2x_file_observer_pick_event(mask, &before, &after);
}

static void framework_file_observer_queue_clear_locked(framework_FileObserverPayload *p) {
    framework_FileObserverQueuedEvent *event = p ? p->queue_head : NULL;
    while (event) {
        framework_FileObserverQueuedEvent *next = event->next;
        free(event);
        event = next;
    }
    if (p) {
        p->queue_head = p->queue_tail = NULL;
        p->queued_count = 0;
    }
}

static bool framework_file_observer_queue_locked(framework_FileObserverPayload *p, int event, const char *path) {
    if (!p || !p->started || !p->thread_valid ||
        atomic_load_explicit(&p->finished, memory_order_acquire) ||
        !(p->mask & event) || p->queued_count >= FILE_OBSERVER_QUEUE_LIMIT) return false;
    framework_FileObserverQueuedEvent *node = (framework_FileObserverQueuedEvent *)calloc(1, sizeof(*node));
    if (!node) return false;
    node->event = event;
    if (path && path[0]) {
        node->has_path = true;
        snprintf(node->path, sizeof(node->path), "%s", path);
    }
    if (p->queue_tail) p->queue_tail->next = node;
    else p->queue_head = node;
    p->queue_tail = node;
    p->queued_count++;
    return true;
}

static void framework_file_observer_request_refresh_locked(framework_FileObserverPayload *p, int event) {
    if (p && (event & (ETD2X_FO_CREATE | ETD2X_FO_DELETE | ETD2X_FO_MODIFY |
                       ETD2X_FO_CLOSE_WRITE | ETD2X_FO_ATTRIB |
                       ETD2X_FO_MOVED_FROM | ETD2X_FO_MOVED_TO | ETD2X_FO_MOVE_SELF)))
        p->refresh_requested = true;
}

static void framework_file_observer_dispatch(void *env, framework_FileObserverPayload *p, int event, const char *path) {
    if (!p || !p->observer_global || !(p->mask & event)) return;
    void *observer = etd2x_jni_new_local_ref_host(env, p->observer_global);
    if (!observer) return;
    void *path_ref = path && path[0] ? framework_new_string(env, path) : NULL;
    Etd2xJniValue args[2] = {framework_v_int(event), framework_v_object(path_ref)};
    Etd2xJniValue ignored = {0};
    (void)framework_java_call_virtual(env, observer, "onEvent", "(ILjava/lang/String;)V", args, 2, &ignored);
    if (path_ref) etd2x_jni_delete_local_ref_host(env, path_ref);
    etd2x_jni_delete_local_ref_host(env, observer);
    if (etd2x_jni_exception_pending_host(env)) {
        /* AOSP catches Throwable around each callback and keeps watching. */
        ETD2X_LOGCW("ANDROID", "FileObserver.onEvent threw; continuing path=%s event=%#x",
                    p->guest_path ? p->guest_path : "", event);
        etd2x_jni_exception_clear_host(env);
    }
}

static bool framework_file_observer_copy_path(framework_FileObserverPayload *p, char *out, size_t cap,
                                    bool *out_directory) {
    if (!p || !out || cap == 0) return false;
    pthread_mutex_lock(&p->lock);
    const bool ok = p->host_path && p->host_path[0] &&
                    snprintf(out, cap, "%s", p->host_path) < (int)cap;
    if (out_directory) *out_directory = p->is_directory;
    pthread_mutex_unlock(&p->lock);
    return ok;
}

void etd2x_android_file_observer_notify_event(const char *host_path, int event) {
    if (!host_path || !host_path[0] || !(event & ETD2X_FO_ALL_EVENTS)) return;
    ETD2X_PERF_LOCK(&framework_g_file_observer_lock);
    for (framework_FileObserverPayload *p = framework_g_file_observers; p; p = p->next) {
        pthread_mutex_lock(&p->lock);
        if (!p->started || !p->thread_valid ||
            atomic_load_explicit(&p->finished, memory_order_acquire) || !p->host_path) {
            pthread_mutex_unlock(&p->lock);
            continue;
        }
        char child[ETD2X_FO_NAME_CAP];
        if (p->is_directory &&
            etd2x_file_observer_immediate_child(p->host_path, host_path, child, sizeof(child))) {
            (void)framework_file_observer_queue_locked(p, event, child);
            framework_file_observer_request_refresh_locked(p, event);
        } else if (!p->is_directory && strcmp(p->host_path, host_path) == 0) {
            const int self_event = event == ETD2X_FO_DELETE ? ETD2X_FO_DELETE_SELF : event;
            (void)framework_file_observer_queue_locked(p, self_event, NULL);
            framework_file_observer_request_refresh_locked(p, self_event);
            if (event == ETD2X_FO_DELETE) p->terminal_pending = true;
        }
        pthread_mutex_unlock(&p->lock);
    }
    pthread_mutex_unlock(&framework_g_file_observer_lock);
}

void etd2x_android_file_observer_notify_move(const char *old_host_path,
                                              const char *new_host_path) {
    if (!old_host_path || !old_host_path[0] || !new_host_path || !new_host_path[0]) return;
    if (etd2x_path_lookup_changed) {
        etd2x_path_lookup_changed(old_host_path);
        etd2x_path_lookup_changed(new_host_path);
    }
    ETD2X_PERF_LOCK(&framework_g_file_observer_lock);
    for (framework_FileObserverPayload *p = framework_g_file_observers; p; p = p->next) {
        pthread_mutex_lock(&p->lock);
        if (!p->started || !p->thread_valid ||
            atomic_load_explicit(&p->finished, memory_order_acquire) || !p->host_path) {
            pthread_mutex_unlock(&p->lock);
            continue;
        }
        if (p->is_directory) {
            char old_child[ETD2X_FO_NAME_CAP], new_child[ETD2X_FO_NAME_CAP];
            const bool old_inside = etd2x_file_observer_immediate_child(
                p->host_path, old_host_path, old_child, sizeof(old_child));
            const bool new_inside = etd2x_file_observer_immediate_child(
                p->host_path, new_host_path, new_child, sizeof(new_child));
            if (old_inside) (void)framework_file_observer_queue_locked(p, ETD2X_FO_MOVED_FROM, old_child);
            if (new_inside) (void)framework_file_observer_queue_locked(p, ETD2X_FO_MOVED_TO, new_child);
            if (old_inside || new_inside) p->refresh_requested = true;
        } else if (strcmp(p->host_path, old_host_path) == 0) {
            (void)framework_file_observer_queue_locked(p, ETD2X_FO_MOVE_SELF, NULL);
            char *replacement = strdup(new_host_path);
            if (replacement) {
                free(p->host_path);
                p->host_path = replacement;
            }
            p->refresh_requested = true;
        } else if (strcmp(p->host_path, new_host_path) == 0 &&
                   strcmp(old_host_path, new_host_path) != 0) {
            /* An active exact watch on the destination implies that the
             * destination existed before replacement. */
            (void)framework_file_observer_queue_locked(p, ETD2X_FO_DELETE_SELF, NULL);
            p->terminal_pending = true;
        }
        pthread_mutex_unlock(&p->lock);
    }
    pthread_mutex_unlock(&framework_g_file_observer_lock);
}

static void framework_file_observer_capture_baseline(framework_FileObserverPayload *p,
                                           struct stat *file_stat, bool *framework_file_exists,
                                           Etd2xFileObserverDirectorySnapshot *directory) {
    if (file_stat) memset(file_stat, 0, sizeof(*file_stat));
    if (framework_file_exists) *framework_file_exists = false;
    etd2x_file_observer_release_directory(directory);
    char path[PATH_CAP];
    bool is_directory = false;
    if (!framework_file_observer_copy_path(p, path, sizeof(path), &is_directory)) return;
    struct stat st;
    const bool exists = stat(path, &st) == 0;
    if (framework_file_exists) *framework_file_exists = exists;
    if (file_stat && exists) *file_stat = st;
    if (exists && is_directory)
        (void)etd2x_file_observer_scan_directory(path, directory);
}

static void *framework_file_observer_worker(void *opaque) {
    framework_FileObserverPayload *p = (framework_FileObserverPayload *)opaque;
    if (etd2x_thread_policy_pin_background) (void)etd2x_thread_policy_pin_background();
    void *env = NULL;
    if (etd2x_jni_attach_current_thread_host(&env) != ETD2X_OK) {
        atomic_store_explicit(&p->finished, true, memory_order_release);
        return NULL;
    }

    struct stat previous = {0};
    bool had_previous = false;
    Etd2xFileObserverDirectorySnapshot previous_directory = {0};
    framework_file_observer_capture_baseline(p, &previous, &had_previous, &previous_directory);

    while (!atomic_load_explicit(&p->stop, memory_order_acquire) &&
           !etd2x_jni_process_exit_requested(NULL, 0)) {
        struct timespec delay = {0, 100000000L};
        nanosleep(&delay, NULL);
        if (atomic_load_explicit(&p->stop, memory_order_acquire)) break;

        framework_FileObserverQueuedEvent *queued = NULL;
        bool refresh = false, terminal = false;
        pthread_mutex_lock(&p->lock);
        queued = p->queue_head;
        p->queue_head = p->queue_tail = NULL;
        p->queued_count = 0;
        refresh = p->refresh_requested;
        p->refresh_requested = false;
        terminal = p->terminal_pending;
        p->terminal_pending = false;
        pthread_mutex_unlock(&p->lock);

        while (queued) {
            framework_FileObserverQueuedEvent *next = queued->next;
            framework_file_observer_dispatch(env, p, queued->event,
                                   queued->has_path ? queued->path : NULL);
            free(queued);
            queued = next;
        }
        if (terminal) break;
        if (refresh) {
            framework_file_observer_capture_baseline(p, &previous, &had_previous, &previous_directory);
            continue;
        }

        char path[PATH_CAP];
        bool is_directory = false;
        if (!framework_file_observer_copy_path(p, path, sizeof(path), &is_directory)) break;
        struct stat current = {0};
        const bool has_current = stat(path, &current) == 0;
        if (!has_current) {
            framework_file_observer_dispatch(env, p, ETD2X_FO_DELETE_SELF, NULL);
            break;
        }

        if (is_directory) {
            Etd2xFileObserverDirectorySnapshot next_directory = {0};
            if (etd2x_file_observer_scan_directory(path, &next_directory)) {
                const size_t max_events = previous_directory.count + next_directory.count + 8u;
                Etd2xFileObserverEvent *events =
                    (Etd2xFileObserverEvent *)calloc(max_events ? max_events : 1u, sizeof(*events));
                if (events) {
                    const size_t count = etd2x_file_observer_diff_directory(
                        p->mask, &previous_directory, &next_directory, events, max_events);
                    for (size_t i = 0; i < count; ++i)
                        framework_file_observer_dispatch(env, p, events[i].event,
                                               events[i].has_path ? events[i].path : NULL);
                    free(events);
                }
                etd2x_file_observer_release_directory(&previous_directory);
                previous_directory = next_directory;
            }
            previous = current;
            had_previous = true;
            continue;
        }

        if (had_previous && previous.st_ino && current.st_ino &&
            previous.st_ino != current.st_ino) {
            framework_file_observer_dispatch(env, p, ETD2X_FO_DELETE_SELF, NULL);
            break;
        }
        const int event = framework_file_observer_pick_event(p->mask, had_previous, &previous,
                                                   true, &current);
        if (event) framework_file_observer_dispatch(env, p, event, NULL);
        previous = current;
        had_previous = true;
    }

    etd2x_file_observer_release_directory(&previous_directory);
    atomic_store_explicit(&p->finished, true, memory_order_release);
    etd2x_jni_detach_current_thread_host();
    return NULL;
}

static Etd2xJniValue framework_file_observer_ctor(void *env, void *token, const Etd2xJniValue *a,
                                        size_t n, void *ud) {
    (void)ud;
    if (!token || n < 1 || n > 2 || !a || !a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "path == null");
        return framework_v_void();
    }
    char guest[PATH_CAP];
    if (!framework_read_jstring(a[0].l, guest, sizeof(guest))) return framework_v_void();
    char mapped[PATH_CAP];
    const char *host = framework_framework_file_host_path(guest, mapped, sizeof(mapped));
    if (!host) return framework_v_void();

    framework_FileObserverPayload *p = framework_file_observer_payload(token);
    if (!p) {
        p = (framework_FileObserverPayload *)calloc(1, sizeof(*p));
        if (!p) {
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "FileObserver");
            return framework_v_void();
        }
        p->magic = FILE_OBSERVER_PAYLOAD_MAGIC;
        pthread_mutex_init(&p->lock, NULL);
        atomic_store_explicit(&p->finished, true, memory_order_release);
        ETD2X_PERF_LOCK(&framework_g_file_observer_lock);
        p->next = framework_g_file_observers;
        framework_g_file_observers = p;
        pthread_mutex_unlock(&framework_g_file_observer_lock);
        (void)etd2x_jni_set_token_host_data(token, p);
    }
    pthread_mutex_lock(&p->lock);
    free(p->guest_path);
    free(p->host_path);
    p->guest_path = strdup(guest);
    p->host_path = strdup(host);
    p->mask = (n == 2 ? a[1].i : ETD2X_FO_ALL_EVENTS) & ETD2X_FO_ALL_EVENTS;
    pthread_mutex_unlock(&p->lock);
    if (!p->guest_path || !p->host_path)
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "FileObserver path");
    return framework_v_void();
}

static Etd2xJniValue framework_file_observer_ctor_file(void *env, void *token, const Etd2xJniValue *a,
                                             size_t n, void *ud) {
    (void)ud;
    if (!token || n < 1 || n > 2 || !a || !a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "file == null");
        return framework_v_void();
    }
    framework_FilePayload *file = (framework_FilePayload *)etd2x_jni_get_object_host_data(a[0].l);
    if (!file || !file->path) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "invalid File");
        return framework_v_void();
    }
    void *path = framework_new_string(env, file->path);
    if (!path) return framework_v_void();
    Etd2xJniValue converted[2] = {framework_v_object(path), framework_v_int(n == 2 ? a[1].i : ETD2X_FO_ALL_EVENTS)};
    Etd2xJniValue result = framework_file_observer_ctor(env, token, converted, 2, NULL);
    etd2x_jni_delete_local_ref_host(env, path);
    return result;
}

static Etd2xJniValue framework_file_observer_start(void *env, void *token, const Etd2xJniValue *a,
                                         size_t n, void *ud) {
    (void)a; (void)n; (void)ud;
    framework_FileObserverPayload *p = framework_file_observer_payload(token);
    if (!p) return framework_v_void();

    pthread_mutex_lock(&p->lock);
    if (p->started) {
        pthread_mutex_unlock(&p->lock);
        return framework_v_void();
    }
    p->started = true; /* even a missing target consumes this start until stopWatching() */
    const bool join_old = p->thread_valid;
    atomic_store_explicit(&p->stop, true, memory_order_release);
    pthread_mutex_unlock(&p->lock);

    if (join_old && !pthread_equal(p->thread, pthread_self())) {
        (void)pthread_join(p->thread, NULL);
        pthread_mutex_lock(&p->lock);
        p->thread_valid = false;
        pthread_mutex_unlock(&p->lock);
    }

    char path[PATH_CAP];
    bool ignored = false;
    if (!framework_file_observer_copy_path(p, path, sizeof(path), &ignored)) return framework_v_void();
    struct stat st;
    if (stat(path, &st) != 0) return framework_v_void();

    void *self = etd2x_jni_new_local_from_token(env, token);
    if (!self) return framework_v_void();
    pthread_mutex_lock(&p->lock);
    if (p->observer_global) etd2x_jni_delete_global_ref_host(env, p->observer_global);
    p->observer_global = etd2x_jni_new_global_ref_host(env, self);
    p->is_directory = S_ISDIR(st.st_mode);
    p->refresh_requested = false;
    p->terminal_pending = false;
    framework_file_observer_queue_clear_locked(p);
    atomic_store_explicit(&p->stop, false, memory_order_release);
    atomic_store_explicit(&p->finished, false, memory_order_release);
    pthread_mutex_unlock(&p->lock);
    etd2x_jni_delete_local_ref_host(env, self);
    if (!p->observer_global) return framework_v_void();

    /* onEvent runs guest Java (and any JNI it reaches) on this thread, so it
     * gets the Java thread stack contract, not the ~128 KiB libnx default. */
    pthread_attr_t attr;
    int create_rc = pthread_attr_init(&attr);
    if (create_rc == 0) create_rc = pthread_attr_setstacksize(&attr, etd2x_android_java_thread_stack_size());
    if (create_rc == 0)
        create_rc = (etd2x_host_pthread_create ? etd2x_host_pthread_create : pthread_create)
            (&p->thread, &attr, framework_file_observer_worker, p);
    (void)pthread_attr_destroy(&attr);
    if (create_rc != 0) {
        pthread_mutex_lock(&p->lock);
        atomic_store_explicit(&p->finished, true, memory_order_release);
        etd2x_jni_delete_global_ref_host(env, p->observer_global);
        p->observer_global = NULL;
        pthread_mutex_unlock(&p->lock);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalStateException",
                                          "FileObserver thread create failed");
        return framework_v_void();
    }
    pthread_mutex_lock(&p->lock);
    p->thread_valid = true;
    pthread_mutex_unlock(&p->lock);
    return framework_v_void();
}

static Etd2xJniValue framework_file_observer_stop(void *env, void *token, const Etd2xJniValue *a,
                                        size_t n, void *ud) {
    (void)env; (void)a; (void)n; (void)ud;
    framework_FileObserverPayload *p = framework_file_observer_payload(token);
    if (!p) return framework_v_void();
    pthread_mutex_lock(&p->lock);
    p->started = false;
    atomic_store_explicit(&p->stop, true, memory_order_release);
    framework_file_observer_queue_clear_locked(p);
    pthread_mutex_unlock(&p->lock);
    return framework_v_void();
}

static void framework_file_observer_reset(void *env) {
    ETD2X_PERF_LOCK(&framework_g_file_observer_lock);
    for (framework_FileObserverPayload *p = framework_g_file_observers; p; p = p->next) {
        pthread_mutex_lock(&p->lock);
        p->started = false;
        atomic_store_explicit(&p->stop, true, memory_order_release);
        pthread_mutex_unlock(&p->lock);
    }
    framework_FileObserverPayload *list = framework_g_file_observers;
    framework_g_file_observers = NULL;
    pthread_mutex_unlock(&framework_g_file_observer_lock);

    while (list) {
        framework_FileObserverPayload *next = list->next;
        if (list->thread_valid && !pthread_equal(list->thread, pthread_self()))
            (void)pthread_join(list->thread, NULL);
        if (list->observer_global) etd2x_jni_delete_global_ref_host(env, list->observer_global);
        pthread_mutex_lock(&list->lock);
        framework_file_observer_queue_clear_locked(list);
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list->guest_path);
        free(list->host_path);
        list->magic = 0;
        free(list);
        list = next;
    }
}

static bool framework_framework_permission_granted(const char *permission) {
    if (!permission) return false;
    static const char *const normal[] = {
        "android.permission.INTERNET", "android.permission.ACCESS_NETWORK_STATE",
        "android.permission.ACCESS_WIFI_STATE", "android.permission.WAKE_LOCK",
        "android.permission.MODIFY_AUDIO_SETTINGS", "android.permission.FOREGROUND_SERVICE",
        "android.permission.VIBRATE"
    };
    for (size_t i=0;i<framework_ARRAY_COUNT(normal);++i) if(strcmp(permission,normal[i])==0) return true;

    /* ETD2X provides an app-scoped writable external-storage backend under the
     * guest /storage/emulated/0 tree. Legacy Android applications commonly
     * gate all external-file access on READ/WRITE_EXTERNAL_STORAGE even when
     * they only use their own Android/data/<package> directory. Report these
     * legacy capabilities as granted when that virtual backend is configured.
     * This does not grant unrelated hardware-backed dangerous permissions. */
    if (framework_g_fw.root[0] &&
        (strcmp(permission, "android.permission.READ_EXTERNAL_STORAGE") == 0 ||
         strcmp(permission, "android.permission.WRITE_EXTERNAL_STORAGE") == 0))
        return true;

    /* Runtime/dangerous or hardware-backed permissions remain denied until a
     * real permission/capability backend exists (camera, microphone, location, etc.). */
    return false;
}
static Etd2xJniValue framework_context_check_permission(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)ud; char permission[256];
    if(n!=1||!args||!args[0].l||!framework_read_jstring(args[0].l,permission,sizeof(permission))) return framework_v_int(-1);
    const bool granted=framework_framework_permission_granted(permission);
    ETD2X_LOGCI("ANDROID","Context.checkCallingOrSelfPermission permission=%s result=%s",permission,granted?"granted":"denied");
    return framework_v_int(granted?0:-1);
}
/* Context.checkPermission(permission, pid, uid): root and system uids hold
 * every permission; this process's pid/uid gets its own grants; the runtime
 * hosts no other process, so any other identity is denied. */
static Etd2xJniValue framework_context_check_permission_pid_uid(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)ud; char permission[256];
    if (n != 3 || !args) return framework_v_int(-1);
    if (!args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "permission is null");
        return framework_v_int(-1);
    }
    if (!framework_read_jstring(args[0].l, permission, sizeof(permission))) return framework_v_int(-1);
    const int32_t uid = args[2].i, pid = args[1].i, self_pid = getpid() > 0 ? getpid() : 1;
    const bool granted = uid == 0 || uid == 1000 ||
                         (uid == 10000 && pid == self_pid && framework_framework_permission_granted(permission));
    ETD2X_LOGCI("ANDROID", "Context.checkPermission permission=%s pid=%d uid=%d result=%s",
                permission, pid, uid, granted ? "granted" : "denied");
    return framework_v_int(granted ? 0 : -1);
}
/* ETD2X has no permission-controller UI, so there is no user-driven prior
 * denial/rationale state to expose here. */
static Etd2xJniValue framework_activity_should_show_permission_rationale(void *env, void *token, const Etd2xJniValue *args,
                                                               size_t n, void *ud) {
    (void)env; (void)token; (void)args; (void)n; (void)ud;
    return framework_v_bool(false);
}
/* Activity.requestPermissions(): ETD2X has no system permission-controller UI, so
 * resolve each requested permission against the runtime's real capabilities and
 * deliver the standard Activity callback immediately. The callback is virtual:
 * package/Unity overrides therefore run exactly as they would after Android's
 * permission controller returns a result. */
static Etd2xJniValue framework_activity_request_permissions(void *env, void *token, const Etd2xJniValue *args,
                                                   size_t n, void *ud) {
    (void)ud;
    if (n != 2 || !args || !args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException",
                                          "permissions must not be null");
        return framework_v_void();
    }

    const int32_t count = etd2x_jni_array_length_host(args[0].l);
    if (count < 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException",
                                          "permissions must be a String array");
        return framework_v_void();
    }

    void *results = etd2x_jni_new_local_int_array(env, count);
    if (!results && count != 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError",
                                          "permission result array allocation failed");
        return framework_v_void();
    }

    for (int32_t i = 0; i < count; ++i) {
        void *permission_ref = NULL;
        char permission[256] = {0};
        bool granted = false;
        if (etd2x_jni_get_object_array_element_host(env, args[0].l, i, &permission_ref) == ETD2X_OK &&
            permission_ref && framework_read_jstring(permission_ref, permission, sizeof(permission))) {
            granted = framework_framework_permission_granted(permission);
        }
        const int32_t result = granted ? 0 : -1; /* PackageManager.PERMISSION_* */
        (void)etd2x_jni_int_array_write(results, i, 1, &result);
        ETD2X_LOGCI("ANDROID", "Activity.requestPermissions permission=%s result=%s requestCode=%d",
                    permission[0] ? permission : "<invalid>", granted ? "granted" : "denied", args[1].i);
        if (permission_ref) etd2x_jni_delete_local_ref_host(env, permission_ref);
    }

    void *self = etd2x_jni_new_local_from_token(env, token);
    if (self) {
        Etd2xJniValue callback_args[3] = {{0}};
        Etd2xJniValue ignored = {0};
        callback_args[0].i = args[1].i;
        callback_args[1].l = args[0].l;
        callback_args[2].l = results;
        if (!framework_java_call_virtual(env, self, "onRequestPermissionsResult", "(I[Ljava/lang/String;[I)V",
                               callback_args, framework_ARRAY_COUNT(callback_args), &ignored) &&
            etd2x_jni_exception_pending_host(env)) {
            ETD2X_LOGCW("ANDROID", "Activity.requestPermissions callback failed requestCode=%d", args[1].i);
        }
        etd2x_jni_delete_local_ref_host(env, self);
    }
    if (results) etd2x_jni_delete_local_ref_host(env, results);
    return framework_v_void();
}
static Etd2xJniValue framework_power_new_wake_lock(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)args; (void)ud; if(n!=2)return framework_v_object(NULL); void *ref=etd2x_jni_new_local_object(env,"android/os/PowerManager$WakeLock");
    if(ref) framework_set_instance_bool_field(ref,"held",false);
    return framework_v_object(ref);
}
