static Etd2xAssetManager *framework_asset_manager_receiver(void *token) {
    Etd2xAssetManager *manager = (Etd2xAssetManager *)etd2x_jni_get_token_host_data(token);
    return manager ? manager : etd2x_assets_manager();
}

static Etd2xJniValue framework_asset_manager_open_java(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    if (n != 1 && n != 2) return framework_v_object(NULL);
    char name[PATH_CAP];
    if (!framework_read_jstring(a[0].l, name, sizeof(name))) return framework_v_object(NULL);
    const int mode = n == 2 ? a[1].i : ETD2X_AASSET_MODE_STREAMING;
    Etd2xAsset *asset = etd2x_asset_open(framework_asset_manager_receiver(t), name, mode);
    if (!asset) {
        etd2x_jni_throw_new_by_name(env, "java/io/FileNotFoundException", name);
        return framework_v_object(NULL);
    }
    void *stream = etd2x_jni_new_local_object(env, "android/content/res/AssetManager$AssetInputStream");
    if (!stream || etd2x_jni_set_object_host_data(stream, asset) != ETD2X_OK) {
        etd2x_asset_close(asset);
        return framework_v_object(NULL);
    }
    return framework_v_object(stream);
}

static Etd2xJniValue framework_asset_manager_list_java(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    if (n != 1) return framework_v_object(NULL);
    char name[PATH_CAP];
    if (!framework_read_jstring(a[0].l, name, sizeof(name))) return framework_v_object(NULL);
    Etd2xAssetDir *dir = etd2x_asset_open_dir(framework_asset_manager_receiver(t), name);
    if (!dir) return framework_v_object(NULL);
    int32_t count = 0;
    while (etd2x_asset_dir_next(dir)) count++;
    etd2x_asset_dir_rewind(dir);
    void *array = etd2x_jni_new_local_object_array(env, count);
    if (!array) { etd2x_asset_dir_close(dir); return framework_v_object(NULL); }
    for (int32_t i = 0; i < count; ++i) {
        const char *entry = etd2x_asset_dir_next(dir);
        void *str = framework_new_string(env, entry ? entry : "");
        if (!str || etd2x_jni_set_object_array_element_host(env, array, i, str) != ETD2X_OK) {
            if (str) etd2x_jni_delete_local_ref_host(env, str);
            etd2x_asset_dir_close(dir);
            return framework_v_object(NULL);
        }
        etd2x_jni_delete_local_ref_host(env, str);
    }
    etd2x_asset_dir_close(dir);
    return framework_v_object(array);
}

