/* ---------- java.io.PrintStream ----------
 * ETD2X has no POSIX stdout/stderr stream exposed to guest Java. Preserve the
 * Java API and route textual output into the runtime diagnostic log instead. */
static Etd2xJniValue framework_print_stream_text(void *env, void *token,
                                       const Etd2xJniValue *a, size_t n, void *u) {
    (void)env; (void)token;
    const bool newline = (uintptr_t)u != 0u;
    char text[1024] = {0};
    if (n == 0) {
        if (newline) ETD2X_LOGCI("JAVA-STDIO", "%s", "");
        return framework_v_void();
    }
    if (n != 1) return framework_v_void();
    if (!a || !a[0].l) {
        framework_copy_text(text, sizeof(text), "null", "");
    } else if (!framework_read_jstring(a[0].l, text, sizeof(text))) {
        char cls[256] = {0};
        if (etd2x_jni_object_class_name_host(a[0].l, cls, sizeof(cls)))
            snprintf(text, sizeof(text), "<%s>", cls);
        else
            framework_copy_text(text, sizeof(text), "<object>", "");
    }
    ETD2X_LOGCI("JAVA-STDIO", "%s%s", text, newline ? "\n" : "");
    return framework_v_void();
}
static Etd2xJniValue framework_print_stream_flush(void *env, void *token,
                                        const Etd2xJniValue *a, size_t n, void *u) {
    (void)env; (void)token; (void)a; (void)n; (void)u;
    return framework_v_void();
}

/* ---------- Class loader ---------- */
static Etd2xJniValue framework_class_lookup_name(void *env, const Etd2xJniValue *a,
                                           size_t n, bool initialize) {
    if (!a || n < 1 || !a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "class name");
        return framework_v_object(NULL);
    }
    char name[512];
    if (!framework_read_jstring(a[0].l, name, sizeof(name))) return framework_v_object(NULL);
    /* Class.forName/ClassLoader.loadClass take Java binary names. ETD2X's JNI
     * registry uses slash-form names; array descriptors also normalize safely. */
    for (char *p = name; *p; ++p) if (*p == '.') *p = '/';
    void *clazz = etd2x_jni_find_class_ref(env, name);
    if (!clazz) {
        ETD2X_LOGCI("JAVA", "class lookup failed name=%s initialize=%d exceptionPending=%d",
                    name, initialize ? 1 : 0, etd2x_jni_exception_pending_host(env) ? 1 : 0);
        return framework_v_object(NULL);
    }
    if (initialize) {
        const Etd2xResult rc = etd2x_jni_initialize_class_host(env, name);
        if (rc != ETD2X_OK || etd2x_jni_exception_pending_host(env)) {
            etd2x_jni_delete_local_ref_host(env, clazz);
            return framework_v_object(NULL);
        }
    }
    return framework_v_object(clazz);
}
static Etd2xJniValue framework_class_for_name(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){
    (void)t;(void)u;return framework_class_lookup_name(env,a,n,true);
}
static Etd2xJniValue framework_class_for_name_loader(void*,void*,const Etd2xJniValue*,size_t,void*);
static Etd2xJniValue framework_classloader_load(void*,void*,const Etd2xJniValue*,size_t,void*);
static Etd2xJniValue framework_classloader_ctor(void*,void*,const Etd2xJniValue*,size_t,void*);
/* BaseDexClassLoader constructors (DexClassLoader, PathClassLoader): each
 * File.pathSeparator-separated dexPath element joins the class path searched
 * after the parent loaders. Like DexPathList, unreadable elements are logged
 * and skipped rather than thrown. optimizedDirectory is ignored since API 26;
 * native library paths stay with the package's linker namespace. */
static Etd2xJniValue framework_base_dex_class_loader_ctor(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){
    (void)u;
    if(n<1)return framework_v_void();
    (void)framework_classloader_ctor(env,t,a+n-1,1,NULL);
    if(!a[0].l){(void)etd2x_jni_throw_new_by_name(env,"java/lang/NullPointerException","dexPath == null");return framework_v_void();}
    char paths[PATH_CAP*4];
    if(!framework_read_jstring(a[0].l,paths,sizeof(paths)))return framework_v_void();
    char *save=NULL;
    for(char *element=strtok_r(paths,":",&save);element;element=strtok_r(NULL,":",&save)){
        if(!element[0])continue;
        char mapped[PATH_CAP];
        const char *host=framework_framework_file_host_path(element,mapped,sizeof(mapped));
        size_t images=0;
        const Etd2xResult rc=host&&etd2x_package_add_secondary_dex
            ?etd2x_package_add_secondary_dex(host,&images):ETD2X_ERR_APK_UNSUPPORTED;
        if(rc==ETD2X_OK)ETD2X_LOGCI("JAVA","BaseDexClassLoader dexPath element=%s images=%zu",element,images);
        else ETD2X_LOGCW("JAVA","BaseDexClassLoader unable to load dex element=%s rc=%d",element,(int)rc);
    }
    return framework_v_void();
}

/* ClassLoader delegation and loaded-class ownership live in class_loader.inc.
 * A miss is null. The app loader retains ART's PathClassLoader metadata fast
 * path; custom loaders only query recorded classes. Neither initializes. */
