struct framework_GmsPackage;                                                               /* framework/gms_presence.inc */
static struct framework_GmsPackage *framework_gms_package_arg(const Etd2xJniValue *a, size_t n);
static void *framework_gms_package_info_local(void *env, struct framework_GmsPackage *pkg, int32_t flags);
static void *framework_gms_application_info_local(void *env, struct framework_GmsPackage *pkg);
static void framework_pm_package_info_components(void *env, void *package_info, int32_t flags); /* api_compat_registration.inc */
static bool framework_package_arg_matches(const Etd2xJniValue*a,size_t n){char p[160];return n>=1&&framework_read_jstring(a[0].l,p,sizeof(p))&&strcmp(p,framework_g_fw.package_name)==0;}
static void *framework_pm_package_snapshot(void *env, int32_t flags) {
    static const struct { const char *name, *sig; int32_t flag; } fields[] = {
        {"packageName", "Ljava/lang/String;", 0}, {"versionName", "Ljava/lang/String;", 0},
        {"versionCode", "I", 0}, {"applicationInfo", "Landroid/content/pm/ApplicationInfo;", 0},
        {"firstInstallTime", "J", 0}, {"lastUpdateTime", "J", 0},
        {"activities", "[Landroid/content/pm/ActivityInfo;", PM_GET_ACTIVITIES},
        {"receivers", "[Landroid/content/pm/ActivityInfo;", PM_GET_RECEIVERS},
        {"services", "[Landroid/content/pm/ServiceInfo;", PM_GET_SERVICES},
        {"signatures", "[Landroid/content/pm/Signature;", PM_GET_SIGNATURES},
        {"signingInfo", "Landroid/content/pm/SigningInfo;", PM_GET_SIGNING_CERTIFICATES},
    };
    void *info = etd2x_jni_new_local_object(env, "android/content/pm/PackageInfo");
    if (!info) return NULL;
    for (size_t i = 0; i < framework_ARRAY_COUNT(fields); ++i) {
        if (fields[i].flag && !(flags & fields[i].flag)) continue;
        Etd2xJniValue value = {0}; bool found = false;
        (void)etd2x_jni_get_instance_field_value(env, framework_g_fw.package_info, "android/content/pm/PackageInfo", fields[i].name, fields[i].sig, &value, &found);
        if (found) (void)etd2x_jni_set_instance_field_value(info, fields[i].name, fields[i].sig, value);
        if (value.l && (fields[i].sig[0] == 'L' || fields[i].sig[0] == '[')) etd2x_jni_delete_local_ref_host(env, value.l);
    }
    return info;
}
static void framework_pm_requested_permissions(void *env, void *info, int32_t flags) {
    if (!(flags & 0x1000) || !etd2x_apk_requested_permissions) return; /* GET_PERMISSIONS */
    char **names = NULL;
    size_t count = 0;
    Etd2xResult rc = etd2x_apk_requested_permissions(framework_g_fw.source_path, (uint32_t)framework_g_fw.compat.platform_api, &names, &count);
    if (rc != ETD2X_OK) {
        ETD2X_LOGCW("ANDROID", "PackageInfo requested permissions unavailable rc=%d", (int)rc);
        return;
    }
    if (count && count <= INT32_MAX) {
        void *permissions = etd2x_jni_new_local_reference_array(env, "[Ljava/lang/String;", (int32_t)count);
        void *permission_flags = etd2x_jni_new_local_int_array(env, (int32_t)count);
        for (size_t i = 0; permissions && permission_flags && i < count; ++i) {
            void *name = framework_new_string(env, names[i]);
            (void)etd2x_jni_set_object_array_element_host(env, permissions, (int32_t)i, name);
            if (name) etd2x_jni_delete_local_ref_host(env, name);
            const int32_t bits = 1 | (framework_framework_permission_granted(names[i]) ? 2 : 0);
            (void)etd2x_jni_int_array_write(permission_flags, (int32_t)i, 1, &bits);
        }
        framework_set_instance_object_field(info, "requestedPermissions", "[Ljava/lang/String;", permissions);
        framework_set_instance_object_field(info, "requestedPermissionsFlags", "[I", permission_flags);
        if (permissions) etd2x_jni_delete_local_ref_host(env, permissions);
        if (permission_flags) etd2x_jni_delete_local_ref_host(env, permission_flags);
    }
    for (size_t i = 0; i < count; ++i) free(names[i]);
    free(names);
    ETD2X_LOGCI("ANDROID", "PackageInfo requested permissions count=%zu", count);
}
static Etd2xJniValue framework_pm_package_info(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){
    (void)t;(void)u;
    struct framework_GmsPackage *google=n==2?framework_gms_package_arg(a,n):NULL;
    if(google){void *gms=framework_gms_package_info_local(env,google,a[1].i);if(gms)return framework_v_object(gms);}
    if(n!=2||!framework_package_arg_matches(a,n)){
        char p[160]="<invalid>"; if(n>=1&&a&&a[0].l)(void)framework_read_jstring(a[0].l,p,sizeof(p));
        ETD2X_LOGCI("ANDROID","PackageManager.getPackageInfo package=%s flags=0x%x result=NameNotFound",p,n>=2?(unsigned)a[1].i:0u);
        etd2x_jni_throw_new_by_name(env,"android/content/pm/PackageManager$NameNotFoundException","package not found");return framework_v_object(NULL);
    }
    framework_package_signing_apply_flags(env, a[1].i);
    framework_pm_package_info_components(env, framework_g_fw.package_info, a[1].i);
    ETD2X_LOGCI("ANDROID","PackageManager.getPackageInfo package=%s flags=0x%x result=ok signing=%s",
                framework_g_fw.package_name, (unsigned)a[1].i,
                ((a[1].i & (PM_GET_SIGNATURES | PM_GET_SIGNING_CERTIFICATES)) != 0)
                    ? (framework_g_fw.package_signatures ? "ready" : "unavailable") : "not-requested");
    void *info = framework_pm_package_snapshot(env, a[1].i);
    if (info) framework_pm_requested_permissions(env, info, a[1].i);
    return framework_v_object(info);
}
static Etd2xJniValue framework_pm_application_info(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){
    (void)t;(void)u;
    struct framework_GmsPackage *google=n==2?framework_gms_package_arg(a,n):NULL;
    if(google){void *gms=framework_gms_application_info_local(env,google);if(gms)return framework_v_object(gms);}
    if(n!=2||!framework_package_arg_matches(a,n)){
        char p[160]="<invalid>"; if(n>=1&&a&&a[0].l)(void)framework_read_jstring(a[0].l,p,sizeof(p));
        ETD2X_LOGCI("ANDROID","PackageManager.getApplicationInfo package=%s flags=0x%x result=NameNotFound",p,n>=2?(unsigned)a[1].i:0u);
        etd2x_jni_throw_new_by_name(env,"android/content/pm/PackageManager$NameNotFoundException","package not found");return framework_v_object(NULL);
    }
    const bool meta=(a[1].i&0x80)!=0&&framework_g_fw.application_info_meta;/* GET_META_DATA */return framework_v_object(framework_local_from_global(env,meta?framework_g_fw.application_info_meta:framework_g_fw.application_info));
}
