/* package features */
/* Package feature queries describe available backends, not SDK class presence. */
static Etd2xJniValue framework_legacy_am_get_device_configuration(void *,void *,const Etd2xJniValue *,size_t,void *);
static const char *const framework_pm_device_features[] = {
    "android.hardware.touchscreen", "android.hardware.faketouch",
    "android.hardware.touchscreen.multitouch", "android.hardware.touchscreen.multitouch.distinct",
    "android.hardware.touchscreen.multitouch.jazzhand",
    "android.hardware.screen.landscape", "android.hardware.screen.portrait",
};
static bool framework_pm_device_feature(size_t index) {
    if (index < 5) {
        const bool finger = framework_g_fw.cfg.touchscreen == ETD2X_ACONFIGURATION_TOUCHSCREEN_FINGER;
        return finger && (index < 2 || (index < 4 ? ETD2X_INPUT_MAX_TOUCHES >= 2 : ETD2X_INPUT_MAX_TOUCHES >= 5));
    }
    if (framework_g_fw.cfg.width_pixels <= 0 || framework_g_fw.cfg.height_pixels <= 0) return false;
    return framework_g_fw.cfg.request_orientation || (index == 5
        ? framework_g_fw.cfg.width_pixels > framework_g_fw.cfg.height_pixels
        : framework_g_fw.cfg.width_pixels < framework_g_fw.cfg.height_pixels);
}
static Etd2xJniValue framework_pm_feature(void *env,void *token,const Etd2xJniValue *a,size_t n,void *u) {
    (void)env;(void)token;(void)u;
    if ((n != 1 && n != 2) || !a[0].l || (n == 2 && a[1].i > 0)) return framework_v_bool(false);
    char name[128];
    if (!framework_read_jstring(a[0].l,name,sizeof(name))) return framework_v_bool(false);
    bool supported = false;
    for (size_t i = 0; i < framework_ARRAY_COUNT(framework_pm_device_features); ++i)
        if (strcmp(name,framework_pm_device_features[i]) == 0) { supported = framework_pm_device_feature(i); break; }
    return framework_v_bool(supported);
}
static Etd2xJniValue framework_pm_feature_list(void *env,void *token,const Etd2xJniValue *a,size_t n,void *u) {
    (void)token;(void)a;(void)u;
    if (n) return framework_v_object(NULL);
    size_t count = 0;
    for (size_t i = 0; i < framework_ARRAY_COUNT(framework_pm_device_features); ++i) count += framework_pm_device_feature(i);
    void *array = etd2x_jni_new_local_reference_array(env,"[Landroid/content/pm/FeatureInfo;",(int32_t)count+1);
    if (!array) return framework_v_object(NULL);
    size_t index = 0;
    for (size_t i = 0; i < framework_ARRAY_COUNT(framework_pm_device_features); ++i) if (framework_pm_device_feature(i)) {
        void *info = etd2x_jni_new_local_object(env,"android/content/pm/FeatureInfo");
        if (!info) { etd2x_jni_delete_local_ref_host(env,array); return framework_v_object(NULL); }
        void *name = framework_new_string(env,framework_pm_device_features[i]);
        if (!name) {
            etd2x_jni_delete_local_ref_host(env,info);etd2x_jni_delete_local_ref_host(env,array);
            return framework_v_object(NULL);
        }
        framework_set_instance_object_field(info,"name","Ljava/lang/String;",name);
        if (name) etd2x_jni_delete_local_ref_host(env,name);
        framework_set_instance_int_field(info,"version",0);framework_set_instance_int_field(info,"flags",0);
        framework_set_instance_int_field(info,"reqGlEsVersion",0);
        (void)etd2x_jni_set_object_array_element_host(env,array,(int32_t)index++,info);
        etd2x_jni_delete_local_ref_host(env,info);
    }
    Etd2xJniValue configuration = framework_legacy_am_get_device_configuration(env,NULL,NULL,0,NULL);
    void *gles = etd2x_jni_new_local_object(env,"android/content/pm/FeatureInfo");
    if (gles && configuration.l) {
        framework_set_instance_int_field(gles,"reqGlEsVersion",framework_get_instance_int_field(env,configuration.l,
            "android/content/pm/ConfigurationInfo","reqGlEsVersion"));
        (void)etd2x_jni_set_object_array_element_host(env,array,(int32_t)index,gles);
    }
    if (gles) etd2x_jni_delete_local_ref_host(env,gles);
    if (configuration.l) etd2x_jni_delete_local_ref_host(env,configuration.l);
    if (!gles || !configuration.l || etd2x_jni_exception_pending_host(env)) {
        etd2x_jni_delete_local_ref_host(env,array); return framework_v_object(NULL);
    }
    return framework_v_object(array);
}



