static bool framework_intent_set_launch_component(framework_IntentPayload *payload) {
    payload->package_name = strdup(framework_g_fw.package_name);
    payload->target_class = strdup(framework_g_fw.activity_class);
    return payload->package_name && payload->target_class &&
        framework_string_list_add_unique(&payload->categories, &payload->category_count,
                               &payload->category_capacity, "android.intent.category.LAUNCHER");
}
static Etd2xJniValue framework_pm_launch_intent(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){
    (void)t;
    (void)u;

    if(n!=1||!framework_package_arg_matches(a,n))
        return framework_v_object(NULL);

    void *intent=etd2x_jni_new_local_object(env,"android/content/Intent");
    if(!intent)
        return framework_v_object(NULL);

    framework_IntentPayload *payload=framework_intent_payload_new(
        etd2x_jni_object_token_host(intent),
        "android.intent.action.MAIN"
    );

    if(!payload){
        etd2x_jni_delete_local_ref_host(env,intent);
        return framework_v_object(NULL);
    }

    if(!framework_intent_set_launch_component(payload)){
        etd2x_jni_delete_local_ref_host(env,intent);
        return framework_v_object(NULL);
    }

    return framework_v_object(intent);
}
