static framework_Property *framework_property_find(const char*key){for(framework_Property*p=framework_g_fw.properties;p;p=p->next)if(strcmp(p->key,key)==0)return p;return NULL;}
static const char *framework_property_get(const char*key){framework_Property*p=framework_property_find(key);return p?p->value:NULL;}
static bool framework_property_set(const char*key,const char*value){framework_Property*p=framework_property_find(key);if(!p){p=calloc(1,sizeof(*p));if(!p)return false;p->key=strdup(key);if(!p->key){free(p);return false;}p->next=framework_g_fw.properties;framework_g_fw.properties=p;}char*v=strdup(value?value:"");if(!v)return false;free(p->value);p->value=v;return true;}
