    if(length)memcpy(mapped+3,name,(size_t)length*sizeof(*mapped));
    mapped[length+3]='.';mapped[length+4]='s';mapped[length+5]='o';
    void *result=etd2x_jni_new_local_string_utf16(env,mapped,length+6);
