/* android.os.Process exposes Linux task identity and nice values.  Keep the
 * Java view aligned with ETD2X's Bionic ABI so native and Java code observe
 * the same current-thread TID/priority whenever compat_threads.c is linked. */
static int32_t framework_android_process_tid(void) {
    if (etd2x_bionic_gettid) return etd2x_bionic_gettid();
    const uintptr_t v = (uintptr_t)pthread_self();
    return (int32_t)(v ? (v & UINT32_C(0x7fffffff)) : 1u);
}
