/* java.lang.Integer.parseInt(String) is used by ordinary Android framework
 * helpers that convert string-valued system properties (including
 * AudioManager output sample rate / frames-per-buffer) to integers. Keep the
 * parser Java-like: optional leading sign, decimal digits only, no whitespace,
 * and signed 32-bit overflow rejection; anything else throws
 * NumberFormatException. */
static bool framework_parse_java_int_decimal(const char *text, int32_t *out_value) {
    if (!text || !*text || !out_value) return false;
    const unsigned char *p = (const unsigned char *)text;
    bool negative = false;
    if (*p == '+' || *p == '-') {
        negative = *p == '-';
        ++p;
        if (!*p) return false;
    }
    const uint64_t limit = negative ? 2147483648ull : 2147483647ull;
    uint64_t value = 0;
    for (; *p; ++p) {
        if (*p < '0' || *p > '9') return false;
        const uint64_t digit = (uint64_t)(*p - '0');
        if (value > (limit - digit) / 10ull) return false;
        value = value * 10ull + digit;
    }
    if (negative) {
        if (value == 2147483648ull) *out_value = INT32_MIN;
        else *out_value = -(int32_t)value;
    } else {
        *out_value = (int32_t)value;
    }
    return true;
}

