static framework_UriPayload *framework_uri_payload_from_token(void *token) {
    framework_UriPayload *payload = (framework_UriPayload *)etd2x_jni_get_token_host_data(token);
    return payload && payload->magic == URI_PAYLOAD_MAGIC ? payload : NULL;
}

static bool framework_uri_encode_allowed(unsigned char c, const char *allow) {
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
        (c >= '0' && c <= '9') || strchr("_-!.~'()*", (int)c)) return true;
    return allow && strchr(allow, (int)c) != NULL;
}

static Etd2xJniValue framework_uri_encode(void *env, void *token, const Etd2xJniValue *args,
                                size_t n, void *ud) {
    (void)token; (void)ud;
    if ((n != 1 && n != 2) || !args) return framework_v_object(NULL);
    if (!args[0].l) return framework_v_object(NULL);
    char input[TEXT_CAP], allow[TEXT_CAP];
    if (!framework_read_jstring(args[0].l, input, sizeof(input))) return framework_v_object(NULL);
    allow[0] = '\0';
    if (n == 2 && args[1].l && !framework_read_jstring(args[1].l, allow, sizeof(allow))) return framework_v_object(NULL);
    const size_t len = strlen(input);
    if (len > (SIZE_MAX - 1) / 3) return framework_v_object(NULL);
    char *out = malloc(len * 3 + 1);
    if (!out) return framework_v_object(NULL);
    static const char hex[] = "0123456789ABCDEF";
    char *dst = out;
    for (const unsigned char *src = (const unsigned char *)input; *src; ++src) {
        const unsigned char c = *src;
        if (c < 0x80 && framework_uri_encode_allowed(c, allow)) *dst++ = (char)c;
        else { *dst++ = '%'; *dst++ = hex[c >> 4]; *dst++ = hex[c & 0x0f]; }
    }
    *dst = '\0';
    void *result = framework_new_string(env, out);
    free(out);
    return framework_v_object(result);
}

static int framework_uri_hex_value(unsigned char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static Etd2xJniValue framework_uri_decode(void *env, void *token, const Etd2xJniValue *args,
                                size_t n, void *ud) {
    (void)token; (void)ud;
    if (n != 1 || !args || !args[0].l) return framework_v_object(NULL);
    char input[TEXT_CAP];
    if (!framework_read_jstring(args[0].l, input, sizeof(input))) return framework_v_object(NULL);
    const size_t len = strlen(input);
    char *out = malloc(len + 1);
    if (!out) return framework_v_object(NULL);
    size_t w = 0;
    for (size_t i = 0; i < len; ++i) {
        if (input[i] == '%' && i + 2 < len) {
            int hi = framework_uri_hex_value((unsigned char)input[i+1]);
            int lo = framework_uri_hex_value((unsigned char)input[i+2]);
            if (hi >= 0 && lo >= 0) {
                out[w++] = (char)((hi << 4) | lo);
                i += 2;
                continue;
            }
        }
        out[w++] = input[i];
    }
    out[w] = '\0';
    void *result = framework_new_string(env, out);
    free(out);
    return framework_v_object(result);
}

static Etd2xJniValue framework_uri_parse(void *env, void *token, const Etd2xJniValue *args,
                               size_t n, void *ud) {
    (void)token; (void)ud;
    if (n != 1 || !args[0].l) return framework_v_object(NULL);
    char text[TEXT_CAP];
    if (!framework_read_jstring(args[0].l, text, sizeof(text))) return framework_v_object(NULL);
    void *ref = etd2x_jni_new_local_object(env, "android/net/Uri");
    if (!ref) return framework_v_object(NULL);
    framework_UriPayload *payload = calloc(1, sizeof(*payload));
    if (!payload) { etd2x_jni_delete_local_ref_host(env, ref); return framework_v_object(NULL); }
    payload->magic = URI_PAYLOAD_MAGIC;
    payload->text = strdup(text);
    if (!payload->text) { free(payload); etd2x_jni_delete_local_ref_host(env, ref); return framework_v_object(NULL); }
    payload->next = framework_g_fw.uris;
    framework_g_fw.uris = payload;
    if (etd2x_jni_set_object_host_data(ref, payload) != ETD2X_OK) {
        etd2x_jni_delete_local_ref_host(env, ref);
        return framework_v_object(NULL);
    }
    return framework_v_object(ref);
}

