typedef struct framework_JavaColl {
    framework_CollectionPayload *list;
    framework_JavaMapPayload *set;        /* HashSet family */
    framework_JavaMapPayload *map;        /* owner of a keySet/values/entrySet view */
    uint8_t view;
    bool descending;
} framework_JavaColl;

static bool framework_java_coll_resolve(void *token, framework_JavaColl *out) {
    memset(out, 0, sizeof(*out));
    const uint64_t *magic = token ? (const uint64_t *)etd2x_jni_get_token_host_data(token) : NULL;
    if (!magic) return false;
    if (*magic == COLLECTION_PAYLOAD_MAGIC) {
        out->list = (framework_CollectionPayload *)(uintptr_t)magic;
        return true;
    }
    if (*magic == JAVA_MAP_PAYLOAD_MAGIC) {
        framework_JavaMapPayload *m = (framework_JavaMapPayload *)(uintptr_t)magic;
        if (!m->is_set) return false;
        out->set = m;
        return true;
    }
    if (*magic == JAVA_VIEW_PAYLOAD_MAGIC) {
        const framework_JavaViewPayload *v = (const framework_JavaViewPayload *)magic;
        if (v->map->is_set) out->set = v->map;
        else out->map = v->map;
        out->descending = v->descending;
        out->view = v->kind;
        return true;
    }
    return false;
}

static bool framework_java_coll_receiver(void *env, void *token, framework_JavaColl *out) {
    if (framework_java_coll_resolve(token, out)) return true;
    const framework_JavaUtilModel *model = framework_java_util_receiver_model(env, token);
    return model && model->shape != JAVA_SHAPE_MAP && framework_java_util_attach_model(model, token) &&
           framework_java_coll_resolve(token, out);
}

