/* Local refs of the elements in encounter order (entry objects for an
 * entrySet view). */
static void **framework_java_coll_snapshot(void *env, const framework_JavaColl *c, size_t *out_count) {
    *out_count = 0;
    if (c->list) {
        framework_collection_lock(c->list);
        const size_t n = c->list->size;
        void **items = calloc(n ? n : 1u, sizeof(*items));
        for (size_t i = 0; items && i < n; ++i)
            items[i] = c->list->items[i] ? etd2x_jni_new_local_ref_host(env, c->list->items[i]) : NULL;
        framework_collection_unlock(c->list);
        if (items) *out_count = n;
        return items;
    }
    if (c->set) {
        void **items = framework_java_map_snapshot(env, c->set, false, out_count);
        if (c->descending) for (size_t i = 0; items && i < *out_count / 2u; ++i) {
            void *tmp = items[i]; items[i] = items[*out_count - 1u - i];
            items[*out_count - 1u - i] = tmp;
        }
        return items;
    }
    if (c->view != JAVA_VIEW_ENTRIES) return framework_java_map_snapshot(env, c->map, c->view == JAVA_VIEW_VALUES, out_count);
    framework_JavaMapPayload *m = c->map;
    framework_java_map_lock(m);
    void **items = calloc(m->live ? m->live : 1u, sizeof(*items));
    size_t n = 0;
    for (size_t i = 0; items && i < m->used; ++i)
        if (m->entries[i].live) items[n++] = framework_java_map_node_local_locked(env, m, i);
    framework_java_map_unlock(m);
    *out_count = n;
    return items;
}

