enum { JAVA_NAV_CEILING = 0, JAVA_NAV_FLOOR, JAVA_NAV_HIGHER, JAVA_NAV_LOWER };

/* Tree index for a navigation query, or SIZE_MAX. */
static size_t framework_java_tree_nav_locked(void *env, framework_JavaMapPayload *m, void *key, int mode) {
    size_t pos = 0;
    bool failed = false;
    const bool found = framework_java_map_tree_search(env, m, key, &pos, &failed);
    if (failed) return SIZE_MAX;
    size_t index = SIZE_MAX;
    switch (mode) {
        case JAVA_NAV_CEILING: index = pos; break;
        case JAVA_NAV_HIGHER: index = found ? pos + 1u : pos; break;
        case JAVA_NAV_FLOOR: index = found ? pos : (pos ? pos - 1u : SIZE_MAX); break;
        default: index = pos ? pos - 1u : SIZE_MAX; break;
    }
    return index < m->used ? index : SIZE_MAX;
}

