static int64_t framework_java_floor_div64(int64_t a, int64_t b) {
    int64_t q = a / b, r = a % b;
    if (r < 0) --q;
    return q;
}

/* Proleptic Gregorian conversion, expressed as days relative to 1970-01-01. */
static int64_t framework_java_days_from_civil(int year, unsigned month, unsigned day) {
    year -= month <= 2u;
    const int era = (year >= 0 ? year : year - 399) / 400;
    const unsigned yoe = (unsigned)(year - era * 400);
    const unsigned shifted_month = month > 2u ? month - 3u : month + 9u;
    const unsigned doy = (153u * shifted_month + 2u) / 5u + day - 1u;
    const unsigned doe = yoe * 365u + yoe / 4u - yoe / 100u + doy;
    return (int64_t)era * 146097 + (int64_t)doe - 719468;
}

static void framework_java_civil_from_days(int64_t z, int *year, unsigned *month, unsigned *day) {
    z += 719468;
    const int64_t era = (z >= 0 ? z : z - 146096) / 146097;
    const unsigned doe = (unsigned)(z - era * 146097);
    const unsigned yoe = (doe - doe / 1460u + doe / 36524u - doe / 146096u) / 365u;
    int y = (int)yoe + (int)era * 400;
    const unsigned doy = doe - (365u * yoe + yoe / 4u - yoe / 100u);
    const unsigned mp = (5u * doy + 2u) / 153u;
    const unsigned d = doy - (153u * mp + 2u) / 5u + 1u;
    const unsigned m = mp < 10u ? mp + 3u : mp - 9u;
    y += m <= 2u;
    if (year) *year = y;
    if (month) *month = m;
    if (day) *day = d;
}

static bool framework_java_date_parts_from_millis(int64_t millis, int32_t offset_ms, framework_JavaDateParts *out) {
    if (!out) return false;
    const int64_t day_ms = INT64_C(86400000);
    int64_t days = millis / day_ms;
    int64_t rem = millis % day_ms + (int64_t)offset_ms;
    days += framework_java_floor_div64(rem, day_ms);
    rem %= day_ms;
    if (rem < 0) rem += day_ms;
    unsigned month = 1, day = 1;
    framework_java_civil_from_days(days, &out->year, &month, &day);
    out->month = (int)month;
    out->day = (int)day;
    out->hour = (int)(rem / 3600000); rem %= 3600000;
    out->minute = (int)(rem / 60000); rem %= 60000;
    out->second = (int)(rem / 1000);
    out->millis = (int)(rem % 1000);
    int w = (int)((days + 4) % 7); if (w < 0) w += 7; out->weekday = w;
    out->yearday = (int)(days - framework_java_days_from_civil(out->year, 1, 1)) + 1;
    return true;
}

