static void framework_java_util_reset(void) {
    void *env = etd2x_jni_current_env();
    framework_JavaMapPayload *map = framework_g_fw.java_maps;
    while (map) {
        framework_JavaMapPayload *next = map->next;
        framework_java_map_lock(map);
        framework_java_map_clear_locked(env, map);
        free(map->entries);
        free(map->slots);
        framework_delete_global(&map->comparator);
        for (int i = 0; i < JAVA_VIEW_COUNT; ++i) framework_delete_global(&map->views[i]);
        map->magic = 0;
        framework_java_map_unlock(map);
        pthread_mutex_destroy(&map->lock);
        free(map);
        map = next;
    }
    framework_g_fw.java_maps = NULL;

    framework_JavaViewPayload *view = framework_g_fw.java_views;
    while (view) {
        framework_JavaViewPayload *next = view->next;
        if (view->reverse_comparator) etd2x_jni_delete_global_ref_host(env, view->reverse_comparator);
        view->magic = 0;
        free(view);
        view = next;
    }
    framework_g_fw.java_views = NULL;

    framework_JavaEntryPayload *entry = framework_g_fw.java_entries;
    while (entry) {
        framework_JavaEntryPayload *next = entry->next;
        framework_delete_global(&entry->key);
        framework_delete_global(&entry->value);
        framework_delete_global(&entry->self);
        entry->magic = 0;
        free(entry);
        entry = next;
    }
    framework_g_fw.java_entries = NULL;

    framework_CollectionPayload *collection = framework_g_fw.collections;
    while (collection) {
        framework_CollectionPayload *next = collection->next;
        framework_collection_lock(collection);
        framework_collection_clear_locked(env, collection);
        free(collection->items);
        framework_delete_global(&collection->comparator);
        collection->magic = 0;
        framework_collection_unlock(collection);
        pthread_mutex_destroy(&collection->lock);
        if (collection->blocking) {
            pthread_cond_destroy(&collection->wait_cond);
            pthread_mutex_destroy(&collection->wait_lock);
        }
        free(collection);
        collection = next;
    }
    framework_g_fw.collections = NULL;

    framework_IteratorPayload *iterator = framework_g_fw.iterators;
    while (iterator) {
        framework_IteratorPayload *next = iterator->next;
        for (size_t i = 0; i < iterator->size; ++i) framework_delete_global(&iterator->items[i]);
        free(iterator->items);
        framework_delete_global(&iterator->last);
        framework_delete_global(&iterator->source);
        iterator->magic = 0;
        free(iterator);
        iterator = next;
    }
    framework_g_fw.iterators = NULL;

    framework_JavaAtomicPayload *atomic = framework_g_fw.java_atomics;
    while (atomic) {
        framework_JavaAtomicPayload *next = atomic->next;
        framework_delete_global(&atomic->ref);
        framework_java_atomic_ref_array_dispose(env, atomic->refs, atomic->ref_count);
        atomic->refs = NULL;
        atomic->ref_count = 0;
        pthread_mutex_destroy(&atomic->lock);
        atomic->magic = 0;
        free(atomic);
        atomic = next;
    }
    framework_g_fw.java_atomics = NULL;

    framework_JavaRandomPayload *random = framework_g_fw.java_randoms;
    while (random) {
        framework_JavaRandomPayload *next = random->next;
        random->magic = 0;
        pthread_mutex_destroy(&random->lock);
        free(random);
        random = next;
    }
    framework_g_fw.java_randoms = NULL;

    framework_delete_global(&framework_g_fw.boolean_true);
    framework_delete_global(&framework_g_fw.boolean_false);
    framework_delete_global(&framework_g_fw.empty_list);
    framework_delete_global(&framework_g_fw.empty_set);
    framework_delete_global(&framework_g_fw.empty_map);
}

