/* text format */
/* ---------- java.text.NumberFormat / DecimalFormat / DecimalFormatSymbols ----------
 *
 * DecimalFormat follows the java.text.DecimalFormat pattern grammar (prefix,
 * '#'/'0' digits, ',' grouping, '.' fraction, suffix, optional ';' negative
 * subpattern, quoted literals, '%' and per-mille multipliers, currency sign)
 * without scientific notation. Rounding applies java.math.RoundingMode to the
 * exact decimal expansion of the value. Locale data is the default en-US set
 * ETD2X reports for every Locale argument. */
#define NUMBER_FORMAT_MAGIC UINT64_C(0x41504b364e464d31)   /* APK6NFM1 */
#define DECIMAL_SYMBOLS_MAGIC UINT64_C(0x41504b3644465331) /* APK6DFS1 */
#define NUMBER_FORMAT_CLASS "java/text/NumberFormat"
#define DECIMAL_FORMAT_CLASS "java/text/DecimalFormat"
#define DECIMAL_SYMBOLS_CLASS "java/text/DecimalFormatSymbols"
#define NF_AFFIX_CAP 64
#define NF_DOUBLE_INTEGER_DIGITS 309
#define NF_DOUBLE_FRACTION_DIGITS 340

typedef struct framework_DecimalSymbols {
    uint16_t zero, grouping, decimal, minus, percent, per_mill;
} framework_DecimalSymbols;

static const framework_DecimalSymbols framework_k_default_decimal_symbols = {'0', ',', '.', '-', '%', 0x2030};

typedef struct framework_DecimalSymbolsPayload {
    uint64_t magic;
    framework_DecimalSymbols s;
} framework_DecimalSymbolsPayload;

/* java.math.RoundingMode declaration order. */
enum { NF_ROUND_UP, NF_ROUND_DOWN, NF_ROUND_CEILING, NF_ROUND_FLOOR, NF_ROUND_HALF_UP,
       NF_ROUND_HALF_DOWN, NF_ROUND_HALF_EVEN, NF_ROUND_UNNECESSARY, NF_ROUND_COUNT };
static const char *const framework_k_rounding_mode_names[NF_ROUND_COUNT] = {
    "UP", "DOWN", "CEILING", "FLOOR", "HALF_UP", "HALF_DOWN", "HALF_EVEN", "UNNECESSARY"};

typedef struct framework_NumberFormatPayload {
    uint64_t magic;
    framework_DecimalSymbols sym;
    /* Affixes are kept in pattern form (quotes and special characters) and
     * expanded against the current symbols when formatting. */
    char pos_prefix[NF_AFFIX_CAP], pos_suffix[NF_AFFIX_CAP];
    char neg_prefix[NF_AFFIX_CAP], neg_suffix[NF_AFFIX_CAP];
    int32_t min_int, max_int, min_frac, max_frac, grouping_size, multiplier, rounding;
    bool grouping_used, decimal_always_shown, parse_integer_only;
} framework_NumberFormatPayload;

static framework_NumberFormatPayload *framework_nf_payload(void *token) {
    framework_NumberFormatPayload *p = (framework_NumberFormatPayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == NUMBER_FORMAT_MAGIC ? p : NULL;
}

static framework_DecimalSymbolsPayload *framework_dfs_payload(void *token) {
    framework_DecimalSymbolsPayload *p = (framework_DecimalSymbolsPayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == DECIMAL_SYMBOLS_MAGIC ? p : NULL;
}

static framework_DecimalSymbolsPayload *framework_dfs_payload_ensure(void *token) {
    framework_DecimalSymbolsPayload *p = framework_dfs_payload(token);
    if (p || !token) return p;
    p = calloc(1, sizeof(*p));
    if (!p) return NULL;
    p->magic = DECIMAL_SYMBOLS_MAGIC;
    p->s = framework_k_default_decimal_symbols;
    if (etd2x_jni_set_token_host_data(token, p) != ETD2X_OK) { free(p); return NULL; }
    return p;
}

/* ---- text building ---- */

typedef struct framework_NfText { char *buf; size_t cap, len; bool overflow; } framework_NfText;

static void framework_nf_put(framework_NfText *t, const char *s, size_t n) {
    if (t->len + n + 1 > t->cap) { t->overflow = true; return; }
    memcpy(t->buf + t->len, s, n);
    t->len += n;
    t->buf[t->len] = '\0';
}

static void framework_nf_put_unit(framework_NfText *t, uint16_t c) {
    char u[3];
    if (c < 0x80) { u[0] = (char)c; framework_nf_put(t, u, 1); }
    else if (c < 0x800) { u[0] = (char)(0xC0 | (c >> 6)); u[1] = (char)(0x80 | (c & 0x3F)); framework_nf_put(t, u, 2); }
    else {
        u[0] = (char)(0xE0 | (c >> 12)); u[1] = (char)(0x80 | ((c >> 6) & 0x3F)); u[2] = (char)(0x80 | (c & 0x3F));
        framework_nf_put(t, u, 3);
    }
}

/* Expand an affix pattern: '' is a quote, '...' is literal, and unquoted
 * '%', per-mille, currency and '-' map to symbols. */
static void framework_nf_expand_affix(const char *pattern, const framework_DecimalSymbols *sym, framework_NfText *t) {
    bool quoted = false;
    for (const char *p = pattern; *p;) {
        if (*p == '\'') {
            if (p[1] == '\'') { framework_nf_put(t, "'", 1); p += 2; continue; }
            quoted = !quoted;
            ++p;
            continue;
        }
        if (!quoted) {
            if (*p == '%') { framework_nf_put_unit(t, sym->percent); ++p; continue; }
            if (*p == '-') { framework_nf_put_unit(t, sym->minus); ++p; continue; }
            if (strncmp(p, "\xE2\x80\xB0", 3) == 0) { framework_nf_put_unit(t, sym->per_mill); p += 3; continue; }
            if (strncmp(p, "\xC2\xA4\xC2\xA4", 4) == 0) { framework_nf_put(t, "USD", 3); p += 4; continue; }
            if (strncmp(p, "\xC2\xA4", 2) == 0) { framework_nf_put(t, "$", 1); p += 2; continue; }
        }
        framework_nf_put(t, p, 1);
        ++p;
    }
}

/* Quote literal text so it round-trips through nf_expand_affix. */
static bool framework_nf_quote_affix(const char *literal, char *out, size_t cap) {
    size_t w = 0;
    if (!*literal) { if (cap) out[0] = '\0'; return cap != 0; }
    if (w + 1 >= cap) return false;
    out[w++] = '\'';
    for (const char *p = literal; *p; ++p) {
        const size_t need = *p == '\'' ? 2u : 1u;
        if (w + need + 1 >= cap) return false;
        if (*p == '\'') out[w++] = '\'';
        out[w++] = *p;
    }
    if (w + 2 > cap) return false;
    out[w++] = '\'';
    out[w] = '\0';
    return true;
}

/* ---- pattern parsing ---- */

static bool framework_nf_is_number_char(char c) { return c == '#' || c == '0' || c == ',' || c == '.'; }

/* Copy one affix (until a number character, ';' or end, honoring quotes). */
static const char *framework_nf_scan_affix(const char *p, bool stop_at_number, char *out, size_t cap, bool *ok) {
    size_t w = 0;
    bool quoted = false;
    for (; *p; ++p) {
        if (*p == '\'') quoted = !quoted;
        else if (!quoted && (*p == ';' || (stop_at_number && framework_nf_is_number_char(*p)))) break;
        if (w + 1 >= cap) { *ok = false; return p; }
        out[w++] = *p;
    }
    out[w] = '\0';
    if (quoted) *ok = false;
    return p;
}

static bool framework_nf_affix_has(const char *affix, const char *special) {
    bool quoted = false;
    const size_t n = strlen(special);
    for (const char *p = affix; *p; ++p) {
        if (*p == '\'') { if (p[1] == '\'') { ++p; continue; } quoted = !quoted; continue; }
        if (!quoted && strncmp(p, special, n) == 0) return true;
    }
    return false;
}

static bool framework_nf_apply_pattern(framework_NumberFormatPayload *p, const char *pattern) {
    framework_NumberFormatPayload next = *p;
    bool ok = true;
    const char *s = framework_nf_scan_affix(pattern, true, next.pos_prefix, sizeof(next.pos_prefix), &ok);
    int32_t int_hash = 0, int_zero = 0, frac_zero = 0, frac_hash = 0, group = -1;
    bool dot = false;
    for (; ok && framework_nf_is_number_char(*s); ++s) {
        switch (*s) {
            case '#':
                if (dot) frac_hash++;
                else if (int_zero) ok = false;
                else int_hash++;
                if (!dot && group >= 0) group++;
                break;
            case '0':
                if (dot) { if (frac_hash) ok = false; frac_zero++; }
                else { int_zero++; if (group >= 0) group++; }
                break;
            case ',':
                if (dot) ok = false;
                group = 0;
                break;
            case '.':
                if (dot) ok = false;
                dot = true;
                break;
        }
    }
    if (ok && (*s == 'E' || int_hash + int_zero + frac_zero + frac_hash == 0)) ok = false;
    if (ok) s = framework_nf_scan_affix(s, false, next.pos_suffix, sizeof(next.pos_suffix), &ok);
    if (ok && *s == ';') {
        s = framework_nf_scan_affix(s + 1, true, next.neg_prefix, sizeof(next.neg_prefix), &ok);
        while (ok && framework_nf_is_number_char(*s)) ++s;
        if (ok) s = framework_nf_scan_affix(s, false, next.neg_suffix, sizeof(next.neg_suffix), &ok);
    } else if (ok) {
        ok = (size_t)snprintf(next.neg_prefix, sizeof(next.neg_prefix), "-%s", next.pos_prefix) <
             sizeof(next.neg_prefix);
        snprintf(next.neg_suffix, sizeof(next.neg_suffix), "%s", next.pos_suffix);
    }
    if (!ok || *s) return false;
    next.min_int = int_zero;
    next.max_int = NF_DOUBLE_INTEGER_DIGITS;
    next.min_frac = frac_zero;
    next.max_frac = frac_zero + frac_hash;
    next.grouping_size = group > 0 ? group : 0;
    next.grouping_used = group > 0;
    next.decimal_always_shown = dot && frac_zero + frac_hash == 0;
    next.multiplier = framework_nf_affix_has(next.pos_prefix, "%") || framework_nf_affix_has(next.pos_suffix, "%") ? 100
                    : framework_nf_affix_has(next.pos_prefix, "\xE2\x80\xB0") || framework_nf_affix_has(next.pos_suffix, "\xE2\x80\xB0") ? 1000
                    : 1;
    *p = next;
    return true;
}

static void framework_nf_to_pattern(const framework_NumberFormatPayload *p, framework_NfText *t) {
    framework_nf_put(t, p->pos_prefix, strlen(p->pos_prefix));
    int32_t len = p->min_int > 0 ? p->min_int : 1;
    if (p->grouping_used && p->grouping_size > 0 && len <= p->grouping_size) len = p->grouping_size + 1;
    for (int32_t i = len - 1; i >= 0; --i) {
        framework_nf_put(t, i < p->min_int ? "0" : "#", 1);
        if (p->grouping_used && p->grouping_size > 0 && i > 0 && i % p->grouping_size == 0) framework_nf_put(t, ",", 1);
    }
    if (p->max_frac > 0 || p->decimal_always_shown) {
        framework_nf_put(t, ".", 1);
        for (int32_t i = 0; i < p->max_frac; ++i) framework_nf_put(t, i < p->min_frac ? "0" : "#", 1);
    }
    framework_nf_put(t, p->pos_suffix, strlen(p->pos_suffix));
}

/* ---- formatting ---- */

/* digits: ASCII decimal digits, *point of them integral. Rounds to max_frac
 * fraction digits with the rounding mode (a carry out of the top digit adds an
 * integral digit); false for UNNECESSARY when a nonzero digit is discarded. */
static bool framework_nf_round(char *digits, size_t *len, size_t *point, int32_t max_frac, int mode, bool negative) {
    const size_t keep = *point + (size_t)max_frac;
    if (keep >= *len) return true;
    const char first = digits[keep];
    bool rest_nonzero = false;
    for (size_t i = keep + 1; i < *len; ++i) if (digits[i] != '0') { rest_nonzero = true; break; }
    const bool discarded = first != '0' || rest_nonzero;
    const bool odd = keep > 0 && ((digits[keep - 1] - '0') & 1);
    bool up = false;
    switch (mode) {
        case NF_ROUND_UP: up = discarded; break;
        case NF_ROUND_DOWN: up = false; break;
        case NF_ROUND_CEILING: up = discarded && !negative; break;
        case NF_ROUND_FLOOR: up = discarded && negative; break;
        case NF_ROUND_HALF_UP: up = first >= '5'; break;
        case NF_ROUND_HALF_DOWN: up = first > '5' || (first == '5' && rest_nonzero); break;
        case NF_ROUND_UNNECESSARY: if (discarded) return false; break;
        default: up = first > '5' || (first == '5' && (rest_nonzero || odd)); break;
    }
    *len = keep;
    digits[keep] = '\0';
    if (!up) return true;
    for (size_t i = keep; i-- > 0;) {
        if (digits[i] != '9') { digits[i]++; return true; }
        digits[i] = '0';
    }
    memmove(digits + 1, digits, *len + 1);
    digits[0] = '1';
    (*len)++;
    (*point)++;
    return true;
}

/* Format |value| given as decimal digits with `point` integral digits. */
static bool framework_nf_format_digits(const framework_NumberFormatPayload *p, bool negative, char *digits, size_t len,
                             size_t point, framework_NfText *t) {
    if (!framework_nf_round(digits, &len, &point, p->max_frac, p->rounding, negative)) return false;
    if (point > len) point = len;
    const char *int_digits = digits;
    size_t int_len = point;
    while (int_len > 0 && *int_digits == '0') { ++int_digits; --int_len; }
    if ((int32_t)int_len > p->max_int) { int_digits += int_len - (size_t)p->max_int; int_len = (size_t)p->max_int; }
    const char *frac = digits + point;
    size_t frac_len = len - point;
    while ((int32_t)frac_len > p->min_frac && frac[frac_len - 1] == '0') --frac_len;
    const size_t shown_frac = (int32_t)frac_len > p->min_frac ? frac_len : (size_t)p->min_frac;

    framework_nf_expand_affix(negative ? p->neg_prefix : p->pos_prefix, &p->sym, t);
    const size_t shown_int = (int32_t)int_len > p->min_int ? int_len : (size_t)p->min_int;
    for (size_t i = 0; i < shown_int; ++i) {
        const size_t pad = shown_int - int_len;
        const char d = i < pad ? '0' : int_digits[i - pad];
        framework_nf_put_unit(t, (uint16_t)(p->sym.zero + (d - '0')));
        const size_t from_right = shown_int - 1 - i;
        if (p->grouping_used && p->grouping_size > 0 && from_right > 0 &&
            from_right % (size_t)p->grouping_size == 0)
            framework_nf_put_unit(t, p->sym.grouping);
    }
    /* DecimalFormat prints a zero when neither integer nor fraction digits appear. */
    if (shown_int == 0 && shown_frac == 0) framework_nf_put_unit(t, p->sym.zero);
    if (shown_frac > 0 || p->decimal_always_shown) framework_nf_put_unit(t, p->sym.decimal);
    for (size_t i = 0; i < shown_frac; ++i)
        framework_nf_put_unit(t, (uint16_t)(p->sym.zero + (i < frac_len ? frac[i] - '0' : 0)));
    framework_nf_expand_affix(negative ? p->neg_suffix : p->pos_suffix, &p->sym, t);
    return true;
}

static void framework_nf_throw_unnecessary(void *env) {
    (void)etd2x_jni_throw_new_by_name(env, "java/lang/ArithmeticException",
        "Rounding needed with the rounding mode being set to RoundingMode.UNNECESSARY");
}

static void *framework_nf_format_double(void *env, const framework_NumberFormatPayload *p, double value) {
    char out[1024];
    framework_NfText t = {out, sizeof(out), 0, false};
    out[0] = '\0';
    if (isnan(value)) return framework_new_string(env, "NaN");
    const bool negative = signbit(value) != 0;
    value = fabs(value) * (double)p->multiplier;
    if (isinf(value)) {
        framework_nf_expand_affix(negative ? p->neg_prefix : p->pos_prefix, &p->sym, &t);
        framework_nf_put(&t, "\xE2\x88\x9E", 3);
        framework_nf_expand_affix(negative ? p->neg_suffix : p->pos_suffix, &p->sym, &t);
        return framework_new_string(env, out);
    }
    /* %.*f is the correctly rounded decimal expansion; 24 guard digits beyond
     * the kept ones decide ties and discarded-digit tests. */
    int prec = p->max_frac + 24;
    if (prec > NF_DOUBLE_FRACTION_DIGITS) prec = NF_DOUBLE_FRACTION_DIGITS;
    char raw[NF_DOUBLE_INTEGER_DIGITS + NF_DOUBLE_FRACTION_DIGITS + 8];
    snprintf(raw, sizeof(raw), "%.*f", prec, value);
    char digits[sizeof(raw)];
    size_t len = 0, point = 0;
    for (const char *c = raw; *c; ++c) {
        if (*c == '.') { point = len; continue; }
        if (*c >= '0' && *c <= '9') digits[len++] = *c;
    }
    if (!strchr(raw, '.')) point = len;
    digits[len] = '\0';
    if (!framework_nf_format_digits(p, negative, digits, len, point, &t)) { framework_nf_throw_unnecessary(env); return NULL; }
    return framework_new_string(env, out);
}

static void *framework_nf_format_long(void *env, const framework_NumberFormatPayload *p, int64_t value) {
    const bool negative = value < 0;
    uint64_t magnitude = negative ? (uint64_t)0 - (uint64_t)value : (uint64_t)value;
    if (p->multiplier != 1) {
        if (magnitude > UINT64_MAX / (uint64_t)p->multiplier || magnitude * (uint64_t)p->multiplier > (uint64_t)INT64_MAX)
            return framework_nf_format_double(env, p, (double)value);
        magnitude *= (uint64_t)p->multiplier;
    }
    char digits[48];
    const int n = snprintf(digits, sizeof(digits), "%" PRIu64, magnitude);
    char out[512];
    framework_NfText t = {out, sizeof(out), 0, false};
    out[0] = '\0';
    if (!framework_nf_format_digits(p, negative, digits, (size_t)n, (size_t)n, &t)) { framework_nf_throw_unnecessary(env); return NULL; }
    return framework_new_string(env, out);
}

/* ---- objects ---- */

static framework_NumberFormatPayload *framework_nf_payload_create(void *token, const char *pattern) {
    if (!token) return NULL;
    framework_NumberFormatPayload *p = framework_nf_payload(token);
    if (!p) {
        p = calloc(1, sizeof(*p));
        if (!p) return NULL;
        p->magic = NUMBER_FORMAT_MAGIC;
        if (etd2x_jni_set_token_host_data(token, p) != ETD2X_OK) { free(p); return NULL; }
    }
    p->sym = framework_k_default_decimal_symbols;
    p->rounding = NF_ROUND_HALF_EVEN;
    (void)framework_nf_apply_pattern(p, pattern);
    return p;
}

static void *framework_nf_new_object(void *env, const char *pattern, framework_NumberFormatPayload **out) {
    void *o = etd2x_jni_new_local_object(env, DECIMAL_FORMAT_CLASS);
    framework_NumberFormatPayload *p = o ? framework_nf_payload_create(etd2x_jni_object_token_host(o), pattern) : NULL;
    if (o && !p) { etd2x_jni_delete_local_ref_host(env, o); o = NULL; }
    if (out) *out = p;
    return o;
}

static framework_NumberFormatPayload *framework_nf_require(void *env, void *token) {
    framework_NumberFormatPayload *p = framework_nf_payload(token);
    if (!p) p = framework_nf_payload_create(token, "#,##0.###");
    if (!p) (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "DecimalFormat");
    return p;
}

static void framework_nf_throw_bad_pattern(void *env, const char *pattern) {
    char message[320];
    snprintf(message, sizeof(message), "Malformed pattern \"%.280s\"", pattern);
    (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", message);
}

/* DecimalFormat(), (String), (String, DecimalFormatSymbols). */
static Etd2xJniValue framework_nf_ctor(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    char pattern[256] = "#,##0.###";
    if (n >= 1) {
        if (!a[0].l) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "pattern"); return framework_v_void(); }
        if (!framework_read_jstring(a[0].l, pattern, sizeof(pattern))) { framework_nf_throw_bad_pattern(env, "?"); return framework_v_void(); }
    }
    framework_NumberFormatPayload *p = framework_nf_payload_create(t, "#,##0.###");
    if (!p) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "DecimalFormat"); return framework_v_void(); }
    if (n == 2) {
        framework_DecimalSymbolsPayload *s = a[1].l ? framework_dfs_payload_ensure(etd2x_jni_object_token_host(a[1].l)) : NULL;
        if (!s) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "symbols"); return framework_v_void(); }
        p->sym = s->s;
    }
    if (!framework_nf_apply_pattern(p, pattern)) framework_nf_throw_bad_pattern(env, pattern);
    return framework_v_void();
}

/* NumberFormat.get*Instance([Locale]). u selects the style. */
static Etd2xJniValue framework_nf_get_instance(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)t; (void)a; (void)n;
    static const char *const patterns[] = {"#,##0.###", "#,##0", "#,##0%", "\xC2\xA4#,##0.00"};
    const intptr_t style = (intptr_t)u;
    framework_NumberFormatPayload *p = NULL;
    void *o = framework_nf_new_object(env, patterns[style], &p);
    if (p && style == 1) p->parse_integer_only = true;
    return framework_v_object(o);
}

static Etd2xJniValue framework_nf_format(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 1) return framework_v_object(NULL);
    switch ((intptr_t)u) {
        case 'D': return framework_v_object(framework_nf_format_double(env, p, a[0].d));
        case 'J': return framework_v_object(framework_nf_format_long(env, p, a[0].j));
        default: break;
    }
    void *value = a[0].l;
    if (!value || !etd2x_jni_is_instance_of_class_host(value, "java/lang/Number")) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException",
                                           "Cannot format given Object as a Number");
        return framework_v_object(NULL);
    }
    static const char *const integral[] = {"java/lang/Long", "java/lang/Integer", "java/lang/Short",
                                           "java/lang/Byte", "java/util/concurrent/atomic/AtomicInteger",
                                           "java/util/concurrent/atomic/AtomicLong"};
    Etd2xJniValue out = {0};
    for (size_t i = 0; i < framework_ARRAY_COUNT(integral); ++i)
        if (etd2x_jni_is_instance_of_class_host(value, integral[i]))
            return framework_v_object(framework_java_call_virtual(env, value, "longValue", "()J", NULL, 0, &out)
                                ? framework_nf_format_long(env, p, out.j) : NULL);
    return framework_v_object(framework_java_call_virtual(env, value, "doubleValue", "()D", NULL, 0, &out)
                        ? framework_nf_format_double(env, p, out.d) : NULL);
}

enum { NF_MIN_INT, NF_MAX_INT, NF_MIN_FRAC, NF_MAX_FRAC, NF_GROUPING_SIZE, NF_MULTIPLIER };

static Etd2xJniValue framework_nf_set_int(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 1) return framework_v_void();
    int32_t v = a[0].i < 0 ? 0 : a[0].i;
    switch ((intptr_t)u) {
        /* Setting a minimum above the maximum raises the maximum, and vice versa. */
        case NF_MIN_INT:
            p->min_int = v > NF_DOUBLE_INTEGER_DIGITS ? NF_DOUBLE_INTEGER_DIGITS : v;
            if (p->max_int < p->min_int) p->max_int = p->min_int;
            break;
        case NF_MAX_INT:
            p->max_int = v > NF_DOUBLE_INTEGER_DIGITS ? NF_DOUBLE_INTEGER_DIGITS : v;
            if (p->min_int > p->max_int) p->min_int = p->max_int;
            break;
        case NF_MIN_FRAC:
            p->min_frac = v > NF_DOUBLE_FRACTION_DIGITS ? NF_DOUBLE_FRACTION_DIGITS : v;
            if (p->max_frac < p->min_frac) p->max_frac = p->min_frac;
            break;
        case NF_MAX_FRAC:
            p->max_frac = v > NF_DOUBLE_FRACTION_DIGITS ? NF_DOUBLE_FRACTION_DIGITS : v;
            if (p->min_frac > p->max_frac) p->min_frac = p->max_frac;
            break;
        case NF_GROUPING_SIZE: p->grouping_size = a[0].i < 0 ? 0 : (a[0].i > 127 ? 127 : a[0].i); break;
        case NF_MULTIPLIER: p->multiplier = a[0].i == 0 ? 1 : a[0].i; break;
    }
    return framework_v_void();
}

static Etd2xJniValue framework_nf_get_int(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)a;
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 0) return framework_v_int(0);
    switch ((intptr_t)u) {
        case NF_MIN_INT: return framework_v_int(p->min_int);
        case NF_MAX_INT: return framework_v_int(p->max_int);
        case NF_MIN_FRAC: return framework_v_int(p->min_frac);
        case NF_MAX_FRAC: return framework_v_int(p->max_frac);
        case NF_GROUPING_SIZE: return framework_v_int(p->grouping_size);
        default: return framework_v_int(p->multiplier);
    }
}

enum { NF_GROUPING_USED, NF_DECIMAL_SHOWN, NF_PARSE_INTEGER_ONLY };

static bool *framework_nf_flag(framework_NumberFormatPayload *p, intptr_t which) {
    return which == NF_GROUPING_USED ? &p->grouping_used
         : which == NF_DECIMAL_SHOWN ? &p->decimal_always_shown : &p->parse_integer_only;
}

static Etd2xJniValue framework_nf_set_flag(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (p && n == 1) *framework_nf_flag(p, (intptr_t)u) = a[0].z != 0;
    return framework_v_void();
}

static Etd2xJniValue framework_nf_get_flag(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)a;
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    return framework_v_bool(p && n == 0 && *framework_nf_flag(p, (intptr_t)u));
}

/* set{Positive,Negative}{Prefix,Suffix}: literal text. */
static Etd2xJniValue framework_nf_set_affix(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 1) return framework_v_void();
    char literal[NF_AFFIX_CAP] = "";
    if (a[0].l) (void)framework_read_jstring(a[0].l, literal, sizeof(literal));
    char *slots[] = {p->pos_prefix, p->pos_suffix, p->neg_prefix, p->neg_suffix};
    char quoted[NF_AFFIX_CAP];
    if (framework_nf_quote_affix(literal, quoted, sizeof(quoted)))
        snprintf(slots[(intptr_t)u], NF_AFFIX_CAP, "%s", quoted);
    return framework_v_void();
}

static Etd2xJniValue framework_nf_get_affix(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)a;
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 0) return framework_v_object(NULL);
    const char *slots[] = {p->pos_prefix, p->pos_suffix, p->neg_prefix, p->neg_suffix};
    char out[NF_AFFIX_CAP * 3];
    framework_NfText text = {out, sizeof(out), 0, false};
    out[0] = '\0';
    framework_nf_expand_affix(slots[(intptr_t)u], &p->sym, &text);
    return framework_v_object(framework_new_string(env, out));
}

static Etd2xJniValue framework_nf_apply_pattern_method(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 1) return framework_v_void();
    char pattern[256];
    if (!a[0].l) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "pattern"); return framework_v_void(); }
    if (!framework_read_jstring(a[0].l, pattern, sizeof(pattern)) || !framework_nf_apply_pattern(p, pattern))
        framework_nf_throw_bad_pattern(env, pattern);
    return framework_v_void();
}

static Etd2xJniValue framework_nf_to_pattern_method(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)a; (void)u;
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 0) return framework_v_object(NULL);
    char out[512];
    framework_NfText text = {out, sizeof(out), 0, false};
    out[0] = '\0';
    framework_nf_to_pattern(p, &text);
    return framework_v_object(framework_new_string(env, out));
}

static Etd2xJniValue framework_nf_set_rounding_mode(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    framework_NumberFormatPayload *p = framework_nf_require(env, t);
    if (!p || n != 1) return framework_v_void();
    framework_EnumPayload *mode = a[0].l ? framework_enum_payload(etd2x_jni_object_token_host(a[0].l)) : NULL;
    if (!mode) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "roundingMode"); return framework_v_void(); }
    if (mode->ordinal >= 0 && mode->ordinal < NF_ROUND_COUNT) p->rounding = mode->ordinal;
    return framework_v_void();
}

