static void *framework_jt_from_millis(void *env, int64_t millis) {
    int64_t seconds = millis / 1000;
    int32_t rem = (int32_t)(millis % 1000);
    if (rem < 0) { --seconds; rem += 1000; }
    return framework_jt_new(env, JT_INSTANT, seconds, rem * 1000000, 0);
}

