/* network proxy */
/* Null means no proxy applies, rather than an empty ProxyInfo fabricated by
 * the API fallback. Host-supplied direct proxies retain immutable snapshots. */
#define PROXY_INFO_CLASS "android/net/ProxyInfo"

static Etd2xJniValue framework_network_proxy_snapshot(void *env, void *token, const Etd2xJniValue *a,
                                           size_t n, void *u) {
    (void)token; (void)a; (void)n; (void)u;
    char host[128]; uint16_t port = 0;
    const int state = etd2x_compat_network_proxy ?
        etd2x_compat_network_proxy(host, sizeof(host), &port) : 0;
    if (framework_framework_network_trace_slot())
        ETD2X_LOGCI("ANDROID", "default HTTP proxy state=%d result=%s", state,
                    state == 1 ? "configured" : state < 0 ? "error" : "null");
    if (state < 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/RuntimeException", "Active-network proxy query failed");
        return framework_v_object(NULL);
    }
    if (state != 1) return framework_v_object(NULL);
    void *proxy = etd2x_jni_new_local_object(env, PROXY_INFO_CLASS);
    if (!proxy) return framework_v_object(NULL);
    void *name = framework_new_string(env, host);
    if (!name) { etd2x_jni_delete_local_ref_host(env, proxy); return framework_v_object(NULL); }
    framework_set_instance_object_field(proxy, "etd2xHost", "Ljava/lang/String;", name);
    framework_set_instance_int_field(proxy, "etd2xPort", port);
    etd2x_jni_delete_local_ref_host(env, name);
    return framework_v_object(proxy);
}

