typedef struct framework_ReflectMethodInfo {
    char owner[256];
    char name[128];
    char signature[ETD2X_DEX_SIGNATURE_CAP];   /* full descriptor when exact, else "(params)" */
    bool is_static;
    bool owner_is_interface;
    bool exact;
    uint32_t access_flags;        /* declared JVMS/DEX access_flags */
    bool declared_in_interface;
} framework_ReflectMethodInfo;

static bool framework_reflect_method_info(void *env, void *token, framework_ReflectMethodInfo *out) {
    memset(out, 0, sizeof(*out));
    void *self = etd2x_jni_new_local_from_token(env, token);
    const bool exact = self && etd2x_jni_reflected_method_info_host(
        self, out->owner, sizeof(out->owner), out->name, sizeof(out->name),
        out->signature, sizeof(out->signature), &out->is_static, &out->owner_is_interface);
    bool modifiers_known = false;
    if (exact) {
        modifiers_known = etd2x_jni_reflected_method_modifiers_host(self, &out->access_flags,
                                                                     &out->declared_in_interface);
    }
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    if (exact) {
        out->exact = true;
        if (!modifiers_known) {
            out->access_flags = 0x0001u | (out->is_static ? 0x0008u :
                                           out->owner_is_interface ? 0x0400u : 0u);
            out->declared_in_interface = out->owner_is_interface;
        }
        return true;
    }
    framework_ReflectMethodPayload *p = framework_reflect_method_payload(token);
    if (!p) return false;
    out->access_flags = 0x0001u;
    framework_copy_text(out->owner, sizeof(out->owner), p->owner, "");
    framework_copy_text(out->name, sizeof(out->name), p->name, "");
    framework_copy_text(out->signature, sizeof(out->signature), p->params, "()");
    return true;
}

static const char *framework_reflection_descriptor_next(const char *p, char *out, size_t cap) {
    if (!p || !*p || !out || cap < 2) return NULL;
    const char *begin = p;
    while (*p == '[') ++p;
    if (*p == 'L') {
        const char *end = strchr(p, ';');
        if (!end) return NULL;
        p = end + 1;
    } else if (strchr("ZBCSIJFDV", *p)) {
        ++p;
    } else return NULL;
    const size_t len = (size_t)(p - begin);
    if (len >= cap) return NULL;
    memcpy(out, begin, len); out[len] = '\0';
    return p;
}

static void *framework_reflection_parameter_types(void *env, const char *signature) {
    if (!signature || signature[0] != '(') return NULL;
    const char *p = signature + 1;
    int32_t count = 0;
    char desc[512];
    for (const char *scan = p; *scan && *scan != ')'; ++count) {
        scan = framework_reflection_descriptor_next(scan, desc, sizeof(desc));
        if (!scan) return NULL;
    }
    void *array = etd2x_jni_new_local_reference_array(env, "[Ljava/lang/Class;", count);
    if (!array) return NULL;
    for (int32_t i = 0; i < count; ++i) {
        p = framework_reflection_descriptor_next(p, desc, sizeof(desc));
        if (!p) { etd2x_jni_delete_local_ref_host(env,array); return NULL; }
        void *clazz = etd2x_jni_class_ref_for_descriptor_host(env, desc);
        if (!clazz || etd2x_jni_set_object_array_element_host(env,array,i,clazz)!=ETD2X_OK) {
            if(clazz)etd2x_jni_delete_local_ref_host(env,clazz);
            etd2x_jni_delete_local_ref_host(env,array); return NULL;
        }
        etd2x_jni_delete_local_ref_host(env,clazz);
    }
    return array;
}

