    if (strcmp(name, "boolean") == 0) array = etd2x_jni_new_local_boolean_array(env, length);
    else if (strcmp(name, "byte") == 0) array = etd2x_jni_new_local_byte_array(env, length);
    else if (strcmp(name, "char") == 0) array = etd2x_jni_new_local_char_array(env, length);
    else if (strcmp(name, "short") == 0) array = etd2x_jni_new_local_short_array(env, length);
    else if (strcmp(name, "int") == 0) array = etd2x_jni_new_local_int_array(env, length);
    else if (strcmp(name, "long") == 0) array = etd2x_jni_new_local_long_array(env, length);
    else if (strcmp(name, "float") == 0) array = etd2x_jni_new_local_float_array(env, length);
    else if (strcmp(name, "double") == 0) array = etd2x_jni_new_local_double_array(env, length);
