/* Array.getLength(Object): NPE for null, IllegalArgumentException for a
 * non-array argument. */
static Etd2xJniValue framework_reflect_array_get_length(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)t; (void)u;
    if (n != 1) return framework_v_int(0);
    if (!a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "array == null");
        return framework_v_int(0);
    }
    const int32_t length = etd2x_jni_array_length_host(a[0].l);
    if (length < 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "Argument is not an array");
        return framework_v_int(0);
    }
    return framework_v_int(length);
}

static void framework_text_append(char *out, size_t cap, size_t *pos, const char *s) {
    while (s && *s && *pos + 1 < cap) out[(*pos)++] = *s++;
    if (cap) out[*pos < cap ? *pos : cap - 1] = '\0';
}

/* Append the Java language name of one descriptor ('.'-separated binary name,
 * "[]" per dimension) as Method.toString prints it; returns the next
 * descriptor or NULL when malformed. */
static const char *framework_java_type_name_append(const char *d, char *out, size_t cap, size_t *pos) {
    unsigned dims = 0;
    while (*d == '[') { dims++; d++; }
    static const char *const primitives[][2] = {
        {"Z", "boolean"}, {"B", "byte"}, {"C", "char"}, {"S", "short"}, {"I", "int"},
        {"J", "long"}, {"F", "float"}, {"D", "double"}, {"V", "void"},
    };
    const char *next = d + 1;
    if (*d == 'L') {
        const char *end = strchr(d, ';');
        if (!end) return NULL;
        for (const char *p = d + 1; p < end && *pos + 1 < cap; ++p) out[(*pos)++] = *p == '/' ? '.' : *p;
        out[*pos] = '\0';
        next = end + 1;
    } else {
        const char *name = NULL;
        for (size_t i = 0; i < framework_ARRAY_COUNT(primitives) && !name; ++i)
            if (*d && *d == primitives[i][0][0]) name = primitives[i][1];
        if (!name) return NULL;
        framework_text_append(out, cap, pos, name);
    }
    for (unsigned i = 0; i < dims; ++i) framework_text_append(out, cap, pos, "[]");
    return next;
}

/* Method.getModifiers(): declared flags masked by Modifier.methodModifiers()
 * (PUBLIC|PROTECTED|PRIVATE|ABSTRACT|STATIC|FINAL|SYNCHRONIZED|NATIVE|STRICT). */
static int32_t framework_reflect_method_modifiers(const framework_ReflectMethodInfo *info) {
    return (int32_t)(info->access_flags & 0x0D3Fu);
}

/* Method.isDefault(): a public, non-abstract instance method declared by an
 * interface ((mods & (ABSTRACT|PUBLIC|STATIC)) == PUBLIC && isInterface()). */
static bool framework_reflect_method_is_default(const framework_ReflectMethodInfo *info) {
    return info->declared_in_interface &&
           (info->access_flags & (0x0400u | 0x0001u | 0x0008u)) == 0x0001u &&
           info->name[0] != '<';
}

static Etd2xJniValue framework_reflect_method_is_default_java(void *env, void *t, const Etd2xJniValue *a,
                                                    size_t n, void *u) {
    (void)a; (void)u;
    framework_ReflectMethodInfo info;
    return framework_v_bool(n == 0 && framework_reflect_method_info(env, t, &info) && framework_reflect_method_is_default(&info));
}

static Etd2xJniValue framework_reflect_method_get_name(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)a; (void)u;
    framework_ReflectMethodInfo info;
    return framework_v_object(n == 0 && framework_reflect_method_info(env, t, &info) ? framework_new_string(env, info.name) : NULL);
}

static Etd2xJniValue framework_reflect_method_get_declaring_class(void *env, void *t, const Etd2xJniValue *a,
                                                        size_t n, void *u) {
    (void)a; (void)u;
    framework_ReflectMethodInfo info;
    return framework_v_object(n == 0 && framework_reflect_method_info(env, t, &info)
                    ? etd2x_jni_find_class_ref(env, info.owner) : NULL);
}

static Etd2xJniValue framework_reflect_method_get_modifiers(void *env, void *t, const Etd2xJniValue *a,
                                                  size_t n, void *u) {
    (void)a; (void)u;
    framework_ReflectMethodInfo info;
    return framework_v_int(n == 0 && framework_reflect_method_info(env, t, &info) ? framework_reflect_method_modifiers(&info) : 0);
}

static Etd2xJniValue framework_reflect_method_to_string(void *env, void *t, const Etd2xJniValue *a,
                                              size_t n, void *u) {
    (void)a; (void)u;
    framework_ReflectMethodInfo info;
    if (n != 0 || !framework_reflect_method_info(env, t, &info)) return framework_v_object(NULL);
    char text[1024] = {0};
    size_t pos = 0;
    /* Modifier.toString() order, then "default" (Method.toString). */
    const int32_t modifiers = framework_reflect_method_modifiers(&info);
    static const struct { int32_t bit; const char *word; } k_words[] = {
        {0x0001, "public "}, {0x0004, "protected "}, {0x0002, "private "},
        {0x0400, "abstract "}, {0x0008, "static "}, {0x0010, "final "},
        {0x0020, "synchronized "}, {0x0100, "native "}, {0x0800, "strictfp "},
    };
    for (size_t i = 0; i < framework_ARRAY_COUNT(k_words); ++i)
        if (modifiers & k_words[i].bit) framework_text_append(text, sizeof(text), &pos, k_words[i].word);
    if (framework_reflect_method_is_default(&info)) framework_text_append(text, sizeof(text), &pos, "default ");
    const char *ret = strchr(info.signature, ')');
    if (!info.exact || !ret || !framework_java_type_name_append(ret + 1, text, sizeof(text), &pos))
        framework_text_append(text, sizeof(text), &pos, "java.lang.Object");
    framework_text_append(text, sizeof(text), &pos, " ");
    for (const char *p = info.owner; *p && pos + 1 < sizeof(text); ++p) text[pos++] = *p == '/' ? '.' : *p;
    text[pos] = '\0';
    framework_text_append(text, sizeof(text), &pos, ".");
    framework_text_append(text, sizeof(text), &pos, info.name);
    framework_text_append(text, sizeof(text), &pos, "(");
    const char *p = info.signature[0] == '(' ? info.signature + 1 : "";
    for (bool first = true; p && *p && *p != ')'; first = false) {
        if (!first) framework_text_append(text, sizeof(text), &pos, ",");
        p = framework_java_type_name_append(p, text, sizeof(text), &pos);
    }
    framework_text_append(text, sizeof(text), &pos, ")");
    return framework_v_object(framework_new_string(env, text));
}

typedef struct framework_FrameworkBoxSpec { char type; const char *wrapper, *value_of, *unbox, *unbox_sig; } framework_FrameworkBoxSpec;
static const framework_FrameworkBoxSpec *framework_framework_box_spec(char type) {
    static const framework_FrameworkBoxSpec specs[] = {
        {'Z', "java/lang/Boolean", "(Z)Ljava/lang/Boolean;", "booleanValue", "()Z"},
        {'B', "java/lang/Byte", "(B)Ljava/lang/Byte;", "byteValue", "()B"},
        {'C', "java/lang/Character", "(C)Ljava/lang/Character;", "charValue", "()C"},
        {'S', "java/lang/Short", "(S)Ljava/lang/Short;", "shortValue", "()S"},
        {'I', "java/lang/Integer", "(I)Ljava/lang/Integer;", "intValue", "()I"},
        {'J', "java/lang/Long", "(J)Ljava/lang/Long;", "longValue", "()J"},
        {'F', "java/lang/Float", "(F)Ljava/lang/Float;", "floatValue", "()F"},
        {'D', "java/lang/Double", "(D)Ljava/lang/Double;", "doubleValue", "()D"},
    };
    for (size_t i = 0; i < framework_ARRAY_COUNT(specs); ++i) if (specs[i].type == type) return &specs[i];
    return NULL;
}

/* Parameter descriptors reduced to one type letter each ('L' for any
 * reference, including arrays). Returns -1 for a malformed descriptor. */
static int framework_reflect_param_types(const char *signature, char *types, size_t cap) {
    if (!signature || signature[0] != '(') return -1;
    size_t count = 0;
    for (const char *p = signature + 1; *p != ')'; ) {
        if (!*p || count >= cap) return -1;
        const char *start = p;
        while (*p == '[') ++p;
        if (*p == 'L') { p = strchr(p, ';'); if (!p) return -1; }
        else if (!*p || !strchr("ZBCSIJFD", *p)) return -1;
        ++p;
        types[count++] = (*start == '[' || *start == 'L') ? 'L' : *start;
    }
    return (int)count;
}

/* Unbox Method.invoke/Constructor.newInstance arguments per parameter type:
 * IllegalArgumentException for a count or type mismatch. elements[] (zeroed
 * by the caller) receives local refs for the caller to release. */
static bool framework_reflect_unbox_args(void *env, const char *signature, void *array,
                               Etd2xJniValue *args, void **elements, int *out_count) {
    char types[ETD2X_JNI_MAX_PARAMETER_SLOTS];
    const int count = framework_reflect_param_types(signature, types, sizeof(types));
    const int32_t supplied = array ? etd2x_jni_array_length_host(array) : 0;
    *out_count = 0;
    if (count < 0 || supplied != count) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "wrong number of arguments");
        return false;
    }
    *out_count = count;
    for (int i = 0; i < count; ++i) {
        (void)etd2x_jni_get_object_array_element_host(env, array, i, &elements[i]);
        if (types[i] == 'L') { args[i].l = elements[i]; continue; }
        const framework_FrameworkBoxSpec *spec = framework_framework_box_spec(types[i]);
        bool found = false;
        if (!spec || !elements[i] || !etd2x_jni_is_instance_of_class_host(elements[i], spec->wrapper) ||
            etd2x_jni_invoke_method_host(env, elements[i], spec->wrapper, spec->unbox, spec->unbox_sig,
                                         false, NULL, &args[i], &found) != ETD2X_OK || !found) {
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "argument type mismatch");
            return false;
        }
    }
    return true;
}

/* An exception thrown by code that Method.invoke/Constructor.newInstance ran
 * reaches the caller wrapped in InvocationTargetException (cause = target). */
static void framework_reflect_wrap_invocation_target(void *env) {
    void *target = etd2x_jni_exception_occurred_host(env);
    if (!target) return;
    etd2x_jni_exception_clear_host(env);
    void *wrapper = etd2x_jni_new_local_object(env, "java/lang/reflect/InvocationTargetException");
    Etd2xJniValue ctor_args[2] = {{0}};
    ctor_args[1].l = target;
    Etd2xJniValue ignored = {0};
    bool found = false;
    if (wrapper)
        (void)etd2x_jni_invoke_method_host(env, wrapper, "java/lang/reflect/InvocationTargetException", "<init>",
                                           "(Ljava/lang/String;Ljava/lang/Throwable;)V", false, ctor_args,
                                           &ignored, &found);
    if (etd2x_jni_exception_pending_host(env)) etd2x_jni_exception_clear_host(env);
    (void)etd2x_jni_throw_host(env, wrapper && found ? wrapper : target);
    if (wrapper) etd2x_jni_delete_local_ref_host(env, wrapper);
    etd2x_jni_delete_local_ref_host(env, target);
}

/* Method.invoke for an exact method: arguments are unboxed per parameter type,
 * instance calls use virtual dispatch on the receiver, primitive results are
 * boxed and a thrown exception is wrapped (java.lang.reflect.Method#invoke). */
static Etd2xJniValue framework_reflect_method_invoke(void *env, void *token, const Etd2xJniValue *a, size_t n, void *u) {
    framework_ReflectMethodInfo info;
    if (n != 2 || !framework_reflect_method_info(env, token, &info)) return framework_v_object(NULL);
    if (!info.exact) return framework_reflect_method_invoke_payload(env, token, a, n, u);
    if (!info.is_static && !a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "null receiver");
        return framework_v_object(NULL);
    }
    Etd2xJniValue args[ETD2X_JNI_MAX_PARAMETER_SLOTS];
    void *elements[ETD2X_JNI_MAX_PARAMETER_SLOTS] = {0};
    memset(args, 0, sizeof(args));
    int count = 0;
    const bool ok = framework_reflect_unbox_args(env, info.signature, a[1].l, args, elements, &count);
    Etd2xJniValue out = {0};
    bool done = false;
    if (ok) {
        Etd2xDexExecReport report = {0};
        if (info.is_static) {
            if (framework_g_fw.source_path[0] && etd2x_dex_execute_static_method) {
                done = etd2x_dex_execute_static_method(framework_g_fw.source_path, info.owner, info.name, info.signature,
                                                       env, args, (size_t)count, &out, &report) == ETD2X_OK &&
                       report.completed;
            } else {
                bool found = false;
                done = etd2x_jni_invoke_method_host(env, NULL, info.owner, info.name, info.signature, true,
                                                    args, &out, &found) == ETD2X_OK && found;
            }
        } else {
            char cls[256] = {0};
            if (!etd2x_jni_object_class_name_host(a[0].l, cls, sizeof(cls)))
                framework_copy_text(cls, sizeof(cls), info.owner, "");
            bool found = false;
            done = framework_framework_dispatch_instance(env, a[0].l, cls, info.name, info.signature, args,
                                               (size_t)count, &out, &found, &report) == ETD2X_OK && found;
        }
        if (etd2x_jni_exception_pending_host(env)) framework_reflect_wrap_invocation_target(env);
        else if (!done)
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/AbstractMethodError", info.name);
    }
    for (int i = 0; i < count; ++i) if (elements[i]) etd2x_jni_delete_local_ref_host(env, elements[i]);
    if (!done || etd2x_jni_exception_pending_host(env)) return framework_v_object(NULL);
    const char *ret = strchr(info.signature, ')');
    const char rt = ret && ret[1] ? ret[1] : 'V';
    if (rt == 'V') return framework_v_object(NULL);
    if (rt == 'L' || rt == '[') return framework_v_object(out.l);
    const framework_FrameworkBoxSpec *spec = framework_framework_box_spec(rt);
    Etd2xJniValue boxed = {0};
    bool found = false;
    if (!spec || etd2x_jni_invoke_method_host(env, NULL, spec->wrapper, "valueOf", spec->value_of, true,
                                              &out, &boxed, &found) != ETD2X_OK || !found)
        return framework_v_object(NULL);
    return framework_v_object(boxed.l);
}

/* Class.getModifiers(): DEX class_def.access_flags uses the Java modifier
 * bit assignments for class modifiers. Read the actual class definition so
 * AOSP overlay/app classes keep their declared public/final/interface/etc.
 * semantics instead of synthesizing provider-specific values. */
/* Java class-path resources. The app PathClassLoader serves ZIP entries of the
 * package's APK components in class-path order (DexPathList.findResource),
 * after its parent BootClassLoader; ETD2X ships no boot-classpath resource
 * archive, so the boot layer always misses. */
static void *framework_class_path_owned_stream(void *env, uint8_t *data, size_t size) {
    Etd2xAsset *asset = etd2x_asset_from_owned_buffer(data, size);
    if (!asset) return NULL;
    void *stream = etd2x_jni_new_local_object(env, "android/content/res/AssetManager$AssetInputStream");
    if (!stream || etd2x_jni_set_object_host_data(stream, asset) != ETD2X_OK) {
        if (stream) etd2x_jni_delete_local_ref_host(env, stream);
        etd2x_asset_close(asset);
        return NULL;
    }
    return stream;
}
static void *framework_class_path_resource_stream(void *env, const char *name) {
    if (!name || !name[0] || !etd2x_package_read_selected_entry_first) return NULL;
    uint8_t *data = NULL; size_t size = 0; bool found = false;
    const Etd2xResult rc = etd2x_package_read_selected_entry_first(framework_g_fw.source_path, name, &data, &size, &found);
    ETD2X_LOGCI("JAVA", "class-path resource name=%s found=%d bytes=%zu rc=%d", name, found ? 1 : 0, size, (int)rc);
    if (rc != ETD2X_OK || !found) { free(data); return NULL; }
    return framework_class_path_owned_stream(env, data, size);
}

static void *framework_class_path_resource_url(void *env, const char *name) {
    char path[PATH_CAP] = {0};
    if (!name || !name[0] || !etd2x_package_find_selected_entry_path) return NULL;
    Etd2xResult rc = etd2x_package_find_selected_entry_path(framework_g_fw.source_path, name, path, sizeof(path));
    if (rc != ETD2X_OK || !path[0]) return NULL;
    /* Java sees the same base APK pathname as ApplicationInfo.sourceDir. */
    const char *archive = !strcmp(path, framework_g_fw.source_path) ? framework_g_fw.package_code_path : path;
    char *encoded_path = framework_uri_encode_text(archive, "/:"), *encoded_name = framework_uri_encode_text(name, "/");
    void *url = NULL;
    if (encoded_path && encoded_name) {
        size_t cap = strlen(encoded_path) + strlen(encoded_name) + 13;
        char *spec = malloc(cap);
        if (spec) {
            snprintf(spec, cap, "jar:file:%s!/%s", encoded_path, encoded_name);
            url = etd2x_jni_new_local_object(env, "java/net/URL");
            void *text = framework_new_string(env, spec);
            Etd2xJniValue arg = {.l = text}, ignored = {0};
            if (url && (!text || !framework_java_call_virtual(env, url, "<init>", "(Ljava/lang/String;)V", &arg, 1, &ignored))) {
                etd2x_jni_delete_local_ref_host(env, url); url = NULL;
            }
            if (text) etd2x_jni_delete_local_ref_host(env, text);
            free(spec);
        }
    }
    free(encoded_path); free(encoded_name);
    ETD2X_LOGCI("JAVA", "class-path resource URL name=%s archive=%s found=%d", name, archive, url ? 1 : 0);
    return url;
}

static bool framework_class_resource_name_arg(void *env, const Etd2xJniValue *a, size_t n, char *out, size_t cap) {
    if (n != 1) return false;
    if (!a || !a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "name == null");
        return false;
    }
    return framework_read_jstring(a[0].l, out, cap);
}

/* Class.getResource*: Class.resolveName (absolute "/x" or relative to the
 * class's package), then the class's defining loader; bootstrap classes use
 * the boot class path. */
static Etd2xJniValue framework_class_get_resource_common(void *env, void *token,
                                               const Etd2xJniValue *a, size_t n,
                                               bool stream) {
    char name[PATH_CAP], resolved[PATH_CAP + 512];
    if (!framework_class_resource_name_arg(env, a, n, name, sizeof(name))) return framework_v_object(NULL);
    void *self = etd2x_jni_new_local_from_token(env, token);
    const bool app_class = self && etd2x_jni_class_uses_application_loader_host(self);
    char cls[512] = {0};
    if (self) (void)etd2x_jni_class_ref_name_host(self, cls, sizeof(cls));
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    if (!app_class) return framework_v_object(NULL);
    if (name[0] == '/') {
        snprintf(resolved, sizeof(resolved), "%s", name + 1);
    } else {
        const char *base = cls;
        while (*base == '[') ++base;
        if (*base == 'L') ++base;
        const char *slash = strrchr(base, '/');
        if (slash) snprintf(resolved, sizeof(resolved), "%.*s/%s", (int)(slash - base), base, name);
        else snprintf(resolved, sizeof(resolved), "%s", name);
    }
    return framework_v_object(stream ? framework_class_path_resource_stream(env, resolved) : framework_class_path_resource_url(env, resolved));
}

/* ClassLoader.getResourceAsStream / getSystemResourceAsStream: the only
 * ClassLoader instance ETD2X hands out is the app PathClassLoader (also the
 * system class loader). Names are class-path relative; no '/' stripping. */
static Etd2xJniValue framework_classloader_get_resource_as_stream(void *env, void *token,
                                                        const Etd2xJniValue *a, size_t n, void *u) {
    (void)token; (void)u;
    char name[PATH_CAP];
    if (!framework_class_resource_name_arg(env, a, n, name, sizeof(name))) return framework_v_object(NULL);
    return framework_v_object(framework_class_path_resource_stream(env, name));
}
static Etd2xJniValue framework_classloader_get_resource_url(void *env, void *token,
                                                   const Etd2xJniValue *a, size_t n, void *u) {
    (void)token; (void)u;
    char name[PATH_CAP];
    if (!framework_class_resource_name_arg(env, a, n, name, sizeof(name))) return framework_v_object(NULL);
    return framework_v_object(framework_class_path_resource_url(env, name));
}
static Etd2xJniValue framework_class_get_resource(void *env, void *token,
                                        const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    return framework_class_get_resource_common(env, token, a, n, false);
}
static Etd2xJniValue framework_class_get_resource_as_stream(void *env, void *token,
                                                  const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    return framework_class_get_resource_common(env, token, a, n, true);
}

static Etd2xJniValue framework_class_get_modifiers(void *env, void *token,
                                         const Etd2xJniValue *a, size_t n, void *u) {
    (void)a; (void)u;
    if (n != 0) return framework_v_int(0);
    char name[512] = {0};
    if (!framework_class_name_from_token(env, token, name, sizeof(name))) return framework_v_int(0);

    Etd2xDexClassView view = {0};
    bool found = false;
    uint32_t flags = 0;
    if (etd2x_package_acquire_dex_class && etd2x_package_release_dex_class &&
        etd2x_package_acquire_dex_class(framework_g_fw.source_path, name, &view, &found) == ETD2X_OK &&
        found && view.dex_data && view.class_def_offset + 8u <= view.dex_size) {
        const uint8_t *p = view.dex_data + view.class_def_offset + 4u;
        flags = (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
                ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
        etd2x_package_release_dex_class(&view);
    } else {
        void *self = etd2x_jni_new_local_from_token(env, token);
        if (self && etd2x_jni_class_is_interface_host(self)) {
            /* Host-modeled interfaces have no DEX class_def. */
            flags = UINT32_C(0x0001) | UINT32_C(0x0200) | UINT32_C(0x0400);
        }
        if (self) etd2x_jni_delete_local_ref_host(env, self);
    }
    /* public/final/interface/abstract/synthetic/annotation/enum */
    flags &= UINT32_C(0x0001) | UINT32_C(0x0010) | UINT32_C(0x0200) |
             UINT32_C(0x0400) | UINT32_C(0x1000) | UINT32_C(0x2000) |
             UINT32_C(0x4000);
    return framework_v_int((int32_t)flags);
}

/* Class.getDeclaredMethod/getMethod/getDeclaredConstructor/getConstructor:
 * the member with exactly these parameter types, else NoSuchMethodException
 * "<binary name>.<name>(<types>)". */
static void *framework_reflect_find_member(void *env, void *token, const char *name, void *param_types,
                                 bool declared_only, bool public_only) {
    char params[ETD2X_DEX_SIGNATURE_CAP];
    if (!param_types) framework_copy_text(params, sizeof(params), "()", "");
    else if (!framework_class_array_params(env, param_types, params, sizeof(params))) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NoSuchMethodException", name);
        return NULL;
    }
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (!self) return NULL;
    void *member = etd2x_jni_class_get_reflected_method_host(env, self, name, params, declared_only, public_only);
    if (!member && !etd2x_jni_exception_pending_host(env)) {
        char owner[256] = {0}, message[1024];
        (void)etd2x_jni_class_ref_name_host(self, owner, sizeof(owner));
        for (char *c = owner; *c; ++c) if (*c == '/') *c = '.';
        size_t pos = (size_t)snprintf(message, sizeof(message), "%s.%s(", owner, name);
        for (const char *p = params + 1; p && *p && *p != ')' && pos < sizeof(message);) {
            if (p != params + 1) framework_text_append(message, sizeof(message), &pos, ", ");
            p = framework_java_type_name_append(p, message, sizeof(message), &pos);
        }
        framework_text_append(message, sizeof(message), &pos, ")");
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NoSuchMethodException", message);
    }
    etd2x_jni_delete_local_ref_host(env, self);
    return member;
}

