static void framework_view_set_children_window_attached(void *env, framework_ViewPayload *view, bool attached);

static void framework_view_set_window_attached_recursive(void *env, framework_ViewPayload *view, bool attached) {
    if (!view || view->attached_to_window == attached) return;
    if (view->detaching) return;

    if (!attached) {
        view->detaching = true;
        framework_view_set_children_window_attached(env, view, false);
    }

    if (attached) {
        view->attached_to_window = true;
        framework_view_tree_attachment(env,view,true);
        framework_view_dispatch_attachment(env, view, true);
        if (etd2x_jni_exception_pending_host(env) || !view->attached_to_window) return;
    }
    if (view->surface_holder_global) {
        void *holder_ref = framework_local_from_global(env, view->surface_holder_global);
        framework_SurfaceHolderPayload *p = holder_ref ? framework_holder_payload(etd2x_jni_object_token_host(holder_ref)) : NULL;
        if (p) {
            p->surface_active = attached;
            if (!attached) framework_holder_dispatch_surface_destroyed(env, p, holder_ref);
        }
        if (holder_ref) etd2x_jni_delete_local_ref_host(env, holder_ref);
    }

    if (attached) {
        framework_view_set_children_window_attached(env, view, true);
    } else {
        framework_view_dispatch_attachment(env, view, false);
        framework_view_tree_attachment(env,view,false);
        view->attached_to_window = false;
        view->laid_out = false;
        view->detaching = false;
    }
}

static void framework_view_set_children_window_attached(void *env, framework_ViewPayload *view, bool attached) {
    const size_t count = view->child_count;
    void **children = count ? calloc(count, sizeof(*children)) : NULL;
    if (count && !children) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "View attachment"); return; }
    size_t used = 0;
    for (framework_ViewChildRef *c = view->children; c && used < count; c = c->next)
        children[used++] = etd2x_jni_new_local_ref_host(env, c->global_ref);
    for (size_t i = 0; i < used; ++i) {
        framework_ViewPayload *child = framework_view_payload_find(etd2x_jni_object_token_host(children[i]));
        if (child && child->parent_token == view->object_token && !etd2x_jni_exception_pending_host(env))
            framework_view_set_window_attached_recursive(env, child, attached);
        if (children[i]) etd2x_jni_delete_local_ref_host(env, children[i]);
    }
    free(children);
}

