/* ---------- java.lang.Runtime ----------
 * Android exposes the process Runtime singleton even on devices without any
 * optional Google/vendor services.  Keep this model deliberately small and
 * truthful: it exposes process-local runtime facts only and does not claim any
 * external platform capability. */
static Etd2xJniValue framework_runtime_get_runtime(void *env, void *token, const Etd2xJniValue *args,
                                         size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    return framework_v_object(n == 0 ? framework_local_from_global(env, framework_g_fw.java_runtime) : NULL);
}
static Etd2xJniValue framework_runtime_available_processors(void *env, void *token, const Etd2xJniValue *args,
                                                   size_t n, void *ud) {
    (void)env; (void)token; (void)args; (void)ud;
    if (n != 0) return framework_v_int(1);
    unsigned count = etd2x_compat_cpu_count ? etd2x_compat_cpu_count() : 1u;
    if (count < 1u) count = 1u;
    if (count > (unsigned)INT32_MAX) count = (unsigned)INT32_MAX;
    return framework_v_int((int32_t)count);
}
static Etd2xJniValue framework_runtime_gc(void *env, void *token, const Etd2xJniValue *args,
                                size_t n, void *ud) {
    (void)env; (void)token; (void)args; (void)n; (void)ud;
    /* ETD2X does not use a moving Java GC.  Objects are reference-model owned,
     * so Runtime.gc()/runFinalization() are advisory no-ops. */
    return framework_v_void();
}

/* Runtime.exec: an app process on Horizon cannot start another process, so
 * every command fails the way a missing executable fails on Android
 * (ProcessBuilder.start -> IOException "Cannot run program ...: error=2").
 * Argument checks follow Runtime.exec: null -> NullPointerException, an empty
 * command -> IllegalArgumentException. */
static Etd2xJniValue framework_runtime_exec_fail(void *env, const char *program) {
    char msg[600];
    snprintf(msg, sizeof(msg), "Cannot run program \"%s\": error=2, No such file or directory", program);
    (void)etd2x_jni_throw_new_by_name(env, "java/io/IOException", msg);
    return framework_v_object(NULL);
}
static Etd2xJniValue framework_runtime_exec_string(void *env, void *token, const Etd2xJniValue *args,
                                         size_t n, void *ud) {
    (void)token; (void)ud;
    char command[512] = {0};
    if (n < 1 || !args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "command");
        return framework_v_object(NULL);
    }
    (void)framework_read_jstring(args[0].l, command, sizeof(command));
    const char *start = command;
    while (*start == ' ' || *start == '\t' || *start == '\n' || *start == '\r' || *start == '\f') ++start;
    size_t len = strcspn(start, " \t\n\r\f");
    if (len == 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "Empty command");
        return framework_v_object(NULL);
    }
    char program[512];
    snprintf(program, sizeof(program), "%.*s", (int)len, start);
    return framework_runtime_exec_fail(env, program);
}
static Etd2xJniValue framework_runtime_exec_array(void *env, void *token, const Etd2xJniValue *args,
                                        size_t n, void *ud) {
    (void)token; (void)ud;
    if (n < 1 || !args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "cmdarray");
        return framework_v_object(NULL);
    }
    const int32_t count = etd2x_jni_array_length_host(args[0].l);
    if (count <= 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IndexOutOfBoundsException", "cmdarray is empty");
        return framework_v_object(NULL);
    }
    char program[512] = {0};
    void *first = NULL;
    if (etd2x_jni_get_object_array_element_host(env, args[0].l, 0, &first) != ETD2X_OK || !first) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "cmdarray[0]");
        return framework_v_object(NULL);
    }
    (void)framework_read_jstring(first, program, sizeof(program));
    etd2x_jni_delete_local_ref_host(env, first);
    return framework_runtime_exec_fail(env, program);
}

