/* ---------- Locale ---------- */

/* locale value */
/* Immutable constructor values retain arbitrary UTF-16; constants keep their
 * existing compact ASCII representation. Clones share values until reset. */
typedef struct framework_LocaleValue framework_LocaleValue;
typedef struct framework_LocalePayload {
    char language[16], country[16], variant[16];
    framework_LocaleValue *value;
} framework_LocalePayload;
struct framework_LocaleValue {
    framework_LocalePayload payload;
    uint16_t *text[3];
    int32_t length[3];
    const char *extension;
    char *owned_extension;
    char script[5];
    framework_LocaleValue *next;
};
static framework_LocalePayload framework_g_locale_default_payload, framework_g_locale_root_payload, framework_g_locale_english_payload, framework_g_locale_us_payload;
static framework_LocaleValue *framework_g_locale_values;
static pthread_mutex_t framework_g_locale_list_lock = PTHREAD_MUTEX_INITIALIZER;
static framework_LocalePayload *framework_locale_payload(void *t) { return etd2x_jni_get_token_host_data(t); }
static const char *framework_locale_ascii(const framework_LocalePayload *p, int part) {
    return !p ? "" : part == 0 ? p->language : part == 1 ? p->country : p->variant;
}
static size_t framework_locale_length(const framework_LocalePayload *p, int part) {
    return p && p->value ? (size_t)p->value->length[part] : strlen(framework_locale_ascii(p, part));
}
static uint16_t framework_locale_unit(const framework_LocalePayload *p, int part, size_t index) {
    return p && p->value ? p->value->text[part][index] : (unsigned char)framework_locale_ascii(p, part)[index];
}
static bool framework_locale_part_is(const framework_LocalePayload *p, int part, const char *s) {
    const size_t len = strlen(s);
    if (framework_locale_length(p, part) != len) return false;
    for (size_t i = 0; i < len; ++i) if (framework_locale_unit(p, part, i) != (unsigned char)s[i]) return false;
    return true;
}
static const char *framework_locale_extension(const framework_LocalePayload *p) {
    return p && p->value ? p->value->extension : "";
}
static const char *framework_locale_script(const framework_LocalePayload *p) {
    return p && p->value ? p->value->script : "";
}
static size_t framework_locale_country_code(const framework_LocalePayload *p, char out[3]) {
    size_t len = framework_locale_length(p, 1);
    if (len == 2) {
        for (size_t i = 0; i < 2; ++i) {
            const uint16_t c = framework_locale_unit(p, 1, i);
            out[i] = c > 0 && c < 128 ? (char)c : '?';
        }
        out[2] = 0;
    }
    return len;
}

