static Etd2xResult framework_register_locale_constants(void) {
    for (size_t i = 0; i < framework_ARRAY_COUNT(framework_g_locale_constants); ++i) {
        Etd2xResult rc = etd2x_jni_register_field("java/util/Locale", framework_g_locale_constants[i].name,
                                                 "Ljava/util/Locale;", true, (Etd2xJniValue){0});
        if (rc != ETD2X_OK) return rc;
    }
    return ETD2X_OK;
}

static Etd2xResult framework_instantiate_locale_constants(void) {
    for (size_t i = 0; i < framework_ARRAY_COUNT(framework_g_locale_constants); ++i) {
        const int alias = framework_g_locale_constants[i].alias;
        void *value = alias < 0 ? framework_make_global_object("java/util/Locale")
            : etd2x_jni_new_global_ref_host(etd2x_jni_current_env(), framework_g_locale_constants[alias].global);
        if (!value) return ETD2X_ERR_NO_MEMORY;
        framework_g_locale_constants[i].global = value;
        if (alias < 0) framework_set_host_data_global(value, &framework_g_locale_constants[i].payload);
        framework_set_static_object("java/util/Locale", framework_g_locale_constants[i].name, "Ljava/util/Locale;", value);
    }
    return ETD2X_OK;
}

static void framework_locale_constants_reset(void) {
    for (size_t i = 0; i < framework_ARRAY_COUNT(framework_g_locale_constants); ++i)
        framework_delete_global(&framework_g_locale_constants[i].global);
}



