static framework_ViewQueuedEvent *framework_queued_event_create(void *env, void *runnable_ref, int64_t delay_ms) {
    if (!env || !runnable_ref) return NULL;
    framework_ViewQueuedEvent *event = calloc(1, sizeof(*event));
    if (!event) return NULL;
    event->runnable_global = etd2x_jni_new_global_ref_host(env, runnable_ref);
    if (!event->runnable_global) { free(event); return NULL; }
    if (delay_ms < 0) delay_ms = 0;
    const int64_t now = framework_framework_uptime_millis();
    event->due_uptime_ms = delay_ms > INT64_MAX - now ? INT64_MAX : now + delay_ms;
    return event;
}

static void framework_queued_event_insert_sorted(framework_ViewQueuedEvent **head, framework_ViewQueuedEvent **tail,
                                        size_t *count, framework_ViewQueuedEvent *event) {
    if (!head || !tail || !count || !event) return;
    framework_ViewQueuedEvent **link = head;
    while (*link && (*link)->due_uptime_ms <= event->due_uptime_ms) link = &(*link)->next;
    event->next = *link;
    *link = event;
    if (!event->next) *tail = event;
    if (!*tail) *tail = event;
    (*count)++;
    if (head == &framework_g_fw.ui_events_head) pthread_cond_broadcast(&framework_g_ui_event_cond);
}

static bool framework_enqueue_main_ui_event(void *env, void *runnable_ref, int64_t delay_ms) {
    framework_ViewQueuedEvent *event = framework_queued_event_create(env, runnable_ref, delay_ms);
    if (!event) return false;
    ETD2X_PERF_LOCK(&framework_g_ui_event_lock);
    framework_queued_event_insert_sorted(&framework_g_fw.ui_events_head, &framework_g_fw.ui_events_tail,
                               &framework_g_fw.ui_event_count, event);
    pthread_mutex_unlock(&framework_g_ui_event_lock);
    return true;
}

static size_t framework_remove_queued_runnable(void *env, framework_ViewQueuedEvent **head, framework_ViewQueuedEvent **tail,
                                     size_t *count, void *runnable_ref) {
    size_t removed = 0;
    if (!head || !tail || !count || !runnable_ref) return 0;
    framework_ViewQueuedEvent **link = head;
    while (*link) {
        framework_ViewQueuedEvent *event = *link;
        if (etd2x_jni_same_object_host(event->runnable_global, runnable_ref)) {
            *link = event->next;
            etd2x_jni_delete_global_ref_host(env, event->runnable_global);
            free(event);
            if (*count) (*count)--;
            removed++;
            continue;
        }
        link = &event->next;
    }
    *tail = NULL;
    for (framework_ViewQueuedEvent *event = *head; event; event = event->next) *tail = event;
    return removed;
}

