static bool framework_invoke_runnable(void *env, void *runnable_ref);

static Etd2xJniValue framework_activity_run_on_ui_thread(void *env, void *token,
                                                const Etd2xJniValue *args,
                                                size_t n, void *ud) {
    (void)ud;
    if (!token || !args || n != 1 || !args[0].l) return framework_v_void();

    /* Android Activity.runOnUiThread() is synchronous when the caller already
     * is the Activity/UI thread. Deferring that work until ETD2X's outer event
     * pump changes lifecycle ordering and can deadlock code that immediately
     * waits for state established by the Runnable. Only off-thread callers are
     * posted to the main queue. */
    if (framework_g_fw.main_thread_valid && pthread_equal(pthread_self(), framework_g_fw.main_thread)) {
        const bool ran = framework_invoke_runnable(env, args[0].l);
        ETD2X_LOGCI("ANDROID", "Activity.runOnUiThread immediate=%s",
                    ran ? "yes" : "no");
        return framework_v_void();
    }

    const bool queued = framework_enqueue_main_ui_event(env, args[0].l, 0);
    ETD2X_LOGCI("ANDROID", "Activity.runOnUiThread queued=%s count=%zu",
                queued ? "yes" : "no", framework_g_fw.ui_event_count);
    return framework_v_void();
}




