    framework_EnumPayload *form=framework_enum_payload(etd2x_jni_object_token_host(args[1].l));
    if (!found || !form || form->ordinal<0 || form->ordinal>3 ||
        !etd2x_jni_is_instance_of_class_host(args[1].l,"java/text/Normalizer$Form")) {
        etd2x_jni_delete_local_ref_host(env,string.l);
        (void)etd2x_jni_throw_new_by_name(env,"java/lang/IllegalArgumentException","normalization form");
        return framework_v_object(NULL);
    }
