static Etd2xJniValue framework_pf_query(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)t;
    const intptr_t op=(intptr_t)u;
    if(op==4)return framework_v_int(1);
    const int32_t format=n?a[0].i:0;
    size_t i=0;while(i<framework_ARRAY_COUNT(framework_pf_formats)&&framework_pf_formats[i].value!=format)++i;
    if(op==0) {
        if(i==framework_ARRAY_COUNT(framework_pf_formats)||!framework_pf_formats[i].bits) {
            char message[80];snprintf(message,sizeof(message),"unknown pixel format %d",format);
            (void)etd2x_jni_throw_new_by_name(env,"java/lang/IllegalArgumentException",message);
        }else if(n!=2||!a[1].l) {
            (void)etd2x_jni_throw_new_by_name(env,"java/lang/NullPointerException","info");
        }else {
            framework_set_instance_int_field(a[1].l,"bitsPerPixel",framework_pf_formats[i].bits);
            framework_set_instance_int_field(a[1].l,"bytesPerPixel",framework_pf_formats[i].bytes);
        }
        return framework_v_void();
    }
    if(op==1)return framework_v_bool(i<framework_ARRAY_COUNT(framework_pf_formats)&&framework_pf_formats[i].alpha);
    if(op==2)return framework_v_bool(i<framework_ARRAY_COUNT(framework_pf_formats)&&framework_pf_formats[i].public_format);
    if(i<framework_ARRAY_COUNT(framework_pf_formats)&&format!=-1)return framework_v_object(framework_new_string(env,framework_pf_formats[i].name));
    char number[40];snprintf(number,sizeof(number),"%d",format);return framework_v_object(framework_new_string(env,number));
}
static Etd2xJniValue framework_pf_ctor(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)env;(void)t;(void)a;(void)n;(void)u;return framework_v_void();
}
static Etd2xResult framework_register_pixel_format_members(void) {
    Etd2xResult rc=etd2x_jni_register_class("android/graphics/PixelFormat","java/lang/Object");
    if(rc!=ETD2X_OK)return rc;
    for(size_t i=0;i<framework_ARRAY_COUNT(framework_pf_formats);++i) {
        rc=etd2x_jni_register_field("android/graphics/PixelFormat",framework_pf_formats[i].name,"I",true,framework_v_int(framework_pf_formats[i].value));
        if(rc!=ETD2X_OK)return rc;
    }
    rc=etd2x_jni_register_field("android/graphics/PixelFormat","bitsPerPixel","I",false,framework_v_int(0));
    if(rc==ETD2X_OK)rc=etd2x_jni_register_field("android/graphics/PixelFormat","bytesPerPixel","I",false,framework_v_int(0));
    if(rc!=ETD2X_OK)return rc;
    static const struct {const char *cls,*name,*sig; bool st; Etd2xJniMethodCallback cb; intptr_t op;} methods[] = {
        {"android/graphics/PixelFormat","<init>","()V",false,framework_pf_ctor,0},
        {"android/graphics/PixelFormat","getPixelFormatInfo","(ILandroid/graphics/PixelFormat;)V",true,framework_pf_query,0},
        {"android/graphics/PixelFormat","formatHasAlpha","(I)Z",true,framework_pf_query,1},
        {"android/graphics/PixelFormat","isPublicFormat","(I)Z",true,framework_pf_query,2},
        {"android/graphics/PixelFormat","formatToString","(I)Ljava/lang/String;",true,framework_pf_query,3},
        {"android/view/Display","getPixelFormat","()I",false,framework_pf_query,4},
    };
    for(size_t i=0;i<framework_ARRAY_COUNT(methods);++i) {
        rc=etd2x_jni_register_method(methods[i].cls,methods[i].name,methods[i].sig,methods[i].st,methods[i].cb,(void*)methods[i].op);
        if(rc!=ETD2X_OK)return rc;
    }
    return ETD2X_OK;
}


