    if (p) framework_view_replace_global(env, &p->context_global, args[0].l);
    if(p&&(args[1].l||n>2))framework_layout_apply_view_attributes(env,token,args[0].l,args[1].l,n>2?args[2].i:0,n>3?args[3].i:0);
