/* View.getLeft/getTop/getRight/getBottom: ETD2X lays every view out at its
 * parent's origin with the view's own size, so left/top are 0. */
/* Bounded trace of the geometry the guest reads back (diagnostic). */
static _Atomic uint32_t framework_g_view_geometry_reports;
static void framework_view_geometry_report(void *env, void *token, const char *what, int32_t value, const framework_ViewPayload *p) {
    if (atomic_fetch_add(&framework_g_view_geometry_reports, 1u) >= 48u) return;
    char cls[160] = "?";
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (self) { (void)etd2x_jni_object_class_name_host(self, cls, sizeof(cls)); etd2x_jni_delete_local_ref_host(env, self); }
    ETD2X_LOGCI("ANDROID", "View.%s class=%s -> %d (size=%dx%d attached=%d parent=%d)", what, cls, (int)value,
                p ? (int)p->width : -1, p ? (int)p->height : -1, p && p->attached_to_window ? 1 : 0,
                p && p->parent_token ? 1 : 0);
}

static Etd2xJniValue framework_view_get_edge(void *env, void *token,
                                   const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args;
    framework_ViewPayload *p = n == 0 ? framework_view_payload_ensure(token) : NULL;
    const uintptr_t edge = (uintptr_t)ud; /* 0 left, 1 top, 2 right, 3 bottom */
    static const char *const names[] = {"getLeft", "getTop", "getRight", "getBottom"};
    const int32_t value = !p ? 0 : edge == 0 ? p->layout_left : edge == 1 ? p->layout_top :
                          edge == 2 ? p->layout_left + p->width : p->layout_top + p->height;
    framework_view_geometry_report(env, token, names[edge & 3u], value, p);
    return framework_v_int(value);
}

