/* Android View measurement is guest-visible state.  Horizon/NWindow sizes are
 * inputs to layout, never the implementation of MeasureSpec semantics. */
static int32_t framework_view_measure_spec_mode(int32_t spec) {
    return (int32_t)((uint32_t)spec & UINT32_C(0xc0000000));
}

static int32_t framework_view_measure_spec_size(int32_t spec) {
    return (int32_t)((uint32_t)spec & UINT32_C(0x3fffffff));
}

static Etd2xJniValue framework_view_measure_spec_get_mode(void *env, void *token,
                                                const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)ud;
    return framework_v_int(n == 1 ? framework_view_measure_spec_mode(args[0].i) : 0);
}

static Etd2xJniValue framework_view_measure_spec_get_size(void *env, void *token,
                                                const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)ud;
    return framework_v_int(n == 1 ? framework_view_measure_spec_size(args[0].i) : 0);
}

static Etd2xJniValue framework_view_measure_spec_make(void *env, void *token,
                                            const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)ud;
    if (n != 2) return framework_v_int(0);
    return framework_v_int((int32_t)(((uint32_t)args[0].i & UINT32_C(0x3fffffff)) |
                           ((uint32_t)args[1].i & UINT32_C(0xc0000000))));
}

static int32_t framework_view_default_measured_size(int32_t current, int32_t spec) {
    const int32_t mode = framework_view_measure_spec_mode(spec);
    const int32_t size = framework_view_measure_spec_size(spec);
    /* View.getDefaultSize(): EXACTLY/AT_MOST use the parent-provided size;
     * UNSPECIFIED uses the view's suggested size.  ETD2X's current base View
     * has no minimum drawable state, so the existing laid-out size is the
     * closest generic suggested-size value. */
    return mode == (int32_t)UINT32_C(0x80000000) || mode == 0x40000000 ? size : current;
}

static Etd2xJniValue framework_view_get_default_size(void *env, void *token,
                                           const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)ud;
    return framework_v_int(n == 2 ? framework_view_default_measured_size(args[0].i, args[1].i) : 0);
}

static Etd2xJniValue framework_view_resolve_size(void *env, void *token,
                                       const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)ud;
    if (n < 2) return framework_v_int(0);
    const int32_t mode = framework_view_measure_spec_mode(args[1].i), size = framework_view_measure_spec_size(args[1].i);
    uint32_t result = (uint32_t)args[0].i;
    if (mode == (int32_t)UINT32_C(0x80000000) && size < args[0].i)
        result = (uint32_t)size | UINT32_C(0x01000000);
    else if (mode == 0x40000000) result = (uint32_t)size;
    if (n == 3) result |= (uint32_t)args[2].i & UINT32_C(0xff000000);
    else result &= UINT32_C(0x00ffffff);
    return framework_v_int((int32_t)result);
}

