/* Topmost View ancestor (a ViewParent that is not a View, such as the
 * window's view root, ends the walk). */
static void *framework_view_root_token(void *env, void *token) {
    void *cur = token;
    for (unsigned guard = 0; cur && guard < 4096u; ++guard) {
        framework_ViewPayload *p = framework_view_payload_find(cur);
        if (!p || !p->parent_token) break;
        void *parent = etd2x_jni_new_local_from_token(env, p->parent_token);
        const bool is_view = parent && etd2x_jni_is_instance_of_class_host(parent, "android/view/View");
        if (parent) etd2x_jni_delete_local_ref_host(env, parent);
        if (!is_view) break;
        cur = p->parent_token;
    }
    return cur;
}

