static Etd2xJniValue framework_view_remove_callbacks(void *env, void *token,
                                           const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)ud;
    if (n == 1 && args[0].l) {
        ETD2X_PERF_LOCK(&framework_g_ui_event_lock);
        size_t removed = framework_remove_queued_runnable(env, &framework_g_fw.ui_events_head, &framework_g_fw.ui_events_tail,
                                                       &framework_g_fw.ui_event_count, args[0].l);
        framework_ViewAnimationEvent **link = &framework_g_fw.view_animations;
        while (*link) {
            framework_ViewAnimationEvent *event = *link;
            if (etd2x_jni_object_token_host(event->view_global) != token ||
                !etd2x_jni_same_object_host(event->runnable_global, args[0].l)) { link = &event->next; continue; }
            *link = event->next;
            framework_delete_global(&event->view_global); framework_delete_global(&event->runnable_global);
            free(event); ++removed;
        }
        pthread_mutex_unlock(&framework_g_ui_event_lock);
        return framework_v_bool(removed != 0);
    }
    return framework_v_bool(false);
}

static Etd2xJniValue framework_viewgroup_default_layout_params(void *env, void *token,
                                                       const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args;
    if (n != 0) return framework_v_object(NULL);
    const char *cls = ud ? (const char *)ud : "android/view/ViewGroup$LayoutParams";
    int32_t w = -2, h = -2;
    if (!strcmp(cls, "android/widget/FrameLayout$LayoutParams")) w = h = -1;
    if (!strcmp(cls, "android/widget/LinearLayout$LayoutParams")) {
        void *self = etd2x_jni_new_local_from_token(env, token);
        int32_t orientation = self ? framework_get_instance_int_field(env, self, "android/widget/LinearLayout", "mOrientation") : 0;
        if (self) etd2x_jni_delete_local_ref_host(env, self);
        if (orientation != 0 && orientation != 1) return framework_v_object(NULL);
        if (orientation == 1) w = -1;
    }
    void *params = etd2x_jni_new_local_object(env, cls);
    if (params) {
        Etd2xJniValue size[2] = {{.i=w}, {.i=h}};
        (void)framework_layout_params_ctor(env, etd2x_jni_object_token_host(params), size, 2, NULL);
        if (!strcmp(cls, "android/widget/FrameLayout$LayoutParams") ||
            !strcmp(cls, "android/widget/LinearLayout$LayoutParams"))
            framework_set_instance_int_field(params, "gravity", -1);
    }
    return framework_v_object(params);
}

static Etd2xJniValue framework_viewgroup_add_view(void *env, void *token,
                                        const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    if (!token || !args || n < 1 || n > 3) return framework_v_void();
    if (!args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "null child view");
        return framework_v_void();
    }
    framework_ViewPayload *parent = framework_view_payload_ensure(token);
    if (!parent) return framework_v_void();
    framework_ViewPayload *child_view = framework_view_payload_ensure(etd2x_jni_object_token_host(args[0].l));
    if (!child_view) return framework_v_void();
    if (child_view->parent_token) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalStateException", "child already has a parent");
        return framework_v_void();
    }
    const int32_t requested_index = n >= 2 ? args[1].i : -1;
    const size_t index = requested_index < 0 ? parent->child_count : (size_t)requested_index;
    if (index > parent->child_count) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IndexOutOfBoundsException", "child index exceeds child count");
        return framework_v_void();
    }
    if (n == 3) {
        if (!args[2].l) {
            (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "LayoutParams == null");
            return framework_v_void();
        }
        framework_view_replace_global(env, &child_view->layout_params_global, args[2].l);
    }
    if (!child_view->layout_params_global) {
        void *self = etd2x_jni_new_local_from_token(env, token);
        Etd2xJniValue params = {0};
        const bool ok = self && framework_java_call_virtual(env, self, "generateDefaultLayoutParams",
                                                   "()Landroid/view/ViewGroup$LayoutParams;", NULL, 0, &params);
        if (self) etd2x_jni_delete_local_ref_host(env, self);
        if (!ok || !params.l) {
            if (!etd2x_jni_exception_pending_host(env))
                (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "null default LayoutParams");
            return framework_v_void();
        }
        framework_view_replace_global(env, &child_view->layout_params_global, params.l);
        etd2x_jni_delete_local_ref_host(env, params.l);
    }
    framework_ViewChildRef *child = calloc(1, sizeof(*child));
    if (!child) return framework_v_void();
    child->global_ref = etd2x_jni_new_global_ref_host(env, args[0].l);
    if (!child->global_ref) { free(child); return framework_v_void(); }
    if (child_view) child_view->parent_token = parent->object_token;
    framework_ViewChildRef **tail = &parent->children;
    for (size_t i = 0; i < index; ++i) tail = &(*tail)->next;
    child->next = *tail;
    *tail = child;
    parent->child_count++;
    ETD2X_LOGCI("ANDROID", "ViewGroup.addView children=%zu", parent->child_count);
    /* Android measures and lays out a newly attached child (setFrame ->
     * onSizeChanged) before a SurfaceView in it creates its surface. */
    framework_view_schedule_layout(env, parent);
    if (parent->attached_to_window) {
        framework_view_set_window_attached_recursive(env, child_view, true);
    }
    return framework_v_void();
}

static framework_ViewPayload *framework_view_find_id_in_tree(void *token, int32_t id, unsigned depth) {
    framework_ViewPayload *p = depth <= 64u ? framework_view_payload_find(token) : NULL;
    if (!p) return NULL;
    if (p->id == id) return p;
    for (framework_ViewChildRef *c = p->children; c; c = c->next) {
        framework_ViewPayload *found = framework_view_find_id_in_tree(etd2x_jni_object_token_host(c->global_ref),
                                                  id, depth + 1u);
        if (found) return found;
    }
    return NULL;
}

/* View.findViewById: depth-first over this view and its descendants; NO_ID never matches. */
static Etd2xJniValue framework_view_find_view_by_id(void *env, void *token,
                                          const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    if (n != 1 || args[0].i == -1) return framework_v_object(NULL);
    framework_ViewPayload *found = framework_view_find_id_in_tree(token, args[0].i, 0);
    return framework_v_object(found ? etd2x_jni_new_local_from_token(env, found->object_token) : NULL);
}

static void *framework_window_content_parent(void *env);

/* Activity/Window.findViewById search the window's view hierarchy. */
static Etd2xJniValue framework_window_find_view_by_id(void *env, void *token,
                                            const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)ud;
    if (n != 1 || args[0].i == -1) return framework_v_object(NULL);
    if(!framework_window_content_parent(env)||etd2x_jni_exception_pending_host(env))return framework_v_object(NULL);
    void *roots[2] = {framework_g_fw.decor_view, framework_g_fw.content_view};
    for (size_t i = 0; i < 2; ++i) {
        framework_ViewPayload *found = roots[i]
            ? framework_view_find_id_in_tree(etd2x_jni_object_token_host(roots[i]), args[0].i, 0) : NULL;
        if (found) return framework_v_object(etd2x_jni_new_local_from_token(env, found->object_token));
    }
    return framework_v_object(NULL);
}

