/* ---------- android.view.Choreographer ----------
 * Java Choreographer is Looper-bound.  Model it with ETD2X's existing Java
 * Looper queue rather than a title-specific vsync shim: each FrameCallback is
 * wrapped in a private Runnable and scheduled for the next display period.
 * This keeps callback execution on the owning thread and preserves the
 * one-shot Android FrameCallback contract. */
static framework_ChoreographerPayload *framework_choreographer_payload_from_token(void *token) {
    framework_ChoreographerPayload *p = (framework_ChoreographerPayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == CHOREOGRAPHER_PAYLOAD_MAGIC ? p : NULL;
}

static framework_ChoreographerRunnablePayload *framework_choreographer_runnable_from_token(void *token) {
    framework_ChoreographerRunnablePayload *p =
        (framework_ChoreographerRunnablePayload *)etd2x_jni_get_token_host_data(token);
    return p && p->magic == CHOREOGRAPHER_RUNNABLE_MAGIC ? p : NULL;
}

static int64_t framework_choreographer_next_due_ms(int64_t delay_ms) {
    if (delay_ms < 0) delay_ms = 0;
    int64_t now = framework_framework_uptime_millis();
    int64_t earliest = delay_ms > INT64_MAX - now ? INT64_MAX : now + delay_ms;
    const double hz = framework_g_fw.cfg.refresh_rate_hz > 1.0f ? framework_g_fw.cfg.refresh_rate_hz : 60.0;
    int64_t period_ms = (int64_t)(1000.0 / hz + 0.5);
    if (period_ms < 1) period_ms = 1;
    if (earliest >= INT64_MAX - period_ms) return INT64_MAX;
    return ((earliest / period_ms) + 1) * period_ms;
}

static Etd2xJniValue framework_choreographer_frame_runnable_run(void *env, void *token,
                                                       const Etd2xJniValue *args,
                                                       size_t n, void *ud) {
    (void)args; (void)ud;
    framework_ChoreographerRunnablePayload *p = framework_choreographer_runnable_from_token(token);
    if (!p || n != 0 || !p->callback_global) return framework_v_void();

    void *callback = framework_local_from_global(env, p->callback_global);
    framework_delete_global(&p->callback_global); /* FrameCallback registrations are one-shot. */
    if (!callback) return framework_v_void();

    char cls[256] = {0};
    Etd2xJniValue arg = {0}, ignored = {0};
    Etd2xDexExecReport report = {0};
    bool found = false;
    struct timespec ts = {0};
    clock_gettime(CLOCK_MONOTONIC, &ts);
    arg.j = (int64_t)ts.tv_sec * INT64_C(1000000000) + ts.tv_nsec;

    const uint64_t sequence = p->choreographer ? ++p->choreographer->callbacks_dispatched : 0;
    const bool trace = sequence <= 4 || sequence % 300 == 0;
    Etd2xResult rc = ETD2X_ERR_ARGUMENT;
    if (etd2x_jni_object_class_name_host(callback, cls, sizeof(cls))) {
        if (trace)
            ETD2X_LOGCI("CHOREO", "Java frame BEGIN class=%s callback=%p owner=%p sequence=%llu frameNs=%lld",
                        cls, etd2x_jni_object_token_host(callback),
                        (void *)(uintptr_t)pthread_self(), (unsigned long long)sequence,
                        (long long)arg.j);
        rc = framework_framework_dispatch_instance(env, callback, cls, "doFrame", "(J)V",
                                         &arg, 1, &ignored, &found, &report);
    }
    if (trace) {
        struct timespec end = {0};
        clock_gettime(CLOCK_MONOTONIC, &end);
        const int64_t elapsed_ns = (int64_t)end.tv_sec * INT64_C(1000000000) + end.tv_nsec - arg.j;
        ETD2X_LOGCI("CHOREO", "Java frame END class=%s sequence=%llu rc=%d found=%d exception=%d elapsedUs=%lld",
                    cls[0] ? cls : "<unknown>", (unsigned long long)sequence,
                    (int)rc, found ? 1 : 0, etd2x_jni_exception_pending_host(env) ? 1 : 0,
                    (long long)(elapsed_ns / 1000));
    }
    etd2x_jni_delete_local_ref_host(env, callback);

    if (rc != ETD2X_OK || !found) {
        char reason[448];
        snprintf(reason, sizeof(reason),
                 "Choreographer.FrameCallback %s.doFrame failed rc=%d: %.220s",
                 cls[0] ? cls : "<unknown>", (int)rc,
                 report.detail[0] ? report.detail : "callback method not found");
        ETD2X_LOGCE("ANDROID", "%s", reason);
        etd2x_jni_request_process_exit(reason);
    }
    return framework_v_void();
}

static Etd2xJniValue framework_choreographer_get_instance(void *env, void *token,
                                                 const Etd2xJniValue *args,
                                                 size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    framework_LooperPayload *looper = framework_looper_for_current_thread();
    if (!looper) {
        etd2x_jni_throw_new_by_name(env, "java/lang/RuntimeException",
                                    "The current thread must have a looper!");
        return framework_v_object(NULL);
    }

    const pthread_t self = pthread_self();
    ETD2X_PERF_LOCK(&framework_g_choreographer_lock);
    for (framework_ChoreographerPayload *p = framework_g_fw.choreographers; p; p = p->next) {
        if (pthread_equal(p->owner_thread, self)) {
            void *r = framework_local_from_global(env, p->object_global);
            pthread_mutex_unlock(&framework_g_choreographer_lock);
            return framework_v_object(r);
        }
    }

    framework_ChoreographerPayload *p = calloc(1, sizeof(*p));
    void *object = p ? etd2x_jni_new_local_object(env, "android/view/Choreographer") : NULL;
    void *handler = object ? etd2x_jni_new_local_object(env, "android/os/Handler") : NULL;
    if (!p || !object || !handler) {
        if (handler) etd2x_jni_delete_local_ref_host(env, handler);
        if (object) etd2x_jni_delete_local_ref_host(env, object);
        free(p);
        pthread_mutex_unlock(&framework_g_choreographer_lock);
        return framework_v_object(NULL);
    }

    framework_HandlerPayload *hp = framework_handler_payload_ensure(env, etd2x_jni_object_token_host(handler));
    if (!hp) {
        etd2x_jni_delete_local_ref_host(env, handler);
        etd2x_jni_delete_local_ref_host(env, object);
        free(p);
        pthread_mutex_unlock(&framework_g_choreographer_lock);
        return framework_v_object(NULL);
    }
    framework_handler_bind_looper(env, hp, looper->looper_global);

    p->magic = CHOREOGRAPHER_PAYLOAD_MAGIC;
    p->owner_thread = self;
    p->object_global = etd2x_jni_new_global_ref_host(env, object);
    p->handler_global = etd2x_jni_new_global_ref_host(env, handler);
    if (!p->object_global || !p->handler_global ||
        etd2x_jni_set_object_host_data(object, p) != ETD2X_OK) {
        framework_delete_global(&p->object_global);
        framework_delete_global(&p->handler_global);
        etd2x_jni_delete_local_ref_host(env, handler);
        etd2x_jni_delete_local_ref_host(env, object);
        free(p);
        pthread_mutex_unlock(&framework_g_choreographer_lock);
        return framework_v_object(NULL);
    }
    p->next = framework_g_fw.choreographers;
    framework_g_fw.choreographers = p;
    etd2x_jni_delete_local_ref_host(env, handler);
    pthread_mutex_unlock(&framework_g_choreographer_lock);
    return framework_v_object(object);
}

static Etd2xJniValue framework_choreographer_post_frame_callback_common(void *env, void *token,
                                                               const Etd2xJniValue *args,
                                                               size_t n, bool delayed) {
    framework_ChoreographerPayload *p = framework_choreographer_payload_from_token(token);
    if (!p || !args || n != (delayed ? 2u : 1u) || !args[0].l) return framework_v_void();

    void *handler = framework_local_from_global(env, p->handler_global);
    void *runnable = etd2x_jni_new_local_object(env, CHOREOGRAPHER_RUNNABLE_CLASS);
    if (!handler || !runnable) {
        if (handler) etd2x_jni_delete_local_ref_host(env, handler);
        if (runnable) etd2x_jni_delete_local_ref_host(env, runnable);
        return framework_v_void();
    }

    framework_ChoreographerRunnablePayload *rp = calloc(1, sizeof(*rp));
    if (!rp) {
        etd2x_jni_delete_local_ref_host(env, runnable);
        etd2x_jni_delete_local_ref_host(env, handler);
        return framework_v_void();
    }
    rp->magic = CHOREOGRAPHER_RUNNABLE_MAGIC;
    rp->choreographer = p;
    rp->callback_global = etd2x_jni_new_global_ref_host(env, args[0].l);
    if (!rp->callback_global || etd2x_jni_set_object_host_data(runnable, rp) != ETD2X_OK) {
        framework_delete_global(&rp->callback_global);
        free(rp);
        etd2x_jni_delete_local_ref_host(env, runnable);
        etd2x_jni_delete_local_ref_host(env, handler);
        return framework_v_void();
    }
    ETD2X_PERF_LOCK(&framework_g_choreographer_lock);
    rp->next = framework_g_fw.choreographer_runnables;
    framework_g_fw.choreographer_runnables = rp;
    pthread_mutex_unlock(&framework_g_choreographer_lock);

    framework_HandlerPayload *hp = framework_handler_payload_from_token(etd2x_jni_object_token_host(handler));
    const int64_t due = framework_choreographer_next_due_ms(delayed ? args[1].j : 0);
    const bool queued = hp && framework_handler_enqueue_event(env, hp,
        etd2x_jni_object_token_host(handler), runnable, due, false,
        etd2x_jni_object_token_host(args[0].l));
    etd2x_jni_delete_local_ref_host(env, runnable);
    etd2x_jni_delete_local_ref_host(env, handler);
    if (!queued) framework_delete_global(&rp->callback_global);
    return framework_v_void();
}

static Etd2xJniValue framework_choreographer_post_frame_callback(void *env, void *token,
                                                        const Etd2xJniValue *args,
                                                        size_t n, void *ud) {
    (void)ud;
    return framework_choreographer_post_frame_callback_common(env, token, args, n, false);
}

static Etd2xJniValue framework_choreographer_post_frame_callback_delayed(void *env, void *token,
                                                                const Etd2xJniValue *args,
                                                                size_t n, void *ud) {
    (void)ud;
    return framework_choreographer_post_frame_callback_common(env, token, args, n, true);
}

static Etd2xJniValue framework_choreographer_remove_frame_callback(void *env, void *token,
                                                          const Etd2xJniValue *args,
                                                          size_t n, void *ud) {
    (void)ud;
    framework_ChoreographerPayload *p = framework_choreographer_payload_from_token(token);
    if (!p || n != 1 || !args[0].l) return framework_v_void();
    void *handler = framework_local_from_global(env, p->handler_global);
    if (handler) {
        const void *callback_token = etd2x_jni_object_token_host(args[0].l);
        (void)framework_handler_queue_scan(env, etd2x_jni_object_token_host(handler), 2,
                                 NULL, 0, (void *)callback_token, true);
        etd2x_jni_delete_local_ref_host(env, handler);
        ETD2X_PERF_LOCK(&framework_g_choreographer_lock);
        for (framework_ChoreographerRunnablePayload *rp = framework_g_fw.choreographer_runnables; rp; rp = rp->next) {
            if (rp->callback_global && etd2x_jni_object_token_host(rp->callback_global) == callback_token)
                framework_delete_global(&rp->callback_global);
        }
        pthread_mutex_unlock(&framework_g_choreographer_lock);
    }
    return framework_v_void();
}


static Etd2xJniValue framework_configuration_get_locales(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    return framework_v_object(n==0?framework_configuration_locales(env,token):NULL);
}

/* ---------- android.view.InputDevice / android.hardware.input.InputManager ----------
 * Android exposes gamepads as stable device IDs plus source/axis metadata.
 * ETD2X has one logical controller endpoint backed by the current libnx pad
 * snapshot.  The object identity is stable while connection state is queried
 * dynamically, matching InputManager's process-wide device registry model. */
enum {
    ETD2X_ANDROID_INPUT_DEVICE_ID = 1,
    ETD2X_ANDROID_TOUCH_DEVICE_ID = 2,
    ETD2X_SOURCE_TOUCHSCREEN = 0x00001002,
    ETD2X_SOURCE_CLASS_BUTTON = 0x00000001,
    ETD2X_SOURCE_CLASS_JOYSTICK = 0x00000010,
    ETD2X_SOURCE_DPAD = 0x00000201,
    ETD2X_SOURCE_GAMEPAD = 0x00000401,
    ETD2X_SOURCE_JOYSTICK = 0x01000010,
};

/* The built-in touchscreen is a second, always present InputDevice. */
static bool framework_input_device_is_touch(void *token) {
    return token && framework_g_fw.touch_device && etd2x_jni_object_token_host(framework_g_fw.touch_device) == token;
}

static bool framework_android_touch_axis_supported(int32_t axis) {
    /* AXIS_X, Y, PRESSURE, SIZE, TOUCH_MAJOR, TOUCH_MINOR, ORIENTATION */
    return (axis >= 0 && axis <= 5) || axis == 8;
}

static bool framework_android_input_connected_locked(void) {
    return framework_g_fw.input_snapshot_valid && framework_g_fw.input_snapshot.controller_connected;
}

static int32_t framework_android_input_sources(void) {
    return ETD2X_SOURCE_DPAD | ETD2X_SOURCE_GAMEPAD | ETD2X_SOURCE_JOYSTICK;
}

static bool framework_android_input_axis_supported(int32_t axis) {
    /* MotionEvent axes used by Android gamepads: left X/Y, right Z/RZ,
     * triggers, and d-pad hats. */
    switch (axis) {
        case 0:  /* AXIS_X */
        case 1:  /* AXIS_Y */
        case 11: /* AXIS_Z */
        case 14: /* AXIS_RZ */
        case 15: /* AXIS_HAT_X */
        case 16: /* AXIS_HAT_Y */
        case 17: /* AXIS_LTRIGGER */
        case 18: /* AXIS_RTRIGGER */
            return true;
        default:
            return false;
    }
}

static bool framework_android_input_key_supported(int32_t keycode) {
    switch (keycode) {
        case 19: case 20: case 21: case 22: case 23: /* DPAD */
        case 96: case 97: case 99: case 100:          /* A/B/X/Y */
        case 102: case 103: case 104: case 105:      /* L1/R1/L2/R2 */
        case 106: case 107:                           /* thumb buttons */
        case 108: case 109:                           /* START/SELECT */
            return true;
        default:
            return false;
    }
}

static Etd2xJniValue framework_input_device_get_device_ids(void *env, void *token,
                                                  const Etd2xJniValue *args,
                                                  size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    if (n != 0) return framework_v_object(NULL);
    ETD2X_PERF_LOCK(&framework_g_input_lock);
    const bool connected = framework_android_input_connected_locked();
    pthread_mutex_unlock(&framework_g_input_lock);
    const int32_t ids[2] = {ETD2X_ANDROID_TOUCH_DEVICE_ID, ETD2X_ANDROID_INPUT_DEVICE_ID};
    const int32_t count = connected ? 2 : 1;
    void *array = etd2x_jni_new_local_int_array(env, count);
    if (array) (void)etd2x_jni_int_array_write(array, 0, count, ids);
    return framework_v_object(array);
}

static Etd2xJniValue framework_input_device_get_device(void *env, void *token,
                                              const Etd2xJniValue *args,
                                              size_t n, void *ud) {
    (void)token; (void)ud;
    if (n == 1 && args[0].i == ETD2X_ANDROID_TOUCH_DEVICE_ID)
        return framework_v_object(framework_local_from_global(env, framework_g_fw.touch_device));
    if (n != 1 || args[0].i != ETD2X_ANDROID_INPUT_DEVICE_ID) return framework_v_object(NULL);
    ETD2X_PERF_LOCK(&framework_g_input_lock);
    const bool connected = framework_android_input_connected_locked();
    pthread_mutex_unlock(&framework_g_input_lock);
    return framework_v_object(connected ? framework_local_from_global(env, framework_g_fw.input_device) : NULL);
}

static Etd2xJniValue framework_input_device_get_id(void *env, void *token,
                                          const Etd2xJniValue *args,
                                          size_t n, void *ud) {
    (void)env; (void)args; (void)ud;
    if (n != 0) return framework_v_int(-1);
    return framework_v_int(framework_input_device_is_touch(token) ? ETD2X_ANDROID_TOUCH_DEVICE_ID : ETD2X_ANDROID_INPUT_DEVICE_ID);
}

