static Etd2xJniValue framework_message_queue_is_idle(void *env, void *token,
                                           const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)args; (void)ud;
    framework_LooperPayload *looper = n == 0 ? (framework_LooperPayload *)etd2x_jni_get_token_host_data(token) : NULL;
    if (!looper || looper->magic != LOOPER_PAYLOAD_MAGIC) return framework_v_bool(true);
    const int64_t now = framework_framework_uptime_millis();
    bool idle;
    if (looper->is_main) {
        ETD2X_PERF_LOCK(&framework_g_ui_event_lock);
        idle = !framework_g_fw.ui_events_head || framework_g_fw.ui_events_head->due_uptime_ms > now;
        pthread_mutex_unlock(&framework_g_ui_event_lock);
    } else {
        pthread_mutex_lock(&looper->lock);
        idle = !looper->events_head || looper->events_head->due_uptime_ms > now;
        pthread_mutex_unlock(&looper->lock);
    }
    return framework_v_bool(idle);
}

static Etd2xJniValue framework_looper_prepare(void *env, void *token,
                                    const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    if (n != 0) return framework_v_void();
    if (framework_looper_for_current_thread()) {
        etd2x_jni_throw_new_by_name(env, "java/lang/RuntimeException",
                                    "Only one Looper may be created per thread");
        return framework_v_void();
    }
    if (!framework_looper_create_for_current_thread(env, false, NULL))
        etd2x_jni_throw_new_by_name(env, "java/lang/RuntimeException", "Unable to create Looper");
    return framework_v_void();
}

static void framework_looper_describe_event(void *env, void *local, bool is_message, int32_t what,
                                  char *out, size_t cap) {
    char cls[96] = "?";
    if (!is_message) {
        (void)etd2x_jni_object_class_name_host(local, cls, sizeof(cls));
        snprintf(out, cap, "runnable=%s", cls);
        return;
    }
    framework_MessagePayload *mp = framework_message_payload(etd2x_jni_object_token_host(local));
    void *ref = mp ? framework_local_from_global(env, mp->callback_global ? mp->callback_global
                                                                : mp->target_global) : NULL;
    if (ref) {
        (void)etd2x_jni_object_class_name_host(ref, cls, sizeof(cls));
        etd2x_jni_delete_local_ref_host(env, ref);
    }
    if (mp && mp->callback_global) {
        snprintf(out, cap, "message callback=%s", cls);
        return;
    }
    void *obj_token = framework_message_obj_token(env, local);
    framework_EnumPayload *obj_enum = obj_token ? framework_enum_payload(obj_token) : NULL;
    snprintf(out, cap, "message what=%d handler=%s obj=%s", (int)what, cls,
             obj_enum && obj_enum->name ? obj_enum->name : "-");
}

static Etd2xJniValue framework_looper_loop(void *env, void *token,
                                 const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)args; (void)ud;
    framework_LooperPayload *looper = n == 0 ? framework_looper_for_current_thread() : NULL;
    if (!looper) {
        etd2x_jni_throw_new_by_name(env, "java/lang/RuntimeException", "No Looper; Looper.prepare() wasn't called");
        return framework_v_void();
    }
    if (looper->is_main) return framework_v_void(); /* Main queue is driven by ETD2X's Activity loop. */
    for (;;) {
        /* MessageQueue.nativePollOnce also dispatches native descriptor
         * callbacks (including NDK sensors) on this Java Looper's owner.
         * Never hold the Java queue lock across guest callbacks. */
        if (ALooper_pollOnce) (void)ALooper_pollOnce(0, NULL, NULL, NULL);
        if (etd2x_jni_exception_pending_host(env)) return framework_v_void();
        pthread_mutex_lock(&looper->lock);
        {
            const int64_t now = framework_framework_uptime_millis();
            if (looper->quit || etd2x_jni_process_exit_requested(NULL, 0) || (looper->quit_safely &&
                                 (!looper->events_head || looper->events_head->due_uptime_ms > now))) {
                pthread_mutex_unlock(&looper->lock);
                return framework_v_void();
            }
            if (!looper->events_head || looper->events_head->due_uptime_ms > now) {
                /* Bounded slices keep a pending process exit observable. */
                int64_t wait_ms = looper->events_head ? looper->events_head->due_uptime_ms - now : 100;
                const int64_t slice_ms = ALooper_pollOnce ? 8 : 100;
                if (wait_ms > slice_ms) wait_ms = slice_ms;
                struct timespec deadline = {0};
                clock_gettime(CLOCK_REALTIME, &deadline);
                deadline.tv_sec += wait_ms / 1000;
                deadline.tv_nsec += (wait_ms % 1000) * 1000000LL;
                if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }
                (void)framework_framework_cond_timedwait(&looper->cond, &looper->lock, &deadline);
                pthread_mutex_unlock(&looper->lock);
                continue;
            }
        }
        framework_ViewQueuedEvent *event = looper->events_head;
        looper->events_head = event->next;
        if (!looper->events_head) looper->events_tail = NULL;
        if (looper->event_count) looper->event_count--;
        pthread_mutex_unlock(&looper->lock);

        void *local = etd2x_jni_new_local_ref_host(env, event->runnable_global);
        etd2x_jni_delete_global_ref_host(env, event->runnable_global);
        const bool is_message = event->is_message;
        const int32_t what = event->what;
        free(event);
        if (local) {
            char desc[sizeof(looper->dispatch_desc)];
            framework_looper_describe_event(env, local, is_message, what, desc, sizeof(desc));
            pthread_mutex_lock(&looper->lock);
            memcpy(looper->dispatch_desc, desc, sizeof(desc));
            looper->dispatch_begin_ms = framework_framework_uptime_millis();
            looper->dispatched++;
            pthread_mutex_unlock(&looper->lock);
            if (is_message) (void)framework_handler_dispatch_message(env, local);
            else (void)framework_invoke_runnable(env, local);
            pthread_mutex_lock(&looper->lock);
            looper->dispatch_begin_ms = 0;
            pthread_mutex_unlock(&looper->lock);
            etd2x_jni_delete_local_ref_host(env, local);
        }
        if (etd2x_jni_exception_pending_host(env)) {
            /* Android's Looper does not swallow a throwing callback: the
             * exception propagates out of loop() and ends the thread. */
            char ex_class[256] = {0}, ex_msg[256] = {0};
            void *ex = etd2x_jni_exception_occurred_host(env);
            if (ex) {
                (void)etd2x_jni_object_class_name_host(ex, ex_class, sizeof(ex_class));
                (void)etd2x_jni_exception_message_host(ex, ex_msg, sizeof(ex_msg));
                etd2x_jni_delete_local_ref_host(env, ex);
            }
            ETD2X_LOGCW("ANDROID", "Looper.loop ending with pending exception %s: %s after %s",
                        ex_class[0] ? ex_class : "<unknown>", ex_msg, looper->dispatch_desc);
            return framework_v_void();
        }
    }
}

static void framework_looper_thread_name(pthread_t owner, char *out, size_t cap) {
    snprintf(out, cap, "-");
    for (framework_ThreadPayload *p = framework_g_fw.threads; p; p = p->next)
        if (p->thread_valid && pthread_equal(p->thread, owner)) {
            if (p->name) snprintf(out, cap, "%s", p->name);
            else snprintf(out, cap, "Thread-%lld", (long long)p->id);
            return;
        }
}

void etd2x_android_log_looper_states(const char *reason) {
    const int64_t now = framework_framework_uptime_millis();
    ETD2X_PERF_LOCK(&framework_g_ui_event_lock);
    const size_t main_queued = framework_g_fw.ui_event_count;
    pthread_mutex_unlock(&framework_g_ui_event_lock);
    ETD2X_LOGCI("ANDROID", "stall-report reason=%s looper=main queued=%zu",
                reason ? reason : "-", main_queued);
    for (framework_LooperPayload *l = framework_g_fw.loopers; l; l = l->next) {
        if (l->is_main) continue;
        char name[64];
        framework_looper_thread_name(l->owner_thread, name, sizeof(name));
        pthread_mutex_lock(&l->lock);
        const size_t queued = l->event_count;
        const int64_t next_due = l->events_head ? l->events_head->due_uptime_ms - now : -1;
        const uint64_t dispatched = l->dispatched;
        const int64_t begin = l->dispatch_begin_ms;
        char desc[sizeof(l->dispatch_desc)];
        memcpy(desc, l->dispatch_desc, sizeof(desc));
        const bool quit = l->quit || l->quit_safely;
        pthread_mutex_unlock(&l->lock);
        if (begin)
            ETD2X_LOGCI("ANDROID",
                        "stall-report reason=%s looper=%s queued=%zu nextDueMs=%lld dispatched=%llu quit=%d state=dispatching elapsedMs=%lld current=%s",
                        reason ? reason : "-", name, queued, (long long)next_due,
                        (unsigned long long)dispatched, quit ? 1 : 0, (long long)(now - begin), desc);
        else
            ETD2X_LOGCI("ANDROID",
                        "stall-report reason=%s looper=%s queued=%zu nextDueMs=%lld dispatched=%llu quit=%d state=idle last=%s",
                        reason ? reason : "-", name, queued, (long long)next_due,
                        (unsigned long long)dispatched, quit ? 1 : 0, desc[0] ? desc : "-");
    }
}

static Etd2xJniValue framework_looper_quit_common(void *env, void *token,
                                        const Etd2xJniValue *args, size_t n, bool safely) {
    (void)args;
    framework_LooperPayload *looper = n == 0 ? (framework_LooperPayload *)etd2x_jni_get_token_host_data(token) : NULL;
    if (!looper || looper->magic != LOOPER_PAYLOAD_MAGIC) return framework_v_void();
    if (looper->is_main) {
        etd2x_jni_throw_new_by_name(env, "java/lang/IllegalStateException",
                                    "Main thread not allowed to quit");
        return framework_v_void();
    }
    pthread_mutex_lock(&looper->lock);
    if (safely) looper->quit_safely = true;
    else looper->quit = true;
    pthread_cond_broadcast(&looper->cond);
    pthread_mutex_unlock(&looper->lock);
    return framework_v_void();
}

static Etd2xJniValue framework_looper_quit(void *env, void *token,
                                 const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud; return framework_looper_quit_common(env, token, args, n, false);
}

static Etd2xJniValue framework_looper_quit_safely(void *env, void *token,
                                        const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud; return framework_looper_quit_common(env, token, args, n, true);
}

/* ---------- android.os.HandlerThread ----------
 * HandlerThread is a Thread whose run() prepares a Looper, publishes it to
 * getLooper(), invokes the protected onLooperPrepared() hook, then enters
 * Looper.loop().  This is the platform contract used by framework code that
 * wants a dedicated callback/Choreographer thread. */
static Etd2xJniValue framework_handler_thread_ctor_common(void *env, void *token,
                                                 const Etd2xJniValue *args,
                                                 size_t n, bool with_priority) {
    if (!token || !args || n != (with_priority ? 2u : 1u)) return framework_v_void();
    if (!args[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException",
                                          "name cannot be null");
        return framework_v_void();
    }
    framework_ThreadPayload *p = framework_thread_payload_identity(token);
    if (!p) return framework_v_void();
    char *name = etd2x_jni_string_utf_dup(args[0].l);
    if (!name) return framework_v_void();
    free(p->name);
    p->name = name;
    p->handler_thread = true;
    p->handler_thread_priority = with_priority ? args[1].i : 0;
    return framework_v_void();
}

static Etd2xJniValue framework_handler_thread_ctor(void *env, void *token,
                                          const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    return framework_handler_thread_ctor_common(env, token, args, n, false);
}

static Etd2xJniValue framework_handler_thread_ctor_priority(void *env, void *token,
                                                   const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    return framework_handler_thread_ctor_common(env, token, args, n, true);
}

static Etd2xJniValue framework_handler_thread_on_looper_prepared(void *env, void *token,
                                                        const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)token; (void)args; (void)n; (void)ud;
    return framework_v_void();
}

static Etd2xJniValue framework_handler_thread_run(void *env, void *token,
                                         const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    framework_ThreadPayload *p = framework_thread_payload(token);
    if (!p || n != 0) return framework_v_void();

    framework_LooperPayload *looper = framework_looper_for_current_thread();
    if (!looper) looper = framework_looper_create_for_current_thread(env, false, NULL);
    if (!looper || !looper->looper_global) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/RuntimeException",
                                          "HandlerThread could not create Looper");
        return framework_v_void();
    }

    void *published = etd2x_jni_new_global_ref_host(env, looper->looper_global);
    if (!published) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError",
                                          "HandlerThread Looper global reference");
        return framework_v_void();
    }
    void *old = __atomic_exchange_n(&p->handler_looper_global, published, __ATOMIC_ACQ_REL);
    if (old) etd2x_jni_delete_global_ref_host(env, old);

    ETD2X_LOGCI("ANDROID", "HandlerThread looper ready name=%s priority=%d",
                p->name ? p->name : "unnamed", (int)p->handler_thread_priority);

    void *self = etd2x_jni_new_local_from_token(env, token);
    if (self) {
        char cls[256] = {0};
        Etd2xJniValue ignored = {0};
        Etd2xDexExecReport report = {0};
        bool found = false;
        if (etd2x_jni_object_class_name_host(self, cls, sizeof(cls))) {
            Etd2xResult rc = framework_framework_dispatch_instance(env, self, cls,
                "onLooperPrepared", "()V", NULL, 0, &ignored, &found, &report);
            if (rc != ETD2X_OK || !found) {
                ETD2X_LOGCE("ANDROID",
                            "HandlerThread.onLooperPrepared failed class=%s rc=%d found=%d detail=%s",
                            cls, (int)rc, found ? 1 : 0, report.detail);
                etd2x_jni_delete_local_ref_host(env, self);
                return framework_v_void();
            }
        }
        etd2x_jni_delete_local_ref_host(env, self);
    }
    if (etd2x_jni_exception_pending_host(env)) return framework_v_void();

    (void)framework_looper_loop(env, NULL, NULL, 0, NULL);
    ETD2X_LOGCI("ANDROID", "HandlerThread looper exit name=%s",
                p->name ? p->name : "unnamed");
    return framework_v_void();
}

static void *framework_handler_thread_published_looper(framework_ThreadPayload *p) {
    if (!p || !p->started) return NULL;
    while (!etd2x_jni_process_exit_requested(NULL, 0) &&
           !__atomic_load_n(&p->finished, __ATOMIC_ACQUIRE)) {
        void *r = __atomic_load_n(&p->handler_looper_global, __ATOMIC_ACQUIRE);
        if (r) return r;
        struct timespec nap = {0, 1000 * 1000};
        nanosleep(&nap, NULL);
    }
    return __atomic_load_n(&p->handler_looper_global, __ATOMIC_ACQUIRE);
}

static Etd2xJniValue framework_handler_thread_get_looper(void *env, void *token,
                                                const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    framework_ThreadPayload *p = framework_thread_payload(token);
    void *global = n == 0 ? framework_handler_thread_published_looper(p) : NULL;
    return framework_v_object(global ? etd2x_jni_new_local_ref_host(env, global) : NULL);
}

static Etd2xJniValue framework_handler_thread_quit_common(void *env, void *token,
                                                 const Etd2xJniValue *args, size_t n,
                                                 bool safely) {
    (void)env; (void)args;
    framework_ThreadPayload *p = framework_thread_payload(token);
    void *global = n == 0 ? framework_handler_thread_published_looper(p) : NULL;
    framework_LooperPayload *looper = global ? framework_looper_payload_from_ref(global) : NULL;
    if (!looper) return framework_v_bool(false);
    pthread_mutex_lock(&looper->lock);
    if (safely) looper->quit_safely = true; else looper->quit = true;
    pthread_cond_broadcast(&looper->cond);
    pthread_mutex_unlock(&looper->lock);
    return framework_v_bool(true);
}

static Etd2xJniValue framework_handler_thread_quit(void *env, void *token,
                                          const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud; return framework_handler_thread_quit_common(env, token, args, n, false);
}

static Etd2xJniValue framework_handler_thread_quit_safely(void *env, void *token,
                                                 const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud; return framework_handler_thread_quit_common(env, token, args, n, true);
}

static Etd2xJniValue framework_handler_thread_get_thread_id(void *env, void *token,
                                                   const Etd2xJniValue *args, size_t n, void *ud) {
    (void)env; (void)args; (void)ud;
    framework_ThreadPayload *p = framework_thread_payload_identity(token);
    if (n != 0 || !p || !p->started || __atomic_load_n(&p->finished, __ATOMIC_ACQUIRE))
        return framework_v_int(-1);
    return framework_v_int((int32_t)(p->id & INT32_MAX));
}

static Etd2xJniValue framework_framework_default_ctor(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){(void)env;(void)t;(void)a;(void)n;(void)u;return framework_v_void();}
static Etd2xJniValue framework_framework_noop_void(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){(void)env;(void)t;(void)a;(void)n;(void)u;return framework_v_void();}
static Etd2xJniValue framework_framework_true(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){(void)env;(void)t;(void)a;(void)n;(void)u;return framework_v_bool(true);}

/* ---------- java.lang.Throwable detail message / cause ----------
 * DEX `new X(msg)` builds an ordinary instance; libcore keeps the message in
 * Throwable.detailMessage and the cause in Throwable.cause. */
static void framework_throwable_store(void *env, void *token, void *message_ref, void *cause_ref) {
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (!self) return;
    bool found = false;
    (void)etd2x_jni_set_instance_field_value_for_class(self, "java/lang/Throwable", "detailMessage", "Ljava/lang/String;", (Etd2xJniValue){.l=message_ref}, &found);
    (void)etd2x_jni_set_instance_field_value_for_class(self, "java/lang/Throwable", "cause", "Ljava/lang/Throwable;", (Etd2xJniValue){.l=cause_ref}, &found);
    etd2x_jni_delete_local_ref_host(env, self);
}
static Etd2xJniValue framework_throwable_ctor(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){(void)u;framework_throwable_store(env,t,n>=1?a[0].l:NULL,n==2?a[1].l:NULL);return framework_v_void();}
static Etd2xJniValue framework_throwable_ctor_cause(void*env,void*t,const Etd2xJniValue*a,size_t n,void*u){
    (void)u;
    void *msg = NULL;
    if (n == 1 && a[0].l) { /* Throwable(Throwable cause): message = cause.toString() */
        char cls[256] = {0}; Etd2xJniValue s = {0}; bool found = false;
        if (etd2x_jni_object_class_name_host(a[0].l, cls, sizeof(cls)))
            (void)etd2x_jni_invoke_method_host(env, a[0].l, cls, "toString", "()Ljava/lang/String;", false, NULL, &s, &found);
        msg = found ? s.l : NULL;
    }
    framework_throwable_store(env, t, msg, n == 1 ? a[0].l : NULL);
    if (msg) etd2x_jni_delete_local_ref_host(env, msg);
    return framework_v_void();
}
