        etd2x_jni_set_instance_field_value(callback, "activity", "Landroid/app/Activity;", (Etd2xJniValue){.l=activity}) == ETD2X_OK &&
        etd2x_jni_set_instance_field_value(callback, "request", "I", args[1]) == ETD2X_OK &&
        etd2x_jni_set_instance_field_value(callback, "data", "Landroid/content/Intent;", (Etd2xJniValue){.l=intent->unavailable_result_global}) == ETD2X_OK &&
        framework_enqueue_main_ui_event(env, callback, 0);
