/* u is the optional Handler argument index, otherwise 0. */
static Etd2xJniValue framework_sensor_manager_register_listener(void *env, void *token,
                                                       const Etd2xJniValue *args, size_t n, void *u) {
    (void)token;
    if (n < 3 || !args || !args[0].l || !args[1].l) return framework_v_bool(false);
    if (args[2].i < 0) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalArgumentException", "negative sensor delay");
        return framework_v_bool(false);
    }
    framework_SensorPayload *sensor = etd2x_jni_get_object_host_data(args[1].l);
    if (!sensor || (sensor->type != 1 && sensor->type != 4)) return framework_v_bool(false);
    void *requested_handler = u ? args[(intptr_t)u].l : NULL;
    pthread_mutex_lock(&framework_g_sensor_listener_lock);
    void *existing_handler = NULL;
    for (framework_SensorListenerRegistration *r = framework_g_fw.sensor_registrations; r; r = r->next) {
        if (!r->active || !etd2x_jni_same_object_host(r->listener_global, args[0].l)) continue;
        existing_handler = r->handler_global;
        if (etd2x_jni_same_object_host(r->sensor_global, args[1].l)) {
            r->rate = args[2].i;
            r->next_due_ns = 0;
            pthread_mutex_unlock(&framework_g_sensor_listener_lock);
            return framework_v_bool(true);
        }
    }
    void *handler = existing_handler ? framework_local_from_global(env, existing_handler) :
                    requested_handler ? etd2x_jni_new_local_ref_host(env, requested_handler) :
                    etd2x_jni_new_local_object(env, "android/os/Handler");
    framework_HandlerPayload *hp = handler ? framework_handler_payload_from_token(etd2x_jni_object_token_host(handler)) : NULL;
    if (handler && !requested_handler && !existing_handler) {
        hp = framework_handler_payload_ensure(env, etd2x_jni_object_token_host(handler));
        framework_handler_bind_looper(env, hp, framework_g_fw.main_looper);
    }
    framework_SensorListenerRegistration *r = hp && hp->looper_global ? calloc(1, sizeof(*r)) : NULL;
    void *event = r ? etd2x_jni_new_local_object(env, "android/hardware/SensorEvent") : NULL;
    void *values = event ? etd2x_jni_new_local_float_array(env, 3) : NULL;
    void *runnable = values ? etd2x_jni_new_local_object(env, SENSOR_RUNNABLE) : NULL;
    bool ok = false;
    if (r && runnable) {
        r->listener_global = etd2x_jni_new_global_ref_host(env, args[0].l);
        r->sensor_global = etd2x_jni_new_global_ref_host(env, args[1].l);
        r->handler_global = etd2x_jni_new_global_ref_host(env, handler);
        r->event_global = etd2x_jni_new_global_ref_host(env, event);
        r->values_global = etd2x_jni_new_global_ref_host(env, values);
        r->runnable_global = etd2x_jni_new_global_ref_host(env, runnable);
        ok = r->listener_global && r->sensor_global && r->handler_global && r->event_global && r->values_global && r->runnable_global;
        if (ok) {
            framework_set_instance_object_field(event, "sensor", "Landroid/hardware/Sensor;", args[1].l);
            framework_set_instance_object_field(event, "values", "[F", values);
            (void)etd2x_jni_set_object_host_data(runnable, r);
            r->active = true; r->rate = args[2].i;
            r->next = framework_g_fw.sensor_registrations; framework_g_fw.sensor_registrations = r;
        }
    }
    if (!ok && r) { framework_sensor_registration_release(r); free(r); }
    if (runnable) etd2x_jni_delete_local_ref_host(env, runnable);
    if (values) etd2x_jni_delete_local_ref_host(env, values);
    if (event) etd2x_jni_delete_local_ref_host(env, event);
    if (handler) etd2x_jni_delete_local_ref_host(env, handler);
    pthread_mutex_unlock(&framework_g_sensor_listener_lock);
    ETD2X_LOGCI("SENSOR", "Java register type=%d rate=%d result=%d handler=%s", sensor->type, args[2].i,
                ok ? 1 : 0, requested_handler ? "explicit" : "main");
    return framework_v_bool(ok);
}
static Etd2xJniValue framework_sensor_manager_unregister_listener(void *env, void *token,
                                                         const Etd2xJniValue *args, size_t n, void *u) {
    (void)token; (void)u;
    if (!args || n < 1 || !args[0].l) return framework_v_void();
    pthread_mutex_lock(&framework_g_sensor_listener_lock);
    for (framework_SensorListenerRegistration *r = framework_g_fw.sensor_registrations; r; r = r->next) {
        if (!r->active || !etd2x_jni_same_object_host(r->listener_global, args[0].l) ||
            (n == 2 && args[1].l && !etd2x_jni_same_object_host(r->sensor_global, args[1].l))) continue;
        r->active = false; r->pending = false;
        (void)framework_handler_queue_scan(env, etd2x_jni_object_token_host(r->handler_global), 0, r->runnable_global, 0, NULL, true);
        framework_sensor_registration_release(r);
        /* Retain the small registration until reset: an executing Runnable may
         * still hold its host-data pointer while unregister runs. */
    }
    pthread_mutex_unlock(&framework_g_sensor_listener_lock);
    return framework_v_void();
}
static void framework_android_sensors_update_input(void *env, const Etd2xInputSnapshot *snapshot) {
    /* Also feeds NDK sensors used from a Java Activity (including native Unity
     * threads), rather than restricting publication to NativeActivity. */
    if (etd2x_sensors_publish) etd2x_sensors_publish(snapshot);
    Etd2xASensorEvent events[2];
    size_t count = etd2x_sensors_read_latest ? etd2x_sensors_read_latest(events, 2) : 0;
    pthread_mutex_lock(&framework_g_sensor_listener_lock);
    for (framework_SensorListenerRegistration *r = framework_g_fw.sensor_registrations; r; r = r->next) {
        if (!r->active) continue;
        if (framework_g_java_sensor_source != (count != 0)) {
            framework_g_java_sensor_source = count != 0;
            ETD2X_LOGCI("SENSOR", "Java motion source available=%d handheld=%d samples=%d",
                        framework_g_java_sensor_source, snapshot->handheld ? 1 : 0, snapshot->sensor_count);
        }
        framework_SensorPayload *sensor = etd2x_jni_get_object_host_data(r->sensor_global);
        for (size_t i = 0; sensor && i < count; ++i) {
            if (events[i].type != sensor->type || events[i].timestamp < r->next_due_ns) continue;
            r->latest = events[i];
            r->next_due_ns = events[i].timestamp + framework_sensor_period_ns(r->rate);
            /* ponytail: one pending event per registration, coalesce to the
             * latest real sample if its Looper is slow; no batching buffer. */
            if (!r->pending) {
                Etd2xJniValue task = {.l = r->runnable_global};
                r->pending = framework_handler_post(env, etd2x_jni_object_token_host(r->handler_global), &task, 1, NULL).z != 0;
            }
        }
    }
    pthread_mutex_unlock(&framework_g_sensor_listener_lock);
}
static void framework_android_sensors_reset(void) {
    while (framework_g_fw.sensor_registrations) {
        framework_SensorListenerRegistration *r = framework_g_fw.sensor_registrations;
        framework_g_fw.sensor_registrations = r->next;
        framework_sensor_registration_release(r); free(r);
    }
    framework_g_java_sensor_source = -1;
}



