static bool framework_activity_lifecycle_dispatch_list(void *env, framework_ActivityLifecycleRegistration *head,
                                             const char *method, const char *signature,
                                             void *bundle_ref, bool reverse, bool optional);

/* Android order (Activity.dispatchActivityX): for create/start/resume events
 * the Application callbacks run first, then the Activity-scoped ones; for
 * pause/stop/destroy the Activity-scoped ones run first, in reverse
 * registration order. Pre/Post events (API 29) are default interface methods,
 * so a callback that does not override one is skipped. */
static bool framework_activity_lifecycle_dispatch_all(void *env, const char *method, const char *signature,
                                            void *bundle_ref, bool teardown, bool optional) {
    if (!teardown) {
        return framework_activity_lifecycle_dispatch_list(env, framework_g_fw.activity_lifecycle_callbacks, method, signature,
                                                bundle_ref, false, optional) &&
               framework_activity_lifecycle_dispatch_list(env, framework_g_fw.activity_scoped_callbacks, method, signature,
                                                bundle_ref, false, optional);
    }
    return framework_activity_lifecycle_dispatch_list(env, framework_g_fw.activity_scoped_callbacks, method, signature,
                                            bundle_ref, true, optional) &&
           framework_activity_lifecycle_dispatch_list(env, framework_g_fw.activity_lifecycle_callbacks, method, signature,
                                            bundle_ref, true, optional);
}

static bool framework_activity_lifecycle_dispatch(void *env, const char *method,
                                        const char *signature, void *bundle_ref,
                                        bool reverse) {
    return framework_activity_lifecycle_dispatch_all(env, method, signature, bundle_ref, reverse, false);
}

/* JVMS 5.4.6 selection for a default interface method: true when DEX code
 * supplies an implementation for the receiver class, i.e. the class or a
 * superclass declares a concrete method, or a DEX superinterface provides a
 * default body. When nothing does, the framework interface's own default runs;
 * for ActivityLifecycleCallbacks Pre/Post events that body is empty. */
static bool framework_dex_type_implements(const char *type_name, const char *method, const char *signature,
                                unsigned depth) {
    if (depth > 16 || !type_name || !type_name[0] || !framework_g_fw.source_path[0] ||
        !etd2x_package_find_dex_class_ex || !etd2x_package_load_dex_method || !etd2x_package_release_dex_method)
        return false;
    char current[256];
    framework_copy_text(current, sizeof(current), type_name, "");
    for (unsigned walk = 0; walk < 64 && current[0]; ++walk) {
        char super_name[256] = "", interfaces[1024] = "";
        bool class_found = false;
        if (etd2x_package_find_dex_class_ex(framework_g_fw.source_path, current, super_name, sizeof(super_name), interfaces,
                                            sizeof(interfaces), &class_found) != ETD2X_OK || !class_found)
            return false; /* framework-modeled type: its behavior is the platform default */
        Etd2xDexMethodImage *image = calloc(1, sizeof(*image));
        if (!image) return false;
        bool declared_class = false, method_found = false;
        const bool loaded = etd2x_package_load_dex_method(framework_g_fw.source_path, current, method, signature, image,
                                                          &declared_class, &method_found) == ETD2X_OK;
        const bool concrete = loaded && method_found && (image->access_flags & 0x0400u /* ACC_ABSTRACT */) == 0;
        if (loaded && method_found) etd2x_package_release_dex_method(image);
        free(image);
        if (concrete) return true;
        for (char *iface = interfaces, *end; iface && *iface; iface = end ? end + 1 : NULL) {
            end = strchr(iface, '\n');
            if (end) *end = '\0';
            if (framework_dex_type_implements(iface, method, signature, depth + 1)) return true;
            if (!end) break;
        }
        framework_copy_text(current, sizeof(current), super_name, "");
    }
    return false;
}

static bool framework_activity_lifecycle_dispatch_list(void *env, framework_ActivityLifecycleRegistration *head,
                                             const char *method, const char *signature,
                                             void *bundle_ref, bool reverse, bool optional) {
    size_t count = 0;
    for (framework_ActivityLifecycleRegistration *r = head; r; r = r->next) count++;
    if (!count) return true;
    void **callbacks = calloc(count, sizeof(*callbacks));
    if (!callbacks) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ActivityLifecycleCallbacks snapshot");
        return false;
    }
    size_t i = 0;
    for (framework_ActivityLifecycleRegistration *r = head; r && i < count; r = r->next)
        callbacks[i++] = etd2x_jni_new_local_ref_host(env, r->callback_global);

    bool ok = true;
    for (size_t step = 0; step < count; ++step) {
        size_t index = reverse ? count - 1u - step : step;
        void *callback = callbacks[index];
        if (!callback) continue;
        char class_name[256] = {0};
        if (!etd2x_jni_object_class_name_host(callback, class_name, sizeof(class_name))) { ok = false; break; }
        if (optional && !framework_dex_type_implements(class_name, method, signature, 0)) continue;
        Etd2xJniValue args[2] = {{0}, {0}};
        args[0].l = framework_g_fw.activity ? framework_local_from_global(env, framework_g_fw.activity) : NULL;
        size_t argc = 1;
        if (strcmp(signature, "(Landroid/app/Activity;Landroid/os/Bundle;)V") == 0) {
            args[1].l = bundle_ref ? etd2x_jni_new_local_ref_host(env, bundle_ref) : NULL;
            argc = 2;
        }
        Etd2xJniValue ignored = {0};
        Etd2xDexExecReport report = {0};
        bool found = false;
        Etd2xResult rc = framework_framework_dispatch_instance(env, callback, class_name, method,
                                                      signature, args, argc, &ignored,
                                                      &found, &report);
        if (args[0].l) etd2x_jni_delete_local_ref_host(env, args[0].l);
        if (argc == 2 && args[1].l) etd2x_jni_delete_local_ref_host(env, args[1].l);
        if (optional && rc == ETD2X_OK && !found && !etd2x_jni_exception_pending_host(env)) continue;
        if (rc != ETD2X_OK || !found || etd2x_jni_exception_pending_host(env)) {
            ETD2X_LOGCE("ANDROID", "ActivityLifecycleCallbacks.%s failed class=%s rc=%d found=%d detail=%s",
                        method, class_name, (int)rc, found ? 1 : 0,
                        report.detail[0] ? report.detail : "-");
            ok = false;
            break;
        }
    }
    for (size_t j = 0; j < count; ++j)
        if (callbacks[j]) etd2x_jni_delete_local_ref_host(env, callbacks[j]);
    free(callbacks);
    return ok;
}

static bool framework_activity_state_transition(void *env, void *token,
                                      Etd2xAndroidActivityState next,
                                      const char *callback) {
    if (!framework_current_activity_token(token)) return true;
    const Etd2xAndroidActivityState old = framework_g_fw.activity_state;
    bool allowed = false;
    switch (next) {
        case ETD2X_ANDROID_ACTIVITY_CREATED:
            allowed = old == ETD2X_ANDROID_ACTIVITY_INITIALIZED;
            break;
        case ETD2X_ANDROID_ACTIVITY_STARTED:
            allowed = old == ETD2X_ANDROID_ACTIVITY_CREATED || old == ETD2X_ANDROID_ACTIVITY_STOPPED;
            break;
        case ETD2X_ANDROID_ACTIVITY_RESUMED:
            allowed = old == ETD2X_ANDROID_ACTIVITY_STARTED || old == ETD2X_ANDROID_ACTIVITY_PAUSED;
            break;
        case ETD2X_ANDROID_ACTIVITY_PAUSED:
            allowed = old == ETD2X_ANDROID_ACTIVITY_RESUMED;
            break;
        case ETD2X_ANDROID_ACTIVITY_STOPPED:
            allowed = old == ETD2X_ANDROID_ACTIVITY_PAUSED || old == ETD2X_ANDROID_ACTIVITY_STARTED;
            break;
        case ETD2X_ANDROID_ACTIVITY_DESTROYED:
            allowed = old >= ETD2X_ANDROID_ACTIVITY_CREATED && old < ETD2X_ANDROID_ACTIVITY_DESTROYED;
            break;
        default:
            break;
    }
    if (!allowed) {
        char msg[160];
        snprintf(msg, sizeof(msg), "%s from %s", callback ? callback : "lifecycle",
                 framework_activity_state_name_internal(old));
        ETD2X_LOGCE("ANDROID", "invalid Activity lifecycle transition callback=%s old=%s new=%s",
                    callback ? callback : "-", framework_activity_state_name_internal(old),
                    framework_activity_state_name_internal(next));
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/IllegalStateException", msg);
        return false;
    }
    framework_g_fw.activity_state = next;
    if (next == ETD2X_ANDROID_ACTIVITY_DESTROYED) framework_g_fw.activity_destroyed = true;
    ETD2X_LOGCI("ANDROID", "Activity lifecycle %s -> %s callback=%s",
                framework_activity_state_name_internal(old), framework_activity_state_name_internal(next),
                callback ? callback : "-");
    return true;
}

static Etd2xJniValue framework_application_ctor(void *env, void *token,
                                      const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0 || !token) return framework_v_void();
    /* Activity, Application and Service constructors all reach ContextWrapper(null). */
    void *self = etd2x_jni_new_local_from_token(env, token);
    if (!self || !framework_context_wrapper_bind_base(env, self, NULL, false))
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ContextWrapper constructor");
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    return framework_v_void();
}

