static void framework_rb_park(void *env, int64_t deadline_ns, bool timed) {
    framework_ThreadPayload *p = framework_rb_current_thread_payload(env);
    if (!p) { sched_yield(); return; }
    ETD2X_PERF_LOCK(&framework_g_rb_lock);
    framework_RbPermit *r = framework_rb_permit_locked(p);
    while (r && !r->permit && !__atomic_load_n(&p->interrupted, __ATOMIC_ACQUIRE) &&
           !etd2x_jni_process_exit_requested(NULL, 0)) {
        const int64_t now = framework_rb_now_ns();
        if (timed && now >= deadline_ns) break;
        int64_t slice = 50000000;
        if (timed && deadline_ns - now < slice) slice = deadline_ns - now;
        struct timespec ts = {0};
        clock_gettime(CLOCK_REALTIME, &ts);
        int64_t nsec = ts.tv_nsec + slice;
        ts.tv_sec += (time_t)(nsec / 1000000000); ts.tv_nsec = (long)(nsec % 1000000000);
        (void)framework_framework_cond_timedwait(&framework_g_rb_cond, &framework_g_rb_lock, &ts);
    }
    if (r) r->permit = false;
    pthread_mutex_unlock(&framework_g_rb_lock);
}

static Etd2xJniValue framework_rb_lock_park(void *env, void *t, const Etd2xJniValue *a, size_t n, void *ud) {
    (void)t;
    const intptr_t kind = (intptr_t)ud; /* 0 park(), 1 park(Object), 2 parkNanos(J), 3 parkNanos(Object,J), 4 parkUntil(J), 5 parkUntil(Object,J) */
    int64_t v = 0;
    if (kind == 2 || kind == 4) v = n >= 1 ? a[0].j : 0;
    if (kind == 3 || kind == 5) v = n >= 2 ? a[1].j : 0;
    if (kind == 0 || kind == 1) { framework_rb_park(env, 0, false); return framework_v_void(); }
    if (kind == 2 || kind == 3) {
        if (v <= 0) return framework_v_void();
        framework_rb_park(env, framework_rb_now_ns() + v, true);
        return framework_v_void();
    }
    struct timespec wall = {0};
    clock_gettime(CLOCK_REALTIME, &wall);
    const int64_t now_ms = (int64_t)wall.tv_sec * 1000 + wall.tv_nsec / 1000000;
    if (v <= now_ms) return framework_v_void();
    framework_rb_park(env, framework_rb_now_ns() + (v - now_ms) * 1000000, true);
    return framework_v_void();
}

static Etd2xJniValue framework_rb_lock_unpark(void *env, void *t, const Etd2xJniValue *a, size_t n, void *ud) {
    (void)env; (void)t; (void)ud;
    if (n != 1 || !a[0].l) return framework_v_void();
    framework_ThreadPayload *p = framework_thread_payload_identity(etd2x_jni_object_token_host(a[0].l));
    if (!p) return framework_v_void();
    ETD2X_PERF_LOCK(&framework_g_rb_lock);
    framework_RbPermit *r = framework_rb_permit_locked(p);
    if (r) r->permit = true;
    pthread_cond_broadcast(&framework_g_rb_cond);
    pthread_mutex_unlock(&framework_g_rb_lock);
    return framework_v_void();
}

