/* ---------- Long.getLong / Integer.getInteger ---------- */
/* Long.decode grammar: optional sign, then 0x/0X/#, leading 0 octal, else decimal. */
static bool framework_rb_decode_long(const char *s, int64_t *out) {
    if (!s || !*s) return false;
    bool neg = false;
    if (*s == '-' || *s == '+') { neg = *s == '-'; ++s; }
    int base = 10;
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) { base = 16; s += 2; }
    else if (s[0] == '#') { base = 16; s += 1; }
    else if (s[0] == '0' && s[1]) { base = 8; s += 1; }
    if (!*s || *s == '-' || *s == '+') return false;
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, base);
    if (errno || !end || *end) return false;
    if (neg ? v > (unsigned long long)INT64_MAX + 1ull : v > (unsigned long long)INT64_MAX) return false;
    *out = neg ? (int64_t)(0 - v) : (int64_t)v;
    return true;
}

