    if (!d) { if (obj) etd2x_jni_delete_local_ref_host(env, obj); return framework_v_object(NULL); }
    d->magic = RB_DIGEST_MAGIC; d->kind = kind;
    snprintf(d->name, sizeof(d->name), "%s", canon);
    framework_rb_digest_reset(d);
    pthread_mutex_lock(&framework_g_rb_lock); d->next = framework_g_rb_digests; framework_g_rb_digests = d; pthread_mutex_unlock(&framework_g_rb_lock);
    (void)etd2x_jni_set_object_host_data(obj, d);
