/* ud: 0 list() -> String[], 1 listFiles(FilenameFilter), 2 listFiles(FileFilter), 3 list(FilenameFilter) */
static Etd2xJniValue framework_rb_file_list(void *env, void *token, const Etd2xJniValue *a, size_t n, void *ud) {
    const intptr_t mode = (intptr_t)ud;
    Etd2xJniValue all = framework_file_list_files(env, token, NULL, 0, NULL);
    if (!all.l) return framework_v_object(NULL);
    const int32_t count = etd2x_jni_array_length_host(all.l);
    void *filter = (mode != 0 && n == 1) ? a[0].l : NULL;
    void *self = filter ? framework_rb_self(env, token) : NULL;
    const bool want_strings = mode == 0 || mode == 3;
    void *out = etd2x_jni_new_local_reference_array(env, want_strings ? "[Ljava/lang/String;" : "[Ljava/io/File;", count);
    int32_t kept = 0;
    for (int32_t i = 0; out && i < count; ++i) {
        void *file = NULL;
        if (etd2x_jni_get_object_array_element_host(env, all.l, i, &file) != ETD2X_OK || !file) continue;
        Etd2xJniValue name = {0};
        (void)framework_java_call_virtual(env, file, "getName", "()Ljava/lang/String;", NULL, 0, &name);
        bool accept = true;
        if (filter) {
            Etd2xJniValue res = {0};
            if (mode == 2) {
                Etd2xJniValue args[1]; args[0].l = file;
                accept = framework_java_call_virtual(env, filter, "accept", "(Ljava/io/File;)Z", args, 1, &res) && res.z;
            } else {
                Etd2xJniValue args[2]; args[0].l = self; args[1].l = name.l;
                accept = framework_java_call_virtual(env, filter, "accept", "(Ljava/io/File;Ljava/lang/String;)Z", args, 2, &res) && res.z;
            }
            if (etd2x_jni_exception_pending_host(env)) {
                if (name.l) etd2x_jni_delete_local_ref_host(env, name.l);
                etd2x_jni_delete_local_ref_host(env, file);
                break;
            }
        }
        if (accept) (void)etd2x_jni_set_object_array_element_host(env, out, kept++, want_strings ? name.l : file);
        if (name.l) etd2x_jni_delete_local_ref_host(env, name.l);
        etd2x_jni_delete_local_ref_host(env, file);
    }
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    etd2x_jni_delete_local_ref_host(env, all.l);
    if (!out || etd2x_jni_exception_pending_host(env)) { if (out) etd2x_jni_delete_local_ref_host(env, out); return framework_v_object(NULL); }
    if (kept == count) return framework_v_object(out);
    void *trim = etd2x_jni_new_local_reference_array(env, want_strings ? "[Ljava/lang/String;" : "[Ljava/io/File;", kept);
    if (trim && kept) (void)etd2x_jni_arraycopy_host(out, 0, trim, 0, kept);
    etd2x_jni_delete_local_ref_host(env, out);
    return framework_v_object(trim);
}

