/* ---------- java.util.concurrent: Executor / ExecutorService / Future ----------
 *
 * ThreadPoolExecutor and ScheduledThreadPoolExecutor keep their task queue on
 * the host; every worker is a real java.lang.Thread (created through the pool's
 * ThreadFactory when one is supplied, else named like
 * Executors.defaultThreadFactory) whose Runnable target is a pool Worker. The
 * worker therefore inherits the Thread lifecycle: Thread.currentThread(),
 * uncaught-failure reporting and teardown joins. Pool sizing follows the
 * ThreadPoolExecutor contract: start a thread per task up to corePoolSize;
 * beyond that queue the task, and only a hand-off (SynchronousQueue) pool grows
 * to maximumPoolSize. FutureTask implements submit()/schedule() results. */
#define EXECUTOR_PAYLOAD_MAGIC UINT64_C(0x41504b3645584531) /* APK6EXE1 */
#define FUTURE_PAYLOAD_MAGIC UINT64_C(0x41504b3646555431)   /* APK6FUT1 */
#define EXECUTOR_WORKER_MAGIC UINT64_C(0x41504b3645585731)  /* APK6EXW1 */
#define TPE_CLASS "java/util/concurrent/ThreadPoolExecutor"
#define STPE_CLASS "java/util/concurrent/ScheduledThreadPoolExecutor"
#define FUTURE_TASK_CLASS "java/util/concurrent/FutureTask"
#define SCHEDULED_FUTURE_CLASS "java/util/concurrent/ScheduledThreadPoolExecutor$ScheduledFutureTask"
#define EXECUTOR_WORKER_CLASS "java/util/concurrent/ThreadPoolExecutor$Worker"

enum { FUTURE_NEW = 0, FUTURE_RUNNING, FUTURE_DONE, FUTURE_FAILED, FUTURE_CANCELLED };

typedef struct framework_ExecutorTask {
    void *task_global;      /* Runnable; a FutureTask for submit()/schedule() */
    int64_t due_ms;         /* framework_uptime_millis() when runnable */
    int64_t period_ms;      /* >0 fixed rate, <0 fixed delay, 0 one-shot */
    uint64_t seq;           /* FIFO order among equally due tasks */
    struct framework_ExecutorTask *next;
} framework_ExecutorTask;

typedef struct framework_ExecutorPayload {
    uint64_t magic;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    framework_ExecutorTask *queue;
    int32_t core_threads, max_threads;
    int32_t workers, idle, active;
    int64_t keep_alive_ms;
    bool allow_core_timeout;
    bool handoff;           /* SynchronousQueue: grow to max instead of queueing */
    bool shutdown;
    uint64_t next_seq;
    int64_t completed;
    int32_t pool_id, next_thread_index;
    void *factory_global;   /* java.util.concurrent.ThreadFactory, optional */
    void *handler_global;   /* RejectedExecutionHandler; defaults to AbortPolicy */
    void *queue_global;     /* getQueue() view, created on first use */
    struct framework_ExecutorPayload *next;
} framework_ExecutorPayload;

typedef struct framework_FuturePayload {
    uint64_t magic;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int state;
    bool periodic;
    int64_t due_ms;
    void *callable_global;  /* Callable, or NULL for a Runnable task */
    void *runnable_global;
    void *result_global;
    void *failure_global;   /* Throwable thrown by the task */
    struct framework_FuturePayload *next;
} framework_FuturePayload;

typedef struct framework_ExecutorWorkerPayload {
    uint64_t magic;
    framework_ExecutorPayload *pool;
} framework_ExecutorWorkerPayload;

static framework_ExecutorPayload *framework_g_executors;
static framework_FuturePayload *framework_g_futures;
static framework_ExecutorWorkerPayload **framework_g_executor_workers;
static size_t framework_g_executor_worker_count, framework_g_executor_worker_cap;
static pthread_mutex_t framework_g_executor_list_lock = PTHREAD_MUTEX_INITIALIZER;
static int32_t framework_g_next_pool_id = 1;

static bool framework_executor_wait_slice(pthread_cond_t *cond, pthread_mutex_t *lock, int64_t max_ms) {
    if (etd2x_jni_process_exit_requested(NULL, 0)) return false;
    if (max_ms > 50 || max_ms < 0) max_ms = 50;
    if (max_ms == 0) max_ms = 1;
    struct timespec deadline;
    clock_gettime(CLOCK_REALTIME, &deadline);
    deadline.tv_nsec += max_ms * 1000000LL;
    while (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }
    (void)framework_framework_cond_timedwait(cond, lock, &deadline);
    return true;
}

