static void framework_executors_reset(void) {
    ETD2X_PERF_LOCK(&framework_g_executor_list_lock);
    framework_ExecutorPayload *pool = framework_g_executors;
    framework_g_executors = NULL;
    framework_FuturePayload *future = framework_g_futures;
    framework_g_futures = NULL;
    framework_ExecutorWorkerPayload **workers = framework_g_executor_workers;
    const size_t worker_count = framework_g_executor_worker_count;
    framework_g_executor_workers = NULL;
    framework_g_executor_worker_count = framework_g_executor_worker_cap = 0;
    pthread_mutex_unlock(&framework_g_executor_list_lock);

    /* Pools with live workers stay allocated: those threads still reference
     * them until they observe the pending process exit. */
    bool pools_live = false;
    while (pool) {
        framework_ExecutorPayload *next = pool->next;
        pthread_mutex_lock(&pool->lock);
        pool->shutdown = true;
        framework_ExecutorTask *pending = pool->queue;
        pool->queue = NULL;
        const bool live = pool->workers > 0;
        pthread_cond_broadcast(&pool->cond);
        pthread_mutex_unlock(&pool->lock);
        while (pending) { framework_ExecutorTask *n = pending->next; framework_executor_task_free(pending); pending = n; }
        if (live) {
            pools_live = true;
        } else {
            framework_delete_global(&pool->factory_global);
            framework_delete_global(&pool->handler_global);
            pool->magic = 0;
            pthread_mutex_destroy(&pool->lock);
            pthread_cond_destroy(&pool->cond);
            free(pool);
        }
        pool = next;
    }
    for (size_t i = 0; i < worker_count; ++i) {
        if (!pools_live) { workers[i]->magic = 0; free(workers[i]); }
    }
    free(workers);
    while (future) {
        framework_FuturePayload *next = future->next;
        framework_delete_global(&future->callable_global);
        framework_delete_global(&future->runnable_global);
        framework_delete_global(&future->result_global);
        framework_delete_global(&future->failure_global);
        future->magic = 0;
        pthread_mutex_destroy(&future->lock);
        pthread_cond_destroy(&future->cond);
        free(future);
        future = next;
    }
}

