static uint16_t framework_pe_mirror_char(uint16_t ch) {
    size_t lo = 0, hi = framework_ARRAY_COUNT(framework_pe_mirroring);
    while (lo < hi) {
        const size_t mid = lo + (hi - lo) / 2;
        if (framework_pe_mirroring[mid][0] < ch) lo = mid + 1; else hi = mid;
    }
    return lo < framework_ARRAY_COUNT(framework_pe_mirroring) && framework_pe_mirroring[lo][0] == ch ? framework_pe_mirroring[lo][1] : ch;
}

static Etd2xJniValue framework_pe_android_mirror(void *env, void *token, const Etd2xJniValue *a,
                                      size_t n, void *ud) {
    (void)token; (void)ud;
    if (n == 1) { Etd2xJniValue r = {0}; r.c = framework_pe_mirror_char(a[0].c); return r; }
    const int32_t len = etd2x_jni_array_length_host(a[0].l), start = a[1].i, count = a[2].i;
    if (!a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "chars");
        return framework_v_bool(false);
    }
    if (start < 0 || count < 0 || start > len || count > len - start) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/ArrayIndexOutOfBoundsException", "mirror range");
        return framework_v_bool(false);
    }
    bool changed = false;
    for (int32_t i = start; i < start + count; ++i) {
        uint16_t ch = 0;
        if (etd2x_jni_char_array_read(a[0].l, i, 1, &ch) != ETD2X_OK) break;
        const uint16_t mirrored = framework_pe_mirror_char(ch);
        if (ch != mirrored) {
            if (etd2x_jni_char_array_write(a[0].l, i, 1, &mirrored) != ETD2X_OK) break;
            changed = true;
        }
    }
    return framework_v_bool(changed);
}

/* ExpandableListView's packed-position representation is independent of UI. */
static Etd2xJniValue framework_pe_packed_position(void *env, void *token, const Etd2xJniValue *a,
                                       size_t n, void *ud) {
    (void)env; (void)token; (void)n;
    const int op = (int)(intptr_t)ud;
    const uint64_t p = (uint64_t)a[0].j;
    if (op >= 3) {
        const uint64_t group = ((uint64_t)(uint32_t)a[0].i & UINT64_C(0x7fffffff)) << 32;
        return framework_v_long((int64_t)(group | (op == 4 ? UINT64_C(0x8000000000000000) | (uint32_t)a[1].i : 0)));
    }
    if (p == UINT64_C(0x00000000ffffffff)) return framework_v_int(op == 0 ? 2 : -1);
    if (op == 0) return framework_v_int((int32_t)(p >> 63));
    if (op == 1) return framework_v_int((int32_t)((p >> 32) & 0x7fffffff));
    return framework_v_int((p >> 63) ? (int32_t)p : -1);
}

static Etd2xJniValue framework_pe_combine_measured_states(void *env, void *token, const Etd2xJniValue *a,
                                               size_t n, void *ud) {
    (void)env; (void)token; (void)n; (void)ud;
    return framework_v_int(a[0].i | a[1].i);
}

static Etd2xJniValue framework_pe_complex_to_float(void *env, void *token, const Etd2xJniValue *a,
                                        size_t n, void *ud) {
    (void)env; (void)token; (void)n; (void)ud;
    static const float radix[] = {1.0f / 256, 1.0f / 32768, 1.0f / 8388608, 1.0f / 2147483648.0f};
    return framework_v_float((float)(int32_t)((uint32_t)a[0].i & 0xffffff00u) * radix[((uint32_t)a[0].i >> 4) & 3]);
}

static Etd2xJniValue framework_pe_complex_to_fraction(void *env, void *token, const Etd2xJniValue *a,
                                           size_t n, void *ud) {
    const uint32_t unit = (uint32_t)a[0].i & 15;
    if (unit > 1) return framework_v_float(0);
    const Etd2xJniValue value = framework_pe_complex_to_float(env, token, a, n, ud);
    return framework_v_float(value.f * a[unit + 1].f);
}

