static void framework_pe_dotted(char *s) {
    for (; *s; ++s) if (*s == '/') *s = '.';
}

static Etd2xJniValue framework_pe_intent_get_component(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    framework_IntentPayload *p = framework_intent_payload(token);
    if (n != 0 || !p || !p->target_class || !p->target_class[0]) return framework_v_object(NULL);
    char cls[512];
    framework_copy_text(cls, sizeof(cls), p->target_class, "");
    framework_pe_dotted(cls);
    void *cn = etd2x_jni_new_local_object(env, "android/content/ComponentName");
    if (!cn) return framework_v_object(NULL);
    Etd2xJniValue ctor[2] = {{0}, {0}}, ignored = {0};
    ctor[0].l = framework_new_string(env, p->package_name && p->package_name[0] ? p->package_name : framework_g_fw.package_name);
    ctor[1].l = framework_new_string(env, cls);
    bool found = false;
    (void)etd2x_jni_invoke_method_host(env, cn, "android/content/ComponentName", "<init>",
                                       "(Ljava/lang/String;Ljava/lang/String;)V", false, ctor, &ignored, &found);
    if (ctor[0].l) etd2x_jni_delete_local_ref_host(env, ctor[0].l);
    if (ctor[1].l) etd2x_jni_delete_local_ref_host(env, ctor[1].l);
    return framework_v_object(cn);
}

static Etd2xJniValue framework_pe_intent_set_component(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    framework_IntentPayload *p = framework_pe_intent(token);
    if (!p || n != 1) return framework_pe_self(env, token);
    free(p->target_class);
    p->target_class = NULL;
    if (args[0].l) {
        Etd2xJniValue cls = {0}, pkg = {0};
        char name[512];
        if (framework_java_call_virtual(env, args[0].l, "getClassName", "()Ljava/lang/String;", NULL, 0, &cls) && cls.l &&
            framework_read_jstring(cls.l, name, sizeof(name))) {
            for (char *c = name; *c; ++c) if (*c == '.') *c = '/';
            p->target_class = strdup(name);
        }
        if (framework_java_call_virtual(env, args[0].l, "getPackageName", "()Ljava/lang/String;", NULL, 0, &pkg) && pkg.l &&
            framework_read_jstring(pkg.l, name, sizeof(name))) {
            free(p->package_name);
            p->package_name = strdup(name);
        }
        if (cls.l) etd2x_jni_delete_local_ref_host(env, cls.l);
        if (pkg.l) etd2x_jni_delete_local_ref_host(env, pkg.l);
    }
    return framework_pe_self(env, token);
}

static Etd2xJniValue framework_pe_intent_get_categories(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    framework_IntentPayload *p = framework_intent_payload(token);
    if (n != 0 || !p || p->category_count == 0) return framework_v_object(NULL);
    void *set = etd2x_jni_new_local_object(env, "java/util/HashSet");
    Etd2xJniValue ignored = {0};
    bool found = false;
    if (set) (void)etd2x_jni_invoke_method_host(env, set, "java/util/HashSet", "<init>", "()V", false, NULL, &ignored, &found);
    for (size_t i = 0; set && i < p->category_count; ++i) {
        Etd2xJniValue arg = {0};
        arg.l = framework_new_string(env, p->categories[i]);
        (void)framework_java_call_virtual(env, set, "add", "(Ljava/lang/Object;)Z", &arg, 1, &ignored);
        if (arg.l) etd2x_jni_delete_local_ref_host(env, arg.l);
    }
    return framework_v_object(set);
}

/* Intent(Intent o): copies action, package, component, flags, categories,
 * data and (shallowly) extras. */
static Etd2xJniValue framework_pe_intent_ctor_copy(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    framework_IntentPayload *dst = framework_pe_intent(token);
    framework_IntentPayload *src = n == 1 && args[0].l ? (framework_IntentPayload *)etd2x_jni_get_object_host_data(args[0].l) : NULL;
    if (!dst || !src) return framework_v_void();
    dst->unavailable_completion = src->unavailable_completion;
    framework_delete_global(&dst->unavailable_result_global);
    if (src->unavailable_result_global) dst->unavailable_result_global = etd2x_jni_new_global_ref_host(env, src->unavailable_result_global);
    if (src->action) dst->action = strdup(src->action);
    if (src->package_name) dst->package_name = strdup(src->package_name);
    if (src->target_class) dst->target_class = strdup(src->target_class);
    dst->flags = src->flags;
    for (size_t i = 0; i < src->category_count; ++i) {
        Etd2xJniValue arg = {0}, ignored = {0};
        arg.l = framework_new_string(env, src->categories[i]);
        (void)framework_java_call_virtual(env, etd2x_jni_new_local_from_token(env, token), "addCategory",
                                "(Ljava/lang/String;)Landroid/content/Intent;", &arg, 1, &ignored);
        if (arg.l) etd2x_jni_delete_local_ref_host(env, arg.l);
        if (ignored.l) etd2x_jni_delete_local_ref_host(env, ignored.l);
    }
    if (src->data_global) dst->data_global = etd2x_jni_new_global_ref_host(env, src->data_global);
    if (src->extras) {
        framework_BundlePayload *extras = framework_intent_ensure_extras(dst);
        if (extras) (void)framework_android_map_copy(&extras->map, &src->extras->map);
    }
    return framework_v_void();
}

static Etd2xJniValue framework_pe_intent_ctor_action_uri(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)ud;
    framework_IntentPayload *p = framework_pe_intent(token);
    char action[TEXT_CAP];
    if (!p || n != 2) return framework_v_void();
    if (args[0].l && framework_read_jstring(args[0].l, action, sizeof(action))) {
        free(p->action);
        p->action = strdup(action);
    }
    if (args[1].l) p->data_global = etd2x_jni_new_global_ref_host(env, args[1].l);
    return framework_v_void();
}

