/* malloc'd UTF-8 of CharSequence.toString(), or NULL for null. */
static char *framework_pe_char_sequence_text(void *env, void *cs) {
    if (!cs) return NULL;
    Etd2xJniValue out = {0};
    if (!framework_java_call_virtual(env, cs, "toString", "()Ljava/lang/String;", NULL, 0, &out) || !out.l) return NULL;
    char *text = etd2x_jni_string_utf_dup(out.l);
    etd2x_jni_delete_local_ref_host(env, out.l);
    return text;
}

static Etd2xJniValue framework_pe_text_utils_equals(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token; (void)ud;
    if (n != 2) return framework_v_bool(false);
    if (args[0].l == args[1].l || etd2x_jni_same_object_host(args[0].l, args[1].l)) return framework_v_bool(true);
    if (!args[0].l || !args[1].l) return framework_v_bool(false);
    char *a = framework_pe_char_sequence_text(env, args[0].l), *b = framework_pe_char_sequence_text(env, args[1].l);
    const bool equal = a && b && strcmp(a, b) == 0;
    free(a);
    free(b);
    return framework_v_bool(equal);
}

static bool framework_pe_append(char **buf, size_t *len, size_t *cap, const char *text) {
    const size_t add = strlen(text);
    if (*len + add + 1 > *cap) {
        size_t next = *cap ? *cap * 2 : 64;
        while (next < *len + add + 1) next *= 2;
        char *grown = realloc(*buf, next);
        if (!grown) return false;
        *buf = grown;
        *cap = next;
    }
    memcpy(*buf + *len, text, add + 1);
    *len += add;
    return true;
}

static bool framework_pe_append_element(void *env, char **buf, size_t *len, size_t *cap, void *element) {
    if (!element) return framework_pe_append(buf, len, cap, "null");
    char *text = framework_pe_char_sequence_text(env, element);
    const bool ok = framework_pe_append(buf, len, cap, text ? text : "null");
    free(text);
    return ok;
}

/* TextUtils.join(CharSequence delimiter, Object[] | Iterable tokens). */
static Etd2xJniValue framework_pe_text_utils_join(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)token;
    const bool iterable = ud != NULL;
    if (n != 2 || !args[1].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "tokens");
        return framework_v_object(NULL);
    }
    char *delim = framework_pe_char_sequence_text(env, args[0].l);
    char *buf = NULL;
    size_t len = 0, cap = 0;
    bool ok = framework_pe_append(&buf, &len, &cap, "");
    if (!iterable) {
        const int32_t count = etd2x_jni_array_length_host(args[1].l);
        for (int32_t i = 0; ok && i < count; ++i) {
            void *e = NULL;
            (void)etd2x_jni_get_object_array_element_host(env, args[1].l, i, &e);
            if (i && delim) ok = framework_pe_append(&buf, &len, &cap, delim);
            if (ok) ok = framework_pe_append_element(env, &buf, &len, &cap, e);
            if (e) etd2x_jni_delete_local_ref_host(env, e);
        }
    } else {
        Etd2xJniValue it = {0};
        ok = ok && framework_java_call_virtual(env, args[1].l, "iterator", "()Ljava/util/Iterator;", NULL, 0, &it) && it.l;
        for (bool first = true; ok;) {
            Etd2xJniValue has = {0}, next = {0};
            if (!framework_java_call_virtual(env, it.l, "hasNext", "()Z", NULL, 0, &has) || !has.z) break;
            if (!framework_java_call_virtual(env, it.l, "next", "()Ljava/lang/Object;", NULL, 0, &next)) { ok = false; break; }
            if (!first && delim) ok = framework_pe_append(&buf, &len, &cap, delim);
            if (ok) ok = framework_pe_append_element(env, &buf, &len, &cap, next.l);
            if (next.l) etd2x_jni_delete_local_ref_host(env, next.l);
            first = false;
        }
        if (it.l) etd2x_jni_delete_local_ref_host(env, it.l);
    }
    void *result = ok && !etd2x_jni_exception_pending_host(env) ? framework_new_string(env, buf) : NULL;
    free(buf);
    free(delim);
    return framework_v_object(result);
}

