/* ---- platform Fragments: android.app.FragmentManagerImpl (core library) ---- */

static void *framework_g_pe_fragment_manager; /* global ref, current Activity's manager */

static void framework_pe_fragment_dispatch(void *env, int32_t fragment_state) {
    if (!framework_g_pe_fragment_manager) return;
    void *manager = framework_local_from_global(env, framework_g_pe_fragment_manager);
    Etd2xJniValue arg = {0}, out = {0};
    arg.i = fragment_state;
    bool found = false;
    Etd2xDexExecReport report = {0};
    if (framework_framework_dispatch_instance(env, manager, "android/app/FragmentManagerImpl", "dispatchActivityState",
                                    "(I)V", &arg, 1, &out, &found, &report) != ETD2X_OK || !found)
        ETD2X_LOGCW("ANDROID", "FragmentManager state dispatch failed state=%d detail=%s", fragment_state,
                    report.detail[0] ? report.detail : "-");
    if (manager) etd2x_jni_delete_local_ref_host(env, manager);
}

/* Fragment state for the current Activity lifecycle state (Fragment.CREATED
 * while onCreate runs; ACTIVITY_CREATED once it has returned). */
static int32_t framework_pe_fragment_state_for_activity(void) {
    switch (framework_g_fw.activity_state) {
        case ETD2X_ANDROID_ACTIVITY_CREATED: return 1;
        case ETD2X_ANDROID_ACTIVITY_STARTED: return 3;
        case ETD2X_ANDROID_ACTIVITY_RESUMED: return 4;
        case ETD2X_ANDROID_ACTIVITY_PAUSED: return 3;
        case ETD2X_ANDROID_ACTIVITY_STOPPED: return 2;
        default: return 0;
    }
}

static Etd2xJniValue framework_pe_activity_get_fragment_manager(void *env, void *token, const Etd2xJniValue *args, size_t n, void *ud) {
    (void)args; (void)ud;
    if (n != 0 || !framework_current_activity_token(token)) return framework_v_object(NULL);
    if (!framework_g_pe_fragment_manager) {
        void *manager = etd2x_jni_new_local_object(env, "android/app/FragmentManagerImpl");
        if (!manager) return framework_v_object(NULL);
        Etd2xJniValue arg = {0}, out = {0};
        arg.l = etd2x_jni_new_local_from_token(env, token);
        bool found = false;
        const Etd2xResult rc = framework_framework_dispatch_instance(env, manager, "android/app/FragmentManagerImpl", "<init>",
                                                           "(Landroid/app/Activity;)V", &arg, 1, &out, &found, NULL);
        if (arg.l) etd2x_jni_delete_local_ref_host(env, arg.l);
        if (rc != ETD2X_OK || !found || etd2x_jni_exception_pending_host(env)) {
            etd2x_jni_delete_local_ref_host(env, manager);
            return framework_v_object(NULL);
        }
        framework_g_pe_fragment_manager = etd2x_jni_new_global_ref_host(env, manager);
        etd2x_jni_delete_local_ref_host(env, manager);
        framework_pe_fragment_dispatch(env, framework_pe_fragment_state_for_activity());
    }
    return framework_v_object(framework_local_from_global(env, framework_g_pe_fragment_manager));
}

/* Activity.performX moves its fragments along with its own lifecycle. */
static void framework_pe_fragment_lifecycle_event(void *env, const char *event) {
    static const struct { const char *event; int32_t state; } k_map[] = {
        {"PostCreated", 2}, {"PostStarted", 3}, {"PostResumed", 4},
        {"PrePaused", 3}, {"PreStopped", 2}, {"PreDestroyed", 0},
    };
    for (size_t i = 0; i < framework_ARRAY_COUNT(k_map); ++i)
        if (strcmp(k_map[i].event, event) == 0) framework_pe_fragment_dispatch(env, k_map[i].state);
}

