static int framework_aps_hex(int c) {
    return c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : -1;
}

/* openAssetFileDescriptor(Uri, String mode[, CancellationSignal]). file: URIs
 * open the path (ContentResolver's SCHEME_FILE branch); content: URIs need
 * ContentProvider.openAssetFile, which ETD2X does not route yet, and fail as
 * an unresolvable provider does. */
static Etd2xJniValue framework_aps_open_asset_fd(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)u;
    if (n < 2 || !a[0].l) {
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/NullPointerException", "uri");
        return framework_v_object(NULL);
    }
    const char *text = framework_uri_text_of_ref(a[0].l);
    char msg[PATH_CAP + 32];
    if (!text || strncmp(text, "file:", 5) != 0) {
        snprintf(msg, sizeof(msg), "No content provider: %s", text ? text : "null");
        ETD2X_LOGCW("ANDROID", "ContentResolver.openAssetFileDescriptor %s", msg);
        (void)etd2x_jni_throw_new_by_name(env, "java/io/FileNotFoundException", msg);
        return framework_v_object(NULL);
    }
    const char *path = text + 5;
    if (!strncmp(path, "//", 2)) { path += 2; path = strchr(path, '/') ? strchr(path, '/') : path + strlen(path); }
    char decoded[PATH_CAP];
    size_t o = 0;
    for (const char *c = path; *c && *c != '?' && *c != '#' && o + 1 < sizeof(decoded); ++c) {
        if (c[0] == '%' && framework_aps_hex(c[1]) >= 0 && framework_aps_hex(c[2]) >= 0) {
            decoded[o++] = (char)(framework_aps_hex(c[1]) * 16 + framework_aps_hex(c[2]));
            c += 2;
        } else {
            decoded[o++] = *c;
        }
    }
    decoded[o] = '\0';
    Etd2xJniValue mode = framework_parcel_fd_parse_mode(env, t, &a[1], 1, NULL);
    if (etd2x_jni_exception_pending_host(env)) return framework_v_object(NULL);
    void *file = framework_new_file(env, decoded);
    Etd2xJniValue open_args[2] = {{.l = file}, {.i = mode.i}};
    const Etd2xJniValue pfd = framework_parcel_fd_open(env, NULL, open_args, 2, NULL);
    if (file) etd2x_jni_delete_local_ref_host(env, file);
    if (!pfd.l) return framework_v_object(NULL);
    void *afd = framework_aps_afd_new(env, pfd.l, 0, AFD_UNKNOWN_LENGTH);
    etd2x_jni_delete_local_ref_host(env, pfd.l);
    return framework_v_object(afd);
}

static void framework_app_services_reset_all(void) {
    void *env = etd2x_jni_current_env();
    ETD2X_PERF_LOCK(&framework_g_aps_lock);
    framework_ApsPendingIntent *pi = framework_g_aps_pending_intents;
    framework_g_aps_pending_intents = NULL;
    framework_ApsAlarm *alarm = framework_g_aps_alarms;
    framework_g_aps_alarms = NULL;
    framework_ApsBroadcast *b = framework_g_aps_broadcasts;
    framework_g_aps_broadcasts = NULL;
    framework_ApsProviderClient *c = framework_g_aps_clients;
    framework_g_aps_clients = NULL;
    void *am = framework_g_aps_alarm_manager, *uh = framework_g_aps_user_handle;
    framework_g_aps_alarm_manager = framework_g_aps_user_handle = NULL;
    pthread_mutex_unlock(&framework_g_aps_lock);
    while (alarm) { framework_ApsAlarm *next = alarm->next; free(alarm); alarm = next; }
    while (pi) {
        framework_ApsPendingIntent *next = pi->next;
        if (env) {
            if (pi->self) etd2x_jni_delete_global_ref_host(env, pi->self);
            if (pi->intent) etd2x_jni_delete_global_ref_host(env, pi->intent);
        }
        free(pi->key);
        pi->magic = 0;
        free(pi);
        pi = next;
    }
    while (b) { framework_ApsBroadcast *next = b->next; framework_aps_broadcast_release(env, b); b->magic = 0; free(b); b = next; }
    while (c) { framework_ApsProviderClient *next = c->next;
        if (c->provider_global && env) etd2x_jni_delete_global_ref_host(env, c->provider_global);
        c->magic = 0; free(c); c = next; }
    if (env && am) etd2x_jni_delete_global_ref_host(env, am);
    if (env && uh) etd2x_jni_delete_global_ref_host(env, uh);
}

