/* notifications */
/* ---------- android.app.NotificationManager / NotificationChannel ----------
 * Context.getSystemService("notification") never returns null on Android.
 * ETD2X has no notification shade, which is observably the same as the user
 * having blocked this app's notifications: areNotificationsEnabled() is false,
 * getImportance() is IMPORTANCE_NONE, notify()/cancel() are accepted and
 * nothing is shown, and getActiveNotifications() is empty. Channels follow
 * NotificationManagerService/PreferencesHelper rules: importance must be in
 * [IMPORTANCE_NONE, IMPORTANCE_MAX], re-creating an existing channel updates
 * only its name/description (and group when unset), and deleted channels
 * disappear from getNotificationChannel(s). The notification delegate is
 * recorded per package (API 29). */

#define NM_CLASS "android/app/NotificationManager"
#define NC_CLASS "android/app/NotificationChannel"
#define NB_CLASS "android/app/Notification$Builder"
#define NM_IMPORTANCE_NONE 0
#define NM_IMPORTANCE_DEFAULT 3
#define NM_IMPORTANCE_MAX 5
#define NM_INTERRUPTION_FILTER_ALL 1

typedef struct framework_NmChannel {
    char *id;
    void *channel; /* global NotificationChannel */
    struct framework_NmChannel *next;
} framework_NmChannel;

static pthread_mutex_t framework_g_nm_lock = PTHREAD_MUTEX_INITIALIZER;
static void *framework_g_nm_manager;   /* global ref */
static framework_NmChannel *framework_g_nm_channels;
static char *framework_g_nm_delegate;

/* Android's Builder exposes its mutable user metadata even when notifications
 * cannot be displayed. Keep it in a JNI-owned instance slot so subsequent
 * getExtras calls see the same Bundle and native local cleanup cannot lose it. */
static Etd2xJniValue framework_nb_get_extras(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    (void)a; (void)n; (void)u;
    void *self = etd2x_jni_new_local_from_token(env, t);
    Etd2xJniValue extras = {0};
    bool found = false;
    Etd2xResult rc = etd2x_jni_get_instance_field_value(env, self, NB_CLASS, "mUserExtras",
                                                        "Landroid/os/Bundle;", &extras, &found);
    if (rc == ETD2X_OK && found && !extras.l) {
        extras.l = etd2x_jni_new_local_object(env, "android/os/Bundle");
        if (extras.l && framework_bundle_payload_ensure(etd2x_jni_object_token_host(extras.l)))
            rc = etd2x_jni_set_instance_field_value(self, "mUserExtras", "Landroid/os/Bundle;", extras);
        else rc = ETD2X_ERR_NO_MEMORY;
    }
    if (self) etd2x_jni_delete_local_ref_host(env, self);
    if (rc != ETD2X_OK || !found) {
        if (extras.l) etd2x_jni_delete_local_ref_host(env, extras.l);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "notification extras");
        return framework_v_object(NULL);
    }
    return extras;
}

static Etd2xJniValue framework_nb_build(void *env, void *t, const Etd2xJniValue *a, size_t n, void *u) {
    Etd2xJniValue extras = framework_nb_get_extras(env, t, a, n, u);
    if (!extras.l) return framework_v_object(NULL);
    void *notification = etd2x_jni_new_local_object(env, "android/app/Notification");
    void *copy = etd2x_jni_new_local_object(env, "android/os/Bundle");
    framework_BundlePayload *src = framework_bundle_payload(etd2x_jni_object_token_host(extras.l));
    framework_BundlePayload *dst = copy ? framework_bundle_payload_ensure(etd2x_jni_object_token_host(copy)) : NULL;
    bool ok = notification && src && dst && framework_android_map_copy(&dst->map, &src->map);
    if (ok) ok = etd2x_jni_set_instance_field_value(notification, "extras", "Landroid/os/Bundle;",
                                                    framework_v_object(copy)) == ETD2X_OK;
    etd2x_jni_delete_local_ref_host(env, extras.l);
    if (copy) etd2x_jni_delete_local_ref_host(env, copy);
    if (!ok) {
        if (notification) etd2x_jni_delete_local_ref_host(env, notification);
        (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "notification build");
        return framework_v_object(NULL);
    }
    return framework_v_object(notification);
}

static void *framework_notification_manager_local(void *env) {
    ETD2X_PERF_LOCK(&framework_g_nm_lock);
    if (!framework_g_nm_manager) {
        void *obj = etd2x_jni_new_local_object(env, NM_CLASS);
        if (obj) { framework_g_nm_manager = etd2x_jni_new_global_ref_host(env, obj); etd2x_jni_delete_local_ref_host(env, obj); }
    }
    void *r = framework_local_from_global(env, framework_g_nm_manager);
    pthread_mutex_unlock(&framework_g_nm_lock);
    return r;
}

