static const framework_NcField framework_k_nc_name = {"mName", "Ljava/lang/CharSequence;"};
static const framework_NcField framework_k_nc_desc = {"mDesc", "Ljava/lang/String;"};
static const framework_NcField framework_k_nc_group = {"mGroup", "Ljava/lang/String;"};
static const framework_NcField framework_k_nc_importance = {"mImportance", "I"};
static const framework_NcField framework_k_nc_badge = {"mShowBadge", "Z"};
static const framework_NcField framework_k_nc_lights = {"mLights", "Z"};
static const framework_NcField framework_k_nc_vibration = {"mVibrationEnabled", "Z"};
static const framework_NcField framework_k_nc_light_color = {"mLightColor", "I"};
static const framework_NcField framework_k_nc_lockscreen = {"mLockscreenVisibility", "I"};
static const framework_NcField framework_k_nc_bypass_dnd = {"mBypassDnd", "Z"};
static const framework_NcField framework_k_nc_sound = {"mSound", "Landroid/net/Uri;"};
