/* Depth-first search of the attached View tree for the focused view. */
static void *framework_view_find_focused_local(void *env, void *ref, unsigned depth) {
    if (!ref || depth > 64) return NULL;
    framework_ViewPayload *p = framework_view_payload_find(etd2x_jni_object_token_host(ref));
    if (!p) return NULL;
    if (p->focused) return etd2x_jni_new_local_ref_host(env, ref);
    for (framework_ViewChildRef *c = p->children; c; c = c->next) {
        void *found = framework_view_find_focused_local(env, c->global_ref, depth + 1);
        if (found) return found;
    }
    return NULL;
}

