/* ----- java.util.ServiceLoader -----
 * Android uses ordinary class-path META-INF/services descriptors. ETD2X reads
 * the exact descriptor across the selected logical-package APKs, deduplicates
 * provider names, validates assignability, and eagerly instantiates the same
 * provider classes the iterator would expose. */
static bool framework_service_loader_add_provider(void *env, void *service_class, void *providers, const char *binary_name) {
    if (!service_class || !providers || !binary_name || !binary_name[0]) return false;
    char slash[512];
    snprintf(slash, sizeof(slash), "%s", binary_name);
    for (char *p = slash; *p; ++p) if (*p == '.') *p = '/';
    void *provider_class = etd2x_jni_find_class_ref(env, slash);
    if (!provider_class) {
        if (etd2x_jni_exception_pending_host(env)) etd2x_jni_exception_clear_host(env);
        char msg[640]; snprintf(msg, sizeof(msg), "Provider %s not found", binary_name);
        (void)etd2x_jni_throw_new_by_name(env, "java/util/ServiceConfigurationError", msg);
        return false;
    }
    Etd2xJniValue assign_arg = {.l = provider_class}, assign = {0};
    if (!framework_java_call_virtual(env, service_class, "isAssignableFrom", "(Ljava/lang/Class;)Z", &assign_arg, 1, &assign) || !assign.z) {
        etd2x_jni_delete_local_ref_host(env, provider_class);
        char msg[640]; snprintf(msg, sizeof(msg), "Provider %s not a subtype", binary_name);
        (void)etd2x_jni_throw_new_by_name(env, "java/util/ServiceConfigurationError", msg);
        return false;
    }
    Etd2xJniValue instance = {0};
    if (!framework_java_call_virtual(env, provider_class, "newInstance", "()Ljava/lang/Object;", NULL, 0, &instance) || !instance.l) {
        etd2x_jni_delete_local_ref_host(env, provider_class);
        if (!etd2x_jni_exception_pending_host(env)) {
            char msg[640]; snprintf(msg, sizeof(msg), "Provider %s could not be instantiated", binary_name);
            (void)etd2x_jni_throw_new_by_name(env, "java/util/ServiceConfigurationError", msg);
        }
        return false;
    }
    Etd2xJniValue add_arg = {.l = instance.l}, ignored = {0};
    const bool ok = framework_java_call_virtual(env, providers, "add", "(Ljava/lang/Object;)Z", &add_arg, 1, &ignored);
    etd2x_jni_delete_local_ref_host(env, instance.l);
    etd2x_jni_delete_local_ref_host(env, provider_class);
    return ok;
}

static void *framework_service_loader_build_provider_list(void *env, void *service_class) {
    void *providers = etd2x_jni_new_local_object(env, "java/util/ArrayList");
    if (!providers || !service_class || !framework_g_fw.source_path[0] || !etd2x_package_read_selected_entry_concat)
        return providers;

    char service[512] = {0};
    if (!etd2x_jni_class_ref_name_host(service_class, service, sizeof(service))) return providers;
    for (char *p = service; *p; ++p) if (*p == '/') *p = '.';
    char entry[640];
    if (snprintf(entry, sizeof(entry), "META-INF/services/%s", service) >= (int)sizeof(entry)) return providers;

    uint8_t *raw = NULL; size_t raw_size = 0;
    const Etd2xResult rc = etd2x_package_read_selected_entry_concat(framework_g_fw.source_path, entry, &raw, &raw_size);
    if (rc != ETD2X_OK) {
        if (providers) etd2x_jni_delete_local_ref_host(env, providers);
        (void)etd2x_jni_throw_new_by_name(env, "java/util/ServiceConfigurationError", "Unable to read service configuration");
        return NULL;
    }
    if (!raw || !raw_size) { free(raw); return providers; }

    char *text = malloc(raw_size + 1u);
    if (!text) { free(raw); if (providers) etd2x_jni_delete_local_ref_host(env, providers); (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ServiceLoader configuration"); return NULL; }
    memcpy(text, raw, raw_size); text[raw_size] = '\0'; free(raw);
    char **seen = NULL; size_t seen_count = 0;
    char *save = NULL;
    for (char *line = strtok_r(text, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
        char *comment = strchr(line, '#'); if (comment) *comment = '\0';
        char *begin = line; while (*begin && isspace((unsigned char)*begin)) ++begin;
        char *end = begin + strlen(begin); while (end > begin && isspace((unsigned char)end[-1])) *--end = '\0';
        if (!*begin) continue;
        bool duplicate = false;
        for (size_t i = 0; i < seen_count; ++i) if (strcmp(seen[i], begin) == 0) { duplicate = true; break; }
        if (duplicate) continue;
        char **next = realloc(seen, (seen_count + 1u) * sizeof(*seen));
        if (!next) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ServiceLoader provider set"); break; }
        seen = next; seen[seen_count] = strdup(begin);
        if (!seen[seen_count]) { (void)etd2x_jni_throw_new_by_name(env, "java/lang/OutOfMemoryError", "ServiceLoader provider name"); break; }
        ++seen_count;
        if (!framework_service_loader_add_provider(env, service_class, providers, begin)) break;
    }
    for (size_t i = 0; i < seen_count; ++i) free(seen[i]);
    free(seen);
    free(text);
    if (etd2x_jni_exception_pending_host(env)) { if (providers) etd2x_jni_delete_local_ref_host(env, providers); return NULL; }
    return providers;
}

