/* ----- android.util.Base64 encoder (flags NO_PADDING=1 NO_WRAP=2 CRLF=4 URL_SAFE=8) ----- */
static char *framework_base64_encode_text(const uint8_t *in, size_t len, int flags, size_t *out_len) {
    const char *alphabet = (flags & 8) ? "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
                                       : "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const bool pad = !(flags & 1), wrap = !(flags & 2), crlf = (flags & 4) != 0;
    const size_t chars = (len + 2) / 3 * 4;
    char *out = malloc(chars + (chars / 76 + 2) * 2 + 1);
    if (!out) return NULL;
    size_t o = 0, line = 0;
    for (size_t i = 0; i < len; i += 3) {
        const uint32_t v = ((uint32_t)in[i] << 16) | (i + 1 < len ? (uint32_t)in[i + 1] << 8 : 0) | (i + 2 < len ? in[i + 2] : 0);
        const size_t emit = i + 2 < len ? 4 : i + 1 < len ? 3 : 2;
        for (size_t k = 0; k < 4; ++k) {
            if (k < emit) out[o++] = alphabet[(v >> (18 - 6 * k)) & 63];
            else if (pad) out[o++] = '=';
        }
        line += 4;
        /* Android's encoder breaks lines every 19 groups (76 characters). */
        if (wrap && line == 76 && i + 3 < len) { if (crlf) out[o++] = '\r'; out[o++] = '\n'; line = 0; }
    }
    if (wrap && len) { if (crlf) out[o++] = '\r'; out[o++] = '\n'; }
    out[o] = '\0';
    *out_len = o;
    return out;
}

