static Etd2xAssetConfiguration framework_framework_asset_configuration(void) {
    Etd2xAssetConfiguration c = {0};
    const int32_t density = framework_g_fw.cfg.density_dpi > 0 ? framework_g_fw.cfg.density_dpi : 160;
    c.language[0] = framework_g_fw.language[0];
    c.language[1] = framework_g_fw.language[1];
    c.country[0] = framework_g_fw.country[0];
    c.country[1] = framework_g_fw.country[1];
    c.orientation = framework_g_fw.cfg.width_pixels > framework_g_fw.cfg.height_pixels
        ? ETD2X_ACONFIGURATION_ORIENTATION_LAND
        : (framework_g_fw.cfg.width_pixels < framework_g_fw.cfg.height_pixels
            ? ETD2X_ACONFIGURATION_ORIENTATION_PORT
            : ETD2X_ACONFIGURATION_ORIENTATION_SQUARE);
    c.touchscreen = framework_g_fw.cfg.touchscreen;
    c.density = density;
    c.keyboard = framework_g_fw.cfg.keyboard;
    c.navigation = framework_g_fw.cfg.navigation;
    c.keys_hidden = framework_g_fw.cfg.keys_hidden;
    c.nav_hidden = framework_g_fw.cfg.nav_hidden;
    c.sdk_version = framework_g_fw.compat.platform_api;
    c.ui_mode_type = framework_g_fw.cfg.ui_mode_type;
    c.ui_mode_night = framework_g_fw.cfg.ui_mode_night;
    c.layout_direction = framework_g_fw.cfg.layout_direction;
    c.screen_round = framework_g_fw.cfg.screen_round;
    c.screen_width_dp = framework_g_fw.cfg.width_pixels > 0 ? framework_g_fw.cfg.width_pixels * 160 / density : 0;
    c.screen_height_dp = framework_g_fw.cfg.height_pixels > 0 ? framework_g_fw.cfg.height_pixels * 160 / density : 0;
    const int32_t short_dp = c.screen_width_dp < c.screen_height_dp ? c.screen_width_dp : c.screen_height_dp;
    const int32_t long_dp = c.screen_width_dp > c.screen_height_dp ? c.screen_width_dp : c.screen_height_dp;
    c.smallest_screen_width_dp = short_dp;
    if (long_dp > 0 && short_dp > 0) {
        if (long_dp < 470) c.screen_size = ETD2X_ACONFIGURATION_SCREENSIZE_SMALL;
        else if (long_dp >= 960 && short_dp >= 720) c.screen_size = ETD2X_ACONFIGURATION_SCREENSIZE_XLARGE;
        else if (long_dp >= 640 && short_dp >= 480) c.screen_size = ETD2X_ACONFIGURATION_SCREENSIZE_LARGE;
        else c.screen_size = ETD2X_ACONFIGURATION_SCREENSIZE_NORMAL;
        c.screen_long = (int64_t)long_dp * 3 >= (int64_t)short_dp * 5
            ? ETD2X_ACONFIGURATION_SCREENLONG_YES
            : ETD2X_ACONFIGURATION_SCREENLONG_NO;
    }
    return c;
}

