bool etd2x_android_has_pending_activity(void) { return framework_g_fw.pending_activity && framework_g_fw.pending_activity_class[0]; }
bool etd2x_android_activity_finish_requested(void) { return framework_g_fw.activity_finish_requested; }
size_t etd2x_android_class_count(void){return framework_g_fw.class_count;} size_t etd2x_android_preference_store_count(void){size_t n=0;for(framework_PrefStore*s=framework_g_fw.prefs;s;s=s->next)n++;return n;}

bool etd2x_android_has_attached_surface(void) {
    for (framework_SurfaceHolderPayload *p = framework_g_fw.surface_holders; p; p = p->next)
        if (p->surface_active && p->callback_created_dispatched) return true;
    return false;
}

void etd2x_android_mark_activity_finishing(void) { framework_g_fw.activity_finishing = true; }
void etd2x_android_mark_activity_destroyed(void) { framework_g_fw.activity_destroyed = true; }

size_t etd2x_android_live_java_thread_count(void) {
    size_t live = 0;
    for (framework_ThreadPayload *p = framework_g_fw.threads; p; p = p->next)
        if (p->launched && !__atomic_load_n(&p->finished, __ATOMIC_ACQUIRE)) live++;
    return live;
}

size_t etd2x_android_wait_java_threads_idle(uint32_t timeout_ms) {
    const int64_t deadline = framework_framework_uptime_millis() + (int64_t)timeout_ms;
    size_t live = etd2x_android_live_java_thread_count();
    while (live && framework_framework_uptime_millis() < deadline) {
        struct timespec nap = {0, 10 * 1000 * 1000};
        nanosleep(&nap, NULL);
        live = etd2x_android_live_java_thread_count();
    }
    /* A finished worker still executes ETD2X text until its host thread exits. */
    ETD2X_PERF_LOCK(&framework_g_java_thread_reap_lock);
    for (framework_ThreadPayload *p = framework_g_fw.threads; p; p = p->next) {
        if (p->launched && !p->joined && __atomic_load_n(&p->finished, __ATOMIC_ACQUIRE)) {
            (void)pthread_join(p->thread, NULL);
            p->joined = true;
        }
    }
    pthread_mutex_unlock(&framework_g_java_thread_reap_lock);
    return live;
}




/* surface diagnostics */
/* Surface discovery diagnostics read the owned tree, not guest overrides. */
static void framework_surface_log_view(void *env, void *ref, unsigned depth, size_t *remaining) {
    if (!ref || !*remaining || depth > 32u) return;
    --*remaining;
    char cls[512] = {0};
    (void)etd2x_jni_object_class_name_host(ref, cls, sizeof(cls));
    framework_ViewPayload *p = framework_view_payload_find(etd2x_jni_object_token_host(ref));
    ETD2X_LOGCI("SURFACE", "view depth=%u token=%p class=%s payload=%d id=0x%x attached=%d visibility=%d size=%dx%d measured=%dx%d children=%zu holder=%d renderer=%d resumed=%d",
                depth, etd2x_jni_object_token_host(ref), cls[0] ? cls : "<unknown>", p != NULL,
                p ? (unsigned)p->id : 0u, p && p->attached_to_window, p ? p->visibility : -1,
                p ? p->width : 0, p ? p->height : 0, p ? p->measured_width : 0,
                p ? p->measured_height : 0, p ? p->child_count : 0u,
                p && p->surface_holder_global, p && p->renderer_global, p && p->gl_resumed);
    for (framework_ViewChildRef *c = p ? p->children : NULL; c && *remaining; c = c->next)
        framework_surface_log_view(env, c->global_ref, depth + 1u, remaining);
    (void)env;
}

void etd2x_android_log_surface_state(void *env, const char *reason) {
    size_t views = 0, renderers = 0, holders = 0, active = 0, delivered = 0;
    for (framework_ViewPayload *v = framework_g_fw.views; v; v = v->next) {
        ++views;
        if (v->renderer_global) ++renderers;
    }
    for (framework_SurfaceHolderPayload *h = framework_g_fw.surface_holders; h; h = h->next) {
        ++holders;
        if (h->surface_active) ++active;
        if (h->surface_active && h->callback_created_dispatched) ++delivered;
    }
    const char *missing = !framework_g_fw.content_view ? "no-content-root" : !holders ? "no-surface-holders" :
                          !active ? "holders-not-attached" : !delivered ? "created-callback-not-delivered" : "none";
    ETD2X_LOGCI("SURFACE", "discovery reason=%s activity=%s state=%d content=%p decor=%p views=%zu renderers=%zu holders=%zu active=%zu delivered=%zu pendingActivity=%s surfaceAttached=%d missing=%s",
                reason ? reason : "-", framework_g_fw.activity_class, (int)framework_g_fw.activity_state,
                etd2x_jni_object_token_host(framework_g_fw.content_view), etd2x_jni_object_token_host(framework_g_fw.decor_view),
                views, renderers, holders, active, delivered, framework_g_fw.pending_activity_class[0] ? framework_g_fw.pending_activity_class : "-",
                delivered != 0, missing);
    size_t remaining = 128;
    framework_surface_log_view(env, framework_g_fw.decor_view ? framework_g_fw.decor_view : framework_g_fw.content_view, 0, &remaining);
    if (!remaining) ETD2X_LOGCW("SURFACE", "view inventory truncated at 128 nodes");
    size_t candidates = 0;
    for (framework_ViewPayload *v = framework_g_fw.views; v && candidates < 64u; v = v->next) {
        void *ref = etd2x_jni_new_local_from_token(env, v->object_token);
        if (ref && (v->renderer_global ||
                    etd2x_jni_is_instance_of_class_host(ref, "android/view/SurfaceView") ||
                    etd2x_jni_is_instance_of_class_host(ref, "android/view/TextureView"))) {
            ++candidates;
            ETD2X_LOGCI("SURFACE", "surface candidate parent=%p", v->parent_token);
            size_t one = 1;
            framework_surface_log_view(env, ref, 0, &one);
        }
        if (ref) etd2x_jni_delete_local_ref_host(env, ref);
    }
    size_t limit = 0;
    for (framework_SurfaceHolderPayload *h = framework_g_fw.surface_holders; h && limit++ < 64u; h = h->next) {
        char cls[512] = {0}, callback[512] = {0};
        void *owner = etd2x_jni_new_local_from_token(env, h->owner_view_token);
        if (owner) (void)etd2x_jni_object_class_name_host(owner, cls, sizeof(cls));
        size_t callback_count = 0;
        ETD2X_PERF_LOCK(&framework_g_surface_callback_lock);
        for (framework_SurfaceCallbackRef *r = h->callbacks; r; r = r->next) {
            if (!callback_count) (void)etd2x_jni_object_class_name_host(r->global_ref, callback, sizeof(callback));
            ++callback_count;
        }
        pthread_mutex_unlock(&framework_g_surface_callback_lock);
        framework_ViewPayload *v = framework_view_payload_find(h->owner_view_token);
        ETD2X_LOGCI("SURFACE", "holder owner=%p class=%s parent=%p attached=%d active=%d callback=%s callbacks=%zu created=%d surface=%p format=%d",
                    h->owner_view_token, cls[0] ? cls : "<unknown>", v ? v->parent_token : NULL,
                    v && v->attached_to_window, h->surface_active, callback[0] ? callback : "<none>", callback_count,
                    h->callback_created_dispatched, etd2x_jni_object_token_host(h->surface_global), h->format);
        if (owner) etd2x_jni_delete_local_ref_host(env, owner);
    }
}



/* thread diagnostics */
void etd2x_android_log_java_threads(const char *reason) {
    for (framework_ThreadPayload *p = framework_g_fw.threads; p; p = p->next) {
        if (!p->launched || __atomic_load_n(&p->exited, __ATOMIC_ACQUIRE)) continue;
        char cls[512] = {0}, target[512] = {0};
        if (p->object_global) (void)etd2x_jni_object_class_name_host(p->object_global, cls, sizeof(cls));
        if (p->target_global) (void)etd2x_jni_object_class_name_host(p->target_global, target, sizeof(target));
        ETD2X_LOGCI("THREAD", "java-worker reason=%s pthread=%p class=%s target=%s finished=%d exited=%d joined=%d",
                    reason ? reason : "-", (void *)(uintptr_t)p->thread,
                    cls[0] ? cls : "-", target[0] ? target : "-",
                    __atomic_load_n(&p->finished, __ATOMIC_ACQUIRE),
                    __atomic_load_n(&p->exited, __ATOMIC_ACQUIRE),
                    __atomic_load_n(&p->joined, __ATOMIC_ACQUIRE));
    }
}



/* gms presence */
/* ---------- Opt-in Google Play services presence ----------
 * ETD2X is a device without Google Play services by default. Some apps refuse
 * to start unless the Play services package is installed (for example the
 * Firebase Unity SDK aborts FirebaseApp creation when a module reports
 * "missing dependency"). With sdmc:/switch/earntodie2_nx/config/gms-present.flag, ETD2X
 * reports the Google Play services (com.google.android.gms) and Play Store
 * (com.android.vending) packages as installed system apps, enabled and signed
 * with the public Google release certificate, as microG does, so client-library
 * availability checks (GoogleApiAvailability / GoogleSignatureVerifier, which
 * verify the Store before Play services) succeed. Nothing else is emulated: no
 * component of either package is hosted, so binds, intents and IPC to them
 * still fail, which apps observe as Play services being installed but its
 * services unavailable.
 *
 * The certificate is the public Google "Android" release certificate
 * (SHA-1 38:91:8A:45:3D:07:19:93:54:F8:B1:9A:F0:5E:C6:56:2C:ED:57:88) that signs
 * both packages, as published by the microG project (Apache-2.0). */

#define GMS_PRESENT_FLAG_PATH "sdmc:/switch/earntodie2_nx/config/gms-present.flag"
#define GMS_INSTALL_TIME_MS 1230768000000LL /* 2009-01-01: part of the system image */

