typedef struct framework_GmsPackage {
    const char *name;
    const char *version_name;
    const char *class_name; /* ApplicationInfo.className, NULL when unset */
    int32_t version_code;
    int32_t uid;
    void *application_info; /* global ApplicationInfo, built on first use */
} framework_GmsPackage;

static framework_GmsPackage framework_g_gms_packages[] = {
    /* A current Play services release (25.40.32); above every client
     * library's minimum GOOGLE_PLAY_SERVICES_VERSION_CODE. */
    {"com.google.android.gms", "25.40.32 (190400-etd2x-unavailable)",
     "com.google.android.gms.chimera.GmsApplication", 254032035, 10090, NULL},
    {"com.android.vending", "48.3.19-31 [0] [PR] etd2x-unavailable", NULL, 84831930, 10091, NULL},
};

static int framework_g_gms_present = -1; /* -1 undecided, 0 absent, 1 present */
static void *framework_g_gms_signatures;   /* global Signature[] shared by both packages */
static void *framework_g_gms_signing_info; /* global SigningInfo */

/* Host tests (and embedders) can force the mode; otherwise the SD flag decides. */
void etd2x_android_set_gms_present(bool present) { framework_g_gms_present = present ? 1 : 0; }

static bool framework_gms_present(void) {
    if (framework_g_gms_present < 0) {
#ifdef __SWITCH__
        framework_g_gms_present = access(GMS_PRESENT_FLAG_PATH, F_OK) == 0 ? 1 : 0;
#else
        framework_g_gms_present = 0;
#endif
        ETD2X_LOGCI("ANDROID", "Google Play services presence=%s (%s)",
                    framework_g_gms_present ? "installed-unavailable" : "absent", GMS_PRESENT_FLAG_PATH);
    }
    return framework_g_gms_present == 1;
}

static struct framework_GmsPackage *framework_gms_package_arg(const Etd2xJniValue *a, size_t n) {
    char p[160];
    if (n < 1 || !a[0].l || !framework_read_jstring(a[0].l, p, sizeof(p))) return NULL;
    for (size_t i = 0; i < sizeof(framework_g_gms_packages) / sizeof(framework_g_gms_packages[0]); ++i)
        if (strcmp(p, framework_g_gms_packages[i].name) == 0) return &framework_g_gms_packages[i];
    return NULL;
}

static bool framework_gms_signatures_build(void *env) {
    if (framework_g_gms_signatures) return true;
    void *sigs = etd2x_jni_new_local_reference_array(env, "[Landroid/content/pm/Signature;", 1);
    void *sig = etd2x_jni_new_local_object(env, "android/content/pm/Signature");
    void *bytes = etd2x_jni_new_local_byte_array(env, (int32_t)sizeof(framework_k_gms_release_cert));
    void *signing = etd2x_jni_new_local_object(env, "android/content/pm/SigningInfo");
    bool ok = sigs && sig && bytes && signing &&
              etd2x_jni_byte_array_write(bytes, 0, (int32_t)sizeof(framework_k_gms_release_cert),
                                         (const int8_t *)framework_k_gms_release_cert) == ETD2X_OK &&
              framework_signature_store_bytes(env, etd2x_jni_object_token_host(sig), bytes) &&
              etd2x_jni_set_object_array_element_host(env, sigs, 0, sig) == ETD2X_OK;
    if (ok) {
        framework_set_instance_object_field(signing, "etd2xSigners", "[Landroid/content/pm/Signature;", sigs);
        framework_set_instance_object_field(signing, "etd2xHistory", "[Landroid/content/pm/Signature;", sigs);
        framework_g_gms_signatures = etd2x_jni_new_global_ref_host(env, sigs);
        framework_g_gms_signing_info = etd2x_jni_new_global_ref_host(env, signing);
        ok = framework_g_gms_signatures && framework_g_gms_signing_info;
    }
    void *locals[] = {sigs, sig, bytes, signing};
    for (size_t i = 0; i < sizeof(locals) / sizeof(locals[0]); ++i)
        if (locals[i]) etd2x_jni_delete_local_ref_host(env, locals[i]);
    return ok;
}

static bool framework_gms_objects_build(void *env, framework_GmsPackage *pkg) {
    if (!framework_gms_signatures_build(env)) return false;
    if (pkg->application_info) return true;
    void *app = etd2x_jni_new_local_object(env, "android/content/pm/ApplicationInfo");
    if (!app) return false;
    framework_set_object_string_field(app, "packageName", pkg->name);
    framework_set_object_string_field(app, "processName", pkg->name);
    if (pkg->class_name) framework_set_object_string_field(app, "className", pkg->class_name);
    framework_set_instance_bool_field(app, "enabled", true);
    framework_set_instance_int_field(app, "uid", pkg->uid);
    /* FLAG_SYSTEM | FLAG_HAS_CODE | FLAG_UPDATED_SYSTEM_APP | FLAG_INSTALLED */
    framework_set_instance_int_field(app, "flags", 0x1 | 0x4 | 0x80 | 0x00800000);
    framework_set_instance_int_field(app, "targetSdkVersion", 30);
    framework_set_instance_int_field(app, "minSdkVersion", 21);
    pkg->application_info = etd2x_jni_new_global_ref_host(env, app);
    etd2x_jni_delete_local_ref_host(env, app);
    return pkg->application_info != NULL;
}

/* PackageManager.getPackageInfo(<Google package>, flags): a fresh PackageInfo
 * per call, as the platform returns a parcelled copy. */
static void *framework_gms_package_info_local(void *env, struct framework_GmsPackage *pkg, int32_t flags) {
    if (!framework_gms_present() || !framework_gms_objects_build(env, pkg)) return NULL;
    void *info = etd2x_jni_new_local_object(env, "android/content/pm/PackageInfo");
    if (!info) return NULL;
    framework_set_object_string_field(info, "packageName", pkg->name);
    framework_set_object_string_field(info, "versionName", pkg->version_name);
    framework_set_instance_int_field(info, "versionCode", pkg->version_code);
    framework_set_instance_object_field(info, "applicationInfo", "Landroid/content/pm/ApplicationInfo;", pkg->application_info);
    framework_set_instance_long_field(info, "firstInstallTime", GMS_INSTALL_TIME_MS);
    framework_set_instance_long_field(info, "lastUpdateTime", GMS_INSTALL_TIME_MS);
    framework_set_instance_object_field(info, "signatures", "[Landroid/content/pm/Signature;",
                              (flags & PM_GET_SIGNATURES) ? framework_g_gms_signatures : NULL);
    framework_set_instance_object_field(info, "signingInfo", "Landroid/content/pm/SigningInfo;",
                              (flags & PM_GET_SIGNING_CERTIFICATES) ? framework_g_gms_signing_info : NULL);
    ETD2X_LOGCI("ANDROID", "PackageManager.getPackageInfo package=%s flags=0x%x result=ok (installed-unavailable)",
                pkg->name, (unsigned)flags);
    return info;
}

static void *framework_gms_application_info_local(void *env, struct framework_GmsPackage *pkg) {
    if (!framework_gms_present() || !framework_gms_objects_build(env, pkg)) return NULL;
    return framework_local_from_global(env, pkg->application_info);
}

static void framework_gms_presence_reset(void) {
    void *env = etd2x_jni_current_env();
    void **globals[] = {&framework_g_gms_signatures, &framework_g_gms_signing_info,
                        &framework_g_gms_packages[0].application_info, &framework_g_gms_packages[1].application_info};
    for (size_t i = 0; i < sizeof(globals) / sizeof(globals[0]); ++i) {
        if (env && *globals[i]) etd2x_jni_delete_global_ref_host(env, *globals[i]);
        *globals[i] = NULL;
    }
}




