/* ---- framework contracts ---- */


#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

bool etd2x_context_stream_path(const char *files_dir, const char *name,
                               char *out, size_t cap) {
    if (!files_dir || !name || !out || cap == 0) return false;
    if (strchr(name, '/')) return false;
    const int n = snprintf(out, cap, "%s/%s", files_dir, name);
    return n >= 0 && (size_t)n < cap;
}

const char *etd2x_context_output_fopen_mode(int32_t mode) {
    if (mode & ~ETD2X_CONTEXT_MODE_APPEND) return NULL;
    return (mode & ETD2X_CONTEXT_MODE_APPEND) ? "ab" : "wb";
}

bool etd2x_file_observer_path_exists(const char *path) {
    struct stat st;
    return path && stat(path, &st) == 0;
}

int etd2x_file_observer_pick_event(int mask,
                                   const Etd2xFileObserverSnapshot *before,
                                   const Etd2xFileObserverSnapshot *after) {
    if (!before || !after) return 0;
    if (!before->exists && after->exists) {
        if (mask & ETD2X_FO_CREATE) return ETD2X_FO_CREATE;
        if (mask & ETD2X_FO_MOVED_TO) return ETD2X_FO_MOVED_TO;
    } else if (before->exists && !after->exists) {
        if (mask & ETD2X_FO_DELETE_SELF) return ETD2X_FO_DELETE_SELF;
        if (mask & ETD2X_FO_DELETE) return ETD2X_FO_DELETE;
        if (mask & ETD2X_FO_MOVED_FROM) return ETD2X_FO_MOVED_FROM;
    } else if (before->exists && after->exists) {
        if (before->inode != after->inode) {
            if (mask & ETD2X_FO_MOVE_SELF) return ETD2X_FO_MOVE_SELF;
            if (mask & ETD2X_FO_MOVED_TO) return ETD2X_FO_MOVED_TO;
        }
        if (before->size != after->size || before->mtime != after->mtime) {
            if (mask & ETD2X_FO_CLOSE_WRITE) return ETD2X_FO_CLOSE_WRITE;
            if (mask & ETD2X_FO_MODIFY) return ETD2X_FO_MODIFY;
        }
        if (before->mode != after->mode && (mask & ETD2X_FO_ATTRIB))
            return ETD2X_FO_ATTRIB;
    }
    return 0;
}


static int framework_contracts_etd2x_fo_entry_compare(const void *left, const void *right) {
    const Etd2xFileObserverEntry *a = (const Etd2xFileObserverEntry *)left;
    const Etd2xFileObserverEntry *b = (const Etd2xFileObserverEntry *)right;
    return strcmp(a->name, b->name);
}

bool etd2x_file_observer_immediate_child(const char *directory, const char *path,
                                         char *out_name, size_t out_cap) {
    if (!directory || !path || !out_name || out_cap == 0) return false;
    size_t dl = strlen(directory);
    while (dl > 1 && directory[dl - 1] == '/') --dl;
    if (strncmp(directory, path, dl) != 0 || path[dl] != '/') return false;
    const char *name = path + dl + 1;
    if (!name[0] || strchr(name, '/')) return false;
    const size_t nl = strlen(name);
    if (nl >= out_cap) return false;
    memcpy(out_name, name, nl + 1);
    return true;
}

bool etd2x_file_observer_scan_directory(const char *path,
                                        Etd2xFileObserverDirectorySnapshot *out) {
    if (!out) return false;
    out->entries = NULL;
    out->count = 0;
    if (!path) return false;
    DIR *dir = opendir(path);
    if (!dir) return false;

    size_t cap = 0;
    bool ok = true;
    struct dirent *de = NULL;
    while ((de = readdir(dir)) != NULL) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        if (out->count == cap) {
            const size_t next = cap ? cap * 2u : 16u;
            Etd2xFileObserverEntry *grown =
                (Etd2xFileObserverEntry *)realloc(out->entries, next * sizeof(*grown));
            if (!grown) { ok = false; break; }
            out->entries = grown;
            cap = next;
        }

        Etd2xFileObserverEntry entry;
        memset(&entry, 0, sizeof(entry));
        if (snprintf(entry.name, sizeof(entry.name), "%s", de->d_name) >= (int)sizeof(entry.name))
            continue;

        const size_t pl = strlen(path), nl = strlen(de->d_name);
        char *child = (char *)malloc(pl + nl + 2u);
        if (!child) { ok = false; break; }
        memcpy(child, path, pl);
        size_t off = pl;
        if (off && child[off - 1] != '/') child[off++] = '/';
        memcpy(child + off, de->d_name, nl + 1u);

        struct stat st;
        if (stat(child, &st) == 0) {
            entry.inode = (uint64_t)st.st_ino;
            entry.size = (int64_t)st.st_size;
            entry.mtime = (int64_t)st.st_mtime;
            entry.ctime = (int64_t)st.st_ctime;
            entry.mode = (uint32_t)st.st_mode;
            entry.is_directory = S_ISDIR(st.st_mode);
            out->entries[out->count++] = entry;
        }
        free(child);
    }
    closedir(dir);
    if (!ok) {
        free(out->entries);
        out->entries = NULL;
        out->count = 0;
        return false;
    }
    if (out->count > 1)
        qsort(out->entries, out->count, sizeof(*out->entries), framework_contracts_etd2x_fo_entry_compare);
    return true;
}

void etd2x_file_observer_release_directory(Etd2xFileObserverDirectorySnapshot *snapshot) {
    if (!snapshot) return;
    free(snapshot->entries);
    snapshot->entries = NULL;
    snapshot->count = 0;
}

static const Etd2xFileObserverEntry *framework_contracts_etd2x_fo_find_name(
    const Etd2xFileObserverDirectorySnapshot *snapshot, const char *name) {
    if (!snapshot || !name) return NULL;
    size_t lo = 0, hi = snapshot->count;
    while (lo < hi) {
        const size_t mid = lo + (hi - lo) / 2u;
        const int cmp = strcmp(snapshot->entries[mid].name, name);
        if (cmp < 0) lo = mid + 1u;
        else if (cmp > 0) hi = mid;
        else return &snapshot->entries[mid];
    }
    return NULL;
}

static bool framework_contracts_etd2x_fo_same_identity(const Etd2xFileObserverEntry *a,
                                   const Etd2xFileObserverEntry *b) {
    if (!a || !b || a->is_directory != b->is_directory) return false;
    if (a->inode && b->inode) return a->inode == b->inode;
    /* libnx/fsdev exposes st_ino as zero. Exact guest rename notifications are
     * authoritative; this fingerprint is only the external-change fallback. */
    return a->size == b->size && a->mtime == b->mtime && a->ctime == b->ctime &&
           ((a->mode ^ b->mode) & 0170000u) == 0;
}

static void framework_contracts_etd2x_fo_emit(Etd2xFileObserverEvent *out, size_t cap, size_t *count,
                          int event, const char *name) {
    if (!event || !count) return;
    if (*count < cap && out) {
        Etd2xFileObserverEvent *dst = &out[*count];
        memset(dst, 0, sizeof(*dst));
        dst->event = event;
        if (name && name[0]) {
            dst->has_path = true;
            snprintf(dst->path, sizeof(dst->path), "%s", name);
        }
    }
    (*count)++;
}

size_t etd2x_file_observer_diff_directory(
    int mask,
    const Etd2xFileObserverDirectorySnapshot *before,
    const Etd2xFileObserverDirectorySnapshot *after,
    Etd2xFileObserverEvent *out_events,
    size_t event_capacity) {
    if (!before || !after) return 0;
    bool *old_paired = (bool *)calloc(before->count ? before->count : 1u, sizeof(bool));
    bool *new_paired = (bool *)calloc(after->count ? after->count : 1u, sizeof(bool));
    if (!old_paired || !new_paired) {
        free(old_paired); free(new_paired);
        return 0;
    }
    size_t count = 0;

    /* Removed+added entries with a unique identity are a rename pair. */
    for (size_t i = 0; i < before->count; ++i) {
        if (framework_contracts_etd2x_fo_find_name(after, before->entries[i].name)) continue;
        size_t candidate = SIZE_MAX, candidates = 0;
        for (size_t j = 0; j < after->count; ++j) {
            if (framework_contracts_etd2x_fo_find_name(before, after->entries[j].name)) continue;
            if (framework_contracts_etd2x_fo_same_identity(&before->entries[i], &after->entries[j])) {
                candidate = j;
                candidates++;
            }
        }
        if (candidates != 1) continue;
        size_t reverse = 0;
        for (size_t k = 0; k < before->count; ++k) {
            if (framework_contracts_etd2x_fo_find_name(after, before->entries[k].name)) continue;
            if (framework_contracts_etd2x_fo_same_identity(&before->entries[k], &after->entries[candidate]))
                reverse++;
        }
        if (reverse != 1) continue;

        old_paired[i] = true;
        new_paired[candidate] = true;
        if (mask & ETD2X_FO_MOVED_FROM)
            framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_MOVED_FROM,
                          before->entries[i].name);
        if (mask & ETD2X_FO_MOVED_TO)
            framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_MOVED_TO,
                          after->entries[candidate].name);
    }

    for (size_t i = 0; i < before->count; ++i) {
        const Etd2xFileObserverEntry *now =
            framework_contracts_etd2x_fo_find_name(after, before->entries[i].name);
        if (!now) {
            if (!old_paired[i] && (mask & ETD2X_FO_DELETE))
                framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_DELETE,
                              before->entries[i].name);
            continue;
        }
        const Etd2xFileObserverEntry *old = &before->entries[i];
        const bool data_changed = old->size != now->size || old->mtime != now->mtime ||
                                  old->ctime != now->ctime;
        const bool attrs_changed = old->mode != now->mode;
        if (data_changed) {
            if (mask & ETD2X_FO_CLOSE_WRITE)
                framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_CLOSE_WRITE, now->name);
            else if (mask & ETD2X_FO_MODIFY)
                framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_MODIFY, now->name);
        }
        if (attrs_changed && (mask & ETD2X_FO_ATTRIB))
            framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_ATTRIB, now->name);
    }

    for (size_t j = 0; j < after->count; ++j) {
        if (framework_contracts_etd2x_fo_find_name(before, after->entries[j].name)) continue;
        if (!new_paired[j] && (mask & ETD2X_FO_CREATE))
            framework_contracts_etd2x_fo_emit(out_events, event_capacity, &count, ETD2X_FO_CREATE,
                          after->entries[j].name);
    }

    free(old_paired);
    free(new_paired);
    return count > event_capacity ? event_capacity : count;
}

Etd2xEnumMapKeyPolicy etd2x_enum_map_key_policy(bool inserting,
                                                 bool key_nonnull,
                                                 bool key_matches_type) {
    if (!key_nonnull)
        return inserting ? ETD2X_ENUM_MAP_KEY_NULL : ETD2X_ENUM_MAP_KEY_QUERY_MISS;
    if (!key_matches_type)
        return inserting ? ETD2X_ENUM_MAP_KEY_WRONG_TYPE : ETD2X_ENUM_MAP_KEY_QUERY_MISS;
    return ETD2X_ENUM_MAP_KEY_OK;
}

